-- 导出  表 public.attempt 结构
CREATE TABLE IF NOT EXISTS "attempt" (
	"id" BIGINT NOT NULL,
	"user_id" BIGINT NOT NULL,
	"question_id" BIGINT NOT NULL,
	"sequence" INTEGER NOT NULL,
	"answer" TEXT NULL DEFAULT NULL,
	"score" DOUBLE PRECISION NULL DEFAULT NULL,
	"points" DOUBLE PRECISION NULL DEFAULT NULL,
	"feedback" TEXT NULL DEFAULT NULL,
	"dimensions_json" TEXT NULL DEFAULT NULL,
	"submitted_at" BIGINT NOT NULL,
	"evaluated_at" BIGINT NULL DEFAULT NULL,
	PRIMARY KEY ("id"),
	CONSTRAINT "attempt_submitted_at_not_null1" CHECK (submitted_at IS NOT NULL),
	CONSTRAINT "attempt_sequence_not_null1" CHECK (sequence IS NOT NULL),
	CONSTRAINT "attempt_question_id_not_null1" CHECK (question_id IS NOT NULL),
	CONSTRAINT "attempt_user_id_not_null1" CHECK (user_id IS NOT NULL),
	CONSTRAINT "attempt_id_not_null1" CHECK (id IS NOT NULL)
)
CREATE INDEX "idx_attempt_user_question" ON "" ("user_id", "question_id", "sequence");;

