DiscardPolicy将丢弃任务
DiscardOldestPolicy将丢弃最老的任务
Discard的两个策略适用于允许任务丢失，并配合任务未执行的持久化策略来实现最终数据一致，适用于不需要保证强一致性的业务中
AbortPolicy式Executors的默认策略
CallerRunsPolicy适用与不允许任务丢失，允许任务积压的场景
当前默认配置将导致任务丢失，用户侧下单失败
2 使用无界队列将存在OOM风险，同时不会触发拒绝策略  使用有界队列，队列容量要根据实际场景配置，保证队列内任务不会持续积压同时也要避免非核心线程的频繁创建 
3 拒绝策略不应当使用Discard，在使用Abort时也要保证任务执行失败时的持久化存储以便后续补录，', 4.5, 10.4, '正确：① **四种拒绝策略的行为基本都对**：AbortPolicy 抛 **RejectedExecutionException**、CallerRunsPolicy 由**提交线程自己执行**、DiscardPolicy 丢弃、DiscardOldestPolicy 丢最老的；**AbortPolicy 是默认策略**也答对了；场景搭配上「Discard 系适合允许丢失的业务」「CallerRunsPolicy 适合不可丢、可接受积压」方向正确；当前默认策略在这个场景下**导致下单失败**这一结论答到。
不足：① 各策略的适用场景没说清**触发后的系统行为**差异——CallerRunsPolicy 的价值在于**天然限流降速**（提交方被占用，反压上游），DiscardOldestPolicy 适合**只关心最新任务**的场景，这两点没展开。② **无界队列 OOM、不触发拒绝策略**答对了；但问点里「**突发流量下核心/最大线程数如何搭配、为什么**」基本没答，只说「容量根据实际场景配置、避免非核心线程频繁创建」——既没给搭配原则（核心数按常态流量、队列中小容量、最大线程数设弹性上限，队列满先扩线程再拒绝），也没讲原因（延迟与保护的权衡），这是 8 分问点里的一半以上。③ 方案只有一句「Abort + 失败持久化以便补录」，**自定义思路与配套动作、取舍都没展开**：应答自定义 **RejectedExecutionHandler**（拒绝时落库/MQ 兜底再异步重试），配套**入口限流降级、队列水位与拒绝数监控告警、扩容**，取舍是**持久化保不丢但增加延迟与存储成本、补录需幂等与状态校验、限流牺牲非核心体验**。
错误：① 「AbortPolicy 将抛异常**并将任务丢弃**」表述不准——抛异常意味着任务**未被接受执行**，需要调用方捕获处理，与 DiscardPolicy 的静默丢弃不是一回事，混着说会显得概念不分。② 「避免非核心线程的频繁创建」逻辑说反了：队列越小、越早满，**越会**触发创建非核心线程直至 max，之后才拒绝；用有界队列不是为了少建非核心线程，而是为了**能触发拒绝策略、控内存**。

【记忆点】
1. 四策略一句话：Abort 抛异常（默认）、CallerRuns 提交线程执行（反压限流）、Discard 静默丢、DiscardOldest 丢队头最老任务
2. 无界队列 = 永不拒绝 + 无限堆积 OOM；有界队列 = 可控内存 + 触发拒绝策略，队列越小越早扩到最大线程数
3. 突发流量搭配：核心线程按常态流量、队列中小容量、最大线程数设弹性上限，队列满先扩线程、再拒绝
4. 自定义拒绝策略核心：拒绝时落库/MQ 兜底 + 异步补录重试，配套限流降级、监控告警、扩容，取舍在延迟/存储成本与不丢任务之间', '{"正确性":5.0,"完整性":4.0,"表述":5.0}', 1793611922664, 1793612080647),
	(124, 2, 157, 1, 'AbortPolicy是抛出RejectedExecutionException并丢弃任务，而DiscardPolicy是静默丢弃，不会抛出异常', 10, 8, '正确：**AbortPolicy** 抛出 **RejectedExecutionException** 且任务不执行，**DiscardPolicy** 静默丢弃、不抛异常——两种策略的行为和差异本质（**失败是否让调用方感知**）都说对了。
扩展：实际选型上，Abort 的价值在于异常能被调用方捕获后做日志/告警/落库补偿；Discard 连日志都没有，任务丢了无人知晓，除非明确允许丢任务，否则生产不用。

【记忆点】
1. AbortPolicy：抛 RejectedExecutionException，任务被拒，调用方能感知。
2. DiscardPolicy：静默丢弃，不抛异常，任务丢失无感知。
3. 差异本质是失败是否对调用方可见：要兜底用 Abort，允许丢才用 Discard。
4. 另两种：DiscardOldest 丢队首最老任务；CallerRunsPolicy 让提交任务的线程自己执行。', '{"正确性":10.0,"完整性":10.0,"表述":9.0}', 1793689376175, 1793690690213),
	(125, 2, 151, 1, '用于定义线程池名称以及一切其他参数，在实际项目开发中，明确的线程池名可以更好的定位问题', 8, 6.4, '正确：**threadFactory** 用于定制线程池中线程的创建方式，项目里最常用的作用是**给线程统一起业务名**，方便看线程 dump 和日志、快速定位问题——核心用途答到了。
不足：① 说成"定义线程池名称"不准确，它定的是**线程名**，不是线程池名；② 除名字外还能设置**守护线程、优先级、线程分组、UncaughtExceptionHandler**（线程内未捕获异常统一记录），作答只笼统写"一切其他参数"；③ 没点出它本质是**生产线程对象的工厂**，默认用 Executors.defaultThreadFactory()。

【记忆点】
1. threadFactory 是生产线程池中线程的工厂，默认 Executors.defaultThreadFactory()。
2. 项目里最核心的作用：给线程统一起业务名，线程 dump/日志一眼定位归属。
3. 还能设置守护线程、优先级、线程分组、UncaughtExceptionHandler。
4. 写法：实现 ThreadFactory，在 newThread 里 setName("业务名-" + 自增序号) 再返回。', '{"正确性":8.0,"完整性":7.0,"表述":7.0}', 1793689404861, 1793690690237),
	(126, 2, 153, 1, 'CPU密集型任务设置为CPU核心数+1，IO密集型任务设置为CPU核心数*2
CPU密集时，保证CPU各核心没有空闲，+1为当某个任务中断，被丢弃时能有新任务来执行，尽量避免核心的空闲时间
IO密集型大部分时间是在执行资源IO，为保证CPU利用最大化，通常设置为CPU核心数的2-n倍，具体数量由实际压测决定。', 6, 4.8, '正确：**CPU 密集型取 CPU 核心数 + 1**，**IO 密集型取核心数的 2 倍起（2~n 倍）**，并指出具体倍数要靠压测确定——设置结论和"差异来自任务是否长时间占用 CPU"这层意思答到了。
错误：+1 的原因说成"某个任务中断、**被丢弃**时有新任务来执行"——任务不会被丢弃；+1 是为了在某条线程**短暂无法运行**（缺页、GC、上下文切换等）时，仍有线程把 CPU 核心喂满，不让 CPU 空转。
不足：IO 密集型的差异原因表述不准——不是"在执行 IO"，而是线程**大部分时间阻塞在等待 IO**、CPU 空闲，所以要开更多线程让 CPU 一直有活干；CPU 密集型线程几乎不阻塞，线程数超过核心数只会增加上下文切换。

【记忆点】
1. CPU 密集型：线程数 = CPU 核心数 + 1，+1 是防止某线程短暂停顿时 CPU 空转。
2. IO 密集型：线程数 = 核心数 × 2 起（2~n 倍），靠压测定具体值。
3. 差异根源：CPU 密集线程不阻塞，多了只增加切换；IO 密集线程常阻塞，多了才能喂饱 CPU。
4. 线程多了不是越多越好，切换开销和内存都要算进去。', '{"正确性":6.0,"完整性":8.0,"表述":6.0}', 1793689520978, 1793690690262),
	(127, 2, 154, 1, '同步移交队列本身不存储任务，当任务来时直接创建非核心线程执行
多用于不允许等待，尽量快的，执行时间短，数量小的场景', 6, 4.8, '正确：抓住 **SynchronousQueue 不存储任务**这一核心特征，也答到了"不希望任务排队等待"的场景倾向。
不足：① "任务来时直接创建非核心线程执行"不准确——它是**交接**：提交时若有空闲线程就直接把任务交给它（不入队、不新建线程），只有没有空闲线程且未达 maxPoolSize 才创建新线程，达上限则走拒绝策略；② 场景说成"数量小"不够准，典型场景是**任务来得急、执行时间短、量不可预期**（CachedThreadPool 就用它），希望任务立刻被执行、线程能被快速复用，而不是堆积排队。

