	(128, 2, 155, 1, 'Executors创建的4个线程池，newFixedThreadPool newSingleThreadExcutor newCachedThreadPool newSchduledThreadPool，其中Fixed使用LinkedBlockingQueue无界队列，将导致不会触发拒绝策略，任务堆积导致OOM，SingleThreadExcutor同样使用无界队列，Cached使用有界队列，但是最大线程数为Integer最大值，当任务量大时可能频繁创建新线程导致OOM，Schduled同样使用无界队列。
手写可以显式指定参数，保证核心线程数，最大线程数，队列长度和拒绝策略复合实际业务需求，保证系统稳定。', 5, 3.5, '正确：**FixedThreadPool 与 SingleThreadExecutor 用 LinkedBlockingQueue 无界队列**（容量 Integer.MAX_VALUE），任务堆积导致 OOM 且**永不触发拒绝策略**；**CachedThreadPool 最大线程数 Integer.MAX_VALUE**，任务多时线程数暴涨导致 OOM；Scheduled 系列的队列同样无界；手写可**显式指定核心数、最大线程数、队列容量、拒绝策略**——这些都答到了。
错误：CachedThreadPool **不是用有界队列**，它用的是 **SynchronousQueue**（不存储任务），并不存在"队列满"这一说；机制是**没有空闲线程就直接新建线程**，直冲 Integer.MAX_VALUE 上限。
不足：手写多解决的问题可再点透一层：Executors 只给"便捷模板"、把容量参数写死，手写让你能**按业务量级设定边界并配套拒绝兜底与监控**。

【记忆点】
1. Fixed/Single：LinkedBlockingQueue 无界队列 → 任务堆积 OOM，拒绝策略形同虚设。
2. Cached：SynchronousQueue + maxPoolSize=Integer.MAX_VALUE → 线程数暴涨 OOM。
3. 阿里手册要求手写 new ThreadPoolExecutor：容量参数显式可控，能配拒绝策略与监控。
4. 核心风险是"边界不可控"：要么队列无界，要么线程数无界。', '{"正确性":4.0,"完整性":7.0,"表述":6.0}', 1793689770169, 1793690690294),
	(129, 2, 159, 1, '两个参数分别表示非核心线程空闲存活时间的数量单位以及时间单位，例如 1 second  就表示1秒
