扩展：@Lazy 生成代理延迟获取，是解决循环依赖/减轻启动开销的手段，对「可有可无」这个诉求并非必需，属于超出题面的正确内容，不加分。

【记忆点】
1. 强依赖 → 构造器注入：保证非空、不可变、启动即失败；只有一个构造器时可省略 @Autowired。
2. 可选依赖 → setter 注入 + @Autowired(required=false) 或 @Nullable，缺依赖也能启动。
3. @Lazy 用于生成延迟解析的代理，解决循环依赖或延迟初始化，不是「可选依赖」的必需品。', '{"正确性":8.0,"完整性":8.0,"表述":7.0}', 1793862972649, 1793863407410),
	(187, 2, 231, 1, '1 可以针对某一类方法的前后中都进行代码增强
2 基于动态代理实现
3 接口耗时的计算，日志的记录', 6, 4.8, '正确：①方向对，增强对象是**方法**（切点匹配到的方法/连接点）；②点到了**动态代理**；③日志记录、接口耗时统计都是典型横切场景。
不足：②只给了「基于动态代理」这句结论，没讲清「与手写代理相比」的关键区别——容器通过 **BeanPostProcessor 在 Bean 初始化后自动**为匹配的 Bean 创建 JDK 接口代理或 CGLIB 子类代理，并用代理对象替换原 Bean，业务代码零侵入；手写代理则要自己 new Proxy、自己把代理对象交出去，无法对容器内 Bean 统一生效。
不足：①可再补一句「增强的是被切点表达式命中的业务方法，而不是类本身」。

【记忆点】
1. AOP 增强目标是切点匹配到的方法（连接点），不是整个类。
2. 统一增强靠 BeanPostProcessor 在初始化后自动生成代理（JDK 接口代理 / CGLIB 子类代理）并替换容器中的 Bean。
3. 典型横切场景：日志、事务、权限校验、耗时监控、缓存。', '{"正确性":7.0,"完整性":6.0,"表述":7.0}', 1793863101594, 1793863407416),
	(188, 2, 232, 1, '执行PreDestroy', 3, 2.4, '正确：@PreDestroy 确实是销毁回调之一。
不足：只答了一个环节。销毁前容器依次做的是：**BeanPostProcessor 的 postProcessBeforeDestruction（@PreDestroy 在此触发）→ DisposableBean.destroy() → 自定义 destroy-method**，单例 Bean 在容器 close 时统一走这套流程。

【记忆点】
1. 销毁顺序：@PreDestroy（postProcessBeforeDestruction）→ DisposableBean.destroy() → 自定义 destroy-method。
2. 只有单例 Bean 会被容器管理销毁；prototype 的销毁容器不负责。', '{"正确性":4.0,"完整性":3.0,"表述":6.0}', 1793863118294, 1793863407416),
	(189, 2, 233, 1, '字段注入和setter注入有什么区别？？？', 0, 0, '**错误**：作答内容为「字段注入和setter注入有什么区别？？」，是把题面反问回来，并未给出任何答案；题面所问的两个问点——①两种方式各自在 Bean 生命周期的什么时间点完成注入，②由此带来的一个实际差异——均未作答。

**不足**：连结论层面的方向性表述也没有。至少应说明两条注入发生在**属性填充（populateBean）**阶段：字段注入靠反射直接写字段，setter 注入靠调用 setter 方法；然后任选一个实际差异（比如 setter 里能加校验、包装、默认值逻辑，字段注入绕过方法就没有这个位置）。

【记忆点】
1. 字段注入与 setter 注入都在**属性填充（populateBean）**阶段完成，都在初始化回调（@PostConstruct / afterPropertiesSet）之前。
2. 区别在执行方式：字段注入用**反射直接写字段**，setter 注入是**调用 setter 方法**。
3. 实际差异：setter 注入可以在 setter 里做校验、默认值、包装等逻辑；字段注入绕过方法，没有这个插入点。
4. 字段注入的副作用还包括：依赖被隐藏、单元测试需容器或反射、不能注入 static/final 字段。', '{"正确性":0.0,"完整性":0.0,"表述":0.0}', 1793863141233, 1793863413070),
	(190, 2, 234, 1, '1 可以使用Primary指定当类冲突时使用哪一个bean，或使用Qulifier通过bean名称来区分
2 提供了Conditional机制，条件不满足时bean不会被创建', 8, 8.8, '正确：①**@Primary** 指定默认优先、**@Qualifier("beanName")** 按名称精确指定，两种主流方式都答对；②**@Conditional** 条件装配，条件不满足该 Bean 不会注册/创建，答对。
不足：①还漏了一种常用方式——按**字段名/参数名**与 bean 名称匹配（以及 @Resource 按名称注入）；②可补一句「条件不满足时该 Bean 的 BeanDefinition 直接被跳过，若有别处强依赖注入它，启动会报找不到 Bean」。

【记忆点】
1. 多候选消歧：@Primary 定默认、@Qualifier("name") 按名称选、字段名/参数名与 bean 名匹配、@Resource 按名称。
2. @Conditional 及其派生注解（如 @ConditionalOnProperty）控制 Bean 是否注册；条件不满足则不创建，强依赖注入它会启动失败。', '{"正确性":8.0,"完整性":7.0,"表述":8.0}', 1793863200026, 1793863407416),
	(191, 2, 235, 1, '匹配UserService中的所有方法，方法参数不限，方法返回值不限，
*表示任意返回值  ..表示任意参数
UserService表示UserService以及其子类', 6, 6.6, '正确：整体含义答对了——匹配 UserService 中**所有方法**、返回值不限、参数不限；第一个 `*` = 任意返回值，`..` = 任意参数，都对。
错误：把 `UserService.` 说成「UserService 及其子类」是错的。这里是**类型限定**，只匹配 com.example.service.UserService 这个类的方法，不含子类；要含子类得写成 `com.example.service.UserService+.*(..)`。

【记忆点】
1. execution(* com.example.service.UserService.*(..))：返回任意、UserService 类中任意方法、参数任意。
2. 位置含义：第一个 * 是返回值，第二个 * 是方法名，() 内 .. 表示任意个任意类型参数，`类名+` 才表示含子类。', '{"正确性":6.0,"完整性":7.0,"表述":7.0}', 1793863245369, 1793863407416),
	(192, 2, 230, 1, '1 日志应当是before  事务应当是around
2 是在实例化时，通过ObjectFacotries获取的
3 jdk是创建一个接口的实现类，cglib是生成一个子类', 3, 6.9, '**正确：**
① Advice 类型判断方向基本正确——日志适合用 **@Before**（也可 @Around），事务确实用 **@Around**。
③ 能说出 JDK 动态代理基于**接口**生成实现类、CGLIB 基于**继承**生成子类。

**不足：**
① 没有回答「如何与业务代码**解耦**」——应说明：把横切逻辑抽到切面类中，用**切点表达式**匹配 OrderService.createOrder，在配置类上开 **@EnableAspectJAutoProxy**，业务类中不出现任何日志/事务代码。
① 题面明确问「为什么事务用 @Around 而不是 @Before」，你只给了结论没给原因。
③ 题面明确要求「至少两点选择依据」，一条都没给。
③ 两者区别只说了半句，未提到 CGLIB **不能代理 final 类和 final 方法**、JDK 代理目标是接口实现类等关键边界。

**错误：**
② 说「在实例化时，通过 ObjectFactory 获取」，机制说反了。代理不是在实例化阶段创建，也不是通过 ObjectFactory 拿到的；真正创建代理的是**初始化阶段**中 **BeanPostProcessor**（AbstractAutoProxyCreator）的 **postProcessAfterInitialization**，它把原生 Bean 包一层代理后返回，替换掉容器里的引用。单例 Bean 默认在**容器启动时**（refresh 的 finishBeanFactoryInitialization 预实例化）就完成代理创建，不是第一次调用时。

【记忆点】
1. AOP 代理创建时机：初始化阶段、BeanPostProcessor 的 postProcessAfterInitialization 里由 AbstractAutoProxyCreator 包一层代理。
2. 单例 Bean 默认容器启动时预实例化（finishBeanFactoryInitialization）就完成代理创建，非懒加载。
3. 事务用 @Around 是因为要控制目标方法执行前后：能捕获异常决定回滚、能决定是否执行目标方法、能改写返回值。
4. JDK 代理基于接口（Proxy + InvocationHandler），CGLIB 基于继承生成子类，无法代理 final 类/方法。', '{"正确性":3.0,"完整性":3.0,"表述":3.0}', 1793863376834, 1793863407432);

