-- 导出  表 public.memory_point 结构
CREATE TABLE IF NOT EXISTS "memory_point" (
	"id" BIGINT NOT NULL,
	"user_id" BIGINT NOT NULL,
	"practice_id" BIGINT NOT NULL,
	"question_id" BIGINT NULL DEFAULT NULL,
	"point_names_json" TEXT NULL DEFAULT NULL,
	"text" TEXT NULL DEFAULT NULL,
	"created_at" BIGINT NOT NULL,
	PRIMARY KEY ("id"),
	CONSTRAINT "memory_point_created_at_not_null1" CHECK (created_at IS NOT NULL),
	CONSTRAINT "memory_point_practice_id_not_null1" CHECK (practice_id IS NOT NULL),
	CONSTRAINT "memory_point_user_id_not_null1" CHECK (user_id IS NOT NULL),
	CONSTRAINT "memory_point_id_not_null1" CHECK (id IS NOT NULL)
)
CREATE INDEX "idx_mp_user_practice" ON "" ("user_id", "practice_id", "created_at");;

