-- 导出  表 public.note 结构
CREATE TABLE IF NOT EXISTS "note" (
	"id" BIGINT NOT NULL,
	"user_id" BIGINT NOT NULL,
	"practice_id" BIGINT NOT NULL,
	"question_id" BIGINT NULL DEFAULT NULL,
	"scene" VARCHAR(16) NULL DEFAULT NULL,
	"text" TEXT NULL DEFAULT NULL,
	"created_at" BIGINT NOT NULL,
	"updated_at" BIGINT NOT NULL,
	PRIMARY KEY ("id"),
	CONSTRAINT "note_updated_at_not_null1" CHECK (updated_at IS NOT NULL),
	CONSTRAINT "note_created_at_not_null1" CHECK (created_at IS NOT NULL),
	CONSTRAINT "note_practice_id_not_null1" CHECK (practice_id IS NOT NULL),
	CONSTRAINT "note_user_id_not_null1" CHECK (user_id IS NOT NULL),
	CONSTRAINT "note_id_not_null1" CHECK (id IS NOT NULL)
)
CREATE INDEX "idx_note_user_practice" ON "" ("user_id", "practice_id", "created_at");;

-- 正在导出表  public.note 的数据：-1 rows
DELETE FROM "note";

-- 导出  表 public.paper 结构
CREATE TABLE IF NOT EXISTS "paper" (
	"id" BIGINT NOT NULL,
	"user_id" BIGINT NOT NULL,
	"practice_id" BIGINT NOT NULL,
	"sequence" INTEGER NOT NULL,
	"kind" VARCHAR(16) NULL DEFAULT NULL,
	"focus_points_json" TEXT NULL DEFAULT NULL,
	"composition_mode" VARCHAR(16) NULL DEFAULT NULL,
	"status" VARCHAR(16) NULL DEFAULT NULL,
	"summary_json" TEXT NULL DEFAULT NULL,
	"progress_json" TEXT NULL DEFAULT NULL,
	"plan_json" TEXT NULL DEFAULT NULL,
	"max_score" INTEGER NULL DEFAULT NULL,
	"created_at" BIGINT NOT NULL,
	"submitted_at" BIGINT NULL DEFAULT NULL,
	PRIMARY KEY ("id"),
	CONSTRAINT "paper_created_at_not_null1" CHECK (created_at IS NOT NULL),
	CONSTRAINT "paper_sequence_not_null1" CHECK (sequence IS NOT NULL),
	CONSTRAINT "paper_practice_id_not_null1" CHECK (practice_id IS NOT NULL),
	CONSTRAINT "paper_user_id_not_null1" CHECK (user_id IS NOT NULL),
	CONSTRAINT "paper_id_not_null1" CHECK (id IS NOT NULL)
)
CREATE INDEX "idx_paper_user_practice" ON "" ("user_id", "practice_id", "sequence");;

-- 正在导出表  public.paper 的数据：22 rows
DELETE FROM "paper";
INSERT INTO "paper" ("id", "user_id", "practice_id", "sequence", "kind", "focus_points_json", "composition_mode", "status", "summary_json", "progress_json", "plan_json", "max_score", "created_at", "submitted_at") VALUES
	(1, 2, 1, 1, NULL, NULL, 'regular', 'graded', '{"overall":"基础概念掌握较扎实，复杂度、扩容倍数、树化条件、线程安全等硬知识得分高；主要短板是答题只给结论不给理由，第 2、4 题因此被扣分，中档题的机制边界也常漏细节。","strengths":["关键参数记忆准确：1.5 倍扩容、树化 8/64 条件都答对","复杂度判断正确，能说清随机访问与搬移的原因","HashMap equals/hashCode 配套重写的因果链讲清了","Hashtable 与 ConcurrentHashMap 的对比抓住锁粒度差异"],"improvements":["题目要求\"简述理由\"时必须补上依据，不能只写类名","中档题要主动说清机制边界，如遍历加锁、读无锁等细节","术语要准确，别把 HashMap 的\"阈值\"套到 ArrayList 上","并发问题描述要具体，避免\"中间状态数据\"这类模糊说法"],"gradedAt":1793081347246}', NULL, '[{"points":["ArrayList · 增删与扩容机制"],"angle":"末尾 add 与中间插入的复杂度、扩容倍数","tier":"基础","type":"概念辨析","weight":10},{"points":["集合框架 · 体系结构"],"angle":"按定位说四大接口及常用实现类关系","tier":"基础","type":"概念辨析","weight":10},{"points":["集合 · Comparable 与 Comparator"],"angle":"给自定义对象写排序规则的两种方式辨析","tier":"基础","type":"概念辨析","weight":9},{"points":["集合选型 · 综合场景"],"angle":"按有序/去重/查询增删选集合的小场景","tier":"基础","type":"概念辨析","weight":9},{"points":["集合 · equals/hashCode 契约"],"angle":"自定义对象作 key 前该重写什么、为何","tier":"基础","type":"概念辨析","weight":9},{"points":["ConcurrentHashMap · 并发特性"],"angle":"多线程共享 Map 时为何选它而非 Hashtable","tier":"基础","type":"概念辨析","weight":9},{"points":["ArrayList · 底层结构与特性"],"angle":"由数组特性推随机访问与增删的表现","tier":"基础","type":"概念辨析","weight":9},{"points":["HashMap · 扩容机制"],"angle":"何时触发扩容与扩容后的容量变化","tier":"基础","type":"概念辨析","weight":9},{"points":["List · 线程安全方案"],"angle":"多线程下让 List 安全的几种包装做法","tier":"中档","type":"原理追问","weight":13},{"points":["HashMap · 底层结构与特性"],"angle":"说 JDK8 结构、null 键值与线程安全性","tier":"中档","type":"原理追问","weight":13}]', 100, 1793073158735, 1793081360885),
	(2, 2, 1, 2, NULL, NULL, 'regular', 'graded', '{"overall":"基础概念题整体掌握较好，尤其 HashMap 方法语义、fail-fast 机制、CME 原因等高频点答题准确；但答案普遍偏简略，机制细节与适用场景的取舍表述不够完整，导致有分题被扣。Set 去重的判定依据（hashCode 定位桶、equals 判等）理解有偏差，大题内存优化与并发方案的回答较粗，需加强规范表述与场景化分析。","strengths":["HashMap 方法语义与返回值判断准确","fail-fast 机制、CME 原因表述清晰","并发方案选型方向正确，能对比锁粒度","能想到用初始容量减少扩容开销"],"improvements":["答案需展开关键机制细节，不能只给结论","Set 去重判定依据要答 hashCode/equals 分工","方案题要写明适用场景与取舍，不能只列名字","大题要点分层次，覆盖内存与并发两个维度"],"gradedAt":1793083231785}', NULL, '[{"points":["集合 · fail-fast 与 fail-safe"],"angle":"遍历中删除元素为何抛异常、如何正确删","tier":"基础","type":"概念辨析","weight":8},{"points":["HashMap · 线程安全与替代方案"],"angle":"多线程 put 丢数据现象与替代方案选型","tier":"基础","type":"概念辨析","weight":8},{"points":["集合框架 · 体系结构"],"angle":"Collection 与 Map 的关系及各自子接口辨析","tier":"基础","type":"概念辨析","weight":8},{"points":["List · 线程安全方案"],"angle":"线程安全 List 的各方案如何选择取舍","tier":"基础","type":"概念辨析","weight":8},{"points":["集合选型 · 综合场景"],"angle":"带线程安全约束的缓存与统计场景选集合","tier":"基础","type":"概念辨析","weight":8},{"points":["ArrayList · 底层结构与特性"],"angle":"从有序可重复角度辨析 ArrayList 特性","tier":"基础","type":"概念辨析","weight":8},{"points":["集合 · 迭代器 Iterator"],"angle":"用 Iterator 遍历并安全删除元素的写法","tier":"基础","type":"概念辨析","weight":7},{"points":["HashMap · put 过程"],"angle":"put 与 get 基本用法与返回值含义","tier":"中档","type":"原理追问","weight":11},{"points":["Set · 去重原理"],"angle":"用 Set 对一批数据去重的写法与判定依据","tier":"中档","type":"原理追问","weight":11},{"points":["HashMap · 底层结构与特性","HashMap · 扩容机制","ConcurrentHashMap · 并发特性"],"angle":"爬虫 URL 计数场景串联结构、扩容与并发取舍","tier":"大题","type":"场景应用","weight":23}]', 100, 1793082101122, 1793083251352),
	(3, 2, 2, 1, NULL, NULL, 'regular', 'graded', '{"overall":"本卷10题仅作答3题，覆盖不足。已答部分对 volatile 可见性、锁对象辨析等核心概念记忆准确，但普遍存在「只给结论不展开机制」的问题，尤其 count++ 丢更新未讲读-改-写三步、示例题未写出代码。需补足未作答题目，并练习把原理讲透。","strengths":["volatile 可见性核心结论表述准确","锁对象辨析全对，this 与 Class 区分清楚","能判断 volatile 禁止指令重排","count++ 非原子操作这一根本前提抓得住"],"improvements":["答题须展开机制，如读-改-写三步被覆盖丢更新","示例题要写出完整可运行代码，不能只写声明","错题必须修正：a() 与 synchronized(this) 是互斥的","未作答题目太多，需完整练习 AQS、CAS、锁升级等高频点"],"gradedAt":1793088111724}', NULL, '[{"points":["volatile · 可见性与原子性边界"],"angle":"i++ 用 volatile 修饰为何仍会丢更新","tier":"基础","type":"概念辨析","weight":10},{"points":["CAS · 原理与三大问题"],"angle":"讲清 CAS 思想及其 ABA 问题的应对","tier":"基础","type":"概念辨析","weight":10},{"points":["ReentrantLock · 与 synchronized"],"angle":"什么场景下应该改用 ReentrantLock","tier":"基础","type":"概念辨析","weight":9},{"points":["volatile · 典型使用场景"],"angle":"写一个优雅停机的状态标志位示例","tier":"基础","type":"概念辨析","weight":9},{"points":["synchronized · 锁升级过程"],"angle":"无锁到偏向到重量级的升级顺序与动因","tier":"基础","type":"概念辨析","weight":9},{"points":["AtomicInteger · 常用方法与适用场景"],"angle":"用 AtomicInteger 改写共享计数器的累加","tier":"基础","type":"概念辨析","weight":9},{"points":["synchronized · 等待唤醒与线程协作"],"angle":"生产者消费者中 wait/notify 的调用条件","tier":"基础","type":"概念辨析","weight":9},{"points":["ReentrantLock · 公平锁与非公平锁"],"angle":"构造参数 true 和 false 分别选在什么场景","tier":"基础","type":"概念辨析","weight":9},{"points":["volatile · 指令重排序与 happens-befo"],"angle":"双重检查锁单例为何要给 instance 加 volatile","tier":"中档","type":"原理追问","weight":13},{"points":["synchronized · 三种使用形式与语义"],"angle":"实例方法与静态方法 synchronized 分别锁谁","tier":"中档","type":"原理追问","weight":13}]', 100, 1793087662225, 1793088131274),
	(4, 2, 2, 2, NULL, NULL, 'regular', 'graded', '{"overall":"基础概念辨析题掌握较扎实，选型、锁对象互斥、公平锁等题答得准确；但涉及 API 具体用法、volatile 可见性机制、原子类方法等细节记忆不牢，大题第①②问失分明显。需加强原理机制的完整表述，避免只给结论不写依据。","strengths":["锁对象互斥判断准确，能识别不同锁实例不互斥","CAS 与加锁的选型结论正确，抓住原子性与顺序性差异","公平/非公平锁优缺点与吞吐差异表述完整","能指出 CAS 自旋开销在高并发下的性能退化"],"improvements":["常用 API（原子类方法、tryLock 超时）需熟记签名与用途","volatile 可见性机制要讲清内存屏障与缓存一致性","答案不要只给结论，补充关键理由与触发条件","wait/notify 套路需完整记忆：持锁、while、notifyAll 区别"],"gradedAt":1793089791014}', NULL, '[{"points":["ReentrantLock · 与 synchronized"],"angle":"给出并发需求，让选择用哪种锁并说明理由","tier":"基础","type":"概念辨析","weight":8},{"points":["CAS · 原理与三大问题"],"angle":"问 CAS 无锁思想、与加锁对比，以及它的局限","tier":"基础","type":"概念辨析","weight":8},{"points":["synchronized · 三种使用形式与语义"],"angle":"给出一段混用三种写法的代码，判断各段互斥与否","tier":"基础","type":"概念辨析","weight":8},{"points":["AtomicInteger · 常用方法与适用场景"],"angle":"写出原子类常用方法，并说明什么场景下优先选用它","tier":"基础","type":"概念辨析","weight":8},{"points":["synchronized · 等待唤醒与线程协作"],"angle":"写出 wait/notify 必须配套的加锁与判断套路","tier":"基础","type":"概念辨析","weight":8},{"points":["ReentrantLock · 公平锁与非公平锁"],"angle":"公平与非公平各自的优缺点和吞吐量差异","tier":"基础","type":"概念辨析","weight":8},{"points":["ReentrantLock · tryLock 超时与可中断"],"angle":"写出让等待锁的线程能超时退出的代码片段","tier":"基础","type":"概念辨析","weight":7},{"points":["synchronized · 锁升级过程"],"angle":"说明升级是单向的还是可降级的、为什么","tier":"中档","type":"原理追问","weight":11},{"points":["volatile · 指令重排序与 happens-befo"],"angle":"解释什么是指令重排序以及带来的可见性问题","tier":"中档","type":"原理追问","weight":11},{"points":["volatile · 可见性与原子性边界","volatile · 典型使用场景"],"angle":"配置热更新场景：让另一线程及时看到新配置","tier":"大题","type":"场景应用","weight":23}]', 100, 1793088789678, 1793089811485),
	(5, 2, 4, 3, NULL, NULL, 'regular', 'graded', '{"overall":"基础概念掌握较扎实，拒绝策略、参数作用、队列特性等要点大多答对，口述清晰有条理。但两处硬伤：一是自定义拒绝策略题答偏，把实现思路答成了策略选型；二是 CachedThreadPool 队列类型连续两次答错（实为 SynchronousQueue 而非 ArrayBlockingQueue）。线程池推进流程与参数配合关系理解到位，大题表现良好。","strengths":["拒绝策略行为差异把握准确，Abort/Discard 对比到位","keepAliveTime 与核心线程回收设置回答完整准确","线程池推进流程与 maximumPoolSize 失效原因讲得清楚","线程数按 CPU/IO 密集型的设置思路和压测定值原则正确"],"improvements":["自定义拒绝策略要答实现 RejectedExecutionHandler 接口重写方法","CachedThreadPool 用的是 SynchronousQueue 不是有界队列，需纠正","CPU 密集型 +1 的原因不是防任务被丢弃，是防线程短暂不可用","兜底方案不要只写 CallerRunsPolicy，需结合拒绝后落库补偿"],"gradedAt":1793690712850}', NULL, '[{"points":["自定义线程池 · 优雅关闭"],"angle":"任务跑完后线程池要不要关、怎么关","tier":"基础","type":"概念辨析","weight":8},{"points":["拒绝策略 · DiscardPolicy 与 DiscardOldestPoli"],"angle":"两种丢弃策略分别做什么、有何差异","tier":"基础","type":"概念辨析","weight":8},{"points":["线程池参数 · threadFactory"],"angle":"threadFactory 参数是干嘛的、起什么作用","tier":"基础","type":"概念辨析","weight":8},{"points":["拒绝策略 · 自定义拒绝策略"],"angle":"如何实现 RejectedExecutionHandler 自定义拒绝行为","tier":"基础","type":"概念辨析","weight":8},{"points":["线程池参数调优 · CPU/IO密集型线程数设置"],"angle":"CPU/IO 密集型任务线程数怎么设置","tier":"基础","type":"概念辨析","weight":8},{"points":["线程池 · 同步移交队列适用场景"],"angle":"同步移交队列是什么、什么场景用","tier":"基础","type":"概念辨析","weight":8},{"points":["四种内置线程池 · 为什么不推荐直接用 Executors 创建"],"angle":"换角度：面试官追问手写 ThreadPoolExecutor 比 Executors 多解决了什么","tier":"基础","type":"概念辨析","weight":7},{"points":["线程池参数 · keepAliveTime 与 unit"],"angle":"keepAliveTime 和 unit 管什么、默认值多少","tier":"中档","type":"原理追问","weight":11},{"points":["内置线程池的风险 · 无界队列与MAX_VALUE"],"angle":"无界队列和 MAX_VALUE 线程上限会带来什么问题","tier":"中档","type":"原理追问","weight":11},{"points":["线程池 · 为什么要用","线程池 · 核心工作流程","线程池参数 · corePoolSize 与 maximumPoolSize"],"angle":"同一场景串联：引入线程池解决什么、任务推进流程、core/max 如何配合","tier":"大题","type":"场景应用","weight":23}]', 100, 1793689220143, 1793690731001),
	(6, 2, 2, 3, NULL, NULL, 'regular', 'graded', '{"overall":"基础概念题完成度尚可，CAS、volatile、synchronized 用法类题得分较稳；但锁升级、Lock/Condition 等题大片空缺，大题方案取舍论证不足。需补齐未作答知识点，强化按题面逐问作答与结论先行的表达习惯。","strengths":["CAS 无锁与上下文切换开销答得准确","volatile 禁止重排、防中间态对象抓住核心","synchronized 三种形式的锁对象全部答对","识别出 synchronized 进程内锁不跨实例"],"improvements":["未作答题必须补练，锁升级与 AQS 是高频考点","每问先给结论再讲依据，避免逻辑自相矛盾","大题逐小问作答，方案取舍要给量化理由","Condition 与 wait/notify 规范需专项复习"],"gradedAt":1793092983345}', NULL, '[{"points":["CAS · 原理与三大问题"],"angle":"高并发限流计数为何不用 synchronized 而用 CAS","tier":"基础","type":"概念辨析","weight":8},{"points":["synchronized · 锁升级过程"],"angle":"多线程短临界区下锁状态如何演变并说明动因","tier":"基础","type":"概念辨析","weight":8},{"points":["volatile · 典型使用场景"],"angle":"一次性发布安全构造对象为何用 volatile 引用","tier":"基础","type":"概念辨析","weight":8},{"points":["synchronized · 三种使用形式与语义"],"angle":"写 synchronized(this)、类.class、方法三种形式代码","tier":"基础","type":"概念辨析","weight":8},{"points":["synchronized · 等待唤醒与线程协作"],"angle":"notify 之后为何还要继续 wait 直到条件满足","tier":"基础","type":"概念辨析","weight":8},{"points":["ReentrantLock · tryLock 超时与可中断"],"angle":"lockInterruptibly 与 lock 在被中断时行为差异","tier":"基础","type":"概念辨析","weight":8},{"points":["Condition · 多条件等待唤醒"],"angle":"用两个 Condition 实现有界队列的存取等待","tier":"基础","type":"概念辨析","weight":7},{"points":["volatile · 指令重排序与 happens-befo"],"angle":"volatile 为何能禁止重排序、happens-before 含义","tier":"中档","type":"原理追问","weight":11},{"points":["volatile · 可见性与原子性边界"],"angle":"标记位为何够用、计数为何不够用的辨析","tier":"中档","type":"原理追问","weight":11},{"points":["ReentrantLock · 与 synchronized","ReentrantLock · 公平锁与非公平锁","AtomicInteger · 常用方法与适用场景"],"angle":"库存扣减场景对比三方案并给出取舍理由","tier":"大题","type":"场景应用","weight":23}]', 100, 1793090360933, 1793093007026),
	(7, 2, 2, 4, NULL, NULL, 'regular', 'graded', '{"overall":"","strengths":["volatile 可见性/原子性辨析准确，能用交错时序说明丢失更新","synchronized 实例锁锁对象实例的判定全对，理解继承不改变锁对象","主动提出版本管理机制等思路，说明有独立思考"],"improvements":["概念题只答定义就停，必须答出适用条件与理由（如 notify 场景）","方法类题要先写返回值语义，再讲行为差异，别漏基础结论","后半程多题未作答，需保持完整作答，避免中途放弃","简答题要覆盖题面全部问点，逐问对应作答，别漏第二问"],"gradedAt":1793151061785}', NULL, '[{"points":["volatile · 可见性与原子性边界"],"angle":"两个线程读写同一 volatile long 为何仍可能读到中间值","tier":"基础","type":"概念辨析","weight":8},{"points":["CAS · 原理与三大问题"],"angle":"CAS 自旋开销大如何应对、何时应退回加锁","tier":"基础","type":"概念辨析","weight":8},{"points":["volatile · 典型使用场景"],"angle":"volatile 修饰的引用型对象，其字段改动能否被看到","tier":"基础","type":"概念辨析","weight":8},{"points":["synchronized · 三种使用形式与语义"],"angle":"继承关系下 synchronized 方法的互斥情况判断","tier":"基础","type":"概念辨析","weight":8},{"points":["synchronized · 等待唤醒与线程协作"],"angle":"生产者消费者中 notifyAll 与 notify 的取舍场景","tier":"基础","type":"概念辨析","weight":8},{"points":["ReentrantLock · tryLock 超时与可中断"],"angle":"tryLock 无参版与带超时版的返回值语义与用法区别","tier":"基础","type":"概念辨析","weight":8},{"points":["Condition · 多条件等待唤醒"],"angle":"Condition await 与 Object wait 的调用前提差异","tier":"基础","type":"概念辨析","weight":7},{"points":["volatile · 指令重排序与 happens-befo"],"angle":"happens-before 保证的可见性与时间先后的关系辨析","tier":"中档","type":"原理追问","weight":11},{"points":["synchronized · 锁升级过程"],"angle":"偏向锁与轻量级锁分别在什么竞争程度下被启用","tier":"中档","type":"原理追问","weight":11},{"points":["ReentrantLock · 与 synchronized","ReentrantLock · 公平锁与非公平锁","AtomicInteger · 常用方法与适用场景"],"angle":"热点计数器与慢操作临界区混合服务，三者如何分工取舍","tier":"大题","type":"场景应用","weight":23}]', 100, 1793150212552, 1793151078353),
	(8, 2, 2, 5, NULL, NULL, 'regular', 'graded', '{"overall":"整体概念方向基本正确，synchronized、volatile 定位和 CAS 思路抓得住，但作答偏简略、缺机制原因，个别点语义说反。多题未作答影响分数。建议练完整表述与分点作答，把「为什么」讲清楚。","strengths":["synchronized 实例方法锁 this 的机制答得准确完整","CAS 核心思想（比较+修改）和高并发自旋开销认识到位","volatile 可见性/禁止重排的定位准确，边界意识好"],"improvements":["结论对但缺细节：声明类型、位置、原因要答全","重排序后果描述要精确，别把语义说反","题面要求分点（读/写、各自作用）时务必分开作答","拼写与术语要规范（ReentrantLock）"],"gradedAt":1793155915655}', NULL, '[{"points":["ReentrantLock · 与 synchronized"],"angle":"一个锁对象需跨方法共享，选哪种并说明理由","tier":"基础","type":"概念辨析","weight":8},{"points":["volatile · 典型使用场景"],"angle":"延迟初始化的缓存引用，volatile 在这里解决什么问题","tier":"基础","type":"概念辨析","weight":8},{"points":["synchronized · 三种使用形式与语义"],"angle":"给一段含 synchronized 方法与代码块的代码，判断是否互斥","tier":"基础","type":"概念辨析","weight":8},{"points":["volatile · 可见性与原子性边界"],"angle":"volatile 修饰状态变量，读写分别有什么保证、边界在哪","tier":"基础","type":"概念辨析","weight":8},{"points":["ReentrantLock · 公平锁与非公平锁"],"angle":"线程等待时间差异大时，构造参数怎么选及理由","tier":"基础","type":"概念辨析","weight":8},{"points":["ReentrantLock · tryLock 超时与可中断"],"angle":"tryLock 与 lockInterruptibly 组合使用时如何写超时与中断处理","tier":"基础","type":"概念辨析","weight":8},{"points":["Condition · 多条件等待唤醒"],"angle":"单 Condition 与多 Condition 的选择依据与 signal 调用位置","tier":"基础","type":"概念辨析","weight":7},{"points":["volatile · 指令重排序与 happens-befo"],"angle":"volatile 写读如何与前后普通读写建立可见性关系","tier":"中档","type":"原理追问","weight":11},{"points":["synchronized · 锁升级过程"],"angle":"偏向锁撤销后可能转成什么状态，为什么会这样","tier":"中档","type":"原理追问","weight":11},{"points":["AtomicInteger · 常用方法与适用场景","CAS · 原理与三大问题","synchronized · 等待唤醒与线程协作"],"angle":"限流计数器场景：累加、竞争处理与超限后的线程协作取舍","tier":"大题","type":"场景应用","weight":23}]', 100, 1793155208191, 1793155934424),
	(9, 2, 2, 6, NULL, NULL, 'regular', 'graded', '{"overall":"本卷基础概念题掌握较好，synchronized 锁对象、非公平锁默认值、Condition 唤醒取舍等记忆点扎实；但 volatile 的 happens-before 语义答反，重排序环节没答准，暴露对内存可见性与指令重排机制理解偏浅。tryLock、unlock 位置等题答得不够完整具体。大题未作答，场景分析与方案取舍能力需要补。","strengths":["synchronized 三种写法的锁对象判断准确","ReentrantLock 默认非公平锁的性能取舍讲清了","Condition 的 signal/signalAll 取舍判断到位","count++ 非原子性及丢失更新的例子讲得清楚"],"improvements":["搞清 volatile 写读之间的 happens-before 关系","重排序的三个环节要记准，别答成允许重排的条件","答\"怎么写\"时直接给出代码或步骤，别只说原因","大题要练：先给结论，再分流程、问题、取舍展开"],"gradedAt":1793178918811}', NULL, '[{"points":["synchronized · 锁升级过程"],"angle":"偏向锁升级为轻量级锁后又遇竞争，后续怎么走","tier":"基础","type":"概念辨析","weight":8},{"points":["volatile · 典型使用场景"],"angle":"任务执行完成标志位场景下 volatile 是否够用","tier":"基础","type":"概念辨析","weight":8},{"points":["volatile · 可见性与原子性边界"],"angle":"多线程下 `volatile int count` 累加后读取结果对不对","tier":"基础","type":"概念辨析","weight":8},{"points":["synchronized · 三种使用形式与语义"],"angle":"一个类里三种 synchronized 写法混用，指出各自动的锁对象","tier":"基础","type":"概念辨析","weight":8},{"points":["ReentrantLock · 公平锁与非公平锁"],"angle":"new ReentrantLock() 默认是公平还是非公平，为什么这么定","tier":"基础","type":"概念辨析","weight":8},{"points":["ReentrantLock · tryLock 超时与可中断"],"angle":"tryLock 抢到锁后 finally 里 unlock 该怎么写才安全","tier":"基础","type":"概念辨析","weight":8},{"points":["Condition · 多条件等待唤醒"],"angle":"Condition 的 signal 与 signalAll 在何时选用哪个","tier":"基础","type":"概念辨析","weight":7},{"points":["volatile · 指令重排序与 happens-befo"],"angle":"重排序发生在哪些环节，为什么单线程感知不到","tier":"中档","type":"原理追问","weight":11},{"points":["ReentrantLock · 与 synchronized"],"angle":"要不要显式 unlock，忘写 unlock 会发生什么","tier":"中档","type":"原理追问","weight":11},{"points":["AtomicInteger · 常用方法与适用场景","CAS · 原理与三大问题","synchronized · 等待唤醒与线程协作"],"angle":"秒杀扣减库存：计数选原子类还是 CAS 自旋还是 wait/notify 协作，取舍怎么说","tier":"大题","type":"场景应用","weight":23}]', 100, 1793157029524, 1793178938281),
	(10, 2, 2, 7, NULL, NULL, 'regular', 'graded', '{"overall":"基础概念较扎实，锁升级、锁对象辨析、volatile 适用场景、公平锁等回答准确。主要短板：wait/notify 骨架的 wait 时机与 while 防虚假唤醒表述不完整，大题方案层面（分段/读写分离、长临界区降级）思路偏窄，未作答1题需补练。","strengths":["synchronized 锁对象与类锁实例锁辨析准确","volatile 可见性与非原子复合操作结论正确","公平/非公平锁差异与饥饿场景表述清晰","CAS 与 synchronized 失败分支对比到位"],"improvements":["wait/notify 骨架要写清 wait 时机与 while 判断","tryLock 超时实现类题型需完整作答","大题方案要展开分段、读写锁等落地方向","长临界区与高频计数的取舍需更具体"],"gradedAt":1793238586306}', NULL, '[{"points":["synchronized · 锁升级过程"],"angle":"偏、轻、重三态各自在什么条件下存在，简述为何需要升级","tier":"基础","type":"概念辨析","weight":8},{"points":["synchronized · 三种使用形式与语义"],"angle":"给一段多线程打印交错的代码，判哪些方法能并行执行","tier":"基础","type":"概念辨析","weight":8},{"points":["volatile · 可见性与原子性边界"],"angle":"volatile boolean 停止标志 vs volatile int 计数，各自能不能做到正确","tier":"基础","type":"概念辨析","weight":8},{"points":["synchronized · 等待唤醒与线程协作"],"angle":"两个线程交替打印奇偶数，wait/notify 怎么搭骨架","tier":"基础","type":"概念辨析","weight":8},{"points":["ReentrantLock · 公平锁与非公平锁"],"angle":"new ReentrantLock(true) 拿到什么锁，什么场景下这样构造","tier":"基础","type":"概念辨析","weight":8},{"points":["ReentrantLock · tryLock 超时与可中断"],"angle":"只给 tryLock 无参版，如何实现\"最多等 3 秒拿锁，拿不到就放弃\"","tier":"基础","type":"概念辨析","weight":8},{"points":["Condition · 多条件等待唤醒"],"angle":"一个锁下\"队列满/队列空\"两种等待，Condition 怎么分工","tier":"基础","type":"概念辨析","weight":7},{"points":["volatile · 指令重排序与 happens-befo"],"angle":"写 a=1 在 flag=true 之前，读方为何仍可能看到 flag 但读不到 a","tier":"中档","type":"原理追问","weight":11},{"points":["volatile · 典型使用场景"],"angle":"给三种候选场景（轮询停止位/累加器/对象发布），选哪些用 volatile 及理由","tier":"中档","type":"原理追问","weight":11},{"points":["AtomicInteger · 常用方法与适用场景","CAS · 原理与三大问题","ReentrantLock · 与 synchronized"],"angle":"一个排行榜计数服务里有热点计数与慢查询临界区，串联对比三种手段的分工、失败分支与取舍","tier":"大题","type":"场景应用","weight":23}]', 100, 1793236841504, 1793238612328),
	(11, 2, 2, 8, NULL, NULL, 'regular', 'graded', '{"overall":"","strengths":["第8题volatile引用答得较全面，可见性、重排、复合操作均覆盖","能识别并发下查询与扣款的重复执行现象","部分题能给出结论式回答，方向基本正确"],"improvements":["多题未作答，需坚持完成整卷，不留空白","概念需精确，如notify不释放锁、tryLock抛异常时未持锁","回答要覆盖题面全部子问，尤其原因类问题讲清机制","并发题要点出原子性/互斥缺失，不只描述现象"],"gradedAt":1793240863137}', NULL, '[{"points":["volatile · 指令重排序与 happens-befo"],"angle":"旧库读到写后值，编译器与处理器谁重排","tier":"基础","type":"概念辨析","weight":8},{"points":["synchronized · 三种使用形式与语义"],"angle":"修饰构造方法与静态工厂方法各锁什么","tier":"基础","type":"概念辨析","weight":8},{"points":["volatile · 可见性与原子性边界"],"angle":"volatile long 六十四位读写为何天然原子","tier":"基础","type":"概念辨析","weight":8},{"points":["synchronized · 等待唤醒与线程协作"],"angle":"notify 唤醒后仍需 while 判断条件的原因","tier":"基础","type":"概念辨析","weight":8},{"points":["ReentrantLock · 公平锁与非公平锁"],"angle":"吞吐优先的线程池用哪种构造参数及理由","tier":"基础","type":"概念辨析","weight":8},{"points":["ReentrantLock · tryLock 超时与可中断"],"angle":"tryLock 抛 InterruptedException 时该怎么处理","tier":"基础","type":"概念辨析","weight":8},{"points":["Condition · 多条件等待唤醒"],"angle":"await 返回后为何要重新检查条件再执行","tier":"基础","type":"概念辨析","weight":7},{"points":["volatile · 典型使用场景"],"angle":"volatile 修饰配置对象引用能否替代加锁更新","tier":"中档","type":"原理追问","weight":11},{"points":["synchronized · 锁升级过程"],"angle":"对象 hashcode 调用对偏向锁的影响是什么","tier":"中档","type":"原理追问","weight":11},{"points":["AtomicInteger · 常用方法与适用场景","CAS · 原理与三大问题","ReentrantLock · 与 synchronized"],"angle":"订单幂等扣款服务，三手段分工与失败处理取舍","tier":"大题","type":"场景应用","weight":23}]', 100, 1793238966136, 1793240885634),
	(12, 2, 2, 9, NULL, NULL, 'regular', 'graded', '{"overall":"基础概念题掌握较好，volatile 语义、synchronized 锁对象辨析、原子性判断答得准确清晰。主要短板在锁升级的不可逆原因描述不准，以及场景题中方案部分失分。建议加强锁状态迁移、同步方案选型的完整表述，避免只答现象不答机制。","strengths":["volatile 可见性与原子性辨析准确，i++、count++ 丢数机制清晰","synchronized 锁对象辨析到位，实例与静态方法互斥判断全对","DCL 三步创建与重排序根源表述准确，两题角度一致","check-then-act 竞态能举实例说明，根因判断正确"],"improvements":["锁升级不可逆原因需讲清 monitor 绑定后为何不能降级","轻量级锁不必然停留在重量级，状态迁移要准确","场景题第②问方案要展开落地要点，不要只给一句答案","复合字段更新的方案应明确加锁主体，避免方案含糊"],"gradedAt":1793326406490}', NULL, '[{"points":["volatile · 指令重排序与happens-befor"],"angle":"两线程读写顺序颠倒，何时可见性没保证","tier":"基础","type":"概念辨析","weight":8},{"points":["synchronized锁升级 · 单向不可逆与不可降级"],"angle":"锁升级为什么不可逆、何时只能升不能降","tier":"基础","type":"概念辨析","weight":8},{"points":["volatile · 禁止指令重排"],"angle":"volatile 如何阻止重排影响初始化结果","tier":"基础","type":"概念辨析","weight":8},{"points":["AQS · 核心思想与模板结构"],"angle":"AQS 解决什么问题、子类要实现哪两个方法","tier":"基础","type":"概念辨析","weight":8},{"points":["synchronized · 竞态条件导致重复扣款"],"angle":"扣款查库后操作为何仍会并发重复扣款","tier":"基础","type":"概念辨析","weight":8},{"points":["volatile · 不保证复合操作原子性"],"angle":"volatile 计数器并发自增结果为何偏小","tier":"基础","type":"概念辨析","weight":8},{"points":["ReentrantLock · tryLock 超时与可中断"],"angle":"带超时的 tryLock 与 lockInterruptibly 选型区别","tier":"基础","type":"概念辨析","weight":7},{"points":["volatile · 禁止指令重排序"],"angle":"单例双检锁里 volatile 为何不可省略","tier":"中档","type":"原理追问","weight":11},{"points":["synchronized · 方法锁与静态方法锁的对象差异"],"angle":"实例方法锁与静态方法锁互斥范围对比","tier":"中档","type":"原理追问","weight":11},{"points":["volatile · 指令重排序与 happens-befo","volatile · 典型使用场景","volatile · 可见性与原子性边界"],"angle":"配置更新与计数器场景：volatile 何时够、何时必须换手段","tier":"大题","type":"场景应用","weight":23}]', 100, 1793324945272, 1793326427017),
	(13, 2, 2, 10, 'final', NULL, NULL, 'graded', '{"overall":"基础概念题掌握扎实，synchronized 锁对象、CAS/ABA、wait-notify、volatile 防重排等高频点准确。短板集中在：简答题漏答题目明确要求的第二问（如 count++ 修正思路、AtomicLong 自增流程、可重入定义），以及大题里对 Condition/LongAdder 机制挖得不够深。建议养成逐问拆解题干的习惯，避免会而不全。","strengths":["synchronized 四种写法的锁对象与互斥关系判断全部准确","CAS/ABA、check-then-act 竞态、volatile 不保证复合操作原子性理解到位","wait-notify 唤醒语义与 while 重检条件答得完整","大题锁对象辨析（题18）三小问全部正确"],"improvements":["简答题要逐问核对题干，第二问（方案、API、定义）不要漏","AtomicLong 自增要写出「读-算-比较交换」自旋循环的完整流程","可重入定义需点明「同一线程重复获取同一把锁、计数配对解锁」","大题中 Condition await/signal 的锁语义与 LongAdder 适用场景需再强化"],"gradedAt":1793348338920}', NULL, '[{"points":["volatile · 指令重排序与 happens-befo"],"angle":"为何单例 DCL 里 instance 需要 volatile","tier":"基础","type":"概念辨析","weight":3},{"points":["CAS · 原理与三大问题"],"angle":"用 AtomicLong 计数举例讲 CAS 原理与 ABA 问题","tier":"基础","type":"概念辨析","weight":3},{"points":["synchronized · 三种使用形式与语义"],"angle":"修饰方法与修饰 this/class 代码块写法与锁对象","tier":"基础","type":"概念辨析","weight":3},{"points":["ReentrantLock · 与 synchronized"],"angle":"需要 tryLock 超时的库存扣减为何选 ReentrantLock","tier":"基础","type":"概念辨析","weight":3},{"points":["AQS · ReentrantLock 的加锁解锁流程"],"angle":"线程抢锁失败后在 AQS 队列里怎么走","tier":"基础","type":"概念辨析","weight":3},{"points":["happens-before 与 volatile 禁止重排"],"angle":"解释 happens-before 含义与 volatile 如何体现","tier":"基础","type":"概念辨析","weight":3},{"points":["synchronized · 锁对象辨析（实例/类/方法）"],"angle":"synchronized(this) 与 synchronized(X.class) 区别","tier":"基础","type":"概念辨析","weight":3},{"points":["原子性 · 复合操作不保证原子"],"angle":"check-then-act 两步操作为何要整体加锁","tier":"基础","type":"概念辨析","weight":3},{"points":["CAS · 适用场景选型（无锁 vs 加锁）"],"angle":"简单计数器场景怎么在 CAS 与锁之间选","tier":"基础","type":"概念辨析","weight":3},{"points":["CAS · 高竞争下的自旋与退化到锁"],"angle":"自旋迟迟不成功时如何判定该退回加锁","tier":"基础","type":"概念辨析","weight":3},{"points":["synchronized · 方法锁与静态方法锁的对象差异"],"angle":"静态 synchronized 方法与实例方法能否互斥","tier":"基础","type":"概念辨析","weight":3},{"points":["自增操作 · 非原子导致计数丢失"],"angle":"多线程下 count++ 计数少了的原因与修正","tier":"基础","type":"概念辨析","weight":3},{"points":["ReentrantLock · 可重入次数上限"],"angle":"可重入含义与锁持有过深的风险","tier":"基础","type":"概念辨析","weight":3},{"points":["synchronized · 竞态条件导致重复扣款"],"angle":"余额校验与扣减间无同步导致重复扣款定位","tier":"基础","type":"概念辨析","weight":3},{"points":["wait/notify · 唤醒后仍需竞争锁"],"angle":"被 notify 后线程为何还要再抢锁才返回","tier":"基础","type":"概念辨析","weight":3},{"points":["ReentrantLock · tryLock 超时与可中断","Condition · 多条件等待唤醒","ReentrantLock · 公平锁与非公平锁"],"angle":"限流闸机场景：await/signal 分工、tryLock 抢位、公平取舍","tier":"大题","type":"场景应用","weight":11},{"points":["volatile · 引用替换与对象字段修改的可见性差异","volatile · 指令重排序与happens-befor","volatile · 状态标志位典型用法"],"angle":"volatile 引用更新配置，何时够用何时要加锁","tier":"大题","type":"场景应用","weight":11},{"points":["synchronized · 实例锁与类锁的锁定对象","synchronized锁升级 · 升级后状态变化与降级","synchronized · 实例锁与类锁互斥关系"],"angle":"实例方法与静态方法并发调用时的锁竞争判断","tier":"大题","type":"场景应用","weight":11},{"points":["CAS · 自旋开销与高并发下的性能退化","volatile · DCL单例中的指令重排与对象逸出","synchronized锁升级 · 单向不可逆与不可降级"],"angle":"高并发下单例初始化与计数服务的手段取舍","tier":"大题","type":"场景应用","weight":11},{"points":["volatile · 保证可见性但不保证原子性","CAS · 高竞争下的适用性与放弃策略","volatile对引用替换与字段修改的差异"],"angle":"volatile 计数丢失现象与退化方案的取舍分析","tier":"大题","type":"场景应用","weight":11}]', 100, 1793327117075, 1793348357589),
	(14, 2, 4, 1, NULL, NULL, 'regular', 'graded', '{"overall":"基础概念整体扎实，主线流程、拒绝策略、队列分类与取值原因掌握较好。但ThreadFactory一题答非所问，Executors OOM风险归因错误，需区分Cached/Fixed的成因。命名类名与方法名需准确，避免凭印象拼写。","strengths":["提交任务的判断主线（核心→队列→最大→拒绝）准确且复述两次一致","拒绝策略触发时机与CallerRuns反压效果理解到位","任务队列三分类及对线程池行为的影响辨析清晰","CPU/IO密集型取值方向与原因都能说清"],"improvements":["ThreadFactory题易混入Executors风险，答题前先圈定问题对象","CachedThreadPool是SynchronousQueue+MAX线程，勿归为无界队列","类名/方法名需记准（RejectedExecutionException、newSingleThreadExecutor等）","拒绝策略可补一句任务最终去向，避免漏答尾问"],"gradedAt":1793609789610}', NULL, '[{"points":["线程池工作流程 · 主干执行链路"],"angle":"提交一个任务后按什么顺序被处理","tier":"基础","type":"概念辨析","weight":10},{"points":["拒绝策略 · AbortPolicy"],"angle":"默认拒绝策略抛什么、任务去哪了","tier":"基础","type":"概念辨析","weight":10},{"points":["四种内置线程池 · 逐一识别"],"angle":"给场景选对应的 Executors 工厂方法","tier":"基础","type":"概念辨析","weight":9},{"points":["拒绝策略 · CallerRunsPolicy"],"angle":"满了之后任务由谁执行、有何效果","tier":"基础","type":"概念辨析","weight":9},{"points":["线程池参数 · workQueue"],"angle":"任务队列分哪几类、各有何特点","tier":"基础","type":"概念辨析","weight":9},{"points":["线程池参数 · handler"],"angle":"拒绝策略何时触发、作用是什么","tier":"基础","type":"概念辨析","weight":9},{"points":["自定义线程池 · 线程数怎么定"],"angle":"CPU 密集与 IO 密集线程数怎么取","tier":"基础","type":"概念辨析","weight":9},{"points":["自定义线程池 · 自定义线程工厂与命名规范"],"angle":"为什么要自己写 ThreadFactory","tier":"基础","type":"概念辨析","weight":9},{"points":["线程池 · 核心工作流程"],"angle":"核心线程→队列→非核心→拒绝的推进顺序","tier":"中档","type":"原理追问","weight":13},{"points":["四种内置线程池 · 为什么不推荐直接用 Executors 创建"],"angle":"阿里手册为何要求手写 ThreadPoolExecutor","tier":"中档","type":"原理追问","weight":13}]', 100, 1793608849752, 1793609894979),
	(15, 2, 4, 2, NULL, NULL, 'regular', 'graded', '{"overall":"基础概念记忆较扎实，八大参数、拒绝策略、Executors 风险等结论基本准确。但答题常只答一半：题面问『含义/为什么/影响什么行为』时，多停在名称复述或结论，缺少机制解释；大题存在跑题，答了通用知识却未针对给定的队列选型与拒绝处置取舍展开。","strengths":["七大参数、四种拒绝策略名称与行为记忆准确","准确指出 Executors 默认配置不可控的风险并给出正确结论","拒绝策略的适用场景判断到位，大题实得分明显高于表现分"],"improvements":["题面问『含义』或『为什么』时，必须写出机制而非只复述名词","大题先读清子问题，逐问针对场景作答，避免堆通用知识","配置类问题要给出参数取值依据（如 QPS×耗时推算并发）","自定义线程池的好处要答全，不止命名，还有属性与异常统一治理"],"gradedAt":1793612095325}', NULL, '[{"points":["自定义线程池 · 为什么要自定义"],"angle":"新接手项目用Executors创建，怎么向同事说明必须改造","tier":"基础","type":"概念辨析","weight":8},{"points":["线程池七大参数 · 逐个含义"],"angle":"面试要求七个参数逐个说出含义与作用","tier":"基础","type":"概念辨析","weight":8},{"points":["自定义线程池 · 参数怎么定"],"angle":"给一个新接口场景，说明要配哪几个参数定值","tier":"基础","type":"概念辨析","weight":8},{"points":["线程池参数 · corePoolSize 与 maximumPoolSize"],"angle":"两个参数含义与日常配置差异简答","tier":"基础","type":"概念辨析","weight":8},{"points":["自定义线程池 · 为什么不用 Executors"],"angle":"阿里规约这条具体禁止什么、要求怎么做","tier":"基础","type":"概念辨析","weight":8},{"points":["线程池队列类型 · 三种典型选择"],"angle":"有界、无界、同步移交三种队列怎么选怎么用","tier":"基础","type":"概念辨析","weight":8},{"points":["自定义线程池 · 自定义线程工厂与命名规范"],"angle":"自定义ThreadFactory能带来哪些排查与治理上的好处","tier":"基础","type":"概念辨析","weight":7},{"points":["拒绝策略 · 四种内置策略"],"angle":"四种内置拒绝策略各自怎么处置被拒任务","tier":"中档","type":"原理追问","weight":11},{"points":["线程池 · 为什么要用"],"angle":"直接new Thread有什么问题，线程池解决什么","tier":"中档","type":"原理追问","weight":11},{"points":["线程池参数 · workQueue","线程池参数 · handler","拒绝策略 · AbortPolicy"],"angle":"电商下单高峰场景中队列选型与被拒任务处置的联动取舍","tier":"大题","type":"场景应用","weight":23}]', 100, 1793610427343, 1793612115030),
	(16, 2, 4, 4, NULL, NULL, 'regular', 'graded', '{"overall":"线程池主干流程与核心机制掌握扎实，任务流转顺序、配置风险点答得准。但论述常停在结论层面，缺少机制细节与场景展开，多个问点只答一半；对无界队列代价、线程复用原理等追问回答不完整。需加强按问点逐条作答的完整性。","strengths":["任务流转顺序与分支判断掌握准确","能区分 Fixed/Cached 两类内置线程池隐患","自定义拒绝策略的兜底落库思路清晰","核心/最大线程数按 CPU/IO 密集分配正确"],"improvements":["按问点逐条作答，问什么答什么，勿只答一半","结论之外补充机制细节，如前缀在 thread dump 的作用","场景题需展开适用条件与边界，不能只给方向","无界队列、线程复用等追问要覆盖全部代价与原理"],"gradedAt":1793692387772}', NULL, '[{"points":["同步移交队列SynchronousQueue · 特性与适用场景"],"angle":"任务不排队直接给线程，何时用","tier":"基础","type":"概念辨析","weight":8},{"points":["四种内置线程池 · newFixedThreadPool 的队列陷阱"],"angle":"固定线程数+无界队列，已知并发量场景","tier":"基础","type":"概念辨析","weight":8},{"points":["串联 · 一次线程池 OOM 排查到参数重建"],"angle":"现场OOM堆任务：现象→原因→重建有界池","tier":"基础","type":"概念辨析","weight":8},{"points":["四种内置线程池 · newCachedThreadPool 的线程爆炸"],"angle":"短平快任务适合，线程数为何会爆","tier":"基础","type":"概念辨析","weight":8},{"points":["线程池 · submit 与 execute 区别"],"angle":"返回值与异常处理差异，怎么选","tier":"基础","type":"概念辨析","weight":8},{"points":["自定义线程池 · 队列容量与非核心线程创建的平衡"],"angle":"队列满才建非核心线程，容量怎么权衡","tier":"基础","type":"概念辨析","weight":8},{"points":["拒绝策略 · 自定义拒绝策略"],"angle":"自定义拒绝类里该做什么、怎么兜底","tier":"基础","type":"概念辨析","weight":7},{"points":["线程池 · 无界队列适用场景"],"angle":"无界队列何时用、代价是什么","tier":"中档","type":"原理追问","weight":11},{"points":["线程池参数 · threadFactory命名与问题定位"],"angle":"线程名前缀如何帮定位线上问题","tier":"中档","type":"原理追问","weight":11},{"points":["线程池 · 为什么要用","线程池 · 核心工作流程","线程池参数 · workQueue"],"angle":"同一场景：复用→提交推进→队列满后走向","tier":"大题","type":"场景应用","weight":23}]', 100, 1793691140938, 1793692417384),
	(17, 2, 5, 1, NULL, NULL, 'regular', 'graded', '{"overall":"本卷10题仅作答3题，覆盖率低是主要问题。已答题目中能抓住核心结论（构造器循环依赖、JDK/CGLIB代理选择、@Lazy作用），但普遍停在结论层面，缺少机制推演与对比分析，第②问常被遗漏。建议先保证每题都作答，再练习把''为什么''讲透。","strengths":["代理方式结论判断准确，JDK与CGLIB对应关系无误","构造器注入的final不可变性把握到位","@Lazy加在Bean声明上的含义理解正确"],"improvements":["务必每题都作答，空题是最大失分点","答题要覆盖小问，勿漏掉②③等后半部分","结论后要补机制推演，避免同义反复","对比类问题要分点讲清两侧行为差异"],"gradedAt":1793696616941}', NULL, '[{"points":["Bean生命周期 · 主干流程"],"angle":"按创建一个 Bean 的顺序说清四大阶段","tier":"基础","type":"概念辨析","weight":10},{"points":["AOP · 核心概念与切点"],"angle":"写一个 @Aspect 切面例子并说明各注解含义","tier":"基础","type":"概念辨析","weight":10},{"points":["循环依赖 · 三级缓存机制"],"angle":"A setter 依赖 B、B setter 依赖 A，Spring 怎么解决","tier":"基础","type":"概念辨析","weight":9},{"points":["AOP · 失效场景与原理"],"angle":"内部方法调用自调用时切面为何不生效","tier":"基础","type":"概念辨析","weight":9},{"points":["循环依赖 · 构造器注入为何不行"],"angle":"构造器相互注入为什么会启动报错","tier":"基础","type":"概念辨析","weight":9},{"points":["初始化与销毁 · 回调方式"],"angle":"如何在 Bean 创建后和容器关闭时执行逻辑","tier":"基础","type":"概念辨析","weight":9},{"points":["Bean延迟加载 · @Lazy"],"angle":"什么场景下给 Bean 或注入点加 @Lazy","tier":"基础","type":"概念辨析","weight":9},{"points":["Bean作用域 · singleton与prototype"],"angle":"怎么声明 Bean 不被共享、每次拿到新对象","tier":"基础","type":"概念辨析","weight":9},{"points":["IoC/DI · 概念与两种注入方式"],"angle":"为什么推荐构造器注入而不是 setter 注入","tier":"中档","type":"原理追问","weight":13},{"points":["动态代理 · JDK与CGLIB"],"angle":"Spring AOP 默认用哪种代理、两者差异","tier":"中档","type":"原理追问","weight":13}]', 100, 1793696207241, 1793696635469),
	(18, 2, 5, 2, NULL, NULL, 'regular', 'graded', '{"overall":"本卷覆盖 IOC、循环依赖、AOP 代理、Bean 生命周期等高频点，基础题答得较扎实，final 与不可变、组件扫描拿分较高。薄弱处集中在：审题不细（AOP 失效场景答成被排除的 this 调用）、概念表述不严谨（afterPropertiesSet 与 InitializingBean 关系）、场景大题维度覆盖不全。三级缓存与 AOP 术语题未作答，需补练。","strengths":["final 与不可变辨析准确，举 String 例子恰当","组件扫描与默认扫描包理解到位","@Lazy、构造器注入差异有一定认识","Bean 生命周期回调顺序基本把握"],"improvements":["严格审题，先看清题面排除项再作答","区分 InitializingBean 接口与 afterPropertiesSet 方法","大题按维度逐条覆盖，别漏「依赖不可用」这类视角","三级缓存、切点/连接点等术语题要完整作答不空题"],"gradedAt":1793778116653}', NULL, '[{"points":["Bean生命周期 · 主干流程"],"angle":"属性填充阶段没拿到依赖会怎样","tier":"基础","type":"概念辨析","weight":8},{"points":["AOP · 失效场景与原理"],"angle":"同类调用外的其他切面失效场景举例","tier":"基础","type":"概念辨析","weight":8},{"points":["循环依赖 · 破坏方式与现状"],"angle":"改用构造器注入后如何打破互相依赖","tier":"基础","type":"概念辨析","weight":8},{"points":["构造器注入 · 不可变性优势"],"angle":"用final字段说明不可变与不可变的好处","tier":"基础","type":"概念辨析","weight":8},{"points":["动态代理 · JDK与CGLIB选型"],"angle":"无接口类为何必须用CGLIB及配置开关","tier":"基础","type":"概念辨析","weight":8},{"points":["初始化与销毁 · 回调方式"],"angle":"@PostConstruct与InitializingBean并存执行顺序","tier":"基础","type":"概念辨析","weight":8},{"points":["Bean配置 · 组件扫描与注册方式"],"angle":"@ComponentScan指定扫描包的写法与作用","tier":"基础","type":"概念辨析","weight":7},{"points":["循环依赖 · 三级缓存机制"],"angle":"三级缓存各自在什么时候被使用","tier":"中档","type":"原理追问","weight":11},{"points":["AOP · 核心概念与切点"],"angle":"解释切点与连接点的区别及各配哪注解","tier":"中档","type":"原理追问","weight":11},{"points":["IoC/DI · 概念与两种注入方式","Bean延迟加载 · @Lazy"],"angle":"注册慢启动服务时注入方式与@Lazy取舍","tier":"大题","type":"场景应用","weight":23}]', 100, 1793762027526, 1793778135869),
	(19, 2, 5, 3, NULL, NULL, 'regular', 'graded', '{"overall":"本卷基础概念多数能说对方向，但普遍缺细节和完整度：第1题只列四个词、第2/3/8题空答，第9题未写示例。已作答的循环依赖、AOP失效点质量尚可，大题能给出思路但深度不足，需补齐答点完整度。","strengths":["@Autowired消歧与构造器循环依赖的成因抓住核心","AOP失效场景给出this自调用和手动new两条真实高频","末题能用@Lazy权衡启动速度与首访延迟","循环依赖能指出缺少中间态Bean这一本质"],"improvements":["按序答题并写全每步细节，避免空答丢分","术语解释要给完整定义，并按题面补代码示例","循环依赖要讲清三级缓存分工与暴露顺序","大题分点作答并补边界与风险，别只给结论"],"gradedAt":1793779954634}', NULL, '[{"points":["Bean生命周期 · 主干流程"],"angle":"一个Bean被new出来后到可使用，中间经历哪几大步，顺序如何","tier":"基础","type":"概念辨析","weight":8},{"points":["AOP · 与生命周期的关系"],"angle":"Bean的代理对象是在生命周期哪个环节生成的，与普通Bean有何不同","tier":"基础","type":"概念辨析","weight":8},{"points":["Bean作用域 · singleton与prototype"],"angle":"singleton与prototype在容器里表现有何差异，用什么注解或属性声明","tier":"基础","type":"概念辨析","weight":8},{"points":["依赖注入 · @Autowired装配规则"],"angle":"@Autowired默认按类型还是按名称匹配，多个候选Bean时怎么消歧","tier":"基础","type":"概念辨析","weight":8},{"points":["循环依赖 · 构造器注入无法解决循环依赖"],"angle":"为什么构造器注入形成循环时启动报错，怎么从注入方式上规避","tier":"基础","type":"概念辨析","weight":8},{"points":["循环依赖 · 成因与检测"],"angle":"什么情况才构成循环依赖，Spring怎么判定并报错","tier":"基础","type":"概念辨析","weight":8},{"points":["AOP · 失效场景与原理"],"angle":"Bean被代理后还能保证切面生效的条件，哪些改法会让增强悄悄丢失","tier":"基础","type":"概念辨析","weight":7},{"points":["循环依赖 · 三级缓存机制"],"angle":"单例setter循环依赖时，对象在三级缓存间怎么流转完成提前暴露","tier":"中档","type":"原理追问","weight":11},{"points":["AOP · 核心概念与切点"],"angle":"切面、通知、切点、连接点四个术语各指什么，写个最小切面对应起来","tier":"中档","type":"原理追问","weight":11},{"points":["IoC/DI · 概念与两种注入方式","Bean延迟加载 · @Lazy","Bean配置 · 组件扫描与注册方式"],"angle":"新服务模块上线慢，串联讲DI选型、@Lazy延迟与扫描装配的取舍","tier":"大题","type":"场景应用","weight":23}]', 100, 1793778821636, 1793779960467),
	(20, 2, 5, 4, NULL, NULL, 'concept', 'graded', '{"overall":"本卷 25 题全为基础概念题，平均得分偏低。你对循环依赖的三级缓存流程、AOP 自调用失效、JDK 与 CGLIB 的选型这几块掌握较稳；但概念表述常停在方向正确，缺少精确术语与关键细节，且对题面的多问常有漏答，是失分主因。","strengths":["三级缓存与循环依赖的创建流程能完整口述，链条准确","能准确指出AOP自调用失效根因是this不经过代理","JDK与CGLIB的选型依据（是否实现接口）答得干净"],"improvements":["题面多问要逐条对齐作答，避免只答一半被扣分","概念要给出准确术语与阶段名称，别只停在方向对","注解名与拼写要准确，如@PostConstruct、@Pointcut","补充@Bean适用第三方类、@Lazy可加注入点等场景"],"gradedAt":1793848348777}', NULL, '[{"points":["循环依赖 · 三级缓存机制"],"angle":"setter 循环依赖中，三个缓存各存什么、按什么顺序查","tier":"基础","type":"概念辨析","weight":4},{"points":["Bean作用域 · singleton与prototype"],"angle":"给两个 Bean，判断注入到别的 Bean 里拿到的是否同一对象","tier":"基础","type":"概念辨析","weight":4},{"points":["@Lazy · 延迟加载注入点"],"angle":"@Lazy 标在 Bean 类和标在注入点上，效果差别","tier":"基础","type":"概念辨析","weight":4},{"points":["依赖注入 · @Lazy延迟加载解决循环依赖"],"angle":"构造器互相依赖时，在其中一个参数上加 @Lazy 为什么能启动","tier":"基础","type":"概念辨析","weight":4},{"points":["AOP · 内部方法自调用导致切面失效"],"angle":"给出一个提升事务/日志失效的类，让判断原因","tier":"基础","type":"概念辨析","weight":4},{"points":["AOP · 与生命周期的关系"],"angle":"结合四阶段说明代理对象与普通对象可见时的先后","tier":"基础","type":"概念辨析","weight":4},{"points":["AOP · @Aspect/@Pointcut/@JoinPoint注解"],"angle":"不看示例，独立写出一个统计方法耗时的切面骨架","tier":"基础","type":"概念辨析","weight":4},{"points":["循环依赖 · 构造器注入无法解决"],"angle":"为什么不能先造半成品再回填？与 setter 时机对照答","tier":"基础","type":"概念辨析","weight":4},{"points":["Bean生命周期 · @PostConstruct/@PreDestroy注解初"],"angle":"在 init 里连数据库、在 destroy 里关闭资源，该用哪两个注解","tier":"基础","type":"概念辨析","weight":4},{"points":["AOP · JDK动态代理基于接口实现"],"angle":"目标类没接口时 JDK 代理会怎样，怎么判断用哪种","tier":"基础","type":"概念辨析","weight":4},{"points":["@Autowired · 注入点与循环依赖"],"angle":"把字段注入改成构造器注入后启动报错，从时机上解释","tier":"基础","type":"概念辨析","weight":4},{"points":["Bean后处理器 · BeanPostProcessor"],"angle":"自定义一个 BPP，说明它在哪个阶段对 Bean 做了什么处理","tier":"基础","type":"概念辨析","weight":4},{"points":["AOP失效 · 同类内部this调用"],"angle":"同一类里方法 A 调方法 B，B 上的通知为何没执行、怎么改","tier":"基础","type":"概念辨析","weight":4},{"points":["Bean生命周期 · 实例化与初始化顺序"],"angle":"构造器、属性注入、@PostConstruct 三者执行先后排序并说明","tier":"基础","type":"概念辨析","weight":4},{"points":["依赖注入 · @Primary与@Qualifier消歧"],"angle":"两个同类型 Bean，两种消歧注解分别用在什么位置","tier":"基础","type":"概念辨析","weight":4},{"points":["Aware接口 · 常见接口"],"angle":"业务 Bean 需要拿到 ApplicationContext，用什么方式、何时被调用","tier":"基础","type":"概念辨析","weight":4},{"points":["循环依赖 · 构造器注入为何不行"],"angle":"属性注入能解、构造器注入报错，从何时产生状态差异解释","tier":"基础","type":"概念辨析","weight":4},{"points":["AOP · 核心概念与切点"],"angle":"给一句 execution 表达式，让其判断能切入哪些方法","tier":"基础","type":"概念辨析","weight":4},{"points":["初始化与销毁 · 回调方式"],"angle":"用注解写一个含初始化和销毁逻辑的 Bean，说明两个方法何时被调用","tier":"基础","type":"概念辨析","weight":4},{"points":["IoC/DI · 概念与两种注入方式"],"angle":"给一个依赖必填/可选的类，让其选注入方式并说理由","tier":"基础","type":"概念辨析","weight":4},{"points":["Bean延迟加载 · @Lazy"],"angle":"@Lazy 与 prototype 的区别，各自适合什么对象","tier":"基础","type":"概念辨析","weight":4},{"points":["动态代理 · JDK与CGLIB"],"angle":"给一个有接口一个无接口的类，说 AOP 后拿到的对象是什么类型","tier":"基础","type":"概念辨析","weight":4},{"points":["循环依赖 · 破坏方式与现状"],"angle":"不改注入方式，怎么重构拆掉 A 与 B 的属性循环","tier":"基础","type":"概念辨析","weight":4},{"points":["Bean配置 · 组件扫描与注册方式"],"angle":"@Component 与 @Bean 两种注册方式的区别与选择","tier":"基础","type":"概念辨析","weight":4},{"points":["AOP · 失效场景与原理"],"angle":"一个类里两个增强方法互相调用，判断哪些增强会丢","tier":"基础","type":"概念辨析","weight":4}]', 100, 1793784323255, 1793848354673),
	(21, 2, 5, 5, NULL, NULL, 'regular', 'graded', '{"overall":"本卷以 IOC、生命周期、AOP 为主，整体基础概念多数能答对，主干顺序与常见注解掌握尚可。薄弱点集中在三处：作用域选型、分点作答完整度、AOP 代理生成的时机与机制；作答常只给结论，缺少机制说明。","strengths":["Bean 生命周期主干顺序（实例化→属性填充→初始化）记忆准确","多候选注入 @Primary 与 @Qualifier、@Conditional 条件装配答对","JDK 与 CGLIB 代理的接口与继承差异能说清"],"improvements":["按题面分点作答，避免只答一个环节（销毁流程、Aware 接口）","作用域按请求与会话边界区分 request 与 prototype","AOP 增强补上 BeanPostProcessor 生成代理的时机","作答不要反问题目，理清字段注入与 setter 注入的差异"],"gradedAt":1793863420632}', NULL, '[{"points":["Bean生命周期 · 实例化与初始化顺序"],"angle":"用一句执行过程描述对象何时被创建、何时做准备","tier":"基础","type":"概念辨析","weight":8},{"points":["Spring 作用域 · prototype 适用场景"],"angle":"给有状态对象场景，判断该用哪种作用域及原因","tier":"基础","type":"概念辨析","weight":8},{"points":["Spring 注入方式 · 构造器注入与 setter 注入选型"],"angle":"给必需依赖与可选依赖两例，分别选注入方式","tier":"基础","type":"概念辨析","weight":8},{"points":["Aware接口 · 常见接口"],"angle":"列举两个常用Aware接口及各自能拿到什么资源","tier":"基础","type":"概念辨析","weight":8},{"points":["Bean后处理器 · BeanPostProcessor"],"angle":"说明它对容器内Bean统一做增强的整体能力定位","tier":"基础","type":"概念辨析","weight":8},{"points":["Bean生命周期 · 主干流程"],"angle":"给一个Bean，说出销毁前容器做哪几件核心事","tier":"基础","type":"概念辨析","weight":8},{"points":["@Autowired · 注入点与循环依赖"],"angle":"同一依赖分别用字段/setter注入，说明时间点差异","tier":"基础","type":"概念辨析","weight":7},{"points":["Spring 注入注解 · @Qualifier 与 @Conditional "],"angle":"同类型多Bean时如何指定，及按条件决定是否注册","tier":"中档","type":"原理追问","weight":11},{"points":["AOP 切入点表达式 · execution 通配匹配"],"angle":"给含*与..的表达式，判断能匹配哪些方法","tier":"中档","type":"原理追问","weight":11},{"points":["AOP · 核心概念与切点","AOP · 与生命周期的关系","动态代理 · JDK与CGLIB"],"angle":"下单业务需加日志与事务，串起切面、代理生成时机与代理方式选择","tier":"大题","type":"场景应用","weight":23}]', 100, 1793861679023, 1793863425284),
	(22, 2, 6, 1, NULL, NULL, 'concept', 'answering', NULL, NULL, '[{"points":["配置加载 · 多环境与优先级"],"angle":"如何用 profile 文件切换开发/测试环境","tier":"基础","type":"概念辨析","weight":5},{"points":["自动配置 · 条件注解"],"angle":"给三个常用条件注解各举一个使用场景","tier":"基础","type":"概念辨析","weight":5},{"points":["Starter · 是什么与约定"],"angle":"Starter 由哪两部分组成，命名怎么约定","tier":"基础","type":"概念辨析","weight":5},{"points":["自动配置 · 基本原理"],"angle":"@SpringBootApplication 拆开看，自动配置靠哪个注解生效","tier":"基础","type":"概念辨析","weight":5},{"points":["依赖注入 · @Autowired 与 @Resource"],"angle":"两者注入来源有何不同，按名还是按类型","tier":"基础","type":"概念辨析","weight":5},{"points":["过滤器 · 基本概念与用法"],"angle":"Filter 属哪个规范，写一个并说明如何注册","tier":"基础","type":"概念辨析","weight":5},{"points":["参数绑定 · 常用注解"],"angle":"三个注解分别从请求哪里取值","tier":"基础","type":"概念辨析","weight":5},{"points":["配置绑定 · @ConfigurationProperties"],"angle":"把一组配置绑到对象上，需注意什么","tier":"基础","type":"概念辨析","weight":5},{"points":["过滤器与拦截器 · 区别与选型"],"angle":"两者所属体系与执行先后如何，怎么选","tier":"基础","type":"概念辨析","weight":5},{"points":["统一异常处理 · @ControllerAdvice"],"angle":"全局异常处理类由哪两个注解配合完成","tier":"基础","type":"概念辨析","weight":5},{"points":["拦截器 · 基本概念与用法"],"angle":"HandlerInterceptor 三个方法各在何时执行","tier":"基础","type":"概念辨析","weight":5},{"points":["Starter · 自定义步骤"],"angle":"从建工程到能被引入，说清自定义 Starter 步骤","tier":"基础","type":"概念辨析","weight":5},{"points":["Bean 注册 · @Component 与 @Bean"],"angle":"两者标注位置与适用场景有何不同","tier":"基础","type":"概念辨析","weight":5},{"points":["Starter · 开箱即用的设计"],"angle":"举一个官方 Starter 说明它省了什么","tier":"基础","type":"概念辨析","weight":5},{"points":["AOP · 基本概念与场景"],"angle":"哪些横切逻辑适合用 AOP 抽出来","tier":"基础","type":"概念辨析","weight":5},{"points":["自动配置 · 排除与调试"],"angle":"如何排除某个自动配置类，写在哪里","tier":"基础","type":"概念辨析","weight":5},{"points":["请求处理 · 核心流程"],"angle":"一个请求从进入到 Controller 经过谁分发","tier":"基础","type":"概念辨析","weight":5},{"points":["过滤器与拦截器 · 典型应用"],"angle":"各举两个典型用途并说明放在哪层","tier":"基础","type":"概念辨析","weight":5},{"points":["统一响应与跨域 · 常用配置"],"angle":"用配置类统一设置跨域，怎么写","tier":"基础","type":"概念辨析","weight":5},{"points":["自动配置 · 加载与顺序"],"angle":"自动配置类从依赖 jar 的哪个文件被读到","tier":"基础","type":"概念辨析","weight":5}]', 100, 1793944278032, NULL);

-- 导出  表 public.practice 结构
CREATE TABLE IF NOT EXISTS "practice" (
	"id" BIGINT NOT NULL,
	"user_id" BIGINT NOT NULL,
	"stage_id" BIGINT NULL DEFAULT NULL,
	"mode" VARCHAR(16) NULL DEFAULT NULL,
	"topic" TEXT NULL DEFAULT NULL,
	"scope_mode" VARCHAR(16) NULL DEFAULT NULL,
	"scope_text" TEXT NULL DEFAULT NULL,
	"level" VARCHAR(16) NULL DEFAULT NULL,
	"intensity" VARCHAR(16) NULL DEFAULT NULL,
	"paper_size" INTEGER NULL DEFAULT NULL,
	"review" BOOLEAN NOT NULL DEFAULT false,
	"status" VARCHAR(16) NULL DEFAULT NULL,
	"memory_json" TEXT NULL DEFAULT NULL,
	"notes_text" TEXT NULL DEFAULT NULL,
	"notes_updated_at" BIGINT NULL DEFAULT NULL,
	"digest_json" TEXT NULL DEFAULT NULL,
	"created_at" BIGINT NOT NULL,
	"updated_at" BIGINT NOT NULL,
	"completed_at" BIGINT NULL DEFAULT NULL,
	PRIMARY KEY ("id"),
	CONSTRAINT "practice_updated_at_not_null1" CHECK (updated_at IS NOT NULL),
	CONSTRAINT "practice_created_at_not_null1" CHECK (created_at IS NOT NULL),
	CONSTRAINT "practice_review_not_null1" CHECK (review IS NOT NULL),
	CONSTRAINT "practice_user_id_not_null1" CHECK (user_id IS NOT NULL),
	CONSTRAINT "practice_id_not_null1" CHECK (id IS NOT NULL)
)
CREATE INDEX "idx_practice_user_stage" ON "" ("user_id", "stage_id");
CREATE INDEX "idx_practice_stage" ON "" ("stage_id");;

