INSERT INTO "practice" ("id", "user_id", "stage_id", "mode", "topic", "scope_mode", "scope_text", "level", "intensity", "paper_size", "review", "status", "memory_json", "notes_text", "notes_updated_at", "digest_json", "created_at", "updated_at", "completed_at") VALUES
	(1, 2, 1, 'interview', 'java集合高频面试题', 'topic', NULL, 'mid', 'quick', 10, 'false', 'active', '{"mastered":["fail-fast机制与CME原因","迭代器remove安全删除","ArrayList非线程安全与丢失数据","CopyOnWriteArrayList适用场景","Collection存单元素Map存键值对","List/Set/Queue子接口特点","put返回旧值语义","equals相等时hashCode必须相等"],"weakPoints":["迭代器remove用法（未作答需重练）","Collection与Map关系表述不完整","synchronizedList与CopyOnWrite取舍","HashMap线程不安全的具体表现","HashSet判重依据hashCode+equals","同步计数场景应用ConcurrentHashMap","HashMap阈值扩容触发说明"],"misconceptions":["把HashSet判重说成仅基于equals","计数并发场景误选Hashtable"],"nextFocus":["HashMap扩容阈值与负载因子计算","ConcurrentHashMap计数与get/put并发","HashSet判重与equals/hashCode一致性"],"coverage":["ArrayList插入复杂度","ArrayList扩容倍数","Java集合接口体系","常见集合实现类","Comparable与Comparator","ArrayList特性与适用场景","HashSet去重","LinkedList插入删除","HashMap的equals判定","hashCode与equals一致性","Hashtable线程安全与性能","ConcurrentHashMap并发特性","ArrayList数组存储结构","数组下标随机访问","ArrayList中间增删O(n)","ArrayList扩容触发时机","Collections.synchronized","CopyOnWriteArrayList写时复制","HashMap底层结构与树化","HashMap null键值支持","HashMap线程安全性","fail-fast与ConcurrentModi","Iterator边遍历边删除","ArrayList并发写丢数据","Collection与Map关系","List/Set/Queue子接口","线程安全List选型","Map.put/get/putIfAbsent返","HashSet判重依据","HashMap阈值与负载因子","URL去重计数场景选型"],"updatedAt":1793083231785}', '', NULL, '{"overview":"已练2卷20题，均分70.2。覆盖集合体系、ArrayList增删与扩容、fail-fast与Iterator删除、HashMap结构与key约定、HashSet去重、并发集合选型。基础概念尚可但常漏\"为什么\"，中档原理细节易错，equals/hashCode判据答错过。","level":"基础中档尚可，原理细节与解释深度待补","coveredAreas":["集合接口体系","ArrayList增删与","fail-fast与迭代","HashMap结构与ke","HashSet去重判据","Map常用方法返回值","并发集合选型"],"uncoveredAreas":["LinkedList机制","HashMap扩容与负载","HashMap遍历与fa","TreeMap与有序Ma","队列与Deque","集合序列化与拷贝"],"updatedAt":1793083231785}', 1793073156389, 1793083231785, NULL),
	(2, 2, 1, 'interview', 'java多线程锁机制(volatile，CAS，synchronized锁升级，AQS，Lock等等)高频面试题', 'topic', NULL, 'mid', 'quick', 10, 'false', 'active', '{"mastered":["volatile禁止重排序保DCL安全","synchronized实例锁与类锁区分","volatile引用赋值可见性与原子性边界","check-then-act竞态条件现象描述","i++复合操作volatile不保原子性","ReentrantLock tryLock超时获取锁","wait被唤醒后需重新抢锁","count++丢失更新原因与修正"],"weakPoints":["AQS抢锁失败后自旋入队阻塞流程","happens-before定义与volatile体现","可重入语义限定与持锁过深风险","check-then-act为何整体加锁原因","Condition await释放锁与signal入队语义","synchronized锁升级各阶段触发条件","可中断锁获取与超时锁差异","Condition.await返回后while重检"],"misconceptions":["轻量锁释放后永久保持重量级(错)","notify会释放锁(持有到退出同步块)","tryLock中断时未获锁不能unlock(反了)","happens-before不等于执行时间先后(是可见性序)"],"nextFocus":["补答AQS抢锁失败后自旋/入队/阻塞顺序","补答happens-before定义与volatile如何体","补答Condition await释放锁与signal只是入"],"coverage":["volatile 不保证原子性","volatile 状态标志位","CAS 原理与 ABA 问题","ReentrantLock 适用场景","synchronized 锁升级与触发条件","AtomicInteger 原子类","wait/notify 调用条件","公平锁与非公平锁","DCL 单例与 volatile","synchronized 锁对象辨析","volatile不保证原子性","volatile状态标志位","CAS原理与ABA问题","ReentrantLock适用场景","synchronized锁升级与触发条件","AtomicInteger原子类","wait/notify调用条件","DCL单例与volatile","synchronized锁对象辨析","无锁与加锁适用场景对比","原子类常用方法","偏向锁撤销与降级规则","指令重排序与可见性","tryLock超时获取锁","CAS与synchronized自增对比","synchronized实例锁与类锁","wait/notify条件等待语义","lock()与lockInterruptibly","Condition双等待队列实现","volatile内存屏障与happens-bef","synchronized多实例失效边界","数据库条件更新与行锁方案","volatile引用与对象内部字段语义","CAS自旋开销优化与退避策略","tryLock返回值语义辨析","Condition.await调用前提","notifyAll与notify通知策略","偏向锁轻量级锁启用条件","happens-before可见性传递性","锁对象唯一性与final声明"],"updatedAt":1793348338920}', '', NULL, '{"overview":"累计10卷110题均分41.2，近卷73.1。volatile可见性/原子性、DCL重排序、synchronized锁对象、CAS与原子类选型、check-then-act答得较好；AQS队列流程、Condition、锁升级、wait/notify仍弱，大题多问易漏、方向易反。","level":"入门偏下，概念散、多问易漏，原理欠扎实","coveredAreas":["volatile可见性与","指令重排序与DCL","synchronized","CAS与原子类选型","可重入与tryLock","check-then-a","Condition基础","自旋与锁优化概念"],"uncoveredAreas":["AQS原理与同步队列","读写锁","死锁与规避","线程中断与锁","原子类实现原理","锁升级过程","wait/notify协","选型对比综合"],"updatedAt":1793348338920}', 1793083702053, 1793348338920, NULL),
	(3, 2, 1, 'interview', 'ThreadLocal,JVM内存模型，对象内存布局，类加载双亲委派 高频面试题', 'topic', NULL, 'mid', 'quick', 10, 'false', 'active', NULL, '', NULL, NULL, 1793607241607, 1793607241607, NULL),
	(4, 2, 1, 'interview', 'java线程池', 'range', '线程池七大参数，四种内置线程池，拒绝策略，业务中如何自定义线程池', 'mid', 'quick', 10, 'false', 'active', '{"mastered":["SynchronousQueue 直接交接不缓存","FixedThreadPool 无界队列 OOM 风险","CachedThreadPool 线程数上限风险","CachedThreadPool 60s 回收机制","任务提交 core→queue→max→拒绝流程","无界队列适用场景：总量可控批处理","自定义拒绝策略：记日志+落盘+补偿","自定义 ThreadFactory 线程命名"],"weakPoints":["shutdown 与 shutdownNow 区别未掌握","线程池用完是否关闭、核心线程回收","四大拒绝策略任务最终去向未对比","ThreadFactory 除命名外的异常兜底","execute/submit/invokeAll 返回值差异","submit 异常经 Future.get 传播","线程名前缀在排障中的具体用法","有界队列容量由等待时间与任务量权衡"],"misconceptions":["CachedThreadPool 用 Synchronous","把 ThreadFactory 问题答成不要用 Execut","自定义拒绝策略混淆为内置策略选型"],"nextFocus":["shutdown/shutdownNow 与核心线程回收，直","execute/submit/invokeAll 返回值与异","线程名前缀在 dump 排障中的具体帮法"],"coverage":["线程池任务提交处理顺序","七大参数 corePoolSize/maximu","默认拒绝策略 AbortPolicy 与 Rej","Executors 四种内置线程池适用场景","CallerRunsPolicy 反压效果","任务队列分类（无界/有界/同步移交）","拒绝策略触发时机与作用","CPU/IO 密集型线程数取值","自定义 ThreadFactory 必要性","Executors OOM 风险与手写 Thre","keepAliveTime 非核心线程存活","corePoolSize 与 maximumPo","有界队列与拒绝策略业务取值","四种内置线程池的队列类型与线程上限","自定义拒绝策略与降级补偿","线程池 shutdown 与 shutdownN","线程池关闭与核心线程回收","AbortPolicy 与 DiscardPol","SynchronousQueue 适用场景","threadFactory 定制线程创建","keepAliveTime 与 unit 参数作","allowCoreThreadTimeOut 设","Fixed/Cached 内置线程池隐患","无界队列导致 max 失效","SynchronousQueue 不缓存直接移交","FixedThreadPool 任务堆积 OOM","CachedThreadPool 线程数暴涨风险","execute/submit/invokeAll","线程名前缀便于排障定位"],"updatedAt":1793692387772}', '', NULL, '{"overview":"已练4卷40题，百分制均分65.0。七大参数、四种内置线程池、拒绝策略、队列与任务流转主干流程掌握较好；submit/execute差异、自定义线程池实战、大题多问点漏答、参数配合与调优偏弱。","level":"概念记忆尚可，多问点漏答，实战设计与调优偏弱","coveredAreas":["线程池七大参数","四种内置线程池","拒绝策略","阻塞队列","任务流转顺序","参数取值","Executors隐患","线程池关闭"],"uncoveredAreas":["自定义线程池实战","线程池监控","参数调优场景","ThreadFactor"],"updatedAt":1793692387772}', 1793608842590, 1793692387772, NULL),
	(5, 2, 2, 'interview', 'Spring核心', 'range', 'IOC容器，循环依赖，AOP动态代理，Bean生命周期等等高频面试题', 'mid', 'quick', 10, 'false', 'active', '{"mastered":["Bean生命周期主干顺序:实例化→属性填充→初始化→使用","强依赖用构造器注入,可选依赖用setter注入","@Primary与@Qualifier多候选消歧方式","@Conditional条件注册基本用法","执行期切点匹配:首*任意返回值,..任意参数","AOP日志/耗时统计等横切场景适用","构造器注入能让必需依赖在创建时完整"],"weakPoints":["会话级可变状态应选request作用域,非prototype","Aware接口举例与拿到的资源说不清(未作答)","销毁前流程只记得@PreDestroy,漏BeanPostP","字段注入与setter注入的注入时机与差异答不出","注解驱动AOP靠BeanPostProcessor生成代理说","@Before/@Around在事务与日志场景的分工"],"misconceptions":["把BeanPostProcessor当成只作用于自身实现类","@Lazy加注入点=懒加载(实为代理解循环)","注入方式选型理由说不清(构造器/setter)","把AOP增强对象说成Bean整体,未落到方法/连接点"],"nextFocus":["背:BeanNameAware/ApplicationCon","背:字段注入在属性填充后由反射完成,setter注入走set","练:销毁前三步(销毁前BeanPostProcessor→@"],"coverage":["Bean生命周期四大阶段","实例化与初始化的区别","AOP切面注解(@Aspect/@Pointcu","切入点表达式execution匹配","三级缓存解决循环依赖","构造器注入循环依赖无法解决","AOP代理与自调用失效","自调用失效的解决办法","Bean初始化回调(@PostConstruct","Bean销毁回调(@PreDestroy等)","@Lazy延迟初始化(懒加载)","@Lazy注入点代理与解循环","Bean作用域(scope)","prototype作用域声明与特性","构造器注入与setter注入对比","构造器注入与循环依赖的关系","Spring AOP默认代理方式选择","JDK动态代理与CGLIB差异","三级缓存的key与value结构","@Autowired required语义","属性填充阶段依赖缺失行为","AOP切面失效的典型场景","final关键字与不可变关系","不可变类设计条件","@ComponentScan扫描包配置","Spring Boot默认扫描包","切点与连接点的概念与关系","Bean初始化回调执行顺序","@Lazy与构造器注入场景取舍","Bean生命周期每步职责说明","AOP代理生成时机与环节","代理对象与原始Bean区别","singleton与prototype容器表现差","作用域声明方式(@Scope/scope)","@Autowired多候选消歧手段","构造器注入循环依赖报错原因","循环依赖成立条件与判定","AOP生效条件与内部调用失效","组件扫描范围与启动耗时","@Lazy延迟初始化启动优化"],"updatedAt":1793863420632}', '', NULL, '{"overview":"累计5卷65题，平均38.3分，最近一卷64.0分，进步明显但作答率仍偏低。Bean生命周期主干顺序已基本掌握，注入方式选型、多Bean冲突处理、切点表达式结论类问题答得较好。主要失分点：Bean作用域选型（会话场景误选prototype）、Aware接口、销毁阶段回调链、字段注入与setter注入在生命周期中的时机差异（未作答）、AOP通知类型与代理创建时机。","level":"基础薄弱，结论对但机制链条说不全，作答率低","coveredAreas":["Bean生命周期主干","循环依赖与三级缓存","Bean作用域选型","依赖注入方式","AOP切面与切点","JDK与CGLIB代理","条件装配与多Bean","Aware接口"],"uncoveredAreas":["BeanFactory体","配置类装配原理","@Import机制","AOP通知类型进阶","AOP代理创建时机","Bean销毁完整链"],"updatedAt":1793863420632}', 1793607477792, 1793863420632, NULL),
	(6, 2, 2, 'interview', 'SpringBoot自动配置、Starter、过滤器与拦截器等等 高频面试题', 'topic', NULL, 'mid', 'quick', 10, 'false', 'active', NULL, '', NULL, NULL, 1793869752965, 1793944293283, NULL);

-- 导出  表 public.question 结构
CREATE TABLE IF NOT EXISTS "question" (
	"id" BIGINT NOT NULL,
	"user_id" BIGINT NOT NULL,
	"practice_id" BIGINT NULL DEFAULT NULL,
	"paper_id" BIGINT NOT NULL,
	"sequence" INTEGER NOT NULL,
	"prompt" TEXT NULL DEFAULT NULL,
	"reference_answer" TEXT NULL DEFAULT NULL,
	"knowledge_points_json" TEXT NULL DEFAULT NULL,
	"demands_json" TEXT NULL DEFAULT NULL,
	"assigned_points_json" TEXT NULL DEFAULT NULL,
	"angle" TEXT NULL DEFAULT NULL,
	"tier" VARCHAR(8) NULL DEFAULT NULL,
	"question_type" VARCHAR(16) NULL DEFAULT NULL,
	"points" INTEGER NULL DEFAULT NULL,
	"revealed_at" BIGINT NULL DEFAULT NULL,
	"created_at" BIGINT NOT NULL,
	PRIMARY KEY ("id"),
	CONSTRAINT "question_created_at_not_null1" CHECK (created_at IS NOT NULL),
	CONSTRAINT "question_sequence_not_null1" CHECK (sequence IS NOT NULL),
	CONSTRAINT "question_paper_id_not_null1" CHECK (paper_id IS NOT NULL),
	CONSTRAINT "question_user_id_not_null1" CHECK (user_id IS NOT NULL),
	CONSTRAINT "question_id_not_null1" CHECK (id IS NOT NULL)
)
CREATE INDEX "idx_question_user_paper" ON "" ("user_id", "paper_id", "sequence");
CREATE INDEX "idx_question_user_practice" ON "" ("user_id", "practice_id", "sequence");;

-- 正在导出表  public.question 的数据：225 rows
DELETE FROM "question";
INSERT INTO "question" ("id", "user_id", "practice_id", "paper_id", "sequence", "prompt", "reference_answer", "knowledge_points_json", "demands_json", "assigned_points_json", "angle", "tier", "question_type", "points", "revealed_at", "created_at") VALUES
	(1, 2, 1, 1, 9, '多线程环境下需要一个共享的 List，你手上只有 ArrayList。请说明：① 用 Collections.synchronizedList() 包装后，它的线程安全性体现在哪里、有哪些使用上的限制？② 用 CopyOnWriteArrayList 替代它，写操作的机制是什么、适合什么场景、不适合什么场景？', '**synchronizedList 的安全性来自方法级 synchronized**：每个方法内部用包装器持有的 mutex（默认即 list 本身）加锁，保证单个方法串行执行；但**复合操作不保证原子性**（如 check-then-act 仍需手动用同一把锁包住），**遍历也必须 synchronized(list) 包住迭代**，否则可能抛 ConcurrentModificationException，这是主要使用限制。**CopyOnWriteArrayList 采用写时复制**：写操作时复制整个数组副本，在副本上修改后切换引用，读完全无锁；写开销大、内存翻倍，且**迭代器读旧快照、弱一致**。因此适合**读多写少、数据量小**的场景（如监听器列表），不适合**写多、大数据量**的场景。', '["Collections.synchronizedList 的加锁方式与遍历限制","CopyOnWriteArrayList 写时复制机制与适用场景"]', '["说明 synchronizedList 的加锁方式（方法级同步、锁对象）以及遍历需手动加锁等使用限制","说明 CopyOnWriteArrayList 写时复制的机制，并给出适用（读多写少）与不适用（写多、大数据量）场景"]', '["List · 线程安全方案"]', '多线程下让 List 安全的几种包装做法', '中档', '原理追问', 13, NULL, 1793073247502),
	(2, 2, 1, 1, 10, '关于 HashMap，请回答：① JDK 8 中它的底层结构是什么、在什么条件下会从链表转成红黑树？② 它允许 null 键和 null 值吗？③ 它是线程安全的吗，多线程并发写入会有什么问题？', '**JDK 8 HashMap 底层是数组 + 链表 + 红黑树**：主体是 Node 数组，哈希冲突时桶内以链表组织，**当链表长度达到 8 且数组容量达到 64 时转成红黑树**（容量不足 64 先扩容），查询从 O(n) 降到 O(log n)。它**允许一个 null 键和多个 null 值**，null 键放在数组 0 号桶。它**不是线程安全的**：并发 put 可能丢失更新、读到中间状态数据，扩容期间还可能出现数据错乱；需要线程安全应改用 ConcurrentHashMap 或加锁同步。', '["JDK 8 HashMap 底层结构与树化条件","HashMap 对 null 键值的支持","HashMap 的线程安全性"]', '["说明 JDK 8 HashMap 的数组+链表+红黑树结构，以及链表转红黑树的条件（链表长度达到 8 且数组容量达到 64）","准确说明 HashMap 允许一个 null 键和多个 null 值"]', '["HashMap · 底层结构与特性"]', '说 JDK8 结构、null 键值与线程安全性', '中档', '原理追问', 13, NULL, 1793073247503),
	(3, 2, 1, 1, 1, '关于 ArrayList：① 尾部 add 与中间位置插入的平均时间复杂度分别是多少？② 每次扩容时容量大约扩大多少倍？', '**尾部 add 平均 O(1)，中间插入平均 O(n)。** 尾部追加直接放到数组末尾，放不下时才扩容并拷贝，扩容成本均摊到多次插入后仍是常量级；中间插入会破坏连续存储，必须把插入点之后的元素整体后移，搬移量与元素个数成正比，所以是 O(n)。**扩容时容量扩大为原来的约 1.5 倍**（旧容量 + 旧容量右移 1 位）。', '["ArrayList 插入复杂度","ArrayList 扩容倍数"]', '["准确答出 ArrayList 尾部 add 与中间插入的平均时间复杂度，说明差异原因","准确答出 ArrayList 扩容的倍数规律"]', '["ArrayList · 增删与扩容机制"]', '末尾 add 与中间插入的复杂度、扩容倍数', '基础', '概念辨析', 10, NULL, 1793073249503),
	(4, 2, 1, 1, 2, 'Java 集合按“定位方式”分为哪四大接口？请分别说出它们各自的定位特点，以及每个接口下常用的实现类。', '按定位方式分四大接口：**List 按下标定位**（有序、可重复），实现类 ArrayList、LinkedList；**Set 按内容定位**（元素不重复，靠 equals/hashCode 判重），实现类 HashSet、LinkedHashSet；**Map 按 key 定位**（键值对，key 不重复），实现类 HashMap、LinkedHashMap、TreeMap；**Queue 按进出顺序定位**（FIFO，Deque 可当栈），实现类 ArrayDeque、LinkedList、PriorityQueue。', '["Java 集合接口体系","常见集合实现类"]', '["准确列出四大核心接口的名称","分别说明每个接口的定位特点，并给出该接口下常用的实现类"]', '["集合框架 · 体系结构"]', '按定位说四大接口及常用实现类关系', '基础', '概念辨析', 10, NULL, 1793073249504),
	(5, 2, 1, 1, 3, '给自定义对象定义排序规则有 Comparable 和 Comparator 两种方式。请辨析：① 两者分别如何定义、由谁调用？② 分别适合什么使用场景？', '**Comparable 是自然排序**：元素类实现 Comparable 接口、在类内重写 compareTo(T o)，由排序逻辑（Arrays.sort、TreeMap、TreeSet）内部调用 this.compareTo(other)，适合**该类只有一种固定排序规则**时。**Comparator 是定制排序**：独立于元素类，重写 compare(o1,o2)，以参数形式传给排序 API 或集合构造器，由排序逻辑回调，适合**需要多种排序规则、或不便修改元素类**时。', '["Comparable 与 Comparator","排序规则定义方式"]', '["说明 Comparable 与 Comparator 的定义方式与调用方差异","说明两种方式各自适用的场景"]', '["集合 · Comparable 与 Comparator"]', '给自定义对象写排序规则的两种方式辨析', '基础', '概念辨析', 9, NULL, 1793073249505),
	(6, 2, 1, 1, 4, '某系统有以下集合选型需求，请分别给出最合适的集合并简述理由：① 需要有序、可重复、按下标快速读取；② 需要保证元素不重复且不关心顺序；③ 需要频繁按下标插入/删除元素。', '① 选 **ArrayList**：底层数组、元素连续，**按下标随机访问 O(1)**，尾部 add 均摊 O(1)，完全满足有序+可重复+快速读取。② 选 **HashSet**：基于 HashMap，用 **hashCode+equals 判重**，add/contains 平均 O(1)，不关心顺序时开销最小。（③ 频繁按下标插入删除可考虑 LinkedList，但按下标定位本身也要 O(n) 遍历。）', '["ArrayList 特性与适用场景","HashSet 去重","LinkedList 插入删除"]', '["给出场景①的集合选型并说明理由","给出场景②的集合选型并说明理由"]', '["集合选型 · 综合场景"]', '按有序/去重/查询增删选集合的小场景', '基础', '概念辨析', 9, NULL, 1793073249507),
	(7, 2, 1, 1, 5, '把自定义对象放进 HashMap 当 key 之前，通常需要重写哪些方法？① 重写哪个方法才能让两个字段值相同的对象被当作同一个 key？② 为什么 hashCode() 也要一起重写、只重写 equals() 会出什么问题？', '需要重写 **equals() 和 hashCode() 两个**。**equals() 决定两个 key 是否「逻辑相等」**（字段值相同就视为同一个 key）。**hashCode() 必须配套重写**：HashMap 先用 hashCode 定位桶，再用 equals 比较；若 equals 相等而 hashCode 不等，两个 key 会落到不同桶，put 时被当成不同 key 存两份，get 用新对象也查不到，出现「存得进、取不出、size 偏大」。因此约定 equals 为 true 的对象，hashCode 必须相同。', '["HashMap 对 key 的相等判定（equals）","hashCode 与 equals 的一致性约定"]', '["答出需要重写 equals()，并说明其作用是决定两个 key 的\"逻辑相等\"判定。","答出 hashCode() 与 equals() 必须配套重写的原因，以及只重写 equals() 导致的后果。"]', '["集合 · equals/hashCode 契约"]', '自定义对象作 key 前该重写什么、为何', '基础', '概念辨析', 9, NULL, 1793073253947),
	(8, 2, 1, 1, 6, '多个线程会共享同一个 Map 做读多写少的存取时，有人提议用 Hashtable，有人提议用 ConcurrentHashMap。① Hashtable 已经是线程安全的，为什么这种场景下一般仍不选它？② 这个场景下选 ConcurrentHashMap 主要好在哪？', '① **Hashtable 用方法级 synchronized**，读写都抢同一把对象锁，并发下线程互相阻塞、吞吐低，且它是遗留类，所以不选。② 选 **ConcurrentHashMap**：写入用 **CAS + synchronized（锁桶头节点）**，锁粒度细化到桶，竞争大幅下降；**读操作无锁**（volatile 保证可见性），读多写少时吞吐远高于 Hashtable。', '["Hashtable 的线程安全方式与性能代价","ConcurrentHashMap 的并发读写特性"]', '["答出 Hashtable 线程安全的代价，即并发性能差的原因。","答出 ConcurrentHashMap 在并发读写场景下的主要优势。"]', '["ConcurrentHashMap · 并发特性"]', '多线程共享 Map 时为何选它而非 Hashtable', '基础', '概念辨析', 9, NULL, 1793073253949),
	(9, 2, 1, 1, 7, 'ArrayList 底层是数组。请由"数组"这一存储特性出发回答：① 为什么 ArrayList 的随机访问（按 index 取元素）很快？② 为什么它在中间插入/删除元素相对慢？', '① ArrayList 底层是**数组**，元素在内存中**连续存放**，按 index 访问只需「首地址 + 下标×元素大小」直接算出目标地址，**O(1)**，所以随机访问极快。② 中间插入/删除会破坏连续性，必须把**插入点之后的所有元素整体后移或前移**，搬移次数与元素个数成正比，因此相对慢（**O(n)**）。', '["ArrayList 基于数组的存储结构","数组下标随机访问 O(1) 与中间增删 O(n)"]', '["答出随机访问快的原因，与数组下标寻址直接相关。","答出中间插入/删除慢的原因，与元素移动相关。"]', '["ArrayList · 底层结构与特性"]', '由数组特性推随机访问与增删的表现', '基础', '概念辨析', 9, NULL, 1793073253950),
	(10, 2, 1, 1, 8, '关于 ArrayList 的扩容：① 什么情况下会触发扩容？② 一次扩容后容量如何变化？', '① **当调用 add 添加元素、而当前数组已满（元素个数等于当前容量、放不下）时触发扩容**，先扩容再插入。② 扩容后**新容量约为旧容量的 1.5 倍**（旧容量 + 旧容量右移 1 位），再用 Arrays.copyOf 把旧数组元素拷到新数组。', '["ArrayList 扩容触发时机","ArrayList 扩容倍数（约 1.5 倍）"]', '["答出触发扩容的条件（添加元素时容量不够）。","答出扩容后容量的增长规律。"]', '["HashMap · 扩容机制"]', '何时触发扩容与扩容后的容量变化', '基础', '概念辨析', 9, NULL, 1793073253951),
	(11, 2, 1, 2, 5, '一个本地计数统计模块，要求线程安全地对多个 key 计数（get/put 都可能并发）；另一个场景是并发读多写少的缓存，要求读操作不加锁也能安全返回。① 这两个场景分别该选哪种集合？② 请分别说明它们各自为什么满足线程安全要求？', '① 两个场景都应选 **ConcurrentHashMap**：计数场景用它的 **put/get 原子并发安全**，配合 **compute/merge** 做累加；读多写少的缓存利用它 **get 无锁**。② 原因：ConcurrentHashMap 写操作用 **CAS + 桶头加锁**保证互斥与原子性，读依赖 **volatile 的可见性**，所以不加锁也安全；而 **Hashtable 是所有方法 synchronized**，读也加锁，高并发下竞争大，不适合计数和高并发读。', '["ConcurrentHashMap 线程安全机制","线程安全集合选型"]', '["这两个场景分别该选哪种集合？","请分别说明它们各自为什么满足线程安全要求？"]', '["集合选型 · 综合场景"]', '带线程安全约束的缓存与统计场景选集合', '基础', '概念辨析', 8, NULL, 1793082132190),
	(12, 2, 1, 2, 6, '从「是否有序、是否允许重复元素」两个角度说明 ArrayList 的特性，这两个特性对它的常用操作（按下标访问、添加重复元素）有什么影响？', '正确写法：
`Iterator<String> it = list.iterator(); while(it.hasNext()){ if(条件) it.remove(); }`
或反向循环：`for(int i=list.size()-1;i>=0;i--) if(条件) list.remove(i);`。
**必须这样写的原因**：it.remove() 会同步 expectedModCount，不触发 fail-fast；直接调用 **list.remove(obj) 只更新 modCount，迭代器的 expectedModCount 不变**，下一次 next() 校验失败就抛 **ConcurrentModificationException**；正向按下标删除还会**下标错位、漏删元素**。', '["ArrayList 有序性","ArrayList 允许重复元素"]', '["从「是否有序、是否允许重复元素」两个角度说明 ArrayList 的特性，这两个特性对它的常用操作（按下标访问、添加重复元素）有什么影响？"]', '["ArrayList · 底层结构与特性"]', '从有序可重复角度辨析 ArrayList 特性', '基础', '概念辨析', 8, NULL, 1793082132190),
	(13, 2, 1, 2, 7, '用 Iterator 遍历一个 ArrayList 时，如果想边遍历边删除符合条件的元素，直接调用 list.remove(obj) 通常会出问题。请写出正确的删除写法，并说明为什么必须这样写、直接调用 list.remove 会导致什么现象？', '正确写法：用 **iterator.remove()**
```
Iterator<String> it = list.iterator();
while (it.hasNext()) {
    String s = it.next();
    if (符合删除条件) {
        it.remove();  // 通过迭代器自身删除
    }
}
```
原因：迭代器内部维护游标，外部调用 list.remove 会改变集合结构但不更新迭代器游标，下一次 next() 会检测到 **modCount 不一致**，抛出 **ConcurrentModificationException（fail-fast）**。
iterator.remove() 会同步更新迭代器自己的游标和集合的 modCount，因此不会抛异常。', '["Iterator.remove() 安全删除","fail-fast 与 ConcurrentModificationException"]', '["用 Iterator 遍历一个 ArrayList 时，如果想边遍历边删除符合条件的元素，直接调用 list.remove(obj) 通常会出问题。请写出正确的删除写法，并说明为什么必须这样写、直接调用 list.remove 会导致什么现象？"]', '["集合 · 迭代器 Iterator"]', '用 Iterator 遍历并安全删除元素的写法', '基础', '概念辨析', 7, NULL, 1793082132190),
	(14, 2, 1, 2, 8, '下面是一段使用 HashMap 的代码片段：
```
Map<String,Integer> map = new HashMap<>();
map.put("a", 1);
Integer r1 = map.put("a", 2);
Integer r2 = map.get("b");
Integer r3 = map.putIfAbsent("a", 3);
```
请说明：① put、get、putIfAbsent 三个方法各自的作用是什么？② r1、r2、r3 分别是多少？为什么？', '① **put(k,v)**：放入并**覆盖旧值**，**返回被覆盖的旧值**（无则 null）；**get(k)**：取值，不存在返回 **null**；**putIfAbsent(k,v)**：**仅当 k 不存在（或值为 null）时才放入**，否则不动，**返回当前值**。② **r1=1**：put 返回被覆盖的旧值 1；**r2=null**：无 "b"；**r3=2**："a" 已存在且值非 null，不放入 3，返回现值 2。', '["Map.put 返回值语义","Map.get / putIfAbsent 用法与返回值"]', '["put、get、putIfAbsent 三个方法各自的作用是什么？","r1、r2、r3 分别是多少？为什么？"]', '["HashMap · put 过程"]', 'put 与 get 基本用法与返回值含义', '中档', '原理追问', 11, NULL, 1793082132190),
	(15, 2, 1, 2, 9, '你要用 Set 对一批 Java 对象去重，已知这些对象是自定义的 User 类，重写了 equals 但没重写 hashCode，也可能两个都没重写。

① 分别给出这两种情况下，把数据加入 HashSet 后是否能正确去重，判定依据是什么？
② 如果要让 Set 正确去重，equals 和 hashCode 需要满足什么约束关系？为什么必须这样？', '**两种情况都不能正确去重**。① 仅重写 equals 未重写 hashCode：内容相等的对象默认 hashCode 按对象标识散列，落入不同桶，equals 不会被调用，去重失败；② 两个都没重写：equals 与 hashCode 都是身份语义，内容相等的不同实例视为不同对象，不去重。判定依据是 **hashCode 定位桶、equals 在桶内判等**。② 约束：**equals 相等 ⇒ hashCode 必须相等**（反向不必须）。因为 HashSet 先用 hashCode 找桶，再用 equals 判等，两者不一致就会漏判重复。', '["HashSet 判重依据：hashCode 定位桶 + equals 判等","equals 与 hashCode 的一致性约束"]', '["分别给出这两种情况下，把数据加入 HashSet 后是否能正确去重，判定依据是什么？","如果要让 Set 正确去重，equals 和 hashCode 需要满足什么约束关系？为什么必须这样？"]', '["Set · 去重原理"]', '用 Set 对一批数据去重的写法与判定依据', '中档', '原理追问', 11, NULL, 1793082144662),
	(16, 2, 1, 2, 10, '某爬虫服务用 Java 写 URL 去重与计数：需要统计每个 URL 被抓取到的次数，并保证同一 URL 只记录一次。开发同学最初直接用 **HashSet<String>** 存 URL，后来发现内存涨得很快，且需要拿到每个 URL 的次数；再后来爬虫改成多线程并发抓取，同一 URL 会被多个线程同时写入。

请回答：
① 为什么 HashSet 只能做去重、拿不到次数？要去重 + 计数，应该换成哪个集合结构？说明这个结构的判重与计数分别依赖什么机制。
② 这个集合作为 URL 去重表，容量从默认值不断增长到几十万、上百万条 URL 时会发生什么？请说明触发扩容的条件、扩容时的主要代价，以及一个能减少扩容次数的初始化做法。
③ 在多线程并发写入的场景下，这个结构为什么不安全？请给出两种可行的并发取舍方案（各一句话说明代价），并说明如果只是想做「只增不改」的去重表、追求高吞吐，你会怎么选。', '① HashSet 只保存元素、不关联计数值，故只能去重拿不到次数；改用 **HashMap<String,Integer>**：判重靠 key 的 **equals/hashCode**，计数靠 value 累加（如 merge）。② 元素数超过 **容量 × 0.75** 触发扩容（约 2 倍），需重新分配数组并把所有元素重新散列，代价大；用 `预期条数 / 0.75` 作初始容量可减少扩容次数。③ HashMap 非线程安全，并发 put 会互相覆盖丢更新。可选 **Hashtable/synchronizedMap**（方法级锁，吞吐低）或 **ConcurrentHashMap**（锁粒度细，吞吐高）；只增不改、追高吞吐选 **ConcurrentHashMap**。', '["HashMap 结构与扩容机制（阈值、负载因子、初始容量）","HashMap/HashSet 的线程不安全与 ConcurrentHashMap 等并发取舍"]', '["为什么 HashSet 只能做去重、拿不到次数？要去重 + 计数，应该换成哪个集合结构？说明这个结构的判重与计数分别依赖什么机制。","这个集合作为 URL 去重表，容量从默认值不断增长到几十万、上百万条 URL 时会发生什么？请说明触发扩容的条件、扩容时的主要代价，以及一个能减少扩容次数的初始化做法。","在多线程并发写入的场景下，这个结构为什么不安全？请给出两种可行的并发取舍方案（各一句话说明代价），并说明如果只是想做「只增不改」的去重表、追求高吞吐，你会怎么选。"]', '["HashMap · 底层结构与特性","HashMap · 扩容机制","ConcurrentHashMap · 并发特性"]', '爬虫 URL 计数场景串联结构、扩容与并发取舍', '大题', '场景应用', 23, NULL, 1793082144673),
	(17, 2, 1, 2, 1, '遍历 ArrayList 时直接用集合的 remove 删除元素，为什么会抛 ConcurrentModificationException？正确删除元素的做法是什么？', '**原因是 fail-fast 机制**：创建迭代器时会把当前 **modCount 记为 expectedModCount**，每次 next() 都校验两者是否相等；直接调用 **list.remove** 会修改 modCount 而不更新 expectedModCount，下一次遍历就检测到不一致，抛出 **ConcurrentModificationException**。正确做法：① 用迭代器自带的 **it.remove()**，它会同步 expectedModCount；② 或**反向 for 循环**按下标删除；③ 或用 **removeIf**。', '["fail-fast 机制与 ConcurrentModificationException","迭代器的 remove 方法用法"]', '["遍历 ArrayList 时直接用集合的 remove 删除元素，为什么会抛 ConcurrentModificationException","正确删除元素的做法是什么"]', '["集合 · fail-fast 与 fail-safe"]', '遍历中删除元素为何抛异常、如何正确删', '基础', '概念辨析', 8, NULL, 1793082197753),
	(18, 2, 1, 2, 2, '两个线程同时对一个 ArrayList 执行 put（add）操作，可能出现元素丢失的现象，原因是什么？若要保证并发写入不丢数据，有哪些可替代的集合方案？', '**原因是 ArrayList 的 add 非原子**：`elementData[size]=e` 与 `size++` 两步之间可被线程切换打断，两个线程写到同一下标、后写覆盖前写，size 只加一次，元素就丢了。可替代方案：① **Collections.synchronizedList** 或 **Vector**：方法级加锁，读写都互斥，适合读写均衡；② **CopyOnWriteArrayList**：写时加锁复制数组、volatile 发布，读无锁，适合读多写少、集合小、容忍读旧值；③ 纯并发队列可用 **ConcurrentLinkedQueue**。写频繁时不要用 COW。', '["ArrayList 非线程安全与扩容丢失数据原因","CopyOnWriteArrayList 与 synchronizedList 选型"]', '["两个线程同时对一个 ArrayList 执行 put（add）操作，可能出现元素丢失的现象，原因是什么","若要保证并发写入不丢数据，有哪些可替代的集合方案"]', '["HashMap · 线程安全与替代方案"]', '多线程 put 丢数据现象与替代方案选型', '基础', '概念辨析', 8, NULL, 1793082197753),
	(19, 2, 1, 2, 3, 'Java 集合框架中 Collection 和 Map 是什么关系？Collection 下有哪些主要子接口，各自的特点是什么？', '**Collection 与 Map 是并列的两大根接口，Map 不是 Collection 的子接口**：Collection 存放单个元素，Map 存放键值对。Collection 下主要有三个子接口：**List——有序（保持插入顺序）、允许重复、可按下标访问**（ArrayList/LinkedList）；**Set——不允许重复元素**（HashSet/TreeSet）；**Queue——按 FIFO 语义进出**，可选优先级队列（LinkedList/ArrayDeque/PriorityQueue）。', '["Collection 与 Map 的关系","List/Set/Queue 子接口特点"]', '["Java 集合框架中 Collection 和 Map 是什么关系","Collection 下有哪些主要子接口，各自的特点是什么"]', '["集合框架 · 体系结构"]', 'Collection 与 Map 的关系及各自子接口辨析', '基础', '概念辨析', 8, NULL, 1793082197753),
	(20, 2, 1, 2, 4, '需要一个线程安全的 List，Java 中有哪些可选方案？请说明各自的适用场景，帮助我根据需求做出取舍。', '主要有三种：① **Collections.synchronizedList(new ArrayList<>())**：包装后每个方法加锁，读写互斥，适合读写均衡、需要与其他操作合并加锁的场景；遍历时必须手动 `synchronized(list)`。② **CopyOnWriteArrayList**：写时加锁复制数组、volatile 发布，**读完全无锁**，适合**读多写少、集合较小、容忍读到旧数据**的场景（如白名单、监听器列表），写频繁时开销大。③ **Vector**：方法级 synchronized，功能与①重叠，已基本被取代。取舍核心：**读写比例 + 集合大小 + 是否容忍读旧值**。', '["线程安全 List 的三种方案","读写比例与一致性要求下的选型取舍"]', '["需要一个线程安全的 List，Java 中有哪些可选方案","请说明各自的适用场景，帮助我根据需求做出取舍。"]', '["List · 线程安全方案"]', '线程安全 List 的各方案如何选择取舍', '基础', '概念辨析', 8, NULL, 1793082197753),
	(21, 2, 2, 3, 9, '双重检查锁（DCL）实现单例时，为什么必须给 instance 变量加 volatile？请说明：① 不加 volatile 时可能出什么问题；② 出问题的根本原因是什么（从对象创建过程和指令重排序的角度解释）。', '**结论：不加 volatile 时，其他线程可能拿到一个未初始化完成的"半成品"对象，必须用 volatile 禁止相关指令重排序并保证可见性。**

① **问题现象**：线程 A 执行 `instance = new Singleton()` 时，如果发生指令重排，另一个线程 B 可能在第一次判空（不加锁的那次检查）时看到 instance 已非 null，直接返回并使用这个对象，但它的字段可能还没初始化完，读到默认值。

② **根本原因**：`new` 对象不是原子操作，通常分三步——分配内存、初始化对象、把引用指向内存。JVM 允许把后两步重排序，变成"分配内存→引用赋值→初始化"。这样引用一旦可见，对象本身却还没构造完。加 **volatile** 后：**禁止这个重排序**（写屏障保证初始化先于引用赋值对其他线程可见），同时**保证跨线程的可见性**，B 线程要么看到 null 去抢锁，要么看到完整构造好的对象。

扩展：volatile 在这里同时解决了重排序和可见性，但不保证复合操作原子性，所以 DCL 里判空 + new 仍需 synchronized 保护。', '["volatile 禁止指令重排序","对象创建过程的非原子性与半初始化问题"]', '["不加 volatile 时可能出什么问题","出问题的根本原因是什么（从对象创建过程和指令重排序的角度解释）。"]', '["volatile · 指令重排序与 happens-befo"]', '双重检查锁单例为何要给 instance 加 volatile', '中档', '原理追问', 13, NULL, 1793087729221),
	(22, 2, 2, 3, 10, '某类里有三个方法：① 普通实例方法 synchronized void a()；② 静态方法 synchronized static void b()；③ 实例方法里的 synchronized(this) 块。请回答：它们各自锁定的是哪个对象？同一个实例上并发调用 a() 和 ③ 时会互斥吗？静态方法 b() 和实例方法 a() 之间会互斥吗？为什么？', '**锁的对象**：① 实例方法 a() 隐式锁**当前实例 this**；② 静态方法 b() 锁的是 **Class 对象（类的监视器）**；③ `synchronized(this)` 块锁的也是**当前实例 this**。

**a() 与 ③**：**会互斥**——两者锁的都是同一个实例的 this，是同一把锁，同一实例上并发调用会互相阻塞。

**b() 与 a()**：**不会互斥**——b() 锁 Class 对象，a() 锁实例对象，不是同一把锁，即使并发执行也不会互相阻塞。', '["synchronized 实例方法锁 this","synchronized 静态方法锁 Class 对象"]', '["普通实例方法 synchronized void a()","静态方法 synchronized static void b()","实例方法里的 synchronized(this) 块。请回答：它们各自锁定的是哪个对象？同一个实例上并发调用 a() 和","时会互斥吗？静态方法 b() 和实例方法 a() 之间会互斥吗？为什么？"]', '["synchronized · 三种使用形式与语义"]', '实例方法与静态方法 synchronized 分别锁谁', '中档', '原理追问', 13, NULL, 1793087729221),
	(23, 2, 2, 3, 1, '`volatile int count` 上做 `count++`，多线程并发时为什么仍然会丢更新？请说明根本原因。', '**根本原因是 `count++` 不是原子操作，volatile 保证不了复合操作的原子性。** `count++` 实际是「读取 → 加 1 → 写回」三步。volatile 保证的是可见性与有序性：写立即刷回主内存、读立即拉取。但线程 A 读到 count=5 之后、写回之前，线程 B 也读到 5，各自算出 6 写回，B 的写覆盖 A 的写，丢一次更新。所以 volatile 适合「一写多读的标志位」，不适合这种读-改-写，需要 `synchronized` 或 `AtomicInteger`。', '["volatile 保证可见性不保证原子性","复合操作（读-改-写）的竞态条件"]', '["`volatile int count` 上做 `count++`，多线程并发时为什么仍然会丢更新","请说明根本原因。"]', '["volatile · 可见性与原子性边界"]', 'i++ 用 volatile 修饰为何仍会丢更新', '基础', '概念辨析', 10, NULL, 1793087731041),
	(24, 2, 2, 3, 2, '请讲清 CAS 的基本思想是什么，以及它带来的 ABA 问题指的是什么、常规的应对办法有哪些？', '**CAS（Compare And Swap）思想**：更新变量时先比较当前值是否等于预期值，相等才写入新值，否则重试；全程不加锁，靠 CPU 原子指令实现，是乐观锁思路。**ABA 问题**：值从 A 变 B 再变回 A，CAS 只比较最终值，无法察觉中间被改过，对引用类型尤其危险（对象内容可能已变）。**应对办法**：① 用 `AtomicStampedReference` 引入**版本号（stamp）**，值和版本一起比较；② 用 `AtomicMarkableReference` 引入布尔标记（只关心是否变过）；③ 业务上保证不出现 ABA，或改用加锁。', '["CAS 原理（比较并交换、乐观锁）","ABA 问题及版本号/标记的应对"]', '["请讲清 CAS 的基本思想是什么，以及它带来的 ABA 问题指的是什么、常规的应对办法有哪些？"]', '["CAS · 原理与三大问题"]', '讲清 CAS 思想及其 ABA 问题的应对', '基础', '概念辨析', 10, NULL, 1793087731041),
	(25, 2, 2, 3, 3, '什么场景下应该放弃 `synchronized`、改用 `ReentrantLock`？请举出典型的适用场景。', '**当需要 `synchronized` 不提供的能力时改用 `ReentrantLock`**，典型场景：① 需要**可中断**地获取锁（`lockInterruptibly`）；② 需要**超时**获取锁（`tryLock(timeout)`），避免死等；③ 需要**非阻塞尝试**获取锁（`tryLock`）；④ 需要**公平锁**（按等待时间排序）；⑤ 需要多个**条件队列**（`Condition` 分组 await/signal，如生产者-消费者）。只是一般互斥同步时，优先用 `synchronized`（JVM 自动加锁解锁、可锁升级优化、不易遗漏释放）。', '["ReentrantLock 相对 synchronized 的能力差异（可中断/超时/公平/Condition）","加锁方式的选型"]', '["什么场景下应该放弃 `synchronized`、改用 `ReentrantLock`","请举出典型的适用场景。"]', '["ReentrantLock · 与 synchronized"]', '什么场景下应该改用 ReentrantLock', '基础', '概念辨析', 9, NULL, 1793087731041),
	(26, 2, 2, 3, 4, '请写一个用 `volatile` 布尔标志位实现「优雅停机」的最小示例（一个后台工作线程响应停止信号），并说明为什么这里用 `volatile` 是合适的。', '**示例**：`volatile boolean running = true;`  
工作线程：`while (running) { /* 干活 */ }`，主线程执行 `running = false;` 即可让工作线程退出循环。

**为什么用 volatile 合适**：这里是一个**一写多读的布尔标志**，只需要主线程的写入能被工作线程**及时看到**，volatile 恰好提供内存可见性（写立即刷回主内存、读立即拉取）；标志位赋值本身就是原子的，不需要原子性保证，也不需要线程互斥，所以用 volatile 就够了，比 `synchronized` 开销更小。', '["volatile 的适用场景（状态标志位）","可见性保证 vs 原子性"]', '["请写一个用 `volatile` 布尔标志位实现「优雅停机」的最小示例（一个后台工作线程响应停止信号），并说明为什么这里用 `volatile` 是合适的。"]', '["volatile · 典型使用场景"]', '写一个优雅停机的状态标志位示例', '基础', '概念辨析', 9, NULL, 1793087731041),
	(27, 2, 2, 3, 6, '下面是一个用 synchronized 实现的共享计数器：
```java
class Counter {
    private int count = 0;
    public synchronized void add() { count++; }
    public int get() { return count; }
}
```
请用 AtomicInteger 改写这个类，使其不再使用 synchronized，并说明：
① 改写后 add() 方法中累加应该用哪个方法，为什么它能保证线程安全？
② 这种改写相比 synchronized 在竞争激烈时有什么优势？', '```java
class Counter {
    private final AtomicInteger count = new AtomicInteger(0);
    public void add() { count.incrementAndGet(); }   // 等价于 getAndIncrement()+1
    public int get() { return count.get(); }
}
```

① 累加用 **`incrementAndGet()`**（或 `getAndIncrement()`）。它内部基于 **CAS（Compare And Swap）** 实现：读取当前值，计算新值，用原子指令把「旧值→新值」写回，如果这期间值被别的线程改过就重试。整个过程是**CPU 级原子指令**，不靠锁也不靠 synchronized，因此天然线程安全。

② 相比 synchronized 的优势：**CAS 是非阻塞的乐观并发**，线程不挂起、不进内核态、不涉及上下文切换；synchronized 在重量级状态下会让竞争线程阻塞、由 OS 调度唤醒，开销大。竞争激烈、临界区极短（只是个计数）时，CAS 自旋的代价远小于阻塞唤醒，吞吐量更高。

扩展：高并发下 CAS 自旋重试过多也会浪费 CPU，此时 LongAdder（分段累加）是更优选择。', '["AtomicInteger 与原子类","CAS 原理与非阻塞并发"]', '["改写后 add() 方法中累加应该用哪个方法，为什么它能保证线程安全？","这种改写相比 synchronized 在竞争激烈时有什么优势？"]', '["AtomicInteger · 常用方法与适用场景"]', '用 AtomicInteger 改写共享计数器的累加', '基础', '概念辨析', 9, NULL, 1793087748342),
	(28, 2, 2, 3, 7, '经典的生产者消费者模型中，生产者线程在什么条件下应该调用 wait()？在什么条件下应该调用 notify()/notifyAll()？请说明 wait() 必须放在哪种结构里、调用后线程的状态变化，以及为什么要这样调用。', '以有界缓冲区（满则等、空则等）为例：

**生产者**：进入临界区后用 **`while (缓冲区已满) wait();`** 判断——如果缓冲区满了，就调用 `wait()` 等待；当**放入一个元素、缓冲区不再满**后，调用 `notifyAll()` 唤醒可能在等待的消费者。

**消费者**：用 `while (缓冲区为空) wait();` 判断——空则 `wait()`；**取出一个元素、缓冲区不再满**后，调用 `notifyAll()` 唤醒可能在等待的生产者。

要点：
① **`wait()` 必须写在 `while` 循环里**（而非 `if`），因为线程被唤醒后还要**重新检查条件**（防止虚假唤醒、防止被别人抢先消费/生产后条件又不成立）。
② **`wait()/notify()` 必须在持有该对象锁（synchronized 块内）时调用**，否则抛 `IllegalMonitorStateException`。
③ `wait()` 会**释放当前对象锁并进入等待队列（WAITING）**，直到被 `notify/notifyAll` 唤醒后重新竞争锁。
④ 用 `notifyAll()` 而非 `notify()`，避免只唤醒同类线程导致死等。', '["wait/notify 的调用条件与位置","wait/notify 与对象锁、线程状态"]', '["经典的生产者消费者模型中，生产者线程在什么条件下应该调用 wait()","在什么条件下应该调用 notify()/notifyAll()","请说明 wait() 必须放在哪种结构里、调用后线程的状态变化，以及为什么要这样调用。"]', '["synchronized · 等待唤醒与线程协作"]', '生产者消费者中 wait/notify 的调用条件', '基础', '概念辨析', 9, NULL, 1793087748342),
	(29, 2, 2, 3, 8, 'ReentrantLock 的构造函数可以传 true 或 false（有无公平策略）。请说明：
① 传 true 和传 false 分别是什么锁，各自适合什么场景？
② 为什么默认（无参）是 false？', '① `new ReentrantLock(true)` 是**公平锁**：线程按**到来顺序（FIFO）**排队获取锁，不会插队。适合**对公平性有要求**的场景，比如每个请求都必须按顺序处理、避免线程饥饿（某些线程长期拿不到锁）。

`new ReentrantLock(false)` 是**非公平锁**：新到的线程可以**插队**先尝试抢占锁。适合**追求吞吐量、对顺序无要求**的大多数业务场景。

② 无参构造默认是 **false（非公平锁）**，因为**公平锁需要维护一个严格有序的等待队列，每次唤醒都有额外调度与排队开销，吞吐量低**；而非公平锁让刚到的线程有几率直接拿到锁（减少了唤醒等待线程的上下文切换），**整体吞吐量更高**。在绝大多数场景下吞吐量比严格公平更重要，所以默认选非公平。

扩展：公平锁只保证「先到先得」的获取顺序，不保证业务处理结果的公平。', '["ReentrantLock 公平锁与非公平锁","构造参数 true/false 的场景选择"]', '["传 true 和传 false 分别是什么锁，各自适合什么场景？","为什么默认（无参）是 false？"]', '["ReentrantLock · 公平锁与非公平锁"]', '构造参数 true 和 false 分别选在什么场景', '基础', '概念辨析', 9, NULL, 1793087748353),
	(30, 2, 2, 3, 5, 'Java 对象头中的锁状态会随竞争情况升级：无锁 → 偏向锁 → 轻量级锁 → 重量级锁。请回答：① 这个升级顺序中，每一级是被什么情况「触发」升到下一级的（即动因分别是什么）？② 为什么 JVM 不一开始就直接使用重量级锁，而是要设计偏向锁和轻量级锁这两级？', '**① 升级动因**：对象刚创建处于**无锁（或可偏向）**状态，第一个线程来加锁时**偏向锁**记录线程 ID；当**第二个线程**来竞争同一把锁时，偏向锁失效，升级为**轻量级锁**（用 CAS 把 Mark Word 指向线程栈的 Lock Record）；当轻量级锁的 **CAS 自旋多次仍失败**（竞争加剧、持有线程执行时间长），升级为**重量级锁**，改为把线程**阻塞挂起**，由操作系统 Mutex 管理。

**② 为什么不直接上重量级锁**：重量级锁依赖操作系统互斥量，线程阻塞/唤醒要**用户态与内核态切换**，开销大。而大多数场景下**锁竞争很轻甚至没有竞争**，偏向锁让单线程重复进入几乎零成本，轻量级锁用 **CAS 自旋**避免线程挂起，只有竞争真正激烈时重量级锁的阻塞才划算。', '["synchronized 锁升级顺序与触发条件","偏向锁/轻量级锁存在的设计动因"]', '["这个升级顺序中，每一级是被什么情况「触发」升到下一级的（即动因分别是什么）？","为什么 JVM 不一开始就直接使用重量级锁，而是要设计偏向锁和轻量级锁这两级？"]', '["synchronized · 锁升级过程"]', '无锁到偏向到重量级的升级顺序与动因', '基础', '概念辨析', 9, NULL, 1793087760087),
	(31, 2, 2, 4, 1, '一个计数器被多个线程累加，只需保证最终值正确，不要求线程间有先后顺序；另一个场景是多个线程轮流打印 1~100，必须严格按顺序执行。这两个场景分别应选无锁（如原子类）还是加锁（如 synchronized/Lock）？请说明选择理由。', '**计数器用原子类（CAS 无锁），轮流打印用加锁。** 计数器只要求最终值正确、无顺序要求，CAS 通过比较并交换保证单次自增的原子性，低竞争下不阻塞线程、省去上下文切换与唤醒开销，性能优于 synchronized。轮流打印要求严格次序，属于线程间协作：CAS 只能保证各自操作的原子性，无法让线程排队按序执行，必须加锁并配合 wait/notify 或 Condition 让线程等待条件、按顺序被唤醒。', '["无锁（CAS/原子类）与加锁的适用场景对比","按并发需求选择同步方式：原子性 vs 顺序性"]', '["一个计数器被多个线程累加，只需保证最终值正确，不要求线程间有先后顺序；另一个场景是多个线程轮流打印 1~100，必须严格按顺序执行。这两个场景分别应选无锁（如原子类）还是加锁（如 synchronized/Lock）","请说明选择理由。"]', '["ReentrantLock · 与 synchronized"]', '给出并发需求，让选择用哪种锁并说明理由', '基础', '概念辨析', 8, NULL, 1793088827322),
	(32, 2, 2, 4, 2, 'CAS 的无锁思想是什么？它相比加锁（synchronized）有什么优势？它本身又存在哪些局限？', '**CAS 的思想是「比较并交换」：读当前值 V 与期望值比对，一致才写入新值，不一致则自旋重试，全程不加锁、不阻塞线程。** 相比 synchronized，它没有线程挂起/唤醒和上下文切换，也没有死锁风险，低竞争下吞吐更高。局限有三：一是高并发下自旋空转消耗 CPU，反而退化；二是 ABA 问题，值被改回原样仍会成功，需版本号（AtomicStampedReference）解决；三是只能保证单个变量的原子性，复合操作仍要加锁。', '["CAS 的无锁原理（比较并交换 + 重试）","CAS 的局限：ABA、自旋开销、单变量原子性"]', '["CAS 的无锁思想是什么","它相比加锁（synchronized）有什么优势","它本身又存在哪些局限"]', '["CAS · 原理与三大问题"]', '问 CAS 无锁思想、与加锁对比，以及它的局限', '基础', '概念辨析', 8, NULL, 1793088827322),
	(33, 2, 2, 4, 3, '三个线程同时对类 Demo 的静态变量 static int a、实例变量 int b 操作：线程 T1 执行 synchronized(Demo.class){ a++; }，线程 T2 执行 synchronized(new Demo()){ a++; }，线程 T3 在一个 Demo 实例 d 上执行 synchronized(d){ b++; }。问：① T1 和 T2 对 a++ 是否互斥？② T1 和 T3 是否互斥？请说明各自原因。', '**① 不互斥，② 也不互斥，原因都是锁对象不同。** synchronized 的互斥只发生在锁同一个对象时：T1 锁的是 **Demo.class 这个类对象**，T2 锁的是 **new Demo() 出来的另一个实例**，T3 锁的是实例 d——三者是三把不同的锁。因此 T1、T2 对静态变量 a++ 可以并发执行、互相覆盖，T1 与 T3 也互不干扰。若要保护 a++，所有线程必须用同一把锁（如同一个 synchronized(Demo.class)）。', '["synchronized 锁的是对象监视器，锁对象不同不互斥","synchronized 修饰实例方法/代码块与锁对象的对应关系"]', '["T1 和 T2 对 a++ 是否互斥？","T1 和 T3 是否互斥？请说明各自原因。"]', '["synchronized · 三种使用形式与语义"]', '给出一段混用三种写法的代码，判断各段互斥与否', '基础', '概念辨析', 8, NULL, 1793088827340),
	(34, 2, 2, 4, 4, 'Java 原子类（如 AtomicInteger、AtomicLong）有哪些常用方法？请举出至少 3 个并简述用途。什么场景下应优先选用原子类而不是加锁？', '**常用方法至少记三个：get()/set() 读写当前值；incrementAndGet() 自增并返回新值（getAndIncrement() 返回旧值）；compareAndSet(期望值, 新值) 做 CAS 更新，成功返回 true；addAndGet(delta) 加上增量并返回结果。** 适用场景：只需对**单个共享变量**做原子更新（计数器、序号生成、状态标志位）、竞争不太激烈时优先用原子类——它基于 CAS 自旋，不阻塞线程、无上下文切换；当需要多个变量一起保证原子性或竞争很激烈时，才用 synchronized/Lock。', '["原子类常用方法（get/set、自增、CAS、addAndGet）","原子类适用场景：单变量原子更新、低竞争"]', '["Java 原子类（如 AtomicInteger、AtomicLong）有哪些常用方法","请举出至少 3 个并简述用途。什么场景下应优先选用原子类而不是加锁"]', '["AtomicInteger · 常用方法与适用场景"]', '写出原子类常用方法，并说明什么场景下优先选用它', '基础', '概念辨析', 8, NULL, 1793088827343),
	(35, 2, 2, 4, 5, '多线程间用 wait/notify 做线程协作时，必须遵守哪套配套的加锁与判断套路？请写出：① 调用 wait/notify 前必须做什么，否则会抛什么异常；② 对条件的判断应该用 if 还是 while，为什么；③ notify 和 notifyAll 在唤醒对象上有什么区别。', '**① 必须先持有调用对象的监视器锁**，即在 synchronized(obj){...} 内对同一个 obj 调用 wait/notify，否则抛 IllegalMonitorStateException。**② 条件判断要用 while**：线程被唤醒后重新抢到锁前条件可能已被改动，且存在虚假唤醒，必须循环复查条件，用 if 会跳过检查直接执行。**③ notify 只唤醒该对象等待队列中一个线程（随机），notifyAll 唤醒在该对象上等待的全部线程**，两者都只作用于在同一对象上 wait 的线程。', '["wait/notify 必须持有对象监视器锁（synchronized 内调用）","循环判断条件防止虚假唤醒","notify 与 notifyAll 的唤醒范围差异"]', '["调用 wait/notify 前必须做什么，否则会抛什么异常","对条件的判断应该用 if 还是 while，为什么","notify 和 notifyAll 在唤醒对象上有什么区别。"]', '["synchronized · 等待唤醒与线程协作"]', '写出 wait/notify 必须配套的加锁与判断套路', '基础', '概念辨析', 8, NULL, 1793088839232),
	(36, 2, 2, 4, 6, 'ReentrantLock 的公平锁和非公平锁各有什么优缺点？在吞吐量上谁更高、为什么？', '**公平锁按等待队列顺序获取锁，先到先得、不会饥饿，但吞吐较低**——每次都要唤醒队列头线程，排队与调度开销大。**非公平锁允许新线程直接抢锁，吞吐更高**，原因是刚释放锁的线程常能立刻重获锁，省去了线程挂起、唤醒和上下文切换；代价是插队可能导致排队久的线程长期拿不到锁（饥饿）。因此吞吐量上非公平锁更高，ReentrantLock 默认就是非公平锁，只有确实要求公平时才用公平锁。', '["公平锁与非公平锁的获取顺序差异","非公平锁吞吐量更高的原因（减少线程切换、缓存局部性）"]', '["ReentrantLock 的公平锁和非公平锁各有什么优缺点","在吞吐量上谁更高、为什么"]', '["ReentrantLock · 公平锁与非公平锁"]', '公平与非公平各自的优缺点和吞吐量差异', '基础', '概念辨析', 8, NULL, 1793088839232),
	(37, 2, 2, 4, 8, 'synchronized 的锁状态升级（无锁→偏向锁→轻量级锁→重量级锁）是单向的还是可降级的？请说明：① 整体方向上是否可逆；② 偏向锁可以被撤销/降级，轻量级锁、重量级锁之间是否还能降级，典型触发点在哪。', '**锁升级总体是单向的：无锁→偏向锁→轻量级锁→重量级锁，只能升级不能降级。** 其中**偏向锁可以被撤销**：出现其他线程来竞争（或对象调用 hashCode 等）时偏向锁被撤销，退回无锁或直接升级为轻量级锁。而**轻量级锁升级为重量级锁后不能降回轻量级锁**，轻量级与重量级之间是单向的（HotSpot 仅在 GC 时有重量级锁降级的处理，面试中按不可降级理解）。典型触发点：竞争加剧、自旋 CAS 失败次数超阈值时轻量级锁升级重量级锁。', '["synchronized 锁升级方向单向不可逆","偏向锁可撤销、轻量级与重量级锁不降级","锁升级的典型触发条件"]', '["整体方向上是否可逆","偏向锁可以被撤销/降级，轻量级锁、重量级锁之间是否还能降级，典型触发点在哪。"]', '["synchronized · 锁升级过程"]', '说明升级是单向的还是可降级的、为什么', '中档', '原理追问', 11, NULL, 1793088839248),
	(38, 2, 2, 4, 7, '写一段 Java 代码，让线程在等待某个锁时最多等待 3 秒：拿到锁就继续，超时还没拿到就放弃本次加锁、执行超时分支并退出等待。请给出代码片段，并简要说明用的是哪个 API、超时参数怎么传。', '用 **ReentrantLock 的 tryLock(timeout, TimeUnit)**，它会在指定时间内尝试获取锁，超时仍未获取就返回 false，不会一直阻塞：

```java
ReentrantLock lock = new ReentrantLock();

if (lock.tryLock(3, TimeUnit.SECONDS)) {
    try {
        // 拿到锁，执行临界区
    } finally {
        lock.unlock();
    }
} else {
    // 超时未拿到锁，放弃本次加锁，走超时分支
}
```

关键点：**tryLock(long timeout, TimeUnit unit)** 传入超时时长与时间单位，返回 **boolean** 表示是否在限时内拿到锁；配合 **try/finally 保证拿到锁时一定 unlock()**，超时分支不能调用 unlock，否则会抛 IllegalMonitorStateException。

扩展：synchronized 关键字没有超时等待能力，线程会一直阻塞到拿到锁，所以需要超时退出的场景必须用 Lock 体系的 API。', '["ReentrantLock.tryLock 超时获取锁的用法","synchronized 不支持超时等待"]', '["写一段 Java 代码，让线程在等待某个锁时最多等待 3 秒：拿到锁就继续，超时还没拿到就放弃本次加锁、执行超时分支并退出等待。请给出代码片段，并简要说明用的是哪个 API、超时参数怎么传。"]', '["ReentrantLock · tryLock 超时与可中断"]', '写出让等待锁的线程能超时退出的代码片段', '基础', '概念辨析', 7, NULL, 1793088851894),
	(39, 2, 2, 4, 10, '线上配置中心服务有一个 Config 类，字段 configVersion 记录配置版本号，另一个线程轮询检查该版本号判断配置是否更新。开发同学把 configVersion 声明为 volatile 后，更新线程的修改就被轮询线程立即看到了。请说明：① 为什么普通变量可能看不到修改？② volatile 是通过什么机制让另一个线程「立即可见」的？③ 如果把 configVersion 从 int 改成 volatile 修饰的 AtomicInteger，并且用 compareAndSet 更新版本号，这样做主要是为了解决什么问题？', '① **普通变量不保证可见性**：线程可能把变量缓存在自己的副本（寄存器/L1 缓存）中，加上编译器与 CPU **指令重排**，轮询线程可能一直读到旧值，修改对它不立即可见。
② **volatile 靠内存屏障 + 缓存一致性**：写 volatile 变量时插入写屏障，把新值**立即刷新回主内存**，并通过 **MESI 等缓存一致性协议**让其他线程的缓存副本失效；读时强制从主内存重新读取。屏障同时**禁止前后指令重排**，所以轮询线程能「立即」看到新值。
③ **改成 AtomicInteger + CAS 是为了保证原子性**：volatile int 的自增是「读-改-写」复合操作，多线程下会丢失更新；compareAndSet 是原子的 CAS 操作，配合失败重试，保证版本号更新不丢、不产生竞态。', '["volatile 可见性原理（内存屏障）","CAS 与原子类保证复合操作原子性"]', '["为什么普通变量可能看不到修改？","volatile 是通过什么机制让另一个线程「立即可见」的？","如果把 configVersion 从 int 改成 volatile 修饰的 AtomicInteger，并且用 compareAndSet 更新版本号，这样做主要是为了解决什么问题？"]', '["volatile · 可见性与原子性边界","volatile · 典型使用场景"]', '配置热更新场景：让另一线程及时看到新配置', '大题', '场景应用', 23, NULL, 1793088854196),
	(40, 2, 2, 4, 9, '线程 A 依次执行「写 x=1」「写 y=2」，线程 B 读到 y=2 却读到 x=0。请解释：① 什么是指令重排序？② 这个现象是怎么由重排序造成的？③ 什么是重排序带来的可见性问题？它和「指令乱序执行」是一回事吗？', '**① 指令重排序：编译器和处理器为优化性能，在不改变单线程语义的前提下调整指令的实际执行顺序。** **② 本例中 A 线程的「写 y=2」被重排到「写 x=1」之前执行，B 线程先读到 y=2，此时 x=1 还未执行，故读到 x=0。** **③ 重排序带来的可见性问题：线程间观察到的更新顺序与代码书写顺序不一致，可能读到中间状态；它与「指令乱序执行」不是一回事**——乱序执行是 CPU 流水线层面的现象，重排序还包括编译器重排和内存系统重排，且都受 as-if-serial / happens-before 约束，可用 volatile 或加锁禁止。', '["指令重排序的定义与层面","重排序导致的可见性问题"]', '["什么是指令重排序？","这个现象是怎么由重排序造成的？","什么是重排序带来的可见性问题？它和「指令乱序执行」是一回事吗？"]', '["volatile · 指令重排序与 happens-befo"]', '解释什么是指令重排序以及带来的可见性问题', '中档', '原理追问', 11, NULL, 1793088866398),
	(41, 2, 2, 6, 5, '调用 notify() 唤醒等待线程后，被唤醒的线程为什么不能直接往下执行，而要继续 wait() 直到条件满足？', '因为 **notify() 只是"有线程可能可以继续了"的通知，不等于条件已经成立**。被唤醒的线程只是从等待队列移入同步队列，重新去竞争锁；而**等待的条件（如队列非空）可能在它抢到锁之前又被其他线程改变了**。所以正确写法是 **`while (条件不满足) wait();`**，醒来后重新检查条件，不满足就继续 wait。这就是**"条件等待必须放在循环里"**的规范，可以防止**虚假唤醒（spurious wakeup）**和条件被中途破坏导致的逻辑错误。', '["wait/notify 的条件等待语义","虚假唤醒与 while 循环检查条件"]', '["调用 notify() 唤醒等待线程后，被唤醒的线程为什么不能直接往下执行，而要继续 wait() 直到条件满足？"]', '["synchronized · 等待唤醒与线程协作"]', 'notify 之后为何还要继续 wait 直到条件满足', '基础', '概念辨析', 8, NULL, 1793090394521),
	(42, 2, 2, 6, 6, 'Lock 接口的 lock() 与 lockInterruptibly() 在线程等待锁时被其他线程 interrupt()，两者行为有何差异？', '**lock() 在等待锁时是"不可中断"的**：即使被 interrupt()，它也不会响应中断，而是**继续等待直到拿到锁**，中断标志只是被记录下来，拿到锁后线程继续运行。**lockInterruptibly() 是"可中断"的**：等待过程中被 interrupt() 会**立刻抛出 InterruptedException**，放弃获取锁并退出，不会继续阻塞。因此在需要**可取消、避免死等**的场景应选用 lockInterruptibly()，代价是必须处理 InterruptedException。', '["lock() 与 lockInterruptibly() 的中断响应差异","可中断锁获取的适用场景"]', '["Lock 接口的 lock() 与 lockInterruptibly() 在线程等待锁时被其他线程 interrupt()，两者行为有何差异？"]', '["ReentrantLock · tryLock 超时与可中断"]', 'lockInterruptibly 与 lock 在被中断时行为差异', '基础', '概念辨析', 8, NULL, 1793090394525),
	(43, 2, 2, 6, 7, '用一个 Lock 配合两个 Condition 实现有界队列的存取等待，应该怎么做？说明两个 Condition 各自的作用，以及 put/take 在什么条件下 await、什么时机 signal。', '用**一把 Lock 创建两个 Condition**：`notFull` 表示"队列未满"，`notEmpty` 表示"队列非空"。**put()** 在队列已满时调用 `notFull.await()` 等待；放入元素后调用 `notEmpty.signal()` 唤醒等待的消费者。**take()** 在队列为空时调用 `notEmpty.await()` 等待；取出元素后调用 `notFull.signal()` 唤醒等待的生产者。两个 Condition 把生产者和消费者**分到不同的等待队列**，只唤醒对应一方，避免 `signalAll()` 唤醒大量无关线程，提高效率。', '["Condition 的 await/signal 配合 Lock","两个 Condition 分离生产者与消费者等待队列"]', '["用一个 Lock 配合两个 Condition 实现有界队列的存取等待，应该怎么做","说明两个 Condition 各自的作用，以及 put/take 在什么条件下 await、什么时机 signal。"]', '["Condition · 多条件等待唤醒"]', '用两个 Condition 实现有界队列的存取等待', '基础', '概念辨析', 7, NULL, 1793090394528),
	(44, 2, 2, 6, 8, 'volatile 修饰的变量在多线程下为何能禁止指令重排序？volatile 的 happens-before 语义具体指什么？', '**volatile 通过内存屏障（Memory Barrier）禁止重排序**：写操作后插入 StoreLoad 等屏障、读操作前插入 LoadLoad/LoadStore 屏障，保证写操作之前的读写不会重排到写之后、读操作之后的读写不会重排到读之前。**happens-before 语义**指：**volatile 变量的写 happens-before 于随后对该变量的读**。因此一个线程写入 volatile 变量前的所有操作，对另一个线程读到该变量后的操作**可见**，从而既保证**可见性**又保证**有序性**，常用于状态标志、双检锁单例等场景。', '["volatile 禁止重排序的内存屏障机制","volatile 的 happens-before 语义"]', '["volatile 修饰的变量在多线程下为何能禁止指令重排序","volatile 的 happens-before 语义具体指什么"]', '["volatile · 指令重排序与 happens-befo"]', 'volatile 为何能禁止重排序、happens-before 含义', '中档', '原理追问', 11, NULL, 1793090394528),
	(45, 2, 2, 6, 1, '高并发下用一个计数器做限流统计时，为什么通常用 CAS（如 AtomicInteger）的原子自增，而不用 synchronized 包住 count++ ？请从竞争激烈程度与开销两方面说明。', '**计数器自增用 CAS 而不是 synchronized**。原因：
① 开销：CAS 是**无锁**的，compareAndSet 一次完成读改写，失败才重试，全程不阻塞线程，省掉锁的申请释放、阻塞唤醒与上下文切换；synchronized 每次都要走加锁/解锁流程。
② 竞争：自增单次执行极快、冲突窗口小，**CAS 成功率高**，自旋代价低；只有竞争极端激烈、自旋大量失败空耗 CPU 时，才反过来考虑加锁或换 LongAdder。', '["CAS 原子自增与 synchronized 的适用场景对比","短临界区高竞争下的开销差异"]', '["高并发下用一个计数器做限流统计时，为什么通常用 CAS（如 AtomicInteger）的原子自增，而不用 synchronized 包住 count++","请从竞争激烈程度与开销两方面说明。"]', '["CAS · 原理与三大问题"]', '高并发限流计数为何不用 synchronized 而用 CAS', '基础', '概念辨析', 8, NULL, 1793090398763),
	(46, 2, 2, 6, 2, '多线程频繁执行一段很短的临界区代码时，一个 synchronized 锁对象的状态会如何一步步演变？请按顺序说明，并讲出每次演变的动因。', '**结论：短临界区下锁状态典型演变是 无锁 → 偏向锁 → 轻量级锁 →（竞争激烈时）重量级锁。**
1）**无锁**：对象刚创建，无任何线程持有。
2）**偏向锁**：只有一个线程反复进入临界区时，JVM 用**偏向锁**记录该线程 ID，让同一线程再次进入**几乎无同步开销**（动因：消除无竞争时的加锁开销）。
3）**轻量级锁**：出现少量交替竞争，升级为轻量级锁，用**CAS 自旋**尝试获取（动因：避免线程阻塞/唤醒的重量级开销）。
4）**重量级锁**：自旋竞争加剧、多线程争用时升级为重量级锁，走**OS 互斥量**，竞争线程**阻塞挂起**（动因：自旋已不划算，用阻塞换 CPU 空转）。
短临界区的意义：执行时间短，自旋成功率高，轻量级锁阶段停留久、性价比高。', '["synchronized 锁升级过程（偏向锁→轻量级锁→重量级锁）","各阶段升级动因"]', '["多线程频繁执行一段很短的临界区代码时，一个 synchronized 锁对象的状态会如何一步步演变","请按顺序说明，并讲出每次演变的动因。"]', '["synchronized · 锁升级过程"]', '多线程短临界区下锁状态如何演变并说明动因', '基础', '概念辨析', 8, NULL, 1793090398763),
	(47, 2, 2, 6, 3, '多线程里要把一个构造耗时的对象安全地发布给其他线程（例如用双检锁单例），为什么成员引用必须声明为 volatile？请说明它解决了什么问题。', '**成员引用必须加 volatile，为了禁止指令重排序并保证可见性**。
new 一个对象分三步：分配内存 → 执行构造初始化 → 引用赋值。这三步可能被重排，若**引用赋值先于构造完成**执行，另一个线程在最外层判空时会看到非 null 的引用，直接拿到**未构造完的中间态对象**，用它的字段就出错。加 volatile 后写引用具有**禁止重排 + 写立即可见**的语义，其他线程要么看到 null，要么看到构造完成的对象。', '["volatile 的可见性与禁止重排序","双检锁单例中的安全发布（对象逸出）"]', '["多线程里要把一个构造耗时的对象安全地发布给其他线程（例如用双检锁单例），为什么成员引用必须声明为 volatile","请说明它解决了什么问题。"]', '["volatile · 典型使用场景"]', '一次性发布安全构造对象为何用 volatile 引用', '基础', '概念辨析', 8, NULL, 1793090398763),
	(48, 2, 2, 6, 9, 'volatile 只保证可见性与有序性，但没有原子性；可是"一个布尔开关 flag"用 volatile 修饰就足够控制线程停/启，而"计数器 count++"用 volatile 修饰却不能保证结果正确。请辨析：①为什么只做标记位（状态开关）时 volatile 就够用？②为什么做计数（自增）时 volatile 就不够用？分别说明背后的语义依据。', '**① 标记位够用**：flag 只被**单次赋值**（写）和**单次读取**判断，单次读写本身是原子的，volatile 再保证**写入立即对其他线程可见**（也防止循环读被优化），线程就能及时感知停止信号。
**② 计数不够**：count++ 是**读-改-写三步**复合操作，volatile 只保证每一步单次读写的可见性/有序性，**不保证三步整体原子**，两个线程会读到同一旧值各加一次，**丢更新**。
核心：volatile 保证**单次读写的可见性与有序性**，不保证**复合操作的原子性**，自增要靠 AtomicInteger（CAS）或锁。', '["volatile 的可见性与有序性语义边界","volatile 不保证原子性：读—改—写复合操作"]', '["为什么只做标记位（状态开关）时 volatile 就够用？","为什么做计数（自增）时 volatile 就不够用？分别说明背后的语义依据。"]', '["volatile · 可见性与原子性边界"]', '标记位为何够用、计数为何不够用的辨析', '中档', '原理追问', 11, NULL, 1793090417028),
	(49, 2, 2, 6, 10, '某电商库存服务要实现"扣减库存"：商品库存数存在 MySQL 一行中，多实例部署、QPS 约 500，要求**不能超卖**，且高并发下响应时间不能明显劣化。当前团队提出三个候选方案：
  方案一：应用层用 `synchronized` 把"查询库存 + 判断 + 扣减"整段代码锁住，数据库无任何改动。
  方案二：SQL 写成 `UPDATE goods SET stock = stock - 1 WHERE id = ? AND stock > 0`，靠数据库行级锁与条件更新保证。
  方案三：引入 Redis，用 `DECR`（或 Lua 脚本）在 Redis 中扣减，异步同步到 MySQL。

请回答：
① 方案一在"多实例部署"下是否能防住超卖？为什么？
② 三个方案各自依赖的"互斥保证"来自哪里（进程内锁 / 数据库 / 缓存），并说明它们各自的关键约束（如多实例、事务、数据一致性）。
③ 综合 QPS 500、不能超卖、响应时间三个约束，你会选哪个方案？给出取舍理由。', '**① 不能**。synchronized 是 JVM **进程内锁**，锁只在本实例生效，多实例各把各的锁，跨实例无互斥，仍会超卖。
**②** 方案一互斥来自**进程内 JVM 锁**，约束是只在单实例有效；方案二来自**数据库**：`stock>0` 条件判断与扣减在一个语句内**原子**完成，行锁保持到事务提交，约束是热点行竞争、要用**受影响行数**判断成败；方案三来自 **Redis 单线程执行/Lua 原子扣减**（DECR/Lua，不是 setnx），约束是 **Redis 与 MySQL 一致性**，宕机或同步失败会丢数据，需对账兜底。
**③ 选方案二**。QPS 500 数据库绰绰有余，条件更新一行 SQL **强一致、天然防超卖**、改动小；方案三的性能优势在此量级用不上，反而引入一致性风险。日后 QPS 上万再上 Redis 预扣+异步落库+定时对账。', '["synchronized 进程内互斥与多实例下的失效边界","数据库条件更新 + 行锁的原子性；方案选型中的正确性 / 吞吐 / 一致性取舍"]', '["方案一在\"多实例部署\"下是否能防住超卖？为什么？","三个方案各自依赖的\"互斥保证\"来自哪里（进程内锁 / 数据库 / 缓存），并说明它们各自的关键约束（如多实例、事务、数据一致性）。","综合 QPS 500、不能超卖、响应时间三个约束，你会选哪个方案？给出取舍理由。"]', '["ReentrantLock · 与 synchronized","ReentrantLock · 公平锁与非公平锁","AtomicInteger · 常用方法与适用场景"]', '库存扣减场景对比三方案并给出取舍理由', '大题', '场景应用', 23, NULL, 1793090417033),
	(50, 2, 2, 6, 4, '请写出 synchronized 的三种常见用法的代码形式：① synchronized(this) 同步代码块；② synchronized(类.class) 同步代码块；③ synchronized 修饰方法（普通方法或静态方法）。并简要说明每种形式锁的是什么对象。', '**① synchronized(this){ ... }** —— 锁的是**当前实例对象**。
**② synchronized(Xxx.class){ ... }** —— 锁的是 **Class 对象**（全局唯一，跨实例互斥）。
**③ 修饰方法**：`public synchronized void a()` 锁**当前实例**，等价 synchronized(this)；`public static synchronized void b()` 锁**类对象**，等价 synchronized(Xxx.class)。
注意：实例锁与类锁锁的不是同一个对象，两者之间**不互斥**。', '["synchronized 三种写法对应的锁对象","实例锁与类锁（Class 锁）的区别"]', '["synchronized(this) 同步代码块","synchronized(类.class) 同步代码块","synchronized 修饰方法（普通方法或静态方法）。并简要说明每种形式锁的是什么对象。"]', '["synchronized · 三种使用形式与语义"]', '写 synchronized(this)、类.class、方法三种形式代码', '基础', '概念辨析', 8, NULL, 1793090425113),
	(51, 2, 2, 7, 1, '两个线程各执行一次 `i++`（i 是 volatile long）。volatile 保证可见性，为什么两个线程执行完后 i 仍可能不是 2？请说明根本原因。', '**volatile 不保证原子性，只保证可见性**。i++ 是"读-改-写"三步复合操作：两个线程可能都先读到旧值 i=0，再各自改、各自写回，后写的覆盖前写的，最终只加了 1。volatile 只保证每次读都是最新值、写立即刷回主内存，无法把三步合成一个不可分割的动作，所以要原子自增得用 AtomicLong 或 synchronized。', '["volatile 语义（可见性、有序性）","volatile 不保证原子性"]', '["两个线程各执行一次 `i++`（i 是 volatile long）。volatile 保证可见性，为什么两个线程执行完后 i 仍可能不是 2","请说明根本原因。"]', '["volatile · 可见性与原子性边界"]', '两个线程读写同一 volatile long 为何仍可能读到中间值', '基础', '概念辨析', 8, NULL, 1793150253006),
	(52, 2, 2, 7, 2, 'CAS 在高并发下自旋重试频繁、CPU 开销大，通常有哪些应对思路？又在什么情况下应该放弃 CAS、退回加锁？', '应对思路有两条：一是**降竞争**，把单一热点拆成多份分别累加（LongAdder 思路）、批量合并更新、失败后退避再重试；二是**限自旋**，规定最大重试次数，超限就升级为加锁。放弃 CAS 的时机：**写多读少、竞争激烈且长期不降**，或临界区涉及多个变量需要一致修改，或重试频繁仍拿不到预期值——这时 CAS 的 CPU 开销和吞吐都劣于直接加锁，应退回 synchronized / Lock。', '["CAS 自旋开销与优化（分段、退避、限次）","CAS 与加锁的选型取舍"]', '["CAS 在高并发下自旋重试频繁、CPU 开销大，通常有哪些应对思路","又在什么情况下应该放弃 CAS、退回加锁"]', '["CAS · 原理与三大问题"]', 'CAS 自旋开销大如何应对、何时应退回加锁', '基础', '概念辨析', 8, NULL, 1793150253006),
	(53, 2, 2, 7, 3, '有一个 volatile 修饰的引用型字段 `volatile Config config`，另一个线程把 `config` 引用整体替换成了新对象。请问：① 另一线程能否看到新引用？② 对同一个 Config 对象内部字段的改动（不替换引用），能否被其他线程看到？请分别说明原因。', '**① 能看到。** volatile 修饰的是 `config` 这个**引用**，引用被整体替换后，其他线程读 `config` 时会读到最新引用（最新对象），这属于对 volatile 变量本身的写，可见性有保证。

**② 不一定能被看到。** volatile 只保证「引用」这一层的可见性，**不保证该对象内部字段的可见性**。对同一 Config 对象内部字段的修改，如果该字段本身没有 volatile/synchronized 等同步手段，其他线程可能读到旧值（受缓存、指令重排影响）。

所以要让对象字段的改动可见，需把**字段也声明为 volatile**，或用 synchronized / Lock 同步访问，或不可变对象（final）。', '["volatile 修饰引用的语义边界","volatile 不传递到对象内部字段"]', '["另一线程能否看到新引用？","对同一个 Config 对象内部字段的改动（不替换引用），能否被其他线程看到？请分别说明原因。"]', '["volatile · 典型使用场景"]', 'volatile 修饰的引用型对象，其字段改动能否被看到', '基础', '概念辨析', 8, NULL, 1793150253025),
	(54, 2, 2, 7, 4, '父类 Parent 有 synchronized 方法 `show()`，子类 Child 继承了 `show()`；另外 Child 自己又定义了一个 synchronized 方法 `print()`。请问：两个线程分别调用同一个 Child 对象的 `show()` 和 `print()`，能并发执行吗？调用 `show()` 和 Parent 中另一个 synchronized 方法 `other()` 呢？请说明理由。', '**两种情况都不能并发**。synchronized 实例方法的锁是**当前对象实例**，与方法定义在父类还是子类无关：show() 虽然定义在 Parent 里，被继承后调用时锁的仍是这个 Child 对象；Child.print() 锁的也是同一个对象，两个线程抢同一把对象监视器，只能串行执行。同理 Parent.other() 也是 synchronized 实例方法，锁的还是这同一个实例，所以 show() 与 other() 同样互斥、不能并发。', '["synchronized 实例方法锁对象（this）","继承关系下的锁归属（锁对象不随继承改变）"]', '["父类 Parent 有 synchronized 方法 `show()`，子类 Child 继承了 `show()`；另外 Child 自己又定义了一个 synchronized 方法 `print()`。请问：两个线程分别调用同一个 Child 对象的 `show()` 和 `print()`，能并发执行吗","调用 `show()` 和 Parent 中另一个 synchronized 方法 `other()` 呢","请说明理由。"]', '["synchronized · 三种使用形式与语义"]', '继承关系下 synchronized 方法的互斥情况判断', '基础', '概念辨析', 8, NULL, 1793150253027),
	(55, 2, 2, 9, 6, '用 tryLock() 抢锁时，unlock() 放在 finally 里要怎么写才安全？为什么不能直接在 finally 里无条件调用 unlock()？', '**用布尔变量记录 tryLock() 的返回值，只有抢到锁才在 finally 里 unlock**：`boolean locked = lock.tryLock(); try { ... } finally { if (locked) lock.unlock(); }`。因为 tryLock() 失败时当前线程没有持有锁，直接 unlock() 会抛 **IllegalMonitorStateException**，还可能掩盖业务异常。这是 tryLock 与 lock() 在 finally 写法上的关键差异。', '["tryLock 返回值语义","unlock 必须与持有锁的线程配对"]', '["用 tryLock() 抢锁时，unlock() 放在 finally 里要怎么写才安全","为什么不能直接在 finally 里无条件调用 unlock()"]', '["ReentrantLock · tryLock 超时与可中断"]', 'tryLock 抢到锁后 finally 里 unlock 该怎么写才安全', '基础', '概念辨析', 8, NULL, 1793157066591),
	(56, 2, 2, 7, 9, '线程 A 先启动，独自把一个 synchronized 方法执行完后退出；线程 B 随后才启动并进入同一把锁。请问：A 期间这把锁处于什么状态？B 进入时锁处于什么状态，为什么？', '**A 独自执行期间锁处于偏向锁状态**。因为该对象头里的锁记录被写入 A 的线程 ID，JVM 认为"没有竞争"，A 再次进入同一把锁时只需做一次 CAS 比对线程 ID，无需反复加锁解锁，代价接近无锁。

**B 进入时偏向锁被撤销，锁升级为轻量级锁**。因为出现了第二个线程争用同一对象，偏向假设失效；JVM 在安全点把对象头恢复成无锁状态，B 在自己的栈帧中创建 Lock Record，把对象头 Mark Word 拷贝进去并 CAS 置换为指向 Lock Record 的指针，从而进入轻量级锁自旋等待；若竞争继续加剧，才会升级为重量级锁。

**结论：偏向锁服务于单线程反复进出的场景，轻量级锁服务于"少量线程、错峰进入"的场景，二者的启用条件本质上都是"是否有第二个线程来争用"。**', '["偏向锁的启用条件（单线程反复进入、无竞争）","轻量级锁的启用条件（少量线程交替进入、短暂竞争，自旋等待）","偏向锁撤销与升级触发条件"]', '["线程 A 先启动，独自把一个 synchronized 方法执行完后退出；线程 B 随后才启动并进入同一把锁。请问：A 期间这把锁处于什么状态","B 进入时锁处于什么状态，为什么"]', '["synchronized · 锁升级过程"]', '偏向锁与轻量级锁分别在什么竞争程度下被启用', '中档', '原理追问', 11, NULL, 1793150254553),
	(57, 2, 2, 7, 5, '生产者消费者模型中，什么时候应该用 notifyAll 而不是 notify？反过来，什么条件下用 notify 是安全的？请分别说明理由。', '**等待队列里线程等待的条件不一致时必须用 notifyAll**：比如生产者和消费者都在同一队列上等，notify 可能唤醒同类线程，被唤醒者发现条件仍不满足又 wait，信号被吞掉，导致程序假死；notifyAll 让所有线程重新竞争、重检条件，才能保证推进。**notify 安全的条件是等待线程同质**——等待的是同一个条件，唤醒任意一个都能继续干活，典型是单生产者单消费者。另外无论用哪个，唤醒后都必须在 while 里重新检查条件。', '["wait/notify 机制","生产者消费者中的通知策略"]', '["生产者消费者模型中，什么时候应该用 notifyAll 而不是 notify","反过来，什么条件下用 notify 是安全的","请分别说明理由。"]', '["synchronized · 等待唤醒与线程协作"]', '生产者消费者中 notifyAll 与 notify 的取舍场景', '基础', '概念辨析', 8, NULL, 1793150254744),
	(58, 2, 2, 7, 7, 'Condition 的 await() 与 Object 的 wait() 在调用前提上有什么不同？违反各自前提会怎样？', '**调用前提**：**Object.wait()** 必须在持有该对象的 **synchronized 监视器锁**（synchronized(obj){...}）时调用；**Condition.await()** 必须先通过 **Lock.lock()** 获得与该 Condition 绑定的那把 **Lock**（Condition 由 lock.newCondition() 创建）后调用。
**违反后果**：两者的共同点是调用线程必须**持有对应的锁**，否则抛 **IllegalMonitorStateException**；wait() 没在 synchronized 块内、await() 没先 lock() 都属于这种情况。
**区别本质**：wait/notify 依托对象监视器，一个对象只有一组等待队列；Condition 依托显式 Lock，一把 Lock 可以创建**多个 Condition**，实现分组等待与定向唤醒。', '["await 的调用前提（须持有对应 Lock）","Object.wait 的 synchronized 前提"]', '["Condition 的 await() 与 Object 的 wait() 在调用前提上有什么不同","违反各自前提会怎样"]', '["Condition · 多条件等待唤醒"]', 'Condition await 与 Object wait 的调用前提差异', '基础', '概念辨析', 7, NULL, 1793150254744),
	(59, 2, 2, 7, 6, 'Lock 接口里 tryLock() 与 tryLock(long timeout, TimeUnit unit) 的返回值语义分别是什么？两者的锁获取结果判定有什么区别？在拿不到锁时，前者与后者的行为差异是什么（是否阻塞、阻塞多久）？', '**两个方法都返回 boolean，true 表示拿到锁、false 表示没拿到**。区别在于判定范围：tryLock() 只看**当前瞬时**锁是否空闲，立即给出结论；tryLock(timeout, unit) 的结论覆盖**整个等待窗口**，窗口内任意时刻拿到锁就返回 true。行为差异：tryLock() **不阻塞**，拿不到立即返回 false；带 timeout 的版本会**阻塞等待，最多等 timeout**，超时返回 false，等待期间还可被中断并抛出 InterruptedException。', '["tryLock() 无参版的非阻塞语义与返回值含义","tryLock(timeout) 带超时版的限时等待语义与两者行为差异"]', '["Lock 接口里 tryLock() 与 tryLock(long timeout, TimeUnit unit) 的返回值语义分别是什么","两者的锁获取结果判定有什么区别","在拿不到锁时，前者与后者的行为差异是什么（是否阻塞、阻塞多久）"]', '["ReentrantLock · tryLock 超时与可中断"]', 'tryLock 无参版与带超时版的返回值语义与用法区别', '基础', '概念辨析', 8, NULL, 1793150266425),
	(60, 2, 2, 7, 8, '有线程 A 与线程 B 操作同一共享变量：A 执行 `flag = true; x = 42;`，B 执行 `if (flag) { System.out.println(x); }`。已知 A 对 flag 的写 happens-before B 对 flag 的读（读到了 true）。请回答：
① happens-before 保证的"可见性"，究竟保证的是什么？是否保证两个操作在物理时间上先后发生？
② 为什么 A 写入的 x=42 对 B 也保证可见？
③ 如果 A 的两行代码互换顺序，上述保证还成立吗？为什么？', '① **happens-before 保证的是可见性与有序性，不是物理时间先后**。它说的是：如果操作 A happens-before 操作 B，那么 A 的执行结果对 B 可见（且 A 的执行顺序在代码逻辑上先于 B），但这**不等于** A 在时钟时间上一定先完成——现代 CPU 与 JIT 可能对无依赖指令重排序。happens-before 是**内存模型层面的偏序关系**，不是时间轴上的先后。
② 依据 happens-before 的**传递性（transitivity）**：A 写 x=42 happens-before A 写 flag=true（**程序顺序规则**）；A 写 flag=true happens-before B 读 flag=true（题设给定，通常由 volatile/synchronized/锁等建立）；两者传递得到 A 写 x=42 happens-before B 读 x，因此 B 读到的 x 一定是 42。
③ **不成立**。若写成 `x = 42; flag = true;` 顺序互换为 `flag = true; x = 42;`（即先写 flag 后写 x），则 A 写 x 与 A 写 flag 之间只有 flag 在前的程序顺序，无法通过传递性把 x 的写"挂到"flag 的写之前，B 读到 flag=true 之后再读 x 可能读到旧值。可见性保证依赖于**写操作之间、以及写→flag→读**这条链路的顺序，顺序破坏则保证失效。', '["happens-before 的可见性语义","happens-before 传递性与程序顺序规则"]', '["happens-before 保证的\"可见性\"，究竟保证的是什么？是否保证两个操作在物理时间上先后发生？","为什么 A 写入的 x=42 对 B 也保证可见？","如果 A 的两行代码互换顺序，上述保证还成立吗？为什么？"]', '["volatile · 指令重排序与 happens-befo"]', 'happens-before 保证的可见性与时间先后的关系辨析', '中档', '原理追问', 11, NULL, 1793150284274),
	(61, 2, 4, 14, 7, '线程池最大线程数（maximumPoolSize）在 CPU 密集型和 IO 密集型任务下，通常分别怎么取？请说明取值差异的原因。', '**CPU 密集型取核数+1**：线程再多会互相争抢 CPU、增加上下文切换，+1 只是防某线程偶发阻塞让 CPU 空闲；**IO 密集型取核数×2 或更高**：线程大部分时间在等待 IO，需要更多线程把 CPU 时间填满。这是经验公式，实际以压测为准。', '["CPU 密集型线程数取值","IO 密集型线程数取值"]', '["线程池最大线程数（maximumPoolSize）在 CPU 密集型和 IO 密集型任务下，通常分别怎么取","请说明取值差异的原因。"]', '["自定义线程池 · 线程数怎么定"]', 'CPU 密集与 IO 密集线程数怎么取', '基础', '概念辨析', 9, NULL, 1793608962406),
	(62, 2, 2, 7, 10, '某电商订单系统中，计数服务同时承担两类任务：一类是高频的热点计数（每秒数万次的页面浏览量、库存扣减计数，读多写少，要求极高吞吐、允许最终一致）；另一类是低频但耗时的临界区（如批量导出对账文件、退款审核状态流转，单次耗时数十毫秒到秒级，要求严格互斥、可阻塞等待）。现有三种可选同步手段：volatile、synchronized、ReentrantLock（含其 Condition 等待能力）。请回答：
① 对热点计数这类高频更新的计数器，为什么不能用 volatile 保证原子性？如果只能在 synchronized 与 ReentrantLock 中选一个来保护热点计数，你会选哪个，为什么？
② 对耗时的导出/审核临界区，volatile 能否胜任？请说明原因。在 synchronized 与 ReentrantLock 之间做选择时，ReentrantLock 的哪些能力更适合这类临界区（说出至少两点，并说明各自解决什么问题）？
③ 如果让你给这两类任务设计一个统一的分工原则：什么情况下用 synchronized、什么情况下用 ReentrantLock、什么情况下只用 volatile 就够？请给出你的取舍结论并说明依据。', '① **volatile 只保证可见性与有序性，不保证复合操作的原子性**：count++ 是「读-改-写」三步，多线程下会丢失更新。热点计数属于高并发短临界区，**优先选 synchronized**（JDK6 后偏向锁/轻量级锁优化后性能已与 ReentrantLock 接近甚至更好，且代码更简洁、不会忘记释放锁），ReentrantLock 在此场景无明显收益。
② **volatile 完全无法胜任**，因为它没有互斥语义，慢操作会与其它写操作交错执行，导致数据不一致。耗时临界区更适合 **ReentrantLock**，优势至少两点：**可中断地获取锁（lockInterruptibly）**——长时间等待时线程可被取消；**支持多个 Condition、可设置 tryLock 超时**——比如导出线程等资源、审核线程等前置状态，可精准唤醒、可限时拿锁避免无限阻塞；此外还有**公平锁选项**，防止慢操作长期被饿死。
③ 分工原则：**volatile 仅用于一写多读的标志位或状态发布**（如开关、初始化完成标志），无复合写就不用锁；**synchronized 用于临界区短、并发高、逻辑简单**的普通互斥（热点计数、简单缓存更新），开销小、语法简单、自动释放；**ReentrantLock 用于需要高级控制的场景**：可中断、超时获取、多条件等待、公平锁需求、或临界区较长需要精细调度。取舍依据是「需求复杂度 vs 实现成本」——synchronized 覆盖 90% 的常规互斥，ReentrantLock 在需要显式控制语义时才引入。', '["volatile 的语义（可见性、有序性、不保证原子性）","synchronized 与 ReentrantLock 的选型取舍"]', '["对热点计数这类高频更新的计数器，为什么不能用 volatile 保证原子性？如果只能在 synchronized 与 ReentrantLock 中选一个来保护热点计数，你会选哪个，为什么？","对耗时的导出/审核临界区，volatile 能否胜任？请说明原因。在 synchronized 与 ReentrantLock 之间做选择时，ReentrantLock 的哪些能力更适合这类临界区（说出至少两点，并说明各自解决什么问题）？","如果让你给这两类任务设计一个统一的分工原则：什么情况下用 synchronized、什么情况下用 ReentrantLock、什么情况下只用 volatile 就够？请给出你的取舍结论并说明依据。"]', '["ReentrantLock · 与 synchronized","ReentrantLock · 公平锁与非公平锁","AtomicInteger · 常用方法与适用场景"]', '热点计数器与慢操作临界区混合服务，三者如何分工取舍', '大题', '场景应用', 23, NULL, 1793150293420),
	(63, 2, 2, 8, 5, '线程间竞争的等待时间差异很大（有的线程几毫秒就释放，有的要等上百毫秒），用哪种显式锁的构造方式更合适？为什么？', '用 **ReentrantLock 的 `tryLock(long timeout, TimeUnit unit)` 带超时的获取方式**更合适。因为竞争者持有锁的时间差异很大，用普通 `lock()` 会让后来的线程死等、排队堆积；而 tryLock 允许每个线程按自己可接受的等待时间去争取：在超时内拿到就执行，拿不到就返回 false，走放弃、降级或排队稍后重试的逻辑，把「等多久」变成可控的。必要时还可配合 `new ReentrantLock(true)` 公平锁，让等得久的线程优先获取。', '["公平锁与非公平锁的差异与选型","线程饥饿与锁吞吐量的取舍"]', '["线程间竞争的等待时间差异很大（有的线程几毫秒就释放，有的要等上百毫秒），用哪种显式锁的构造方式更合适？为什么？"]', '["ReentrantLock · 公平锁与非公平锁"]', '线程等待时间差异大时，构造参数怎么选及理由', '基础', '概念辨析', 8, NULL, 1793155239786),
	(64, 2, 2, 8, 7, '使用 Condition 时，什么时候用单个 Condition 就够，什么时候需要多个 Condition？signal 应该放在什么位置？', '**单 Condition**：所有等待线程都在等同一类条件（如简单的有界队列非空/非满），用 **await/signalAll** 即可。**多 Condition**：存在多种等待原因（如生产者等"不满"、消费者等"非空"），分别建 notFull / notEmpty 两个 Condition，**精确 signal 对应的那个**，避免惊群和无效唤醒。**signal 应放在持有锁、且条件已满足之后**，即在修改共享状态的同步块内、解锁之前调用，确保被唤醒线程重新竞争锁时条件一定已成立。', '["Condition 单个与多个的使用场景","signal/signalAll 的调用位置与惊群问题"]', '["使用 Condition 时，什么时候用单个 Condition 就够，什么时候需要多个 Condition","signal 应该放在什么位置"]', '["Condition · 多条件等待唤醒"]', '单 Condition 与多 Condition 的选择依据与 signal 调用位置', '基础', '概念辨析', 7, NULL, 1793155239786),
	(65, 2, 2, 8, 8, 'volatile 变量的写和读，是如何与它前后的普通读写建立可见性关系的？请从 happens-before 的角度说明。', '**volatile 写**之前的所有普通写，对随后读到该 volatile 变量的线程**可见**：volatile 写 happens-before 后续对该变量的 volatile 读。**volatile 读**之后的所有普通读，能看到该 volatile 写之前线程的写入。也就是说，volatile 写把之前的操作**刷回主内存**，volatile 读把之后的操作**从主内存加载**，从而通过 volatile 变量作为**同步点**，在两个线程之间建立跨线程的 happens-before 关系，保证前后普通读写的可见性，但**不保证原子性**。', '["volatile 的 happens-before 语义","volatile 写读与普通读写的可见性关系"]', '["volatile 变量的写和读，是如何与它前后的普通读写建立可见性关系的","请从 happens-before 的角度说明。"]', '["volatile · 指令重排序与 happens-befo"]', 'volatile 写读如何与前后普通读写建立可见性关系', '中档', '原理追问', 11, NULL, 1793155239799),
	(66, 2, 2, 8, 9, '某服务的同步方法上已经加了 synchronized。有同学说："锁只会从偏向锁一路升级到重量级锁，不会回头。"请判断这句话是否正确，并说明理由：偏向锁撤销后可能转成什么锁状态？为什么会转成这个状态？', '**这句话不正确**。偏向锁撤销后，如果有其他线程争用，会**升级为轻量级锁**：JVM 在线程栈上建锁记录，用 CAS 尝试把对象 Mark Word 指向它，靠少量自旋获取。之所以转轻量级锁，是因为此时**争用存在但不激烈**，用几次 CAS 的代价就能拿到锁，比直接进入重量级锁（线程阻塞、内核态切换、唤醒）便宜得多；只有自旋也抢不到、争用持续加剧，才会进一步膨胀为重量级锁。另外「只升不降」也不准确，重量级锁在特定时机可以降级，且偏向锁还有批量重偏向、批量撤销等机制，升级路径并非单向直线。', '["偏向锁撤销的开销与安全点","锁升级不可逆（偏向锁撤销后转轻量级锁）"]', '["某服务的同步方法上已经加了 synchronized。有同学说：\"锁只会从偏向锁一路升级到重量级锁，不会回头。\"请判断这句话是否正确，并说明理由：偏向锁撤销后可能转成什么锁状态","为什么会转成这个状态"]', '["synchronized · 锁升级过程"]', '偏向锁撤销后可能转成什么状态，为什么会这样', '中档', '原理追问', 11, NULL, 1793155246254),
	(67, 2, 2, 9, 7, 'ReentrantLock 配合 Condition 使用时，signal() 和 signalAll() 应该怎么选？请说明两者的行为差异和各自的适用场景。', '**行为差异：signal() 只唤醒一个等待线程，signalAll() 唤醒全部等待线程**。当多个角色等在同一个 Condition 上时，signal 可能唤醒"不该醒的"线程，剩下的线程可能一直不被唤醒，所以要配合 while 条件检查并用 signalAll()；当生产者、消费者分别 await 在两个 Condition 上，可以 signal() 精确唤醒对应队列，效率更高。原则：条件单一、角色明确用 signal，角色混杂或不确定时用 signalAll。', '["Condition signal 与 signalAll 的行为差异","signal/signalAll 的选型依据"]', '["ReentrantLock 配合 Condition 使用时，signal() 和 signalAll() 应该怎么选","请说明两者的行为差异和各自的适用场景。"]', '["Condition · 多条件等待唤醒"]', 'Condition 的 signal 与 signalAll 在何时选用哪个', '基础', '概念辨析', 7, NULL, 1793157066591),
	(68, 2, 2, 8, 1, '在 Java 中，一个锁对象需要跨多个方法共享（比如多个方法都要操作同一份共享状态），应该把锁声明成什么类型、放在什么位置？为什么不能用普通实例变量或局部变量来当锁？', '**锁应声明成类的成员字段，并且是 `private final` 的专用锁对象**，例如 `private final Object lock = new Object();`；需要类级别共享时用 `private static final Object LOCK = new Object();`。不能用**局部变量**：每次方法调用都是一个新对象，各线程持有的不是同一把锁，完全起不到互斥作用。不能用**普通实例变量**：它可被重新赋值或本身可变，线程持锁期间锁对象被换掉，前后锁的不再是同一个监视器，互斥被破坏，所以必须用 final 引用不可变的锁对象。', '["锁对象的唯一性与共享方式","final 字段保证锁引用不变"]', '["在 Java 中，一个锁对象需要跨多个方法共享（比如多个方法都要操作同一份共享状态），应该把锁声明成什么类型、放在什么位置","为什么不能用普通实例变量或局部变量来当锁"]', '["ReentrantLock · 与 synchronized"]', '一个锁对象需跨方法共享，选哪种并说明理由', '基础', '概念辨析', 8, NULL, 1793155268594),
	(69, 2, 2, 8, 2, '延迟初始化一个缓存引用（先判空，再创建对象并赋值）时，如果多个线程可能同时进入初始化逻辑，把缓存引用声明成 `volatile` 解决的是什么问题？它解决不了什么问题？', '**volatile 解决的是可见性 + 禁止指令重排序**：防止编译器/CPU 把「对象构造完成」和「引用赋值」顺序颠倒，导致别的线程通过判空拿到引用后，读到的是**尚未初始化完成的对象**；同时保证读线程能看到最新的引用值。它**解决不了初始化逻辑本身的原子性/互斥**：volatile 只约束单个变量的读写，不约束「先判空再创建」这个复合过程，两个线程仍会同时通过判空并重复创建对象，所以双重检查锁里 volatile 只是配角，互斥仍要靠 synchronized 保证。', '["volatile 的可见性与禁止指令重排","volatile 不能保证复合操作的原子性（check-then-act）"]', '["延迟初始化一个缓存引用（先判空，再创建对象并赋值）时，如果多个线程可能同时进入初始化逻辑，把缓存引用声明成 `volatile` 解决的是什么问题","它解决不了什么问题"]', '["volatile · 典型使用场景"]', '延迟初始化的缓存引用，volatile 在这里解决什么问题', '基础', '概念辨析', 8, NULL, 1793155268610),
	(70, 2, 2, 8, 3, '下面这段代码里，`methodA` 是 `synchronized` 实例方法，`methodB` 里用 `synchronized(this) { ... }` 包住一段代码块，二者操作同一个实例对象 obj。两个线程分别调用 obj.methodA() 和 obj.methodB()，请问它们会互斥吗？为什么？

```java
class Foo {
    public synchronized void methodA() { /* ... */ }
    public void methodB() {
        synchronized(this) { /* ... */ }
    }
}
```', '**会互斥**。因为 synchronized 实例方法等价于方法体外面包一层 `synchronized(this)`，两者锁定的监视器是**同一个实例对象 obj**。同一把锁在同一时刻只能被一个线程持有，所以一个线程进入 methodA 时，另一个线程必须等它释放后才能进入 methodB 的同步块。注意：如果是 `static synchronized`，锁的是 `Foo.class`，那就不与 `synchronized(this)` 互斥。', '["synchronized 实例方法的锁对象是 this","synchronized(this) 与 synchronized 方法的互斥条件"]', '["下面这段代码里，`methodA` 是 `synchronized` 实例方法，`methodB` 里用 `synchronized(this) { ... }` 包住一段代码块，二者操作同一个实例对象 obj。两个线程分别调用 obj.methodA() 和 obj.methodB()，请问它们会互斥吗","```java class Foo { public synchronized void methodA() { /* ... */ } public void methodB() { synchronized(this) { /* ... */ } } } ```"]', '["synchronized · 三种使用形式与语义"]', '给一段含 synchronized 方法与代码块的代码，判断是否互斥', '基础', '概念辨析', 8, NULL, 1793155268610),
	(71, 2, 2, 8, 4, '一个线程用 `volatile` 修饰一个布尔状态变量（如 `volatile boolean running = true;`），其他线程循环读取它以判断是否停止。请问：读、写分别提供什么保证？它的边界（做不到什么）在哪里？', '**写保证**：写入立即对其他线程可见，且写之前的内存操作不会被重排到写之后；**读保证**：每次读都拿到最新写入值，且读之后的内存操作不会被重排到读之前，建立 happens-before。用它做停止标志正好够用：工作线程下一次循环读取就能看到新状态。**边界**：只保证单个变量读写的可见性与有序性，**不保证复合操作（如 i++、先检查后执行）的原子性**，所以不能替代锁；另外「可见」也不等于「实时通知」，写入后其他线程什么时候读到没有时间保证。', '["volatile 的可见性与有序性保证","volatile 不保证原子性（复合操作需加锁或用原子类）"]', '["一个线程用 `volatile` 修饰一个布尔状态变量（如 `volatile boolean running = true;`），其他线程循环读取它以判断是否停止。请问：读、写分别提供什么保证","它的边界（做不到什么）在哪里"]', '["volatile · 可见性与原子性边界"]', 'volatile 修饰状态变量，读写分别有什么保证、边界在哪', '基础', '概念辨析', 8, NULL, 1793155268610),
	(72, 2, 2, 8, 6, '在使用 ReentrantLock 时，如果既需要支持 tryLock 超时获取，又需要支持可中断获取，代码结构上应该如何组合 tryLock(long, TimeUnit) 与 lockInterruptibly()？请说明：① 两者各自的作用是什么；② 超时与中断分别应该怎么处理（超时返回 false 后做什么、等待过程中被中断后应该怎么处理）？', '**结论：tryLock 带超时和 lockInterruptibly 都是可中断、可超时的获取方式，但分工不同，通常在不同分支里使用，而不是把两者混在同一个等待里。**

① **tryLock(long timeout, TimeUnit unit)**：在指定时间内尝试获取锁，返回 **true** 表示拿到锁，返回 **false** 表示超时未拿到；**lockInterruptibly()**：获取锁的过程中**响应中断**，一旦被中断会抛出 **InterruptedException**，不会无限期不可中断地阻塞。

② **超时处理**：tryLock 返回 **false** 时不能继续操作共享资源，应走**降级/放弃/重试**逻辑（例如记日志、返回失败给调用方），最后若已持有锁要在 **finally 中 unlock**，未持有则绝不能 unlock。
**中断处理**：调用 lockInterruptibly 抛出 **InterruptedException** 时，应当**恢复中断标志（Thread.currentThread().interrupt()）或向上抛出**，不要吞掉异常后继续执行临界区代码。

扩展：普通 lock() 是不可中断获取，若把 lock() 放在循环里等锁，中断可能被忽略，这是和 lockInterruptibly 的关键区别。', '["tryLock(long, TimeUnit) 与 lockInterruptibly 的语义区别","超时与中断的异常/返回值处理"]', '["两者各自的作用是什么","超时与中断分别应该怎么处理（超时返回 false 后做什么、等待过程中被中断后应该怎么处理）？"]', '["ReentrantLock · tryLock 超时与可中断"]', 'tryLock 与 lockInterruptibly 组合使用时如何写超时与中断处理', '基础', '概念辨析', 8, NULL, 1793155281006),
	(73, 2, 2, 8, 10, '你负责一个网关层的限流计数器：每秒允许通过 1000 个请求，计数器要统计当前秒已放行的请求数，超过阈值就拒绝。单机部署，多个业务线程并发调用。请回答：① 如果用一个普通 int 做计数器，多线程累加时会出现什么问题？为什么会丢计数？② 用 volatile 修饰这个 int 能解决丢计数吗？为什么？③ 如果改用 CAS（如 AtomicInteger）来累加，它是怎么保证计数不丢的？在高并发下 CAS 可能带来什么新的开销？

（请按 ①②③ 分点作答）', '① 普通 int 的 `i++` 是**读-改-写三步复合操作**，非原子：两个线程读到同一个旧值后各自自增写回，一次累加被覆盖，**丢计数**。② **不能**。volatile 只保证**可见性**和禁止重排序，不保证「读-改-写」整个过程的原子性，多个线程仍会基于同一旧值同时自增。③ CAS 的做法是：先读出旧值 expected，执行更新时用**CPU 原子指令**比较内存当前值是否等于 expected，**一致就写入新值，不一致则自旋重试**，直到成功才返回，因此每次累加都基于最新值，不丢数。代价是高并发竞争激烈时线程**反复自旋失败**，白白消耗 CPU，还会造成缓存行频繁失效、总线嗅探压力增大（另有 ABA 问题）。', '["volatile 保证可见性但不保证原子性","CAS 原子操作原理与自旋重试开销"]', '["如果用一个普通 int 做计数器，多线程累加时会出现什么问题？为什么会丢计数？","用 volatile 修饰这个 int 能解决丢计数吗？为什么？","如果改用 CAS（如 AtomicInteger）来累加，它是怎么保证计数不丢的？在高并发下 CAS 可能带来什么新的开销？ （请按","分点作答）"]', '["AtomicInteger · 常用方法与适用场景","CAS · 原理与三大问题","synchronized · 等待唤醒与线程协作"]', '限流计数器场景：累加、竞争处理与超限后的线程协作取舍', '大题', '场景应用', 23, NULL, 1793155302377),
	(74, 2, 2, 9, 1, '偏向锁升级为轻量级锁后，线程又来竞争同一个锁，锁的状态会如何变化？请说明后续升级路径和最终可能停留的状态。', '**轻量级锁遇到竞争会膨胀为重量级锁，且膨胀不可逆**。线程自旋 CAS 抢锁失败后，JVM 将锁对象升级为重量级锁（指向 ObjectMonitor），之后所有线程直接走阻塞唤醒。该对象此后**长期停留在重量级锁状态**，即使锁释放也不会降级回轻量级或偏向锁。所以升级路径是：偏向锁 → 轻量级锁 → 重量级锁，终点就是重量级锁。', '["synchronized 锁升级路径（偏向锁→轻量级锁→重量级锁）","轻量级锁自旋与重量级阻塞的取舍"]', '["偏向锁升级为轻量级锁后，线程又来竞争同一个锁，锁的状态会如何变化","请说明后续升级路径和最终可能停留的状态。"]', '["synchronized · 锁升级过程"]', '偏向锁升级为轻量级锁后又遇竞争，后续怎么走', '基础', '概念辨析', 8, NULL, 1793157064983),
	(75, 2, 2, 9, 2, '一个后台线程执行任务，主线程轮询一个布尔标志位判断任务是否结束。如果这个标志位用 volatile 修饰，能否保证主线程看到任务线程对其他共享变量的修改？为什么？', '**能保证**。线程在写 flag=true 之前对其他共享变量的修改，会 happens-before 主线程对该 flag 的读；主线程一旦读到 flag=true，就一定能看到那些修改。volatile 保证的不是只有 flag 自己可见，而是"写 flag 之前的全部写"对"读到 flag 之后"可见。所以这种轮询标志位的写法本身是安全的，前提是共享变量的修改发生在写标志之前。', '["volatile 的可见性语义","happens-before 与 volatile 写读顺序"]', '["一个后台线程执行任务，主线程轮询一个布尔标志位判断任务是否结束。如果这个标志位用 volatile 修饰，能否保证主线程看到任务线程对其他共享变量的修改？为什么？"]', '["volatile · 典型使用场景"]', '任务执行完成标志位场景下 volatile 是否够用', '基础', '概念辨析', 8, NULL, 1793157064983),
	(76, 2, 2, 9, 3, '10 个线程各对 `volatile int count` 执行 1000 次 `count++`，最后读取 count 的值，结果一定是 10000 吗？请说明原因。', '**不一定，结果通常小于 10000**。count++ 是"读-改-写"三步复合操作，volatile 只保证可见性和禁止重排序，**不保证原子性**。多线程同时读到旧值再各自写回，自增会互相覆盖、丢失更新。要得到 10000，需要 AtomicInteger（CAS）或 synchronized/Lock 保证原子性。', '["volatile 只保证可见性不保证原子性","复合操作（读改写）的线程安全问题"]', '["10 个线程各对 `volatile int count` 执行 1000 次 `count++`，最后读取 count 的值，结果一定是 10000 吗","请说明原因。"]', '["volatile · 可见性与原子性边界"]', '多线程下 `volatile int count` 累加后读取结果对不对', '基础', '概念辨析', 8, NULL, 1793157064983),
	(77, 2, 2, 9, 4, '一个类里有三种 synchronized 写法：实例方法 `synchronized void a()`、静态方法 `static synchronized void b()`、实例方法里的同步块 `synchronized(this) { }`。请分别说出它们各自锁的是哪个对象。', '**实例方法 `synchronized void a()` 锁当前实例 this**；**静态方法 `static synchronized void b()` 锁该类的 Class 对象（Xxx.class）**；**`synchronized(this)` 锁 this**，与 a() 锁的是同一对象。因此 a() 和同步块之间互斥，而 b() 与它们用的是不同的锁，不互斥。', '["synchronized 修饰实例方法/静态方法/同步块的锁对象","实例锁与类锁的区别"]', '["一个类里有三种 synchronized 写法：实例方法 `synchronized void a()`、静态方法 `static synchronized void b()`、实例方法里的同步块 `synchronized(this) { }`。请分别说出它们各自锁的是哪个对象。"]', '["synchronized · 三种使用形式与语义"]', '一个类里三种 synchronized 写法混用，指出各自动的锁对象', '基础', '概念辨析', 8, NULL, 1793157064999),
	(78, 2, 2, 9, 5, 'new ReentrantLock() 默认创建的是公平锁还是非公平锁？为什么 JDK 这样设计默认值？', '**默认是非公平锁**。公平锁要求严格 FIFO：线程被唤醒后还得排队，若抢不到锁要重新入队，产生大量排队记录与**上下文切换**，吞吐量低。非公平锁允许刚来的线程直接 **CAS 抢锁**，省去唤醒等待线程的开销，整体吞吐更高。JDK 以吞吐量优先，所以默认非公平；确有公平需求时用 `new ReentrantLock(true)`。', '["ReentrantLock 公平/非公平的默认值","非公平锁吞吐量优势的原因"]', '["new ReentrantLock() 默认创建的是公平锁还是非公平锁","为什么 JDK 这样设计默认值"]', '["ReentrantLock · 公平锁与非公平锁"]', 'new ReentrantLock() 默认是公平还是非公平，为什么这么定', '基础', '概念辨析', 8, NULL, 1793157066575),
	(79, 2, 2, 9, 8, '某系统压测时发现：两个线程分别执行 a=1; flag=true; 和 if(flag) print(a);，偶尔打印出 a=0。请回答：Java 中重排序可能发生在哪些环节？为什么单线程程序感知不到重排序，多线程才会暴露出来？', '**重排序可能发生在三个环节：编译器重排序、指令级并行（处理器乱序执行）、内存系统重排（写缓冲/缓存）**。单线程受 **as-if-serial 语义**保护——重排不改变单线程可观察结果，所以永远感知不到。多线程下线程间读写交错且缺少同步，重排会暴露中间状态：写线程先写 flag=true 后写 a=1，读线程读到 flag=true 却读到 a=0。用 volatile 修饰 flag 可禁止前序写被重排到写之后。', '["重排序发生的环节（编译期/JIT/处理器）","as-if-serial 语义与单线程不可感知的原因"]', '["某系统压测时发现：两个线程分别执行 a=1; flag=true; 和 if(flag) print(a);，偶尔打印出 a=0。请回答：Java 中重排序可能发生在哪些环节","为什么单线程程序感知不到重排序，多线程才会暴露出来"]', '["volatile · 指令重排序与 happens-befo"]', '重排序发生在哪些环节，为什么单线程感知不到', '中档', '原理追问', 11, NULL, 1793157066591),
	(80, 2, 2, 9, 9, '用 ReentrantLock 写同步代码时，unlock 必须写在哪里？如果忘了写 unlock（或写在了不会执行的分支上），程序会出现什么现象？请分别说明。', '**unlock 必须写在 finally 块里**，保证 lock() 之后无论正常结束、提前 return 还是抛异常都能释放锁。两种漏写情形的结果本质相同但路径不同：完全忘写，是正常流程就泄漏；写在不会执行的分支上，典型是提前 return 或抛异常把 unlock 跳过——这正是必须用 finally 的原因。后果都是**锁永远不会释放**：持有线程一直占着锁，其他线程调用 lock() 后**永久阻塞**（进入等待队列，BLOCKED/WAITING），表现为程序卡死、线程不断堆积，而**不是严格意义的死锁**（没有循环等待）。另外注意 ReentrantLock 可重入，**lock 几次就要 unlock 几次**，少 unlock 一次锁同样不会真正释放。', '["ReentrantLock 的 lock/unlock 配对使用","锁泄漏与线程阻塞"]', '["用 ReentrantLock 写同步代码时，unlock 必须写在哪里","如果忘了写 unlock（或写在了不会执行的分支上），程序会出现什么现象","请分别说明。"]', '["ReentrantLock · 与 synchronized"]', '要不要显式 unlock，忘写 unlock 会发生什么', '中档', '原理追问', 11, NULL, 1793157078749),
	(81, 2, 2, 9, 10, '电商秒杀系统中，商品库存扣减是热点操作，同一时刻会有大量请求并发扣减同一 SKU 的库存。业务要求：不能超卖、库存不能扣成负数，库存耗尽后要能快速拒绝请求，且在库存充足时要有不错的吞吐。

团队在选型时争论三种做法：使用原子类（如 AtomicInteger）的 CAS 操作、自己写 while 循环 + CAS 自旋、以及用 wait/notify 让拿不到库存的线程阻塞等待再被唤醒。

请回答：
① 这三种做法各自的执行流程是什么？在库存扣减这个场景下，它们分别表现为什么样的行为（比如库存不足时线程会怎样）？
② 三种做法在"库存不足"这个分支上的处理差异是什么？为什么 CAS/原子类在这时要走"扣减失败直接返回失败"，而 wait/notify 要设计成"等待—唤醒"协作？
③ 结合秒杀场景的约束（高并发、不能超卖、库存耗尽要快速失败），你会选哪一种？给出你的取舍理由；如果你选的方案在极端热点下还有短板，请说明用什么手段补救。', '**结论先行**：秒杀扣减库存优先选 **原子类的 CAS 揞减（decrementAndGet / getAndDecrement + 校验）**，或基于 CAS 的轻量自旋；wait/notify 不适合这个场景。

**① 三种做法的流程与行为**
- **原子类 CAS**：线程读当前库存值，用 compareAndSet 在期望值未被别人改过时一次性写入新值；失败则由原子类内部重试或直接返回失败。库存充足时几乎无锁竞争，多个线程同时扣减各自成功；库存不足时 CAS 扣到负数前需先校验（`if (stock.get() <= 0) return false;`），失败线程**立即返回秒杀失败**，不阻塞。
- **自己写 CAS 自旋**：本质同上，只是把 `while (!cas(...))` 写在业务里。行为相同，但容易出现**无退出条件的空转**，热点下 CPU 打满。
- **wait/notify 协作**：拿不到库存的线程进入 `wait()` 挂起，等待持有锁的线程 `notify()` 唤醒后重新竞争。库存不足时线程**阻塞挂起**，进入等待队列。

**② 库存不足分支的差异与原因**
- CAS/原子类走**失败即返回**：因为秒杀本身允许大量用户抢不到，业务语义就是"抢不到就返回失败页"，不需要等待未来库存变多（库存只会减少）。让它阻塞毫无意义，反而占住线程。
- wait/notify 是**等待—唤醒协作**：设计初衷是"条件暂时不满足，先等一等"，适合生产者-消费者这类条件会变的场景。秒杀库存单调递减，条件永不反转，等下去只会堆积线程、造成假死风险。

**③ 选型与取舍**
选**原子类 CAS 搭配"预判 + 扣减 + 回滚"或分段/分桶**：
- 不能超卖：CAS 保证原子性，扣减前先判 `stock > 0`，或用 `getAndUpdate`/`accumulateAndGet` 带函数式更新，天然不会扣成负数。
- 库存耗尽快速失败：CAS 失败或库存为 0 时立即返回，不做任何阻塞，符合秒杀"快速失败"要求。
- 吞吐：CAS 无锁、无上下文切换，热点 SKU 上比 synchronized/wait-notify 高一个量级。

**极端热点的短板与补救**：单个原子类在超高并发下 CAS 会大量重试（自旋风暴），可用**库存分桶（把 1 个库存拆成 N 个 bucket，每个 bucket 一个原子计数）**分散竞争，或**先做本地/Redis 预扣 + 异步落库**，DB 只做兜底扣减。

扩展：wait/notify 在"库存回补（如超时订单释放）"这类条件会变的场景里才是合理选项，但那是另一个业务语义，不是秒杀扣减主流程。', '["原子类 CAS 扣减库存的原理与适用场景","CAS 自旋与 wait/notify 协作在扣减失败分支上的行为差异与取舍"]', '["这三种做法各自的执行流程是什么？在库存扣减这个场景下，它们分别表现为什么样的行为（比如库存不足时线程会怎样）？","三种做法在\"库存不足\"这个分支上的处理差异是什么？为什么 CAS/原子类在这时要走\"扣减失败直接返回失败\"，而 wait/notify 要设计成\"等待—唤醒\"协作？","结合秒杀场景的约束（高并发、不能超卖、库存耗尽要快速失败），你会选哪一种？给出你的取舍理由；如果你选的方案在极端热点下还有短板，请说明用什么手段补救。"]', '["AtomicInteger · 常用方法与适用场景","CAS · 原理与三大问题","synchronized · 等待唤醒与线程协作"]', '秒杀扣减库存：计数选原子类还是 CAS 自旋还是 wait/notify 协作，取舍怎么说', '大题', '场景应用', 23, NULL, 1793157134594),
	(82, 2, 2, 10, 9, '下面三个场景，请分别判断是否适合用 volatile 修饰共享变量，并说明理由：
① 一个工作线程循环检查 `shutdown` 标志位来决定是否退出，主线程负责把它置为 true，用 volatile 合适吗？为什么？
② 多个线程并发执行 `counter++` 一个热点计数器，只把 counter 声明为 volatile 能保证最终结果正确吗？为什么？
③ 一个初始化线程构造好配置对象后，把它赋给一个共享的静态字段供其他线程读取，这个字段用 volatile 修饰能带来什么好处？为什么？', '① **适合**：一写多读的**状态标志**是 volatile 的经典用法——volatile 写立即刷新主内存、读每次读主内存，工作线程能立刻看到 shutdown=true 退出，靠**可见性**（不是靠写 boolean 原子）。② **不能**：counter++ 是**读-改-写的复合操作**，volatile 不保证其原子性，并发下丢失更新，应使用 **AtomicLong/LongAdder** 或加锁。③ **好处**：一是新配置引用的写**对其他线程立即可见**；二是**禁止指令重排**，避免别的线程读到尚未构造完成的对象（发布安全）。', '["volatile 的可见性与有序性","volatile 不保证原子性","volatile 与对象发布（指令重排）"]', '["一个工作线程循环检查 `shutdown` 标志位来决定是否退出，主线程负责把它置为 true，用 volatile 合适吗？为什么？","多个线程并发执行 `counter++` 一个热点计数器，只把 counter 声明为 volatile 能保证最终结果正确吗？为什么？","一个初始化线程构造好配置对象后，把它赋给一个共享的静态字段供其他线程读取，这个字段用 volatile 修饰能带来什么好处？为什么？"]', '["volatile · 典型使用场景"]', '给三种候选场景（轮询停止位/累加器/对象发布），选哪些用 volatile 及理由', '中档', '原理追问', 11, NULL, 1793236880370),
	(83, 2, 2, 10, 1, 'synchronized 的偏向锁、轻量级锁、重量级锁分别在什么条件下存在？为什么要引入锁升级机制，而不是一开始就用重量级锁？', '**三种锁的存在条件**：只有一个线程访问、无竞争时是**偏向锁**（对象头记录线程 ID，再次进入免 CAS）；有少量线程**交替执行、没有长时间持锁竞争**时是**轻量级锁**（用户态 CAS 自旋）；**竞争激烈、自旋等待不划算**时膨胀为**重量级锁**（内核互斥量，阻塞/唤醒）。**为什么升级**：重量级锁涉及内核态的线程阻塞与唤醒，开销大；而实际大多数同步块是无竞争或轻竞争，用偏向锁、轻量级锁在用户态 CAS 就能搞定，避免无谓的内核切换。所以用「先轻后重」的升级机制让开销随竞争程度渐进增长。', '["synchronized 锁升级（偏向锁/轻量级锁/重量级锁）","锁升级设计动机"]', '["synchronized 的偏向锁、轻量级锁、重量级锁分别在什么条件下存在","为什么要引入锁升级机制，而不是一开始就用重量级锁"]', '["synchronized · 锁升级过程"]', '偏、轻、重三态各自在什么条件下存在，简述为何需要升级', '基础', '概念辨析', 8, NULL, 1793236882233),
	(84, 2, 4, 14, 8, '业务中为什么要自己实现 ThreadFactory，而不是用默认的？', '自定义 **ThreadFactory** 是为了**可控地创建线程**：给线程指定**有意义的名字**（业务前缀+序号）、设置是否 daemon、优先级、UncaughtExceptionHandler、所属线程组。默认工厂创建的线程名是 pool-x-thread-y，出问题时从日志和堆栈**看不出线程属于哪个业务**，也难做监控和告警。', '["自定义 ThreadFactory 的必要性","线程命名与异常兜底"]', '["业务中为什么要自己实现 ThreadFactory，而不是用默认的？"]', '["自定义线程池 · 自定义线程工厂与命名规范"]', '为什么要自己写 ThreadFactory', '基础', '概念辨析', 9, NULL, 1793608962409),
	(85, 2, 2, 10, 2, '下面代码中，m1 是 synchronized 实例方法，m2 是 synchronized 实例方法，m3 是 static synchronized 方法，m4 是普通方法。同一个对象 obj 被线程 A、B 同时调用（A 调 m1、B 分别调 m2/m3/m4）。请问哪些方法能与 m1 并行执行？为什么？', '**m3 和 m4 可以与 m1 并行**。因为 synchronized 实例方法（m1、m2）锁的是**同一个对象实例 obj**，两者互斥；static synchronized（m3）锁的是**类的 Class 对象**，与实例锁是两把不同的锁，因此能并行；m4 是普通方法**不要求任何锁**，也能并行。', '["synchronized 对象锁与 Class 锁的区别","synchronized 实例方法与静态方法的锁对象"]', '["下面代码中，m1 是 synchronized 实例方法，m2 是 synchronized 实例方法，m3 是 static synchronized 方法，m4 是普通方法。同一个对象 obj 被线程 A、B 同时调用（A 调 m1、B 分别调 m2/m3/m4）。请问哪些方法能与 m1 并行执行？为什么？"]', '["synchronized · 三种使用形式与语义"]', '给一段多线程打印交错的代码，判哪些方法能并行执行', '基础', '概念辨析', 8, NULL, 1793236882233),
	(86, 2, 2, 10, 3, '多线程环境下，用 volatile boolean running 作为停止标志（一个线程写、另一个线程读并退出），和用 volatile int count 做计数（多个线程都执行 count++），这两种用法各自能做到正确吗？为什么？', '**停止标志正确，count++ 计数不正确。**
volatile boolean running 由一个线程写、一个线程读：写一个 boolean 是原子的，且 **volatile 保证写入对读线程立即可见**，读线程能及时看到标志变化并退出，所以正确。
而 volatile int count 多线程执行 count++：**count++ 是「读-改-写」三步复合操作**，volatile 只保证**可见性和禁止指令重排序**，不能把整个复合操作变成原子的，多个线程读到相同旧值后各自自增，会**丢更新**，结果偏小。要正确计数需用 **AtomicInteger 的 incrementAndGet（CAS）或加锁**。
一句话记忆：**单赋值靠 volatile 可见性就够，复合操作必须靠锁或 CAS 保证原子性。**', '["volatile 保证可见性与有序性但不保证原子性","volatile 的适用场景"]', '["多线程环境下，用 volatile boolean running 作为停止标志（一个线程写、另一个线程读并退出），和用 volatile int count 做计数（多个线程都执行 count++），这两种用法各自能做到正确吗？为什么？"]', '["volatile · 可见性与原子性边界"]', 'volatile boolean 停止标志 vs volatile int 计数，各自能不能做到正确', '基础', '概念辨析', 8, NULL, 1793236882249),
	(87, 2, 2, 10, 4, '两个线程 A、B 需要在同一个对象上交替打印奇数和偶数（A 打印 1、3、5…，B 打印 2、4、6…）。请说明用 wait/notify 搭出这个交替打印骨架的思路：共享变量怎么设、循环体里怎么判断、什么时候 wait、什么时候 notify。', '**共享变量**：一个 number（当前要打印的值）和/或一个标志 turn，用一个锁对象 obj。**循环体**：`synchronized(obj)` 内 `while (不满足我的条件) obj.wait();`——例如偶数线程 `while (number % 2 != 0) wait()`，**必须用 while 防虚假唤醒**。**wait 时机**：轮不到自己打印时 wait 释放锁。**notify 时机**：自己打印、number++ 之后调用 `obj.notify()`/`notifyAll()` 唤醒对方，再退出同步块。关键是**同一把锁**上判断、等待、唤醒闭环。', '["wait/notify 与 synchronized 配合","等待/通知机制与共享状态标志"]', '["两个线程 A、B 需要在同一个对象上交替打印奇数和偶数（A 打印 1、3、5…，B 打印 2、4、6…）。请说明用 wait/notify 搭出这个交替打印骨架的思路：共享变量怎么设、循环体里怎么判断、什么时候 wait、什么时候 notify。"]', '["synchronized · 等待唤醒与线程协作"]', '两个线程交替打印奇偶数，wait/notify 怎么搭骨架', '基础', '概念辨析', 8, NULL, 1793236882249),
	(88, 2, 2, 10, 5, '`new ReentrantLock(true)` 拿到的是什么锁？它和无参构造 `new ReentrantLock()` 在线程调度上有什么区别？什么场景下适合用这种公平锁构造？', '`new ReentrantLock(true)` 是**公平锁**，无参构造默认是**非公平锁**。区别在线程调度：公平锁严格按**等待队列 FIFO** 顺序唤醒，新来的线程必须排队；非公平锁允许**新线程先 CAS 插队抢一次锁**，抢不到才排队，吞吐更高但可能让某些线程长期拿不到锁（**饥饿**）。适合公平锁的场景：对**访问顺序/公平性有硬要求**、或需要避免饥饿的场合；一般高并发场景默认非公平即可。', '["ReentrantLock 公平锁与非公平锁","公平锁适用场景与取舍"]', '["`new ReentrantLock(true)` 拿到的是什么锁","它和无参构造 `new ReentrantLock()` 在线程调度上有什么区别","什么场景下适合用这种公平锁构造"]', '["ReentrantLock · 公平锁与非公平锁"]', 'new ReentrantLock(true) 拿到什么锁，什么场景下这样构造', '基础', '概念辨析', 8, NULL, 1793236887692),
	(89, 2, 2, 10, 6, '现在手里只有 `tryLock()` 无参版（不能用带超时的 `tryLock(long, TimeUnit)`），如何实现“最多等 3 秒拿锁，拿不到就放弃”这个需求？请写出做法。', '**用无参 `tryLock()` 轮询 + 时间判断实现**。

做法：记录起始时间 `long deadline = System.currentTimeMillis() + 3000`，然后循环调用 `tryLock()`：
- 拿到锁就返回，结束；
- 没拿到，判断是否已超过 deadline，超过就放弃（返回失败）；
- 未超过就 `Thread.sleep(一小段时间)`（比如 50~100ms）后再重试。

关键点：
1. **无参 `tryLock()` 是立即返回、不阻塞的**，所以必须自己做轮询和 sleep，否则会空转烧 CPU。
2. **退出条件是“拿到锁”或“超过 3 秒”**，二者满足其一即停，不能无限重试。
3. 放弃时要正确处理：释放已持有的其他资源，按业务需要返回失败或降级。

对比：生产上更推荐直接用 `tryLock(long timeout, TimeUnit unit)`，它内部已经实现等待与超时，本题是考察对 tryLock 语义的理解与轮询实现能力。', '["tryLock() 无参版语义（非阻塞立即返回）","超时等待的轮询实现思路"]', '["现在手里只有 `tryLock()` 无参版（不能用带超时的 `tryLock(long, TimeUnit)`），如何实现“最多等 3 秒拿锁，拿不到就放弃”这个需求","请写出做法。"]', '["ReentrantLock · tryLock 超时与可中断"]', '只给 tryLock 无参版，如何实现"最多等 3 秒拿锁，拿不到就放弃"', '基础', '概念辨析', 8, NULL, 1793236887692),
	(90, 2, 2, 10, 7, '生产者-消费者场景里，一个 ReentrantLock 下有“队列满（生产者等待）”和“队列空（消费者等待）”两种等待。用 Condition 应该怎么分工？请说明做法和好处。', '**做法**：在 ReentrantLock 上创建两个 Condition——`notFull` 给生产者、`notEmpty` 给消费者。生产者：`while (队列满) notFull.await();` 放入元素后 `notEmpty.signal();`；消费者：`while (队列空) notEmpty.await();` 取走元素后 `notFull.signal();`。**好处**：两类等待分属不同等待队列，**只唤醒对端**，做到精准唤醒、避免惊群（notifyAll 全唤醒带来的无效竞争与切换），且 while 判断防虚假唤醒。', '["Condition 多条件队列分工（await/signal）","精确唤醒与虚假唤醒防护"]', '["生产者-消费者场景里，一个 ReentrantLock 下有“队列满（生产者等待）”和“队列空（消费者等待）”两种等待。用 Condition 应该怎么分工","请说明做法和好处。"]', '["Condition · 多条件等待唤醒"]', '一个锁下"队列满/队列空"两种等待，Condition 怎么分工', '基础', '概念辨析', 7, NULL, 1793236887707),
	(91, 2, 2, 10, 8, '两个线程共享 a 和 flag 两个普通 int/boolean 变量。线程 T1 依次执行 a=1、flag=true；线程 T2 循环等待 flag 变为 true 后读取 a。a 和 flag 都不加 volatile、不用锁。请说明：① 为什么 T2 可能观察到 flag 已经是 true，却读到 a 还是 0？请从指令重排序和可见性两个角度解释原因。② 如果把 flag 声明为 volatile，a 不变，能否保证 T2 一定读到 a=1？为什么？', '① 两个角度：**重排序**——`a=1` 和 `flag=true` 之间无依赖，可能被重排成先 flag 后 a，T2 看到 flag=true 时 a 还没写；**可见性**——a、flag 的写可能滞留在 T1 的工作内存，T2 又可能从缓存反复读到旧值，即使看到 flag=true，a 的写也不保证对 T2 可见。② **能保证**：flag 加 volatile 后，`a=1` happens-before `volatile 写 flag`，happens-before `T2 的 volatile 读 flag`，happens-before `T2 读 a`；**volatile 写之前的所有写对读到该值的线程可见**，所以 T2 一定读到 a=1。', '["volatile 的 happens-before 语义（写读建立可见性）","指令重排序（普通变量写顺序不保证）"]', '["为什么 T2 可能观察到 flag 已经是 true，却读到 a 还是 0？请从指令重排序和可见性两个角度解释原因。","如果把 flag 声明为 volatile，a 不变，能否保证 T2 一定读到 a=1？为什么？"]', '["volatile · 指令重排序与 happens-befo"]', '写 a=1 在 flag=true 之前，读方为何仍可能看到 flag 但读不到 a', '中档', '原理追问', 11, NULL, 1793236923612),
	(92, 2, 2, 10, 10, '【大题 / 场景应用 / 23 分】你们有一个游戏排行榜计数服务，线上有两类热点：一是玩家得分变更的高频计数（每秒数万次，单个 key 更新很频繁，但单次操作很短）；二是赛季结算时的慢查询临界区（要遍历全量排行榜做重算，一次执行几十秒，期间不能被并发写入破坏一致性）。现在用单个 synchronized 方法扛，高峰期 CPU 飙高、结算时其他请求大量阻塞。请回答：
① 针对「高频计数」这一热点，volatile 能不能解决计数丢失问题？为什么？volatile 在这类场景里适合做什么、不适合做什么？
② 针对同一段计数代码，用 CAS（如 AtomicLong）实现相比 synchronized，在失败时各自的行为分支是什么（抢锁失败阻塞/自旋重试各自怎么走）？各自适合什么频度与临界区长度的场景？
③ 请给出整体改造方案：这两类热点分别用什么手段（可从 volatile / CAS / synchronized / Lock 中选择），并说明取舍理由；以及慢查询临界区如何避免长时间阻塞高频计数。', '① **不能**。volatile 只给**可见性**、不给**原子性**，`count++` 是读-改-写复合操作，多线程下仍会丢更新。它适合**状态标志、单次读写/独立赋值**，不适合复合操作。
② CAS 失败**自旋重试**（CPU 空转），synchronized 失败**阻塞让出 CPU**、唤醒后重抢。CAS 适合**临界区短、高频**；synchronized 适合**临界区长、竞争激烈**。
③ 计数走 **AtomicLong/CAS** 无锁化；结算用 **ReadWriteLock 或快照/写时复制**，让结算基于快照做而不阻塞高频计数，慢查询整体移出主写路径。', '["volatile 的语义（可见性/重排序，不保证原子性）","CAS 与 synchronized 的失败分支与适用场景","Lock 相对 synchronized 的取舍（超时、可中断、读写分离）"]', '["针对「高频计数」这一热点，volatile 能不能解决计数丢失问题？为什么？volatile 在这类场景里适合做什么、不适合做什么？","针对同一段计数代码，用 CAS（如 AtomicLong）实现相比 synchronized，在失败时各自的行为分支是什么（抢锁失败阻塞/自旋重试各自怎么走）？各自适合什么频度与临界区长度的场景？","请给出整体改造方案：这两类热点分别用什么手段（可从 volatile / CAS / synchronized / Lock 中选择），并说明取舍理由；以及慢查询临界区如何避免长时间阻塞高频计数。"]', '["AtomicInteger · 常用方法与适用场景","CAS · 原理与三大问题","ReentrantLock · 与 synchronized"]', '一个排行榜计数服务里有热点计数与慢查询临界区，串联对比三种手段的分工、失败分支与取舍', '大题', '场景应用', 23, NULL, 1793236927850),
	(93, 2, 2, 11, 9, '在 JDK 6+ 的 synchronized 锁升级场景中，如果一个已持有偏向锁的对象被调用了 hashCode()（未重写、返回对象默认 hashCode），会发生什么？请说明：① 偏向锁会如何变化；② 为什么 hashCode 与偏向锁会产生冲突；③ 反过来，如果对象已经计算过 hashCode，它还能进入偏向锁状态吗？', '**结论：调用 hashCode() 会使偏向锁被撤销，锁会膨胀（升级）为轻量级锁（或退回无锁/不可偏向状态），且该对象以后不再适合偏向。**

**① 发生什么：** 偏向锁的对象头中存放的是持有线程的 ThreadID（偏向锁标记 + 线程 ID），而对象的 **hashCode** 默认也存在对象头的 Mark Word 里，两者**共用同一段存储空间**，无法同时保存。因此调用 `hashCode()` 计算默认哈希值时，需要占用对象头中被 ThreadID 占据的位置，JVM 只能**撤销偏向锁**，把对象头改写成存放 hashCode 的形式，锁随之升级（通常膨胀为轻量级锁或进入可重偏向/不可偏向状态），该对象此后不再适合保持偏向。

**② 冲突原因：** 本质是**对象头 Mark Word 空间复用冲突**——偏向锁状态要把对象头用于存偏向线程 ID，hashCode 又必须落在对象头，二者互斥，所以取其一就必须让出另一个。

**③ 反过来：** 如果对象**先被计算过默认 hashCode**（对象头中已存入 hashCode），之后**不能再进入偏向锁状态**，因为偏向线程 ID 无处可写，它只能走轻量级/重量级锁路径。

**扩展：** 若类重写了 hashCode（不使用默认对象头存储的 hash），则不存在这个冲突，对象仍可偏向。', '["偏向锁与对象头 Mark Word 的空间复用冲突","hashCode 计算导致偏向锁撤销/无法偏向"]', '["偏向锁会如何变化","为什么 hashCode 与偏向锁会产生冲突","反过来，如果对象已经计算过 hashCode，它还能进入偏向锁状态吗？"]', '["synchronized · 锁升级过程"]', '对象 hashcode 调用对偏向锁的影响是什么', '中档', '原理追问', 11, NULL, 1793239010768),
	(94, 2, 2, 13, 3, 'synchronized 修饰实例方法、修饰静态方法、修饰 this 的代码块、修饰 class 字面量的代码块，这四种写法各自的锁对象是什么？', '**关键看锁的是实例还是 Class 对象。** ① 修饰实例方法：锁**当前对象实例（this）**；② 修饰静态方法：锁**该类的 Class 对象**；③ synchronized(this)：锁**当前实例**；④ synchronized(X.class)：锁 **Class 对象**。①③ 是同一把锁、互相阻塞；②④ 是同一把锁、互相阻塞；实例锁与类锁互不影响。', '["synchronized 锁对象","实例锁与类锁"]', '["synchronized 修饰实例方法、修饰静态方法、修饰 this 的代码块、修饰 class 字面量的代码块，这四种写法各自的锁对象是什么？"]', '["synchronized · 三种使用形式与语义"]', '修饰方法与修饰 this/class 代码块写法与锁对象', '基础', '概念辨析', 3, NULL, 1793327162785),
	(95, 2, 2, 11, 5, '吞吐优先、任务量大且允许一定排队的场景，线程池应优先用哪个构造方法创建？核心线程数、最大线程数、队列分别怎么设？为什么这样设能提高吞吐量？', '**用 new ThreadPoolExecutor(...) 这个全参构造方法**，不要用 Executors 的快捷工厂（如 newFixedThreadPool 的无界队列会堆积 OOM）。吞吐优先的设置思路：**核心线程数设为 CPU 核数（CPU 密集）或核数×(1+等待/计算比)（IO 密集）**，让线程数贴近实际并行能力；**队列用有界队列（如 ArrayBlockingQueue）**，既缓冲突发流量、减少线程创建销毁开销，又不至于无限堆积；**最大线程数可略高于核心数**作为突发缓冲。吞吐量高的原因是：复用固定的一批线程避免频繁创建销毁的开销，有界队列让任务批量排队、上下文切换更少，线程数贴近 CPU/IO 并行度，减少过度竞争与切换浪费。', '["线程池构造方法与参数含义","线程数与队列对吞吐的影响"]', '["吞吐优先、任务量大且允许一定排队的场景，线程池应优先用哪个构造方法创建","核心线程数、最大线程数、队列分别怎么设","为什么这样设能提高吞吐量"]', '["ReentrantLock · 公平锁与非公平锁"]', '吞吐优先的线程池用哪种构造参数及理由', '基础', '概念辨析', 8, NULL, 1793239011620),
	(96, 2, 2, 11, 6, '调用 Lock 的 tryLock()（不带超时参数）尝试获取锁时抛出了 InterruptedException，应该怎么处理？为什么不能简单地捕获后继续往下执行？', '**结论：先恢复中断标记，再按"锁没拿到"处理，不能继续执行临界区。**tryLock() 响应中断时会抛 InterruptedException 并且**没有持有锁**，所以绝不能调 unlock（会抛 IllegalMonitorStateException）。做法是 catch 里调用 Thread.currentThread().interrupt() 恢复中断位，然后返回或走失败分支（需要锁就改用可中断的 lockInterruptibly() 或带超时的 tryLock）。不能简单捕获继续：一是中断状态已被清除，等于吞掉取消信号；二是锁并未持有，继续往下执行就是无锁访问共享数据，破坏互斥。', '["tryLock 的中断语义","InterruptedException 的处理原则"]', '["调用 Lock 的 tryLock()（不带超时参数）尝试获取锁时抛出了 InterruptedException，应该怎么处理","为什么不能简单地捕获后继续往下执行"]', '["ReentrantLock · tryLock 超时与可中断"]', 'tryLock 抛 InterruptedException 时该怎么处理', '基础', '概念辨析', 8, NULL, 1793239011626),
	(97, 2, 2, 11, 7, '使用 Condition.await() 等待某个条件成立时，为什么从 await() 返回后还要再用 while 重新检查条件，而不能直接往下执行？', '**结论：await 返回只代表"被唤醒"，不代表"条件成立"，所以必须 while 循环复查。**三个原因：① 存在**虚假唤醒**，没有 signal 也可能返回；② signal 选出的线程条件未必成立，条件可能已被其他等待者用掉；③ await 返回前要重新抢锁，从被通知到重新持锁这段时间里，其他持锁线程可能又改了条件。用 if 只检查一次会带着不成立的条件往下执行，while 则不满足就继续 await，保证临界区始终在条件成立时运行。', '["Condition.await 与虚假唤醒","等待-通知模式的条件检查"]', '["使用 Condition.await() 等待某个条件成立时，为什么从 await() 返回后还要再用 while 重新检查条件，而不能直接往下执行？"]', '["Condition · 多条件等待唤醒"]', 'await 返回后为何要重新检查条件再执行', '基础', '概念辨析', 7, NULL, 1793239011631),
	(98, 2, 2, 11, 8, '某服务有一个 Config 配置对象，会不定期被后台线程整体替换为新对象（new 一个新 Config 后赋给引用），读线程频繁读取该引用并使用其中的多个字段。有人提出：把引用声明为 volatile Config config，替换时直接赋值，就不用加锁了。请分析：① volatile 修饰对象引用能保证什么、不能保证什么？② 在“整体替换引用”和“就地修改已有对象字段”两种更新方式下，volatile 的效果有何不同？③ 什么情况下必须用锁（或不可变对象）而不是 volatile？', '**① volatile 引用保证引用赋值的可见性与禁止重排，不保证原子性，也不保护对象内部字段的并发修改。**② **整体替换引用**是安全发布：写引用前对新对象字段的写入，读到新引用的线程都能看到；**就地修改字段**时引用不变，volatile 不提供任何可见性保证，其他线程可能一直读到旧值。③ 出现**复合操作**（读改写、自增）或**多字段需要一致地读写**时，必须加锁；或者把 Config 做成不可变对象、只走整体替换，让 volatile 足够。', '["volatile 的可见性与原子性边界","安全发布与对象不变式"]', '["volatile 修饰对象引用能保证什么、不能保证什么？","在“整体替换引用”和“就地修改已有对象字段”两种更新方式下，volatile 的效果有何不同？","什么情况下必须用锁（或不可变对象）而不是 volatile？"]', '["volatile · 典型使用场景"]', 'volatile 修饰配置对象引用能否替代加锁更新', '中档', '原理追问', 11, NULL, 1793239011639),
	(99, 2, 2, 11, 1, '线程 A 先写入共享变量 flag=true，随后写入数据 data=42；线程 B 先读 data、后读 flag，却出现「读到 data 仍是旧值、flag 却是 true」的可见性异常。请回答：① 这种乱序最可能是谁造成的——编译器、处理器，还是二者都可能？② 为什么说单靠 volatile 修饰 flag 就能消除该现象？（请说明 volatile 在重排上约束的是谁）', '**结论：编译器和处理器都可能造成乱序。**源码顺序不等于执行顺序：编译期优化会重排指令，运行期 CPU 乱序执行、写缓冲也会让写入顺序对其他线程不一致。volatile 修饰 flag 后，约束的是**围绕这次 volatile 访问的重排**：volatile 写之前的 data=42 不会被重排到写之后，volatile 读 flag 之后的读 data 不会被重排到读之前；同时内存屏障同时禁止编译器与处理器重排，并把写入同步给读线程。于是 B 读到 flag=true 时 data=42 必然可见，异常消失。', '["指令重排序（编译器优化重排与处理器乱序/写缓冲）","volatile 的内存语义：禁止重排序 + 可见性（happens-before）"]', '["这种乱序最可能是谁造成的——编译器、处理器，还是二者都可能？","为什么说单靠 volatile 修饰 flag 就能消除该现象？（请说明 volatile 在重排上约束的是谁）"]', '["volatile · 指令重排序与 happens-befo"]', '旧库读到写后值，编译器与处理器谁重排', '基础', '概念辨析', 8, NULL, 1793239016225),
	(100, 2, 2, 11, 2, '对 synchronized 的锁对象选择有两种写法：① 用 synchronized 修饰**构造方法**（或写 synchronized(this){} 在构造函数内）；② 用 synchronized 修饰**静态工厂方法**。请辨析：这两种写法**各自锁住的是哪个对象/Class**？它们能否保证对外可见的并发安全？', '① **构造方法不能用 synchronized 修饰**（Java 语法上不允许），写 `synchronized(this)` 在构造函数内锁的是**当前这个新对象实例**（对象锁）。但**构造期间 this 可能被逸出**，其他线程可能拿到未构造完成的对象，此时加锁并不能保证安全；而且锁的只是这一个实例，多实例间互不互斥。
② **静态工厂方法**被 synchronized 修饰时，锁的是**该类的 Class 对象**（`Xxx.class`），相当于类锁，作用于所有线程调用该静态方法的场景。因为静态方法没有 this，只能锁 Class。它能保证该静态方法（及其共享的静态状态）的并发安全。
结论：**实例锁锁对象（this），类锁锁 Class**；构造方法加锁不仅语法/语义上有逸出风险，也不能覆盖跨实例的共享状态。', '["synchronized 的锁对象：实例锁（this）与类锁（Class 对象）","对象逸出（this 逸出）与构造期安全"]', '["用 synchronized 修饰**构造方法**（或写 synchronized(this){} 在构造函数内）","用 synchronized 修饰**静态工厂方法**。请辨析：这两种写法**各自锁住的是哪个对象/Class**？它们能否保证对外可见的并发安全？"]', '["synchronized · 三种使用形式与语义"]', '修饰构造方法与静态工厂方法各锁什么', '基础', '概念辨析', 8, NULL, 1793239016231),
	(101, 2, 2, 11, 3, '在 32 位虚拟机上，普通 long/double 类型的非 volatile 读写可能不是原子的（可能「撕裂」读）。请辨析：① **volatile long** 的 64 位读写为什么是天然原子的？② 这跟 synchronized 块里的原子性保障有什么区别？', '① JMM 规定 **volatile 的读写本身具有原子性**：对 volatile 变量的单次读或单次写是**一个不可分割的动作**，不会出现半写/撕裂读。所以 volatile long 的 64 位读写天然是原子的——这是规范直接保证的，不需要额外加锁。（注：JLS 对 long/double 允许非 volatile 的 64 位读写拆成两次 32 位，但 volatile long 明确禁止这种拆分。）
② 二者区别：**volatile 只保证「单次读/单次写」这个动作的原子性**，不保证「读-改-写」复合操作（如 i++）的原子性；而 **synchronized 块保证临界区内的一段操作整体原子**，能保护复合操作。volatile 长度是单变量单动作，synchronized 是多语句临界区。', '["volatile 变量读写的原子性（含 long/double 撕裂问题）","volatile 原子性与 synchronized 临界区原子性的区别"]', '["**volatile long** 的 64 位读写为什么是天然原子的？","这跟 synchronized 块里的原子性保障有什么区别？"]', '["volatile · 可见性与原子性边界"]', 'volatile long 六十四位读写为何天然原子', '基础', '概念辨析', 8, NULL, 1793239016241),
	(102, 2, 2, 11, 4, '生产者/消费者用 wait/notify 协作。线程被 notify 唤醒后，为什么不能直接执行，而必须**重新用 while 循环判断等待条件**、不满足就继续 wait？请说明这样做解决了什么并发问题。', '**结论：被唤醒 ≠ 条件成立，所以必须 while 循环复查条件。**原因有三：① 存在**虚假唤醒**，线程可能没被 notify 也会从 wait 返回；② notify 只是挑一个等待者唤醒，它醒来时条件未必成立（资源可能已被其他线程取走）；③ notify 不释放锁，被唤醒线程要等通知线程退出同步块后重新抢锁，这期间条件可能又被改动。用 if 只判断一次就会在条件不满足时误执行，while 则不满足就继续 wait，保证每次执行都基于成立的条件。', '["wait/notify 的虚假唤醒（spurious wakeup）","while 条件检查 + wait 的正确协作范式"]', '["生产者/消费者用 wait/notify 协作。线程被 notify 唤醒后，为什么不能直接执行，而必须**重新用 while 循环判断等待条件**、不满足就继续 wait","请说明这样做解决了什么并发问题。"]', '["synchronized · 等待唤醒与线程协作"]', 'notify 唤醒后仍需 while 判断条件的原因', '基础', '概念辨析', 8, NULL, 1793239016249),
	(103, 2, 2, 11, 10, '某订单系统做幂等扣款，方案是「先查一次是否有成功扣款记录，没有就执行扣款」。在多线程并发请求同一订单时，这个方案会出什么问题？请说明根本原因。

追问一句：如果不引入任何锁，只靠数据库的唯一约束，能否彻底解决？为什么？', '**根本原因："先查后做"不是原子操作，查询与扣款之间没有互斥**，并发下两个请求都查到"无记录"，于是各扣一次款，这是典型竞态（check-then-act / TOCTOU）。**不能只靠唯一约束彻底解决**：唯一约束只拦得住幂等记录的重复插入，拦不住扣款动作本身——先扣款再写记录时，两个事务都能扣款成功，只有一个才因唯一键冲突失败，钱已扣出。正确做法是把扣款与幂等记录写入放**同一事务**，靠唯一键冲突触发整体回滚，或用 SELECT FOR UPDATE / 乐观锁保证同一订单串行。', '["check-then-act 竞态条件","唯一约束的原子性边界"]', '["某订单系统做幂等扣款，方案是「先查一次是否有成功扣款记录，没有就执行扣款」。在多线程并发请求同一订单时，这个方案会出什么问题","请说明根本原因。 追问一句：如果不引入任何锁，只靠数据库的唯一约束，能否彻底解决"]', '["AtomicInteger · 常用方法与适用场景","CAS · 原理与三大问题","ReentrantLock · 与 synchronized"]', '订单幂等扣款服务，三手段分工与失败处理取舍', '大题', '场景应用', 23, NULL, 1793239081508),
	(104, 2, 2, 12, 1, '两个线程共享一个普通变量：线程 A 先写入 flag，再写入 data；线程 B 先读 data，再读 flag。为什么即使 B 看到 flag 为 true，仍可能读到旧的 data？根本原因是什么？', '**根本原因是缺少 happens-before 保证，导致指令重排序。** A 端写 flag、写 data 是两个独立的普通写操作，可被重排为先写 flag 再写 data；B 端读 data、读 flag 也可能被重排。于是 B 可能先看到 flag=true，此时 data 还没被写入新值，就读到了旧 data。**把 flag 声明为 volatile**，写 flag 之前的写不会重排到其后、读 flag 之后的读不会提前，即可解决；或用 synchronized 保证同一临界区内的可见性与有序性。', '["可见性（内存可见性）","指令重排序"]', '["两个线程共享一个普通变量：线程 A 先写入 flag，再写入 data；线程 B 先读 data，再读 flag。为什么即使 B 看到 flag 为 true，仍可能读到旧的 data","根本原因是什么"]', '["volatile · 指令重排序与happens-befor"]', '两线程读写顺序颠倒，何时可见性没保证', '基础', '概念辨析', 8, NULL, 1793324983768),
	(105, 2, 2, 12, 3, '双重检查锁定（DCL）实现单例时，为什么 instance 字段必须声明为 volatile？如果不加 volatile 可能出现什么问题？', '**因为 volatile 禁止指令重排序。** new 对象包含三步：分配内存、执行构造器、引用赋值。不加 volatile 时，赋值可能先于构造执行，另一个线程通过外层判空看到 instance 非 null，就直接返回了**尚未构造完成的对象**，后续使用会出错。加 volatile 后三步严格有序，且写读之间有 happens-before 保证，别的线程要么看到 null，要么看到完整构造好的实例。注意：synchronized 只保证互斥与临界区可见性，不能解决「引用先于构造可见」的重排问题，所以 volatile 不能省。', '["volatile 禁止指令重排序","DCL 单例的可见性/安全性"]', '["双重检查锁定（DCL）实现单例时，为什么 instance 字段必须声明为 volatile","如果不加 volatile 可能出现什么问题"]', '["volatile · 禁止指令重排"]', 'volatile 如何阻止重排影响初始化结果', '基础', '概念辨析', 8, NULL, 1793324983777),
	(106, 2, 2, 12, 9, '同一个类里有实例同步方法和静态同步方法，分别被两个线程调用时，它们的锁对象是什么？这两类方法之间会不会互斥？如果有两个实例，两个线程分别调用这两个实例上的同一个实例同步方法，会不会互斥？请分别说明原因。', '**实例同步方法锁的是对象实例（this），静态同步方法锁的是类对象（XXX.class）。** ①两者锁对象不同，所以**不会互斥**：一个线程进实例方法、另一个进静态方法，可同时执行。②两个实例上调用同一个实例同步方法**也不会互斥**，因为是两个不同的对象、两把不同的锁，各锁各的。只有竞争同一把锁（同一个实例，或都锁 XXX.class）才会互斥。', '["synchronized 实例方法锁对象（this）","synchronized 静态方法锁对象（Class 对象）"]', '["同一个类里有实例同步方法和静态同步方法，分别被两个线程调用时，它们的锁对象是什么","这两类方法之间会不会互斥","如果有两个实例，两个线程分别调用这两个实例上的同一个实例同步方法，会不会互斥","请分别说明原因。"]', '["synchronized · 方法锁与静态方法锁的对象差异"]', '实例方法锁与静态方法锁互斥范围对比', '中档', '原理追问', 11, NULL, 1793324988703),
	(107, 2, 2, 12, 5, '扣款接口先查库判断余额充足、再执行扣款更新，两次操作之间没有加任何锁。为什么高并发下仍会出现重复扣款（余额被扣成负数）？请说明根本原因。', '**根本原因是「查询余额—判断—扣款更新」是复合操作，却没有任何原子性保证，存在 check-then-act 竞态。** 高并发下多个线程几乎同时读到同一份余额（如都是 100），都判断充足，然后各自执行扣款写回，写操作互相覆盖，最后一次写的结果掩盖了前面的扣款，最终余额只减了一次却扣了两笔，甚至被扣成负数。要解决必须让「判断+扣款」在一个原子单元内完成（加锁或条件原子更新）。', '["检查-再-执行（check-then-act）竞态条件","原子性与可见性的区别"]', '["扣款接口先查库判断余额充足、再执行扣款更新，两次操作之间没有加任何锁。为什么高并发下仍会出现重复扣款（余额被扣成负数）","请说明根本原因。"]', '["synchronized · 竞态条件导致重复扣款"]', '扣款查库后操作为何仍会并发重复扣款', '基础', '概念辨析', 8, NULL, 1793324990325),
	(108, 2, 2, 12, 6, '多个线程对一个普通 int 计数器做并发自增（i++），即使给变量加了 volatile，最终结果仍比预期小。请说明为什么 volatile 保证不了计数正确。', '**因为 volatile 不保证操作的原子性。** i++ 实际是「读出旧值—加 1—写回」三步，volatile 只保证每次读都是最新值、禁止指令重排序，但三个步骤之间仍可被其他线程插入，多个线程读到同一旧值后各自写回，造成**丢失更新**，结果比预期小。要计数正确需用 AtomicInteger/LongAdder 等原子类，或用 synchronized/Lock 把整个自增包成原子操作。', '["volatile 语义（可见性、不保证原子性）","i++ 复合操作的竞态"]', '["多个线程对一个普通 int 计数器做并发自增（i++），即使给变量加了 volatile，最终结果仍比预期小。请说明为什么 volatile 保证不了计数正确。"]', '["volatile · 不保证复合操作原子性"]', 'volatile 计数器并发自增结果为何偏小', '基础', '概念辨析', 8, NULL, 1793324990332),
	(109, 2, 2, 12, 7, 'ReentrantLock 有两种获取锁的方式：带超时的 tryLock(timeout) 与 lockInterruptibly()。请说明两者在「获取不到锁时的行为」上的区别，以及各自适合什么场景。', '**核心区别：拿不到锁时，tryLock(timeout) 超时返回 false，lockInterruptibly 则在等待中被中断时抛出 InterruptedException。** tryLock(timeout) 给了明确的等待上限，避免线程无限阻塞，适合「等一小段时间、拿不到就走降级/快速失败逻辑」的场景；lockInterruptibly 让等待可被中断，适合需要**及时响应取消、服务优雅停机**的场景，拿到锁后方法内还要恢复中断状态。若两者都不需要，普通 lock() 会一直等下去且不响应中断。', '["tryLock 超时与 lockInterruptibly 的行为差异","可中断锁获取的适用场景"]', '["ReentrantLock 有两种获取锁的方式：带超时的 tryLock(timeout) 与 lockInterruptibly()。请说明两者在「获取不到锁时的行为」上的区别，以及各自适合什么场景。"]', '["ReentrantLock · tryLock 超时与可中断"]', '带超时的 tryLock 与 lockInterruptibly 选型区别', '基础', '概念辨析', 7, NULL, 1793324990339),
	(110, 2, 2, 12, 8, '双重检查锁（DCL）单例中，instance 变量被声明为 volatile。有人觉得「外层判空 + synchronized 已经够了，volatile 可以省」。请回答：①省掉 volatile 后会出现什么问题？②问题的根源是什么？', '**①省掉 volatile 后，别的线程可能拿到非 null 但尚未构造完成的对象。** ②**根源是指令重排序 + 缺少 happens-before**：new 对象是「分配内存→执行构造→引用赋值」三步，可能被重排为「分配→赋值→构造」；内层判空是在 synchronized 之外读的，写与这次读之间没有顺序与可见性保证，于是看到半成品实例。synchronized 只保证临界区互斥与可见性，挡不住这种锁外读到的重排结果，所以 volatile 不能省。', '["volatile 禁止指令重排序","DCL 单例的半初始化对象问题"]', '["省掉 volatile 后会出现什么问题？","问题的根源是什么？"]', '["volatile · 禁止指令重排序"]', '单例双检锁里 volatile 为何不可省略', '中档', '原理追问', 11, NULL, 1793324990345),
	(111, 2, 2, 12, 4, 'AQS（AbstractQueuedSynchronizer）主要解决什么问题？自定义同步器继承它时，必须重写哪两个方法？', '**AQS 解决的问题**：它是 JUC 中构建**锁和同步器的框架/骨架**，把线程**阻塞、唤醒、排队（FIFO 等待队列）、获取/释放资源**这些通用逻辑统一实现，子类只需定义"资源如何获取与释放"，避免每写一个同步器就重复处理线程调度。**必须重写两个方法**：
1. **tryAcquire(int)**：以独占方式尝试获取资源（成功返回 true）；
2. **tryRelease(int)**：以独占方式尝试释放资源。
（共享模式下对应 tryAcquireShared / tryReleaseShared）。
**核心思想**：AQS 用一个 **volatile 的 int state** 表示同步状态，配合 **CAS** 修改 state，并通过**内置的 FIFO 双向等待队列**管理阻塞线程；tryAcquire/tryRelease 是**模板方法模式**中留给子类实现的"钩子"。', '["AQS 的作用与设计思想（模板方法 + 同步状态 state + 等待队列）","子类需重写的方法：tryAcquire / tryRelease"]', '["AQS（AbstractQueuedSynchronizer）主要解决什么问题","自定义同步器继承它时，必须重写哪两个方法"]', '["AQS · 核心思想与模板结构"]', 'AQS 解决什么问题、子类要实现哪两个方法', '基础', '概念辨析', 8, NULL, 1793325006730),
	(112, 2, 2, 12, 2, 'synchronized 的锁升级（偏向锁→轻量级锁→重量级锁）为什么是单向的、只能升不能降？请说明不可逆的原因，以及在什么情形下只允许升级、不允许退回更轻的锁状态。', '**锁状态记录在对象头 Mark Word 中，升级是单向的状态迁移。** 偏向锁遇到其他线程竞争就撤销并升级为轻量级锁；轻量级锁自旋仍竞争激烈时膨胀为重量级锁。不可逆的原因：一旦对象绑定 monitor、有线程进入等待队列阻塞，锁对象与等待者的状态由 monitor 统一维护，若退回轻量级或偏向状态，这些阻塞线程会被丢失、互斥无法保证，代价与风险极高，JVM 因此不做降级。**当竞争激烈、已有线程在 monitor 队列阻塞时，只允许继续维持/升级重量级锁，不允许退回更轻的状态。**', '["synchronized 锁升级方向不可逆的原因","偏向锁/轻量级锁升级的触发时机"]', '["synchronized 的锁升级（偏向锁→轻量级锁→重量级锁）为什么是单向的、只能升不能降","请说明不可逆的原因，以及在什么情形下只允许升级、不允许退回更轻的锁状态。"]', '["synchronized锁升级 · 单向不可逆与不可降级"]', '锁升级为什么不可逆、何时只能升不能降', '基础', '概念辨析', 8, NULL, 1793325008561),
	(113, 2, 2, 12, 10, '一个服务里有两个变量：一个是从配置中心拉取的配置对象引用 config，用 volatile 修饰，读多写极少；另一个是本地请求计数器 count++，也想用 volatile 修饰。

线上配置读取一直正常，但压测发现计数器数字明显偏小。

请回答：
① 为什么同样是 volatile，config 的读写是安全的，count++ 却会丢数？请说明两者在原子性上的差别。
② 针对 count++ 这种"读—改—写"复合操作，在不引入 synchronized 的前提下，应该换成什么手段？请给出至少两种常见做法。
③ 如果配置更新从"单个对象引用替换"升级为"三个字段一起更新"（比如超时时间、重试次数、开关），volatile 还够不够？请给出你的判断理由和对应的改造方案。', '**①** volatile 保证的是**可见性**和**单次读/写的原子性**。config 只做**整引用替换**，这一步本身就是原子的，读线程要么看到旧引用要么看到新引用，永远是完整对象，所以安全；而 count++ 是**读—改—写三步复合操作**，volatile 只保证每一步各自可见，两线程可能读到同一个旧值再各自写回，丢失更新，所以丢数。**②** 不用 synchronized 的做法：一是用**原子类** AtomicInteger/AtomicLong，底层 CAS 自旋完成读改写；二是高并发下用 **LongAdder**，分段累加降低 CAS 竞争，最后 sum() 汇总。**③** 不够。volatile 只保证**引用本身的可见性**，不保证对象内部字段的修改被感知，且三个字段的更新**不是原子的**，线程可能读到"新超时+旧开关"的中间态。改造方案：把三个字段**封装成不可变配置对象**，用一个 volatile 引用（或 AtomicReference）**整体替换**，读线程拿到的总是一致快照；或在更新方法上加 synchronized 保证互斥。', '["volatile 的语义：可见性与非原子性","复合操作（i++）的线程安全改造","多字段一致性更新与不可变对象封装"]', '["为什么同样是 volatile，config 的读写是安全的，count++ 却会丢数？请说明两者在原子性上的差别。","针对 count++ 这种\"读—改—写\"复合操作，在不引入 synchronized 的前提下，应该换成什么手段？请给出至少两种常见做法。","如果配置更新从\"单个对象引用替换\"升级为\"三个字段一起更新\"（比如超时时间、重试次数、开关），volatile 还够不够？请给出你的判断理由和对应的改造方案。"]', '["volatile · 指令重排序与 happens-befo","volatile · 典型使用场景","volatile · 可见性与原子性边界"]', '配置更新与计数器场景：volatile 何时够、何时必须换手段', '大题', '场景应用', 23, NULL, 1793325039192),
	(114, 2, 2, 13, 1, '单例模式的双重检查锁（DCL）写法里，instance 字段为什么要加 volatile？请说明不加 volatile 可能出什么问题，以及根本原因是什么。', '**加 volatile 的核心是禁止指令重排序，避免拿到「半初始化」对象。** 对象创建分三步：分配内存、执行构造函数、把引用赋给 instance。JMM 允许后两步重排，可能变成「分配内存→赋引用→执行构造」。此时线程 B 在第一次判空看到 instance 非 null，直接返回一个构造还没跑完的对象，字段是脏的。volatile 通过内存屏障禁止这种重排，并保证写入结果对其他线程可见。', '["volatile 禁止重排序","DCL 单例"]', '["单例模式的双重检查锁（DCL）写法里，instance 字段为什么要加 volatile","请说明不加 volatile 可能出什么问题，以及根本原因是什么。"]', '["volatile · 指令重排序与 happens-befo"]', '为何单例 DCL 里 instance 需要 volatile', '基础', '概念辨析', 3, NULL, 1793327162769),
	(115, 2, 2, 13, 2, '用 AtomicLong 做计数器为例，简述 CAS 是怎么完成一次自增的？再说明这种机制会遇到的 ABA 问题指什么。', '**CAS 是「读—算—比较交换」的自旋循环**：先读出当前值 old，算出 old+1，用原子指令比较内存里的值是否仍等于 old，是则替换成 old+1，否则重新读值重试。AtomicLong.incrementAndGet 就是这样自增的。**ABA 问题**指值从 A 改成 B 又改回 A，CAS 只比较最终值，无法察觉中间被改过，可能做出错误判断；通常用 **AtomicStampedReference 加版本号**解决。', '["CAS 原理","ABA 问题"]', '["用 AtomicLong 做计数器为例，简述 CAS 是怎么完成一次自增的","再说明这种机制会遇到的 ABA 问题指什么。"]', '["CAS · 原理与三大问题"]', '用 AtomicLong 计数举例讲 CAS 原理与 ABA 问题', '基础', '概念辨析', 3, NULL, 1793327162774),
	(116, 2, 2, 13, 4, '库存扣减场景要求"拿不到锁就等一小段时间、超时直接失败"，为什么通常选 ReentrantLock 而不是 synchronized？请指出关键 API 与取舍。', '**要「等一小段就失败」，只有 ReentrantLock 做得到。** 关键 API 是 **lock.tryLock(long timeout, TimeUnit unit)**：限定时间内抢到锁返回 true，超时返回 false，业务直接返回失败；synchronized 只能无限阻塞，没有超时 API。取舍上，ReentrantLock 更灵活（超时、可中断、公平锁），但必须在 **finally 中手动 unlock**，否则可能泄漏锁；synchronized 由 JVM 自动释放、写法简单，不需要超时控制时优先用它。', '["ReentrantLock tryLock 超时","synchronized 与 Lock 的取舍"]', '["库存扣减场景要求\"拿不到锁就等一小段时间、超时直接失败\"，为什么通常选 ReentrantLock 而不是 synchronized","请指出关键 API 与取舍。"]', '["ReentrantLock · 与 synchronized"]', '需要 tryLock 超时的库存扣减为何选 ReentrantLock', '基础', '概念辨析', 3, NULL, 1793327162790),
	(117, 2, 2, 13, 9, '简单计数器场景（无复杂业务逻辑，只需保证 count++ 原子性）下，什么时候选 CAS 实现（如 AtomicInteger），什么时候选锁（如 synchronized）？请给出判断依据。', '**看竞争程度。** 竞争不激烈、只有少量线程更新时，用 **AtomicInteger**：CAS 无锁，一次比较交换基本都能成功，性能优于加锁。竞争激烈、大量线程同时更新时，用 **synchronized**：此时 CAS 会反复自旋失败，空耗 CPU；而锁竞争激烈时会升级为重量级锁、进入队列阻塞等待，避免空转，吞吐更稳。', '["CAS 与锁的适用场景对比","CAS 的局限（单变量原子性、高竞争自旋开销）"]', '["简单计数器场景（无复杂业务逻辑，只需保证 count++ 原子性）下，什么时候选 CAS 实现（如 AtomicInteger），什么时候选锁（如 synchronized）","请给出判断依据。"]', '["CAS · 适用场景选型（无锁 vs 加锁）"]', '简单计数器场景怎么在 CAS 与锁之间选', '基础', '概念辨析', 3, NULL, 1793327163001),
	(118, 2, 2, 13, 11, '静态 synchronized 方法与实例 synchronized 方法能否互斥？它们各自锁的是什么对象？', '**不能互斥**。静态 synchronized 方法锁的是**该类的 Class 对象**（如 Foo.class），实例 synchronized 方法锁的是**当前实例 this**。二者监视器不是同一个，所以可以同时进入。若要让它们互斥，必须让两者锁同一个对象，例如实例方法也去锁 Foo.class。', '["synchronized 静态方法与实例方法的锁对象差异","锁对象决定是否互斥"]', '["静态 synchronized 方法与实例 synchronized 方法能否互斥","它们各自锁的是什么对象"]', '["synchronized · 方法锁与静态方法锁的对象差异"]', '静态 synchronized 方法与实例方法能否互斥', '基础', '概念辨析', 3, NULL, 1793327163001),
	(119, 2, 2, 13, 12, '多线程下执行 count++ 得到的结果比预期少，原因是什么？请说明并给出修正思路。', '原因是 **count++ 是非原子的「读-改-写」三步复合操作**：线程 A、B 同时读到旧值，各自加 1 后先后写回，后写的覆盖先写的，导致少加。修正思路：① 用 **synchronized 或 Lock** 把「读-判断-写」放入同一同步块，保证互斥与原子性；② 用原子类 **AtomicInteger.incrementAndGet()**（CAS 实现）；③ 超高并发计数用 **LongAdder** 分段累加。注意 volatile 只保证可见性，不能解决 count++ 的原子性。', '["count++ 的非原子性与丢失更新","原子性修正手段（synchronized/AtomicInteger/LongAdder）"]', '["多线程下执行 count++ 得到的结果比预期少，原因是什么","请说明并给出修正思路。"]', '["自增操作 · 非原子导致计数丢失"]', '多线程下 count++ 计数少了的原因与修正', '基础', '概念辨析', 3, NULL, 1793327163016),
	(120, 2, 2, 13, 5, '线程在 AQS 中抢锁失败后，会依次经历哪些步骤最终进入等待？请说明自旋重试、入队与阻塞这几个环节的先后顺序。', '抢锁失败后，线程并非立即阻塞，而是走**自旋重试 → 入队 → 阻塞**的顺序。①**自旋重试**：先在本地自旋几次重新尝试获取锁，若在自旋期间锁被释放，可直接拿到锁而不必入队，减少上下文切换。②**入队**：自旋仍失败，就把节点加入 AQS 同步队列尾部（CLH 队列），排队等待。③**阻塞**：入队后线程被挂起，进入等待状态，直到前驱节点释放锁并唤醒它。被唤醒后再次尝试获取锁，失败则继续排队。这样设计能兼顾吞吐量与公平性：自旋减少无谓阻塞，队列保证等待有序。', '["AQS 同步队列（CLH 队列）","自旋与阻塞的先后顺序"]', '["线程在 AQS 中抢锁失败后，会依次经历哪些步骤最终进入等待","请说明自旋重试、入队与阻塞这几个环节的先后顺序。"]', '["AQS · ReentrantLock 的加锁解锁流程"]', '线程抢锁失败后在 AQS 队列里怎么走', '基础', '概念辨析', 3, NULL, 1793327169464),
	(121, 2, 2, 13, 6, '什么是 happens-before？volatile 关键字是如何体现 happens-before 关系的？', '**happens-before 是 JMM 描述两个操作之间可见性与顺序保证的规则**：若 A happens-before B，则 A 的结果对 B 可见，且 A 排在 B 之前。volatile 体现在两处：①**对 volatile 变量的写 happens-before 之后对该变量的读**，写线程写入的值及其之前的普通写，对读线程都可见；②volatile 写/读形成内存屏障，禁止普通读写跨越它重排序。', '["happens-before 语义","volatile 的可见性与禁止重排序"]', '["什么是 happens-before","volatile 关键字是如何体现 happens-before 关系的"]', '["happens-before 与 volatile 禁止重排"]', '解释 happens-before 含义与 volatile 如何体现', '基础', '概念辨析', 3, NULL, 1793327169464),
	(122, 2, 2, 13, 7, 'synchronized(this) 与 synchronized(X.class) 有什么区别？分别锁住的是什么对象？', '**区别在锁对象不同。** synchronized(this) 锁的是**当前对象实例**，作用范围是这一个实例；synchronized(X.class) 锁的是**该类的 Class 对象**，对所有实例和静态资源生效。因为锁对象不同，**两者互不阻塞**——线程 A 持有实例锁时，线程 B 仍可进入类锁代码块，反之亦然。', '["synchronized 的锁对象","实例锁与类锁（Class 锁）的区别"]', '["synchronized(this) 与 synchronized(X.class) 有什么区别","分别锁住的是什么对象"]', '["synchronized · 锁对象辨析（实例/类/方法）"]', 'synchronized(this) 与 synchronized(X.class) 区别', '基础', '概念辨析', 3, NULL, 1793327169473),
	(123, 2, 2, 13, 8, 'check-then-act（先检查再执行）这种两步操作，为什么要作为一个整体加锁？', '**因为检查和执行之间存在时间窗口，不是一个原子操作。** 线程 A 完成检查后、执行前，线程 B 可能已经修改了共享状态，A 的检查结果就此失效。例如两线程都通过「库存>0」的检查，再各自扣减，就会超卖。只锁检查或只锁执行都无法消除这个窗口，必须把**检查+执行放在同一临界区整体加锁**，让二者成为一个原子操作。', '["check-then-act 竞态条件","临界区与原子性"]', '["check-then-act（先检查再执行）这种两步操作，为什么要作为一个整体加锁？"]', '["原子性 · 复合操作不保证原子"]', 'check-then-act 两步操作为何要整体加锁', '基础', '概念辨析', 3, NULL, 1793327169473),
	(124, 2, 2, 13, 13, 'synchronized 是可重入的，这里的"可重入"指什么？如果一个线程对同一把锁反复加锁、持锁层级过深（例如递归调用层层加锁），会带来哪些风险？', '**可重入**指：同一个线程可以**再次获得自己已经持有的同一把锁**而不会被自己阻塞，锁内部记录持有线程与重入次数，解锁次数与加锁次数对齐后才真正释放。风险：递归层层加锁**不会导致自我死锁**，但会使**持锁时间变长**、其他线程等待更久、吞吐下降；轻量级锁会在栈帧中不断压入锁记录，栈膨胀甚至**升级为重量级锁**；只有多把锁交叉获取才会死锁。', '["可重入锁的语义","锁持有时间与并发度"]', '["synchronized 是可重入的，这里的\"可重入\"指什么","如果一个线程对同一把锁反复加锁、持锁层级过深（例如递归调用层层加锁），会带来哪些风险"]', '["ReentrantLock · 可重入次数上限"]', '可重入含义与锁持有过深的风险', '基础', '概念辨析', 3, NULL, 1793327179968),
	(125, 2, 2, 13, 14, '某账户系统里，扣款逻辑是先读余额、判断余额是否足够，再执行扣减。这三步没有放在同一个同步块内，也没有加锁。结果同账户并发扣款时出现重复扣款。请定位：这是并发问题里的什么性质？根本原因是什么？', '性质是**竞态（race condition）**，表现为重复扣款/丢失更新。根本原因：**「读余额→判断是否足够→扣减」是一组 check-then-act 复合操作，既没有放在同一同步块，也没有任何互斥/原子性保护**，检查与执行之间存在时间窗口——两个线程同时读到余额并都通过检查，再各自扣减，于是同一笔余额被扣了两次。', '["原子性与竞态条件","check-then-act 非原子"]', '["某账户系统里，扣款逻辑是先读余额、判断余额是否足够，再执行扣减。这三步没有放在同一个同步块内，也没有加锁。结果同账户并发扣款时出现重复扣款。请定位：这是并发问题里的什么性质","根本原因是什么"]', '["synchronized · 竞态条件导致重复扣款"]', '余额校验与扣减间无同步导致重复扣款定位', '基础', '概念辨析', 3, NULL, 1793327179968),
	(126, 2, 2, 13, 15, '某线程调用 wait() 后被 notify() 唤醒，但它并不能立刻从 wait() 返回继续执行。为什么？', '因为 **notify 只是让被唤醒线程获得重新竞争锁的资格**，并不直接归还锁：notify 后线程进入同步队列，必须等 notify 线程退出同步块释放锁，再与其它线程竞争拿到锁，才能从 wait() 返回继续执行。而且唤醒后**条件可能已被其它线程改变**（也可能虚假唤醒），因此条件判断必须写在 **while 循环**里重新检查，不能假设唤醒即条件成立。', '["wait/notify 与锁的关系","被唤醒线程需重新竞争锁"]', '["某线程调用 wait() 后被 notify() 唤醒，但它并不能立刻从 wait() 返回继续执行。为什么？"]', '["wait/notify · 唤醒后仍需竞争锁"]', '被 notify 后线程为何还要再抢锁才返回', '基础', '概念辨析', 3, NULL, 1793327179984),
	(127, 2, 2, 13, 17, '某电商网关的路由配置由后台线程整体替换，业务线程只读取当前配置对象做路由，配置对象创建后不再修改其内部状态。业务侧目前用一个普通成员变量保存配置引用，线上偶发读到「半初始化」的配置对象。

① 为什么普通成员变量会出现读到半初始化对象的情况？
② 只把该字段改成 volatile 引用，能否彻底解决这个问题？为什么？
③ 在「整体替换、只读、单写多读」这种模式下，什么情况下 volatile 已经够用，什么情况下必须再加锁（synchronized 或 Lock）？请分别给出判据。', '① 普通字段既无**可见性**也无**有序性**保证：JVM 可能把「分配内存→构造→引用赋值」**重排**为「分配内存→引用赋值→构造」，写线程的字段写入也不保证对读线程可见，于是读线程拿到引用时对象还在构造中，即**半初始化**。
② 改成 **volatile 引用能解决这个问题**：volatile 写前的操作 happens-before 读线程读到该引用后的操作，保证**读到的一定是构造完成的对象**（安全发布）。前提是对象**构造后不再修改、构造中不逸出 this**；若对象可变，volatile 只保证引用可见，不保证内部状态一致。
③ **volatile 够用**：只有单个引用被原子整体替换、对象不可变、线程只读引用。**必须加锁**：存在读-改-写、check-then-act，或多字段/多引用需要**同时保持一致不变量**（需要原子性与互斥）时。', '["volatile 的可见性与有序性保证","volatile 适用边界（不保证复合操作原子性）"]', '["为什么普通成员变量会出现读到半初始化对象的情况？","只把该字段改成 volatile 引用，能否彻底解决这个问题？为什么？","在「整体替换、只读、单写多读」这种模式下，什么情况下 volatile 已经够用，什么情况下必须再加锁（synchronized 或 Lock）？请分别给出判据。"]', '["volatile · 引用替换与对象字段修改的可见性差异","volatile · 指令重排序与happens-befor","volatile · 状态标志位典型用法"]', 'volatile 引用更新配置，何时够用何时要加锁', '大题', '场景应用', 11, NULL, 1793327202673),
	(128, 2, 2, 13, 20, '某广告投放系统有一个计数器类：
```java
class AdCounter {
    private volatile long impressions;
    public void incr() { impressions++; }
    public long get() { return impressions; }
}
```
压测发现：启动 8 个线程各执行 10 万次 incr()，最终 get() 结果远小于 80 万，出现「计数丢失」。开发同学提出几个方案：
1）把 incr 改成 synchronized 方法；
2）改用 AtomicLong 的 getAndIncrement；
3）改用 LongAdder。

请回答：
① 为什么加了 volatile 仍然会丢失计数？请解释 impressions++ 的执行过程。
② 三个方案各自能否解决丢失问题？解决原理分别是什么？
③ 该场景 QPS 极高但只需最终总数近似准确（报表用），三个方案中你选哪个？为什么？', '**①** `impressions++` 是**读-改-写**三步：读出旧值、加 1、写回。volatile 只保证**可见性**和禁止重排序，不保证这三步整体原子。两个线程**同时读到同一个旧值**，各加 1 后先后写回，后写覆盖前写，丢掉一次自增，所以结果远小于 80 万。
**②** 三个方案**都能解决丢失**：1）synchronized 方法把自增放入**临界区**，同一时刻只有一个线程执行；2）AtomicLong 的 `getAndIncrement()` 用 **CAS** 把自增做成原子操作，失败重试；3）LongAdder 把值拆成 **base + 多个 Cell**，各线程用 CAS 在不同 Cell 上累加，`sum()` 汇总，**不丢增量**，只是 sum() 非原子快照。
**③ 选 LongAdder**：QPS 极高时 AtomicLong 的 CAS 会激烈重试、synchronized 会排队，LongAdder 把竞争**分散到多个 Cell**，吞吐最高；报表只需最终总数，`sum()` 汇总即可满足。', '["volatile 不保证复合操作原子性（读-改-写丢失）","高并发计数方案取舍（synchronized/AtomicLong/LongAdder）"]', '["为什么加了 volatile 仍然会丢失计数？请解释 impressions++ 的执行过程。","三个方案各自能否解决丢失问题？解决原理分别是什么？","该场景 QPS 极高但只需最终总数近似准确（报表用），三个方案中你选哪个？为什么？"]', '["volatile · 保证可见性但不保证原子性","CAS · 高竞争下的适用性与放弃策略","volatile对引用替换与字段修改的差异"]', 'volatile 计数丢失现象与退化方案的取舍分析', '大题', '场景应用', 11, NULL, 1793327202690),
	(129, 2, 2, 13, 10, '多线程并发抢锁时，线程先做自旋等待。自旋迟迟拿不到锁时，该如何判断该停止自旋、转为阻塞加锁？', '**用自旋次数（或自旋时间）阈值作为退出条件**：线程自旋一定次数仍未拿到锁，就停止自旋、挂起线程，转为阻塞加锁（重量级锁/OS 互斥等待）。HotSpot 还有**自适应自旋**——根据这把锁上一次自旋是否成功来动态调整阈值：上次成功就多自旋一会，上次失败就早点阻塞。核心目的是控制自旋成本，避免在长时间持锁时空转 CPU。', '["自旋锁与自适应自旋","自旋次数上限判断"]', '["多线程并发抢锁时，线程先做自旋等待。自旋迟迟拿不到锁时，该如何判断该停止自旋、转为阻塞加锁？"]', '["CAS · 高竞争下的自旋与退化到锁"]', '自旋迟迟不成功时如何判定该退回加锁', '基础', '概念辨析', 3, NULL, 1793327213951),
	(130, 2, 2, 13, 18, '某服务类 Service 中有实例方法 `synchronized void deduct()` 和静态方法 `synchronized static void init()`，分别持有不同对象的锁。请判断：
① 两个线程一个调用 `deduct()`、一个调用 `init()`，会不会互相阻塞？为什么？
② 如果把 `deduct()` 改成 `synchronized static void deduct()`，两个线程分别调用 `deduct()` 和 `init()`，会不会互相阻塞？为什么？
③ 线程 A 调用实例方法 `deduct()` 的同时，线程 B 在同一实例上执行 `synchronized(this) {}` 代码块，两者会不会互斥？为什么？', '**① 不会互斥**：`synchronized void deduct()` 是实例同步方法，锁的是**当前实例（this）**；`synchronized static void init()` 是静态同步方法，锁的是 **Service.class 类对象**，两把锁不同，互不影响。
**② 会互斥**：改成 static 后两个方法都是静态同步方法，都锁 **Service.class**，同一把锁，必须串行进入。
**③ 会互斥**：实例同步方法内部锁的就是 this，与 `synchronized(this) {}` 竞争的是**同一个实例对象锁**，同一实例下两者互斥；若 B 在**另一个实例**上执行该代码块则不互斥。', '["synchronized 的锁对象（实例对象 vs Class 对象）","synchronized 实例方法与代码块的锁一致性"]', '["两个线程一个调用 `deduct()`、一个调用 `init()`，会不会互相阻塞？为什么？","如果把 `deduct()` 改成 `synchronized static void deduct()`，两个线程分别调用 `deduct()` 和 `init()`，会不会互相阻塞？为什么？","线程 A 调用实例方法 `deduct()` 的同时，线程 B 在同一实例上执行 `synchronized(this) {}` 代码块，两者会不会互斥？为什么？"]', '["synchronized · 实例锁与类锁的锁定对象","synchronized锁升级 · 升级后状态变化与降级","synchronized · 实例锁与类锁互斥关系"]', '实例方法与静态方法并发调用时的锁竞争判断', '大题', '场景应用', 11, NULL, 1793327218189),
	(131, 2, 2, 13, 19, '某订单系统在做秒杀活动，需要一个全局唯一的"请求计数器"用于限流统计，多个工作线程并发自增。有同学提出三个方案：① 用 AtomicLong 的 incrementAndGet；② 用 volatile long 配合 count++；③ 用 synchronized 方法对 long 做 count++。请回答：
① 上述三个方案中，哪几个能保证计数结果准确？为什么？
② 方案②为什么不行？请结合 volatile 的可见性与原子性两个层面说明。', '**① 方案①和③能保证准确**：`AtomicLong.incrementAndGet()` 用 **CAS** 把读-改-写合成一个原子操作；`synchronized` 方法用**锁互斥**保证同一时刻只有一个线程执行 `count++`。方案②不行。
**②** 从**原子性**看：`count++` 是**读-改-写三步**，不是原子操作，volatile 不提供复合操作的原子性。从**可见性**看：volatile 虽能保证线程每次读到**最新值**、写回后立刻对他人可见，但两个线程仍可能**同时读到同一个旧值**，各加 1 后分别写回，后写覆盖前写，丢失一次计数——可见性解决不了"基于同一旧值并发更新"的竞态。', '["volatile 的可见性与原子性边界","CAS 无锁原子操作"]', '["用 AtomicLong 的 incrementAndGet","用 volatile long 配合 count++","用 synchronized 方法对 long 做 count++。请回答：","上述三个方案中，哪几个能保证计数结果准确？为什么？","方案","为什么不行？请结合 volatile 的可见性与原子性两个层面说明。"]', '["CAS · 自旋开销与高并发下的性能退化","volatile · DCL单例中的指令重排与对象逸出","synchronized锁升级 · 单向不可逆与不可降级"]', '高并发下单例初始化与计数服务的手段取舍', '大题', '场景应用', 11, NULL, 1793327252540),
	(132, 2, 2, 13, 16, '某景区闸机服务用 Condition 控制排队许可：`lock.newCondition()` 创建的信号量，`await()` 放行前必须持锁，`signal()` 唤醒一个等待线程。请回答：
① `await()` 与 `signal()` 在锁的语义上分别做了什么（为什么 await 必须在持有锁时调用，signal 后被唤醒线程何时真正拿到锁）？
② 如果把 `signal()` 写成 `signalAll()`，对这个「一次只放行一个」的闸机会带来什么影响？', '① **await() 必须在持有该 Lock 时调用**（否则抛 IllegalMonitorStateException），因为它要原子地做两件事：**释放锁 + 把自己放入该 condition 的等待队列并挂起**；**signal()** 只是把一个等待线程从 condition 队列**转移到同步队列**，被唤醒线程**必须等 signal 线程释放锁**后重新竞争，**抢到锁才从 await() 返回**继续执行。
② 改成 **signalAll()** 会唤醒**全部**等待线程，它们逐个抢锁执行，形成**惊群**、性能下降；若不配合 while 重新检查条件，会**破坏「一次只放行一个」的闸机语义**（多个线程同时通过）。', '["Condition 的 await/signal 语义（await 释放锁并等待、signal 只是移到同步队列）","signal 与 signalAll 的取舍（精准唤醒 vs 唤醒风暴）"]', '["`await()` 与 `signal()` 在锁的语义上分别做了什么（为什么 await 必须在持有锁时调用，signal 后被唤醒线程何时真正拿到锁）？","如果把 `signal()` 写成 `signalAll()`，对这个「一次只放行一个」的闸机会带来什么影响？"]', '["ReentrantLock · tryLock 超时与可中断","Condition · 多条件等待唤醒","ReentrantLock · 公平锁与非公平锁"]', '限流闸机场景：await/signal 分工、tryLock 抢位、公平取舍', '大题', '场景应用', 11, NULL, 1793327300078),
	(133, 2, 4, 14, 6, '线程池的拒绝策略什么时候触发？它起什么作用？', '**当线程数已达最大线程数、且等待队列已满**时触发——此时新任务无法被接收。作用是**兜底处理**：按业务选择抛异常、由调用线程执行、丢弃或只记录日志，让任务被拒时的行为是**显式可控的策略**，而不是静默丢失或无限积压。', '["拒绝策略触发时机","拒绝策略作用"]', '["线程池的拒绝策略什么时候触发","它起什么作用"]', '["线程池参数 · handler"]', '拒绝策略何时触发、作用是什么', '基础', '概念辨析', 9, NULL, 1793608962402),
	(134, 2, 4, 14, 1, '向线程池提交一个任务后，任务会按什么顺序被线程池处理？请说明从提交到被执行的判断顺序（不用讲具体方法名）。', '**先核心线程，再入队，再扩到最大线程，最后拒绝**。提交任务后依次判断：①当前线程数<核心线程数，直接创建核心线程执行；②核心线程已满，任务进入等待队列；③队列也满了，线程数<最大线程数，创建非核心线程执行；④线程数已达最大且队列满，触发拒绝策略。', '["线程池任务提交处理流程","七大参数中的 corePoolSize / maximumPoolSize / workQueue 协作关系"]', '["向线程池提交一个任务后，任务会按什么顺序被线程池处理","请说明从提交到被执行的判断顺序（不用讲具体方法名）。"]', '["线程池工作流程 · 主干执行链路"]', '提交一个任务后按什么顺序被处理', '基础', '概念辨析', 10, NULL, 1793608963614),
	(135, 2, 4, 14, 2, '线程池默认的拒绝策略是哪一种？任务被拒绝时会抛出什么？这个任务最终去哪了？', '默认是 **AbortPolicy（直接抛异常）**。任务被拒绝时抛出 **RejectedExecutionException**（运行时异常），异常抛给提交任务的调用方。这个任务**不会被保存、也不会被执行，直接被丢弃**，只能由调用方感知到提交失败。', '["四种内置拒绝策略之 AbortPolicy","RejectedExecutionException"]', '["线程池默认的拒绝策略是哪一种","任务被拒绝时会抛出什么","这个任务最终去哪了"]', '["拒绝策略 · AbortPolicy"]', '默认拒绝策略抛什么、任务去哪了', '基础', '概念辨析', 10, NULL, 1793608963618),
	(136, 2, 4, 14, 3, '下面三种需求分别适合用 Executors 的哪个工厂方法创建线程池？① 一次性启动一批任务，等所有任务都完成再继续往下走；② 单线程顺序执行，保证任务一个接一个跑；③ 长时间运行的定时/周期任务。', '①**newFixedThreadPool**：固定线程数并发执行一批任务，配合 CountDownLatch 或 Future.get 等全部完成再继续；②**newSingleThreadExecutor**：单线程，保证任务**一个接一个顺序执行**；③**newScheduledThreadPool**：支持**定时与周期执行**，适合长时间运行的调度任务。', '["Executors 四种内置线程池","newFixedThreadPool / newSingleThreadExecutor / newScheduledThreadPool 适用场景"]', '["一次性启动一批任务，等所有任务都完成再继续往下走","单线程顺序执行，保证任务一个接一个跑","长时间运行的定时/周期任务。"]', '["四种内置线程池 · 逐一识别"]', '给场景选对应的 Executors 工厂方法', '基础', '概念辨析', 9, NULL, 1793608963621),
	(137, 2, 4, 14, 4, '线程池使用 CallerRunsPolicy 拒绝策略，当队列和最大线程都满、任务被拒绝时，这个任务由谁执行？对整体有什么效果？', '任务由**提交任务的调用线程（caller）自己执行**，而不是线程池里的线程。效果是形成**反压**：提交方速度被拖慢、请求耗时拉长，任务不丢；同时起到削峰限流作用，保护线程池不被压垮。', '["拒绝策略 CallerRunsPolicy","反压/限流效果与对调用线程的影响"]', '["线程池使用 CallerRunsPolicy 拒绝策略，当队列和最大线程都满、任务被拒绝时，这个任务由谁执行","对整体有什么效果"]', '["拒绝策略 · CallerRunsPolicy"]', '满了之后任务由谁执行、有何效果', '基础', '概念辨析', 9, NULL, 1793608963624),
	(138, 2, 4, 14, 9, '向一个已配置好核心线程数、最大线程数、阻塞队列的 ThreadPoolExecutor 提交任务时，任务从提交到被执行，会按什么顺序依次经历哪些环节？请按「核心线程 → 队列 → 非核心线程 → 拒绝策略」这条主线说明每个环节的触发条件。', '**主线是：核心线程 → 队列 → 非核心线程 → 拒绝策略。** 提交任务后：① 若当前线程数 < **corePoolSize**，直接创建核心线程执行；② 否则尝试把任务放入**阻塞队列**，队列未满就入队，等空闲线程拉取；③ 若队列已满且当前线程数 < **maximumPoolSize**，创建非核心线程执行；④ 若队列满且线程数已达最大值，则执行**拒绝策略**（默认 AbortPolicy 抛 RejectedExecutionException）。**关键点是队列没满永远不会扩容到非核心线程。**', '["线程池任务提交的推进顺序（核心线程→队列→非核心线程→拒绝）","四种拒绝策略的触发时机"]', '["向一个已配置好核心线程数、最大线程数、阻塞队列的 ThreadPoolExecutor 提交任务时，任务从提交到被执行，会按什么顺序依次经历哪些环节","请按「核心线程 → 队列 → 非核心线程 → 拒绝策略」这条主线说明每个环节的触发条件。"]', '["线程池 · 核心工作流程"]', '核心线程→队列→非核心→拒绝的推进顺序', '中档', '原理追问', 13, NULL, 1793608967463),
	(139, 2, 4, 14, 10, '《阿里巴巴 Java 开发手册》强制要求线程池不允许用 Executors 创建，而要手动 new ThreadPoolExecutor。请说明这条规约背后的原因，并解释它与七大参数中的哪几个参数直接相关。

具体请回答：
① 为什么用 Executors 快捷方法创建线程池会有 OOM 风险？
② 手写 ThreadPoolExecutor 能带来什么好处？', '**根因是 Executors 的默认配置里藏了「无界」。** ① **FixedThreadPool / SingleThreadExecutor** 用**无界 LinkedBlockingQueue**，任务堆积导致 OOM；**CachedThreadPool** 的 **maximumPoolSize = Integer.MAX_VALUE**（配 SynchronousQueue），线程数可无限创建导致 OOM。直接相关的参数就是 **workQueue** 与 **maximumPoolSize**。② 手写 new ThreadPoolExecutor 可以**给队列设容量上限**避免堆积、**指定线程名前缀**方便排查、**按业务量级设置核心/最大线程数**、**显式指定拒绝策略**，让资源占用可控、可预期。', '["Executors 创建线程池的 OOM 风险（无界队列、无界线程数）","手写 ThreadPoolExecutor 显式指定有界队列与线程数"]', '["为什么用 Executors 快捷方法创建线程池会有 OOM 风险？","手写 ThreadPoolExecutor 能带来什么好处？"]', '["四种内置线程池 · 为什么不推荐直接用 Executors 创建"]', '阿里手册为何要求手写 ThreadPoolExecutor', '中档', '原理追问', 13, NULL, 1793608987144),
	(140, 2, 4, 14, 5, '线程池的任务队列按容量特性分哪几类？请分别说出每类的代表队列、容量特点，以及它对线程池行为（何时创建新线程、任务能否被拒绝）有什么影响。', '三类：①**无界队列**，代表 LinkedBlockingQueue（容量近似无限）：任务只排队，线程数最多到核心线程数，**最大线程数不生效**，任务堆积易 OOM；②**有界队列**，代表 ArrayBlockingQueue（需指定容量）：队列满才创建新线程到最大线程数，之后触发拒绝，行为可控；③**同步移交队列**，代表 SynchronousQueue（不存储）：直接把任务移交给线程，无空闲线程就创建新线程（到 max）。', '["线程池任务队列分类（无界队列/有界队列/同步移交队列）","队列容量对线程池扩容与拒绝行为的影响"]', '["线程池的任务队列按容量特性分哪几类","请分别说出每类的代表队列、容量特点，以及它对线程池行为（何时创建新线程、任务能否被拒绝）有什么影响。"]', '["线程池参数 · workQueue"]', '任务队列分哪几类、各有何特点', '基础', '概念辨析', 9, NULL, 1793609000712),
	(141, 2, 4, 15, 5, '阿里《Java开发手册》明确禁止用 Executors 创建线程池。这条具体禁止什么？要求开发者怎么做？', '**禁止用 Executors 提供的快捷工厂创建线程池**，要求开发者**手动 new ThreadPoolExecutor 显式指定各项参数**。原因是这些工厂的默认配置都不可控：newFixedThreadPool、newSingleThreadExecutor 用无界 LinkedBlockingQueue，任务无限堆积；newCachedThreadPool 用 SynchronousQueue 但最大线程数为 Integer.MAX_VALUE，可无限建线程；newScheduledThreadPool 的队列同样无界。最终都可能导致**内存耗尽 OOM**，所以必须自定义核心线程数、最大线程数、有界队列和拒绝策略。', '["Executors 创建线程池的风险（无界队列/无线程上限）","阿里规约要求显式 ThreadPoolExecutor 构造"]', '["阿里《Java开发手册》明确禁止用 Executors 创建线程池。这条具体禁止什么","要求开发者怎么做"]', '["自定义线程池 · 为什么不用 Executors"]', '阿里规约这条具体禁止什么、要求怎么做', '基础', '概念辨析', 8, NULL, 1793610468183),
	(142, 2, 4, 15, 6, '线程池常见阻塞队列有有界队列（如 ArrayBlockingQueue）、无界队列（如 LinkedBlockingQueue）、同步移交队列（如 SynchronousQueue）三类。请说明：① 三类队列各自适合什么业务场景？② 为什么会这么选？', '① **有界队列（ArrayBlockingQueue）**：适合大多数业务——容量可控，积压有限，队列满会触发拒绝策略，能尽早反压和限流。② **无界队列（LinkedBlockingQueue）**：适合低并发、任务量可控的批处理或工具类——宁可排队也不丢任务，但失去流量控制，堆积可能 OOM。③ **同步移交（SynchronousQueue）**：不存储任务、直接移交给空闲线程，适合任务少、执行快、要求低延迟的场景；前提是总有空闲线程接，否则会扩容到最大线程数或触发拒绝。', '["有界/无界/同步移交队列的适用场景","队列类型对线程数与内存的影响"]', '["三类队列各自适合什么业务场景？","为什么会这么选？"]', '["线程池队列类型 · 三种典型选择"]', '有界、无界、同步移交三种队列怎么选怎么用', '基础', '概念辨析', 8, NULL, 1793610468187),
	(143, 2, 4, 15, 7, '自定义 ThreadFactory（线程工厂）相比默认工厂，在线上排查与线程治理上能带来哪些好处？', '好处主要有两点：① **排查可观测**——给线程统一命名（如 order-export-pool-1），在 jstack、日志、监控里能立刻定位线程属于哪个业务线程池，而不是默认 pool-1-thread-1 这种无法溯源的名字；② **线程治理**——在工厂里统一设定线程属性（守护线程、优先级、线程组），并统一挂 **UncaughtExceptionHandler**，让任务未捕获异常能被记录而不是静默丢失，方便追责与修复。', '["自定义 ThreadFactory 的作用（命名/守护/统一属性）"]', '["自定义 ThreadFactory（线程工厂）相比默认工厂，在线上排查与线程治理上能带来哪些好处？"]', '["自定义线程池 · 自定义线程工厂与命名规范"]', '自定义ThreadFactory能带来哪些排查与治理上的好处', '基础', '概念辨析', 7, NULL, 1793610468191),
	(144, 2, 4, 15, 8, '线程池四种内置拒绝策略（AbortPolicy、CallerRunsPolicy、DiscardPolicy、DiscardOldestPolicy）在队列满且线程达上限时，各自如何处置被拒任务？请分别说明处置方式与典型适用场景。', '触发条件是**队列满且线程数达 maximumPoolSize**。① **AbortPolicy**：抛出 RejectedExecutionException，任务不执行，是**默认策略**，适合必须感知过载、走降级/告警的场景。② **CallerRunsPolicy**：让**提交任务的线程自己执行**，不丢任务且天然反压（提交端被拖慢），适合不可丢弃、允许积压的业务。③ **DiscardPolicy**：静默丢弃当前任务，适合允许丢失的日志/监控类。④ **DiscardOldestPolicy**：丢弃队列中最老任务后**重新提交当前任务**，适合只关心最新数据、允许淘汰旧任务的场景（如行情、状态刷新）。', '["四种内置拒绝策略的处置方式","拒绝策略的适用场景取舍"]', '["线程池四种内置拒绝策略（AbortPolicy、CallerRunsPolicy、DiscardPolicy、DiscardOldestPolicy）在队列满且线程达上限时，各自如何处置被拒任务","请分别说明处置方式与典型适用场景。"]', '["拒绝策略 · 四种内置策略"]', '四种内置拒绝策略各自怎么处置被拒任务', '中档', '原理追问', 11, NULL, 1793610468194),
	(145, 2, 4, 15, 1, '新接手一个项目，发现里面用 Executors.newFixedThreadPool / newCachedThreadPool 创建线程池。你要向同事说明：为什么必须改成手动 new ThreadPoolExecutor？请说清这两种内置工厂各自的队列/线程上限设计带来的风险。', '**这两种工厂的风险都来自默认参数不可控**。FixedThreadPool 用 LinkedBlockingQueue、容量 Integer.MAX_VALUE，任务只能无限入队堆积，最终 OOM；CachedThreadPool 最大线程数是 Integer.MAX_VALUE，高峰期无限建线程，线程栈内存耗尽同样 OOM。所以要**手动 new ThreadPoolExecutor**，显式设定核心线程数、最大线程数、有界队列长度和拒绝策略，并自定义线程名，既控住资源上限，又便于线上排查。', '["Executors 工厂方法的隐患","无界队列与无界线程的风险"]', '["新接手一个项目，发现里面用 Executors.newFixedThreadPool / newCachedThreadPool 创建线程池。你要向同事说明：为什么必须改成手动 new ThreadPoolExecutor","请说清这两种内置工厂各自的队列/线程上限设计带来的风险。"]', '["自定义线程池 · 为什么要自定义"]', '新接手项目用Executors创建，怎么向同事说明必须改造', '基础', '概念辨析', 8, NULL, 1793610476631),
	(146, 2, 4, 15, 2, '面试官让你把线程池七大参数逐个说出含义与作用。请依次列出这七个参数的名称、含义，以及它主要影响线程池的什么行为。', '**七大参数**：① **corePoolSize** 核心线程数，决定常驻线程规模；② **maximumPoolSize** 最大线程数，决定线程数上限；③ **keepAliveTime** 非核心线程空闲存活时间，控制线程回收；④ **TimeUnit** 该时间的单位；⑤ **workQueue** 工作队列，决定任务积压方式与是否触发扩容/拒绝；⑥ **threadFactory** 线程工厂，决定线程如何创建、命名与属性；⑦ **RejectedExecutionHandler** 拒绝策略，决定队列满且线程达上限时被拒任务如何处置。', '["线程池七大参数","各参数对线程池行为的影响"]', '["面试官让你把线程池七大参数逐个说出含义与作用。请依次列出这七个参数的名称、含义，以及它主要影响线程池的什么行为。"]', '["线程池七大参数 · 逐个含义"]', '面试要求七个参数逐个说出含义与作用', '基础', '概念辨析', 8, NULL, 1793610476638),
	(147, 2, 4, 15, 3, '一个新的订单导出接口，预估峰值 QPS 约 100，单个任务平均耗时 200ms，允许少量积压但不能丢任务。请说明：这个场景下你**必须显式固定取值**的是哪几个线程池参数？每个参数为什么在这个场景下要定死、不能用默认值？', '**必须显式定死四个参数**。① **corePoolSize**：按 QPS 100 × 200ms 得稳态并发约 20，取这个量级，保证常态不排队；② **maximumPoolSize**：在核心线程数之上留突发缓冲并封顶，限制线程总数、防止线程无限创建；③ **workQueue**：取有界队列，容量按「允许积压量」定，避免无界堆积；④ **RejectedExecutionHandler**：因为不能丢任务，选 CallerRunsPolicy 或自定义策略（落库后重试）。keepAliveTime、TimeUnit、threadFactory 可用合理默认，但 threadFactory 建议自定义命名。', '["线程池参数的业务取值","有界队列与拒绝策略选型"]', '["一个新的订单导出接口，预估峰值 QPS 约 100，单个任务平均耗时 200ms，允许少量积压但不能丢任务。请说明：这个场景下你**必须显式固定取值**的是哪几个线程池参数","每个参数为什么在这个场景下要定死、不能用默认值"]', '["自定义线程池 · 参数怎么定"]', '给一个新接口场景，说明要配哪几个参数定值', '基础', '概念辨析', 8, NULL, 1793610476642),
	(148, 2, 4, 15, 4, '简答：线程池的 corePoolSize 和 maximumPoolSize 含义分别是什么？日常业务里这两个值的配置通常有什么差异，为什么？', '**corePoolSize 是核心（常驻）线程数**，即使空闲也默认保留；**maximumPoolSize 是线程数上限**，超过核心线程的部分空闲一段时间后会被回收。日常配置上 **maximumPoolSize 大于 corePoolSize**，通常只大一截做兜底：因为线程池先用核心线程接任务，满了才入队，**队列满才扩到最大线程数**，所以超出核心的线程只是应对突发，不作为常态容量，避免瞬时流量撑爆 CPU 与内存。', '["corePoolSize 与 maximumPoolSize 的区别","线程池参数日常配置取值"]', '["简答：线程池的 corePoolSize 和 maximumPoolSize 含义分别是什么","日常业务里这两个值的配置通常有什么差异，为什么"]', '["线程池参数 · corePoolSize 与 maximumPoolSize"]', '两个参数含义与日常配置差异简答', '基础', '概念辨析', 8, NULL, 1793610476645),
	(149, 2, 4, 15, 9, '团队里有人在业务代码中直接 new Thread() 起任务，高峰期系统变慢。请说明：直接 new Thread 有哪些问题？线程池又是靠什么机制解决这些问题的？', '**直接 new Thread 的问题**：①每个任务新建线程，创建/销毁开销大，高峰期吞吐下降；②线程数没有上限，突发流量下线程暴涨，上下文切换频繁、内存与 CPU 被耗尽；③分散在业务代码里，无法统一监控、调优和兜底。**线程池靠两层机制解决**：一是 **Worker 线程复用**，线程执行完任务继续取下一个任务，省去反复创建销毁；二是**用核心/最大线程数加工作队列控制并发数量与积压上限**，起到削峰作用，并统一提供监控、参数调优与拒绝策略，让资源可控。', '["线程池线程复用机制","阻塞队列缓冲与线程数控制"]', '["团队里有人在业务代码中直接 new Thread() 起任务，高峰期系统变慢。请说明：直接 new Thread 有哪些问题","线程池又是靠什么机制解决这些问题的"]', '["线程池 · 为什么要用"]', '直接new Thread有什么问题，线程池解决什么', '中档', '原理追问', 11, NULL, 1793610485651),
	(150, 2, 4, 15, 10, '某电商订单系统在双 11 下单高峰期间，核心下单接口 P99 延迟明显上升，监控显示线程池活跃线程数长期打满、任务队列积压数千个，部分下单请求被拒绝后直接返回系统繁忙，用户投诉下单失败。

线程池采用的是固定大小 200 个线程、队列容量 1000 的配置，拒绝时使用默认策略直接抛异常给上游。业务方希望在尽量不丢关键下单任务的前提下，评估并调整队列选型与拒绝处置方式。

请回答：
① 高峰期任务被拒绝时，四种内置拒绝策略各自的行为是什么？它们分别适合什么场景？当前配置用的默认策略在这个下单场景下有什么问题？（8 分）
② 任务队列的选型（如有界队列 vs 无界队列、队列容量大小）对线程池行为和系统稳定性有什么影响？针对下单高峰这种突发流量，你会如何选择队列与核心/最大线程数的搭配？为什么？（8 分）
③ 如果既要避免关键下单任务被直接丢弃或抛异常，又不能让线程池无限堆积拖垮系统，请给出一个可落地的处置方案（包括拒绝策略的自定义思路与配套动作），并说明其中的取舍。（7 分）', '① **AbortPolicy** 抛 RejectedExecutionException、任务不执行，适合可感知失败、能降级补偿的场景，是默认策略；**CallerRunsPolicy** 由提交线程执行，天然反压限流，适合不可丢任务、能接受提交方变慢；**DiscardPolicy** 静默丢弃新任务；**DiscardOldestPolicy** 丢队列最老任务再提交，适合只关心最新任务。当前用默认策略，高峰时关键下单直接抛异常失败，与「尽量不丢关键任务」冲突。② **无界队列**无限堆积导致内存 OOM、P99 飙升，且永不触发拒绝策略；**有界队列**控内存、能触发拒绝，队列越小越早扩到最大线程数。突发流量下：**核心线程按常态流量设、队列取中小容量、最大线程数设弹性上限**，让队列满后先扩线程再拒绝，兼顾延迟与系统保护。③ 自定义 **RejectedExecutionHandler**：拒绝时把订单**落库或投 MQ 兜底**，异步补录重试（需幂等+状态校验）；配套**入口限流降级、队列水位与拒绝数告警、必要时扩容**。取舍：不丢任务要付持久化延迟与存储成本，限流牺牲部分非核心体验换核心链路稳定。', '["线程池四种内置拒绝策略及其适用场景","任务队列选型（有界/无界、容量）对线程池的影响","自定义拒绝策略与降级补偿方案"]', '["高峰期任务被拒绝时，四种内置拒绝策略各自的行为是什么？它们分别适合什么场景？当前配置用的默认策略在这个下单场景下有什么问题？（8 分）","任务队列的选型（如有界队列 vs 无界队列、队列容量大小）对线程池行为和系统稳定性有什么影响？针对下单高峰这种突发流量，你会如何选择队列与核心/最大线程数的搭配？为什么？（8 分）","如果既要避免关键下单任务被直接丢弃或抛异常，又不能让线程池无限堆积拖垮系统，请给出一个可落地的处置方案（包括拒绝策略的自定义思路与配套动作），并说明其中的取舍。（7 分）"]', '["线程池参数 · workQueue","线程池参数 · handler","拒绝策略 · AbortPolicy"]', '电商下单高峰场景中队列选型与被拒任务处置的联动取舍', '大题', '场景应用', 23, NULL, 1793610563548),
	(151, 2, 4, 5, 3, '创建线程池时的 threadFactory 参数是干什么的？它在实际项目里主要起什么作用？', '**threadFactory 是生产线程池中线程的工厂**，默认用 Executors.defaultThreadFactory()，自定义后可控制每条线程的创建方式。项目里**最核心的作用是给线程统一起名**（如 order-pool-1），这样线程 dump、日志、监控里一眼看出线程属于哪个业务线程池，出问题能快速定位。此外还能设置**守护线程、优先级、线程分组、UncaughtExceptionHandler**（线程内未捕获异常统一记录告警）。常见写法是自己实现接口或用 ThreadFactoryBuilder，在 newThread 里设置名称后返回。', '["ThreadFactory 线程工厂的作用","自定义线程名便于排障"]', '["创建线程池时的 threadFactory 参数是干什么的","它在实际项目里主要起什么作用"]', '["线程池参数 · threadFactory"]', 'threadFactory 参数是干嘛的、起什么作用', '基础', '概念辨析', 8, NULL, 1793689274413),
	(152, 2, 4, 5, 9, '很多团队图省事，用 Executors.newFixedThreadPool 或 newCachedThreadPool 直接创建线程池。请说明：① 这两种线程池分别用的是什么队列或线程数上限，会带来什么风险？② 为什么说它们不适合直接用于生产环境？请分别说明原因。', '**FixedThreadPool 用 LinkedBlockingQueue 无界队列**（容量 Integer.MAX_VALUE），最大线程数等于核心线程数，任务来多少排多少，**永不触发拒绝策略**，堆积导致 OOM；**CachedThreadPool 用 SynchronousQueue、maxPoolSize=Integer.MAX_VALUE**，没有空闲线程就新建线程，突发流量下线程数暴涨导致 OOM。二者都不适合生产，本质是**队列容量与线程数上限不可控**，无法按业务量级设边界、无法配合拒绝策略做限流兜底，流量一冲直接打爆内存，所以要手写 ThreadPoolExecutor 显式设参。', '["无界队列风险","线程数上限风险"]', '["这两种线程池分别用的是什么队列或线程数上限，会带来什么风险？","为什么说它们不适合直接用于生产环境？请分别说明原因。"]', '["内置线程池的风险 · 无界队列与MAX_VALUE"]', '无界队列和 MAX_VALUE 线程上限会带来什么问题', '中档', '原理追问', 11, NULL, 1793689256355),
	(153, 2, 4, 5, 5, 'CPU 密集型任务和 IO 密集型任务，线程池的线程数分别应该怎么设置？两者设置思路的差异是由什么造成的？', '**CPU 密集型取 CPU 核心数 + 1**，**IO 密集型取核心数的 2 倍起（2~n 倍）**，最终靠压测确定。原因是：CPU 密集型任务线程几乎不阻塞，线程数超过核心数只增加**上下文切换**开销，+1 是为防止某条线程短暂无法运行（缺页、GC 等）时 CPU 空转；IO 密集型任务线程**大部分时间阻塞在等待 IO**、CPU 空闲，需要更多线程把 CPU 喂满。核心原则：**线程数围绕 CPU 利用率与切换开销做平衡**。', '["CPU 密集型与 IO 密集型任务的线程数设置","线程数设置差异的原因"]', '["CPU 密集型任务和 IO 密集型任务，线程池的线程数分别应该怎么设置","两者设置思路的差异是由什么造成的"]', '["线程池参数调优 · CPU/IO密集型线程数设置"]', 'CPU/IO 密集型任务线程数怎么设置', '基础', '概念辨析', 8, NULL, 1793689270577),
	(154, 2, 4, 5, 6, '什么是线程池的「同步移交队列」（SynchronousQueue）？它在什么场景下使用？', '**SynchronousQueue 是不存储任务的交接队列**：提交任务时必须有线程来接手，否则就交给它——**有空闲线程就直接移交**，没有且未达 maxPoolSize 才新建线程，达上限就走拒绝策略；它本身不缓存任何任务。典型场景是**任务来得急、执行时间短、量不可预期**，希望任务立刻被执行、线程被快速复用而不堆积排队，如 **CachedThreadPool** 就默认使用它。', '["SynchronousQueue 同步移交队列","SynchronousQueue 的适用场景"]', '["什么是线程池的「同步移交队列」（SynchronousQueue）","它在什么场景下使用"]', '["线程池 · 同步移交队列适用场景"]', '同步移交队列是什么、什么场景用', '基础', '概念辨析', 8, NULL, 1793689270585),
	(155, 2, 4, 5, 7, '面试官追问：既然已经有 Executors 提供的四种内置线程池，为什么阿里 Java 开发手册还强制要求手写 new ThreadPoolExecutor 来创建线程池？手写方式相比 Executors 多解决了什么问题？', 'Executors 的便捷方法把关键容量参数写死：**FixedThreadPool / SingleThreadExecutor 用 LinkedBlockingQueue 无界队列**（容量 Integer.MAX_VALUE），任务堆积导致 **OOM** 且永不触发拒绝策略；**CachedThreadPool 用 SynchronousQueue、maxPoolSize=Integer.MAX_VALUE**，突发流量下线程数暴涨导致 OOM。手写 new ThreadPoolExecutor 能**显式设定核心数、最大线程数、队列容量与拒绝策略**，让线程池边界可控、可限流、可兜底并便于监控，所以阿里手册强制手写。', '["Executors 内置线程池的隐患（无界队列/无限线程）","手动创建 ThreadPoolExecutor 显式指定参数"]', '["面试官追问：既然已经有 Executors 提供的四种内置线程池，为什么阿里 Java 开发手册还强制要求手写 new ThreadPoolExecutor 来创建线程池","手写方式相比 Executors 多解决了什么问题"]', '["四种内置线程池 · 为什么不推荐直接用 Executors 创建"]', '换角度：面试官追问手写 ThreadPoolExecutor 比 Executors 多解决了什么', '基础', '概念辨析', 7, NULL, 1793689270593),
	(156, 2, 4, 5, 1, '线程池的任务都执行完了，这个线程池还要不要关闭？用什么方法关闭？shutdown() 和 shutdownNow() 有什么区别？', '**要关**，尤其用了 `Executors` 创建的池子或自建的**核心线程数固定的池**，否则线程不退出、可能造成线程泄漏。关闭用 **`shutdown()`** 或 **`shutdownNow()`**。

**`shutdown()`**：**温和关闭**，不再接收新任务，但会**把队列里已提交的任务执行完**才结束，返回一个 `List<Runnable>`（这里是空的）。

**`shutdownNow()`**：**立即关闭**，不再接收新任务，**尝试中断正在执行的线程**并**返回队列里还没执行的任务**，这些任务不会再被处理。

区别核心：**`shutdown()` 等待存量任务跑完，`shutdownNow()` 打断执行、丢弃队列**。一般业务用 `shutdown()`，需要紧急止损时才用 `shutdownNow()`。', '["线程池的关闭 shutdown 与 shutdownNow","线程泄漏与核心线程回收"]', '["线程池的任务都执行完了，这个线程池还要不要关闭","用什么方法关闭","shutdown() 和 shutdownNow() 有什么区别"]', '["自定义线程池 · 优雅关闭"]', '任务跑完后线程池要不要关、怎么关', '基础', '概念辨析', 8, NULL, 1793689274413),
	(157, 2, 4, 5, 2, '线程池内置的四种拒绝策略里，有两种是"直接把任务丢掉"的：AbortPolicy 和 DiscardPolicy。它们分别做什么？行为上有什么差异？', '**AbortPolicy 是默认策略**：队列满且线程数达上限时抛出 **RejectedExecutionException**，任务不入队也不执行，异常抛回提交方，调用方能捕获后做日志、告警或落库补偿。**DiscardPolicy 则静默丢弃**，**不抛任何异常**，调用方完全无感知。差异本质是**失败是否对调用方可见**：Abort 把失败暴露出来便于兜底，Discard 把失败吞掉、任务丢失无痕迹，生产中除非明确允许丢任务，否则不用 Discard。', '["AbortPolicy 默认拒绝策略","DiscardPolicy 静默丢弃策略"]', '["线程池内置的四种拒绝策略里，有两种是\"直接把任务丢掉\"的：AbortPolicy 和 DiscardPolicy。它们分别做什么","行为上有什么差异"]', '["拒绝策略 · DiscardPolicy 与 DiscardOldestPoli"]', '两种丢弃策略分别做什么、有何差异', '基础', '概念辨析', 8, NULL, 1793689274413),
	(158, 2, 4, 5, 4, '如果内置的四种拒绝策略都不满足需求，怎么自定义拒绝行为？说说实现思路和典型用法。', '**自定义拒绝策略就是实现 RejectedExecutionHandler 接口**，重写 **rejectedExecution(Runnable r, ThreadPoolExecutor e)** 方法，在里面写兜底逻辑：记日志并告警、把任务落库或发 MQ 等待补偿重试、降级走备用线程池。然后把它作为 **ThreadPoolExecutor 的构造参数**传入，可封装成静态类或工厂方法（如 MyRejectedPolicy）。典型用法：支付任务不能丢就落库补偿，日志上报允许丢就计数后丢弃。注意兜底里别再往同一线程池提交任务。', '["RejectedExecutionHandler 接口自定义拒绝策略","rejectedExecution 方法与典型兜底做法"]', '["如果内置的四种拒绝策略都不满足需求，怎么自定义拒绝行为","说说实现思路和典型用法。"]', '["拒绝策略 · 自定义拒绝策略"]', '如何实现 RejectedExecutionHandler 自定义拒绝行为', '基础', '概念辨析', 8, NULL, 1793689274430),
	(159, 2, 4, 5, 8, '线程池中 keepAliveTime 和 unit 两个参数分别管什么？在 corePoolSize 之外多创建的线程空闲多久会被回收？如果想让核心线程空闲时也能被回收，应该怎么设置？', '**keepAliveTime 是空闲时长的数值，unit 是它的时间单位**，二者共同决定线程空闲多久被回收。默认**只有 corePoolSize 之外多创建的线程**，空闲超过 keepAliveTime（按 unit 计）才会被回收终止；核心线程一旦创建就常驻。若想让核心线程也在空闲时回收，调用 **allowCoreThreadTimeOut(true)**，此时所有线程都遵守同一空闲超时规则（注意 keepAliveTime 要大于 0）。', '["keepAliveTime 与 unit 参数的作用","allowCoreThreadTimeOut 让核心线程可被回收"]', '["线程池中 keepAliveTime 和 unit 两个参数分别管什么","在 corePoolSize 之外多创建的线程空闲多久会被回收","如果想让核心线程空闲时也能被回收，应该怎么设置"]', '["线程池参数 · keepAliveTime 与 unit"]', 'keepAliveTime 和 unit 管什么、默认值多少', '中档', '原理追问', 11, NULL, 1793689286158),
	(160, 2, 4, 5, 10, '某电商订单系统用线程池异步推送订单状态，线上出现大量任务被拒、部分线程池 CPU 打满。运维发现有同学把核心线程数设为 50、最大线程数也设为 50，队列用的是无界 LinkedBlockingQueue。请回答：
① 在这种参数下，任务提交后线程池的推进流程是怎样的？为什么最大线程数 50 实际上永远不会被用到？
② corePoolSize、maximumPoolSize、workQueue 三者应该如何配合，才能让线程数在压力上来时真正扩到最大值？请给出配合原则。
③ 如果业务要求高峰期不能丢任务，同时线程数不能无限增长，请给出你会如何调整这组参数（说明思路即可，不用写代码）。', '①线程数<**corePoolSize** 就建核心线程；达到 50 后新任务入队；**LinkedBlockingQueue 无界永不满**，永远走不到"队列满才建非核心线程"，故 **maximumPoolSize 永远用不到**。②配合原则：**core < max**，且**队列必须有界、容量要小**，靠队列被塞满触发扩容到 max；队列过大就退化成①。③**有界队列+合理容量**，max 按压测定为有限值（CPU 密集看核数、IO 密集可加大），拒绝策略选 **CallerRunsPolicy**（或提交方阻塞/落库重试），既不丢任务又限制线程规模。', '["线程池任务提交与推进流程（core→queue→max→拒绝）","无界队列导致 maximumPoolSize 失效","corePoolSize/maximumPoolSize/workQueue 参数配合"]', '["在这种参数下，任务提交后线程池的推进流程是怎样的？为什么最大线程数 50 实际上永远不会被用到？","corePoolSize、maximumPoolSize、workQueue 三者应该如何配合，才能让线程数在压力上来时真正扩到最大值？请给出配合原则。","如果业务要求高峰期不能丢任务，同时线程数不能无限增长，请给出你会如何调整这组参数（说明思路即可，不用写代码）。"]', '["线程池 · 为什么要用","线程池 · 核心工作流程","线程池参数 · corePoolSize 与 maximumPoolSize"]', '同一场景串联：引入线程池解决什么、任务推进流程、core/max 如何配合', '大题', '场景应用', 23, NULL, 1793689313067),
	(161, 2, 4, 16, 5, 'submit()、execute()、invokeAll() 三种提交方式，在返回值与异常处理上有什么差异？实际业务中应该怎么选？', '**execute**：无返回值，异常直接抛给**执行线程**，业务拿不到，必须在任务内部 try-catch。**submit**：返回 **Future**，异常被封装进去，**get() 时才抛 ExecutionException**（取消则 CancellationException）。**invokeAll**：批量提交，**阻塞到全部完成**，返回 **List<Future>**，异常同样在各自 get() 时抛出。选型：只要结果或要异常 → submit；只管执行不关心结果且自己兜异常 → execute；一批任务要等全部结果 → invokeAll。', '["execute/submit/invokeAll 的返回值差异","任务异常的传播与捕获方式"]', '["submit()、execute()、invokeAll() 三种提交方式，在返回值与异常处理上有什么差异","实际业务中应该怎么选"]', '["线程池 · submit 与 execute 区别"]', '返回值与异常处理差异，怎么选', '基础', '概念辨析', 8, NULL, 1793691192184),
	(162, 2, 4, 16, 6, '线程池中，任务是不是先交给非核心线程执行？队列容量大小应该怎么权衡？', '**不是**。任务流转顺序是：先给**核心线程**，核心满了进**阻塞队列**，队列满了才创建**非核心线程**，都满了走**拒绝策略**。队列容量的权衡：**太小**（含 SynchronousQueue 的 0）→ 队列易满，频繁创建线程甚至触发拒绝；**太大或无界**→ 任务长期排队、响应延迟不可控，堆积过多还可能 OOM。所以按**可容忍排队时长 × 吞吐量**估一个明确上界，宁可容量偏小配好拒绝策略，也不用无界队列。', '["线程池任务提交的处理顺序（核心线程→队列→非核心线程→拒绝）","队列容量大小的权衡"]', '["线程池中，任务是不是先交给非核心线程执行","队列容量大小应该怎么权衡"]', '["自定义线程池 · 队列容量与非核心线程创建的平衡"]', '队列满才建非核心线程，容量怎么权衡', '基础', '概念辨析', 8, NULL, 1793691192184),
	(163, 2, 4, 16, 7, '自定义 RejectedExecutionHandler 时，reject() 方法里应该做哪些事？怎样做到兜底不丢任务？', 'reject() 里应做：**快速记日志**（带任务标识与拒绝原因）、把**任务持久化**（DB/磁盘/MQ）、必要时**通知告警或触发降级**。兜底不丢任务的关键是：**先落库，再由定时任务/补偿机制异步重新执行**。注意两点取舍：①reject() **运行在提交任务的调用线程**上，不能在里面阻塞等待或做重活；②直接抛异常等于任务丢了，必须由调用方捕获后转为降级或落库处理。', '["自定义拒绝处理器的职责","拒绝后的兜底策略（调用者运行/落盘/降级）"]', '["自定义 RejectedExecutionHandler 时，reject() 方法里应该做哪些事","怎样做到兜底不丢任务"]', '["拒绝策略 · 自定义拒绝策略"]', '自定义拒绝类里该做什么、怎么兜底', '基础', '概念辨析', 7, NULL, 1793691192184),
	(164, 2, 4, 16, 8, '线程池使用无界队列（如不设容量的 LinkedBlockingQueue）在什么场景下合适？这样用的代价是什么？', '**合适场景**：任务总量**有限且可预估**、允许排队等待的场景，如一次性的批处理、数据迁移、脚本类任务。**代价**：①任务只进不出地堆积，**占堆内存，极端时 OOM**；②排队时间**不可控**，任务可能等到超时也没执行；③队列永远不满，**maximumPoolSize 形同虚设**，只有核心线程在干活；④没有背压，流量突增时直接失控。所以在线服务不建议用无界队列，宁可用有界队列加拒绝策略。', '["无界队列的适用场景","无界队列的风险（内存堆积、最大线程数与拒绝策略失效）"]', '["线程池使用无界队列（如不设容量的 LinkedBlockingQueue）在什么场景下合适","这样用的代价是什么"]', '["线程池 · 无界队列适用场景"]', '无界队列何时用、代价是什么', '中档', '原理追问', 11, NULL, 1793691192184),
	(165, 2, 4, 16, 1, '线程池配置为 corePoolSize 个核心线程 + SynchronousQueue 阻塞队列 + maximumPoolSize 个最大线程，任务来时不排队直接交给线程处理。这种"不排队直接给线程"的配置适合什么特点的任务？请说明适用场景，并指出这种配置在什么情况下容易把线程数顶满甚至触发拒绝策略。', '**不排队直接交给线程**，适合**执行时间短、要求低延迟、并发量不可预估**的任务，比如突发的即时请求处理——宁可临时开线程，也不让任务在队列里等。典型场景：短平快的即时计算、突发流量的事件处理。它的风险在于：一旦**提交速率持续超过处理速率**（任务变慢或并发骤增），SynchronousQueue 没有缓冲，只能不断新建线程，线程数很快顶到 maximumPoolSize，再来的任务就直接**触发拒绝策略**。', '["SynchronousQueue 不缓存任务、直接交接的特性","任务快速提交场景下的线程扩容与拒绝策略触发条件"]', '["线程池配置为 corePoolSize 个核心线程 + SynchronousQueue 阻塞队列 + maximumPoolSize 个最大线程，任务来时不排队直接交给线程处理。这种\"不排队直接给线程\"的配置适合什么特点的任务","请说明适用场景，并指出这种配置在什么情况下容易把线程数顶满甚至触发拒绝策略。"]', '["同步移交队列SynchronousQueue · 特性与适用场景"]', '任务不排队直接给线程，何时用', '基础', '概念辨析', 8, NULL, 1793691200803),
	(166, 2, 4, 16, 2, '针对并发量可预估、任务执行时间相对稳定的业务（例如订单导出、报表生成），常采用"固定线程数 + 无界队列"的线程池配置。请回答：①这种配置对应 JDK 内置的哪一种线程池？②它的线程数是如何确定的，为什么能匹配"并发量已知"的场景？③无界队列带来什么风险？', '①对应 **newFixedThreadPool**。②它的线程数是**构造时显式指定、固定不变**的；并发量可预估时，直接把线程数设成预期并发数即可，线程不随任务波动创建销毁，**稳定可控**，所以匹配「并发量已知」的场景。③代价是**无界队列**：任务提交快于处理时只进不出地堆积，最终**堆内存 OOM**；而且队列永远不满，maximumPoolSize 永远不会生效，排在队列里的任务延迟也不可控。', '["FixedThreadPool 的构造与线程数固定特性","无界队列的任务堆积 OOM 风险"]', '["这种配置对应 JDK 内置的哪一种线程池？","它的线程数是如何确定的，为什么能匹配\"并发量已知\"的场景？","无界队列带来什么风险？"]', '["四种内置线程池 · newFixedThreadPool 的队列陷阱"]', '固定线程数+无界队列，已知并发量场景', '基础', '概念辨析', 8, NULL, 1793691200803),
	(167, 2, 4, 16, 3, '线上服务某天频繁出现 OOM（OutOfMemoryError），排查发现线程池使用了默认的 newCachedThreadPool 或 newFixedThreadPool + 无界队列，任务大量堆积在队列里没被处理。请回答：①这种 OOM 现象的直接原因是什么？②为什么这两种内置线程池会埋下这个隐患？③请给出重建为"有界线程池"的关键配置要点。', '①直接原因是**任务在内存里无界堆积**：FixedThreadPool 的无界队列把任务越堆越多，堆内存耗尽 OOM；CachedThreadPool 则是 max=Integer.MAX_VALUE，突发下**线程数暴涨**，线程资源耗尽（也可能 OOM）。②因为它们都**没有边界**：一个队列无界，一个最大线程数无界，都没有背压，流量一冲就失控。③重建要点：**核心线程数按 CPU/IO 密集型设定**、使用**有界队列并显式给容量**、**显式设定 maximumPoolSize**、配好**拒绝策略**（记录/降级/兜底），必要时监控队列水位。', '["无界队列导致任务堆积 OOM","CachedThreadPool 线程数无限扩大的风险","有界线程池的关键参数配置（corePoolSize/maxPoolSize/workQueue/拒绝策略）"]', '["这种 OOM 现象的直接原因是什么？","为什么这两种内置线程池会埋下这个隐患？","请给出重建为\"有界线程池\"的关键配置要点。"]', '["串联 · 一次线程池 OOM 排查到参数重建"]', '现场OOM堆任务：现象→原因→重建有界池', '基础', '概念辨析', 8, NULL, 1793691200820),
	(168, 2, 4, 16, 4, '某业务提交的都是短平快任务（毫秒级完成，如本地缓存查询、简单字符串处理），使用了 newCachedThreadPool。请回答：①为什么短平快任务"适合"用它？②在提交速率很高的情况下，线程数为什么会爆？请讲清背后的机制。', '①短平快任务**耗时极短、希望提交后立刻被执行**，CachedThreadPool 用 **SynchronousQueue 不缓存任务**，来一个任务就交给线程（核心忙就新建线程），任务几乎零等待；且任务短，空闲线程 60 秒即回收，平时不占资源，所以适合。②线程数会爆是因为：SynchronousQueue **没有缓冲**，当**提交速率持续高于执行速率**，没有空闲线程可接时就不断新建线程，而它的 **maximumPoolSize 是 Integer.MAX_VALUE**，线程数没有上限，于是暴涨直至耗尽资源。', '["CachedThreadPool 的线程复用与 60s 回收机制","maximumPoolSize=Integer.MAX_VALUE 导致线程数无限扩张"]', '["为什么短平快任务\"适合\"用它？","在提交速率很高的情况下，线程数为什么会爆？请讲清背后的机制。"]', '["四种内置线程池 · newCachedThreadPool 的线程爆炸"]', '短平快任务适合，线程数为何会爆', '基础', '概念辨析', 8, NULL, 1793691200820),
	(169, 2, 4, 16, 9, '一个电商系统的线程池里，线程名都是默认的 pool-1-thread-N。线上报警 dump 出的线程栈里看到一堆这样的线程在跑，排查很慢。

① 线程名前缀在定位线上问题时具体能帮上什么忙？
② 在自定义线程池时，怎样给线程池里的线程统一加上有业务含义的前缀？', '**线程名前缀是线程的身份标识**：线上 **thread dump / jstack** 时，能一眼看出这个线程属于**哪个业务线程池**、执行的是哪类任务，把线程栈和业务模块对上号，快速定位慢任务、线程泄漏、线程数异常的来源；多个线程池共存时不会全是 pool-1-thread-N 无法区分。**做法是自定义 ThreadFactory**：实现 ThreadFactory 接口，在 newThread 里 **setName("order-async-" + 自增序号)**，或用 Guava 的 **ThreadFactoryBuilder().setNameFormat("order-async-%d").build()**，把它作为 threadFactory 参数传给 ThreadPoolExecutor。注意线程池构造器本身没有设置线程名的参数。', '["线程名前缀在排障中的作用","自定义 ThreadFactory 设置线程名"]', '["线程名前缀在定位线上问题时具体能帮上什么忙？","在自定义线程池时，怎样给线程池里的线程统一加上有业务含义的前缀？"]', '["线程池参数 · threadFactory命名与问题定位"]', '线程名前缀如何帮定位线上问题', '中档', '原理追问', 11, NULL, 1793691201603),
	(170, 2, 4, 16, 10, '某订单系统压测时发现：每次请求都新建 Thread 执行任务，QPS 上来后线程数暴涨、GC 频繁，系统接近瘫痪。运维临时改为复用线程执行，负载随即平稳。请回答：
① 线程池用哪两个核心机制实现线程复用？为什么复用能显著降低系统开销？
② 线程池把「提交任务」到「任务被执行」拆成哪几步流转？请按顺序说明。
③ 如果要把这套复用方案正式落地，你会怎样设置核心线程数与最大线程数？说明你的理由。', '① 两个机制：**Worker 线程复用**——线程执行完任务不销毁，循环从**阻塞队列**取下一个任务继续跑；**阻塞队列**缓冲待执行任务。复用省去每次新建/销毁线程的内存分配与初始化开销、减少上下文切换，线程数可控，内存占用和 **GC 压力**大幅下降。② 流转：提交任务 → 核心线程未满则创建**核心线程**执行 → 核心满则任务入**阻塞队列** → 队列满且线程数<**最大线程数**则创建非核心线程执行 → 达到最大线程数走**拒绝策略**。③ **CPU 密集：核心数=CPU 核数+1**（防止缺页等使 CPU 偶发空闲），最大=核心数×1~2；**IO 密集：核心数=CPU 核数×2** 起步（线程多在等 IO，需更多线程填满 CPU），最大线程数可更大以抗突发流量，最终**以压测结果为准**，并结合队列容量与可接受排队延迟权衡。', '["线程复用与工作线程机制","任务提交主干流程（核心线程→队列→最大线程→拒绝）","核心线程数与最大线程数设置"]', '["线程池用哪两个核心机制实现线程复用？为什么复用能显著降低系统开销？","线程池把「提交任务」到「任务被执行」拆成哪几步流转？请按顺序说明。","如果要把这套复用方案正式落地，你会怎样设置核心线程数与最大线程数？说明你的理由。"]', '["线程池 · 为什么要用","线程池 · 核心工作流程","线程池参数 · workQueue"]', '同一场景：复用→提交推进→队列满后走向', '大题', '场景应用', 23, NULL, 1793691250903),
	(171, 2, 5, 17, 9, '团队里有人坚持用 setter 注入，有人主张全用构造器注入。请说明：① 为什么官方更推荐构造器注入？② 构造器注入在"依赖不可变"和"循环依赖"这两点上分别有什么表现？', '**官方更推荐构造器注入**：依赖通过构造参数显式声明，可配合 final 保证不可变；对象一创建就完整可用，便于单元测试，不需要反射设值。
在**依赖不可变**上，构造器参数可声明 final，注入后不可修改，天然支持不可变对象。
在**循环依赖**上，构造器注入**无法被容器解决**：依赖必须在实例化时就绪，循环会直接在**启动时抛异常**暴露问题，而不是像 setter 注入那样被缓存悄悄化解。', '["构造器注入与 setter 注入对比","构造器注入与循环依赖的关系"]', '["为什么官方更推荐构造器注入？","构造器注入在\"依赖不可变\"和\"循环依赖\"这两点上分别有什么表现？"]', '["IoC/DI · 概念与两种注入方式"]', '为什么推荐构造器注入而不是 setter 注入', '中档', '原理追问', 13, NULL, 1793696236021),
	(172, 2, 5, 17, 1, '按 Spring 创建一个 Bean 的顺序，说清它经历的四大阶段分别是什么？', '**四大阶段依次是：实例化 → 属性赋值（依赖注入）→ 初始化 → 使用（销毁）。**

1. **实例化**：容器通过构造方法（或工厂方法）创建出 Bean 的原始对象，此时属性还是默认值。
2. **属性赋值**：对依赖的属性做注入（setter 或字段注入），完成依赖对象的装配。
3. **初始化**：执行 Aware 回调（如 BeanNameAware）、BeanPostProcessor 的前置处理、@PostConstruct / InitializingBean#afterPropertiesSet、自定义 init-method，再执行 BeanPostProcessor 的后置处理（AOP 代理往往在这里生成）。
4. **使用与销毁**：Bean 就绪供容器使用；容器关闭时执行 @PreDestroy / DisposableBean#destroy / 自定义 destroy-method。

一句话概括：**先 new 出对象，再填依赖，再做初始化增强，最后使用与销毁。**', '["Bean 生命周期四大阶段","实例化与初始化的区别"]', '["按 Spring 创建一个 Bean 的顺序，说清它经历的四大阶段分别是什么？"]', '["Bean生命周期 · 主干流程"]', '按创建一个 Bean 的顺序说清四大阶段', '基础', '概念辨析', 10, NULL, 1793696244687),
	(173, 2, 5, 17, 3, 'A 类用 setter 注入依赖 B，B 类用 setter 注入依赖 A（互相依赖），Spring 容器是如何解决这种循环依赖、让两个 Bean 都能正常创建出来的？', '**Spring 通过三级缓存提前暴露"半成品" Bean 来解决 setter 形式的循环依赖。**

流程：创建 A 时先**实例化** A（此时 A 还未完成属性填充），把 A 的早期引用提前放入缓存；接着给 A 填充属性，发现依赖 B，于是转去创建 B；创建 B 填充属性时依赖 A，此时从缓存拿到 A 的早期引用注入给 B，B 完成创建并被缓存；再回到 A，把 B 注入给 A，A 完成初始化。

因此两个 Bean 都能创建成功。前提是依赖通过**setter / 字段注入**发生在实例化之后；如果是**构造器注入**导致的循环依赖，无法提前暴露引用，Spring 无法解决，会直接抛出循环依赖异常。', '["三级缓存解决循环依赖","构造器注入循环依赖无法解决"]', '["A 类用 setter 注入依赖 B，B 类用 setter 注入依赖 A（互相依赖），Spring 容器是如何解决这种循环依赖、让两个 Bean 都能正常创建出来的？"]', '["循环依赖 · 三级缓存机制"]', 'A setter 依赖 B、B setter 依赖 A，Spring 怎么解决', '基础', '概念辨析', 9, NULL, 1793696244691),
	(174, 2, 5, 17, 4, '同一个类中，方法 A 内部直接调用方法 B（this 调用），而方法 B 上加了事务/切面注解，此时切面为什么不生效？有什么办法让它生效？', '**不生效的原因：Spring AOP 基于代理实现，只有通过代理对象发起的调用才会被拦截。**

内部 this 调用走的是目标对象本身的方法，绕过了代理对象，因此切面逻辑（如事务）不会被织入。

**让它生效的办法：**
1. 把被调用的方法抽到**另一个 Bean** 中，通过注入该 Bean 来调用，调用就经过代理。
2. 通过 **AopContext.currentProxy()** 拿到当前代理对象再调用（需开启 exposeProxy）。
3. 从容器中**获取自身代理 Bean** 再调用。

核心原则：**自调用不走代理，跨 Bean 调用才走代理。**', '["AOP 代理与自调用失效","自调用失效的解决办法"]', '["同一个类中，方法 A 内部直接调用方法 B（this 调用），而方法 B 上加了事务/切面注解，此时切面为什么不生效","有什么办法让它生效"]', '["AOP · 失效场景与原理"]', '内部方法调用自调用时切面为何不生效', '基础', '概念辨析', 9, NULL, 1793696244695),
	(175, 2, 5, 17, 5, '两个 Bean 的构造器互相注入对方，Spring 容器启动时会报错。请说明：① 为什么会启动失败？② 为什么 setter 注入或字段注入的循环依赖通常不会报错？', '**构造器循环依赖会启动失败，因为依赖在实例化阶段就必须就绪**：创建 A 时要调用构造器传入 B，创建 B 又要 A，两者都无法先产出可用实例，形成死结，容器直接抛 BeanCurrentlyInCreationException。
而 **setter/字段注入走的是"先实例化、后填充属性"的两阶段流程**：A 可先用无参构造器创建出**早期引用**并放入缓存，再去创建 B，B 拿到 A 的早期引用完成初始化，最后回填 A 的属性，循环被打破，所以通常不报错。', '["构造器循环依赖无法解决的原因","三级缓存提前暴露与 setter/字段注入的差异"]', '["为什么会启动失败？","为什么 setter 注入或字段注入的循环依赖通常不会报错？"]', '["循环依赖 · 构造器注入为何不行"]', '构造器相互注入为什么会启动报错', '基础', '概念辨析', 9, NULL, 1793696247595),
	(176, 2, 5, 17, 6, '希望一个单例 Bean 在初始化完成后执行一段逻辑，又在容器关闭时执行清理逻辑。分别有哪些声明方式？各自用哪个回调或注解？', '**初始化完成后**：实现 **InitializingBean** 接口的 **afterPropertiesSet()**，或用 **@PostConstruct** 注解，或在 @Bean 里指定 **initMethod**。

**容器关闭时**：实现 **DisposableBean** 接口的 **destroy()**，或用 **@PreDestroy** 注解，或 @Bean 指定 **destroyMethod**。

**执行顺序**：@PostConstruct → afterPropertiesSet → initMethod；关闭时相反。

注意这些回调都是在**单例 Bean 初始化/销毁阶段**触发，prototype Bean 不会回调销毁方法。', '["Bean 初始化回调（@PostConstruct/InitializingBean/initMethod）","Bean 销毁回调（@PreDestroy/DisposableBean/destroyMethod）"]', '["希望一个单例 Bean 在初始化完成后执行一段逻辑，又在容器关闭时执行清理逻辑。分别有哪些声明方式","各自用哪个回调或注解"]', '["初始化与销毁 · 回调方式"]', '如何在 Bean 创建后和容器关闭时执行逻辑', '基础', '概念辨析', 9, NULL, 1793696247601),
	(177, 2, 5, 17, 7, 'Spring 中 @Lazy 可以加在 Bean 声明上，也可以加在注入点（字段/参数）上。请说明：① 加在这两个位置分别起什么作用？② 各举一个典型使用场景。', '**加在 Bean 声明上：整个 Bean 变为懒加载**，容器启动时不创建它，第一次 getBean 或被使用时才实例化。典型场景：启动慢、不常用的重量级 Bean（如报表导出组件）。
**加在注入点上：注入的不是真实 Bean，而是一个代理**，直到首次调用其方法才向容器获取真正实例。典型场景：两个 Bean 存在**循环依赖**时用它延迟解析，或避免某个 Bean 拖慢启动速度。', '["@Lazy 延迟初始化（懒加载）","@Lazy 注入点代理与解循环依赖"]', '["加在这两个位置分别起什么作用？","各举一个典型使用场景。"]', '["Bean延迟加载 · @Lazy"]', '什么场景下给 Bean 或注入点加 @Lazy', '基础', '概念辨析', 9, NULL, 1793696247605),
	(178, 2, 5, 17, 8, '默认情况下 Spring 的 Bean 是单例、容器内共享。如果希望某个 Bean 不被共享、每次获取都是新对象，应该怎么声明？有哪几种写法？', '**结论：把作用域声明为 prototype**。

**写法**：类上加 **@Scope("prototype")** 或 **@Scope(ConfigurableBeanFactory.SCOPE_PROTOTYPE)**；@Bean 方式则写 **@Bean @Scope("prototype")**。

**效果**：容器不缓存该 Bean，每次 getBean/每次注入都创建一个新实例。

**注意**：prototype Bean 的**生命周期由调用方管理**，容器不负责销毁回调；若单例 Bean 依赖 prototype Bean，注入的仍只是**创建时那一个实例**，需要用 lookup 或 ObjectProvider 每次现取。', '["Bean 作用域（scope）","prototype 作用域的声明与特性"]', '["默认情况下 Spring 的 Bean 是单例、容器内共享。如果希望某个 Bean 不被共享、每次获取都是新对象，应该怎么声明","有哪几种写法"]', '["Bean作用域 · singleton与prototype"]', '怎么声明 Bean 不被共享、每次拿到新对象', '基础', '概念辨析', 9, NULL, 1793696247610),
	(179, 2, 5, 17, 10, '在 Spring AOP 中，默认情况下对实现了接口的 Bean 和没有实现接口的 Bean 分别会使用哪种动态代理方式？这两种代理方式在生成方式和调用机制上的核心差异是什么？', '**实现了接口的 Bean 默认用 JDK 动态代理；没实现接口的默认用 CGLIB**。
生成方式上：JDK 代理基于**接口**在内存中生成实现类；CGLIB 通过字节码生成**目标类的子类**。
调用机制上：JDK 代理把调用经 **InvocationHandler** 反射转发给目标方法；CGLIB 子类重写方法，经 **MethodInterceptor** 拦截后可直接调用父类（目标）方法，不依赖反射。', '["Spring AOP 默认代理方式的选择规则","JDK 动态代理与 CGLIB 的机制差异"]', '["在 Spring AOP 中，默认情况下对实现了接口的 Bean 和没有实现接口的 Bean 分别会使用哪种动态代理方式","这两种代理方式在生成方式和调用机制上的核心差异是什么"]', '["动态代理 · JDK与CGLIB"]', 'Spring AOP 默认用哪种代理、两者差异', '中档', '原理追问', 13, NULL, 1793696268634),
	(180, 2, 5, 17, 2, '请写一个最小可用的 @Aspect 切面示例（比如对 Service 层方法做增强），并逐一说明你用到的 @Aspect、@Pointcut、@Before / @AfterReturning 这些注解各自的作用是什么。
① 切面类与方法的完整示例代码
② 上述每个注解的含义分别是什么', '**① 示例**：
```java
@Aspect
@Component
public class LogAspect {
    @Pointcut("execution(* com.example.service.*.*(..))")
    public void serviceLayer() {}

    @Before("serviceLayer()")
    public void before(JoinPoint jp) {
        System.out.println("调用方法: " + jp.getSignature().getName());
    }

    @AfterReturning(pointcut = "serviceLayer()", returning = "result")
    public void afterReturn(Object result) {
        System.out.println("返回值: " + result);
    }
}
```
**② 注解含义**：
- **@Aspect**：声明当前类是一个**切面**，把通知（Advice）和切点（Pointcut）组织在一起，配合 @Component 交给 IOC 容器管理才会生效。
- **@Pointcut**：定义一个**切点表达式**（这里是 execution 表达式，匹配 service 包下所有方法），方法体为空，作用是**抽取复用切入点**，供各通知引用。
- **@Before**：**前置通知**，在目标方法执行前执行，通常用于记录入参、权限校验。
- **@AfterReturning**：**返回后通知**，在目标方法**正常返回后**执行，可通过 returning 属性拿到返回值；若目标方法抛异常则不执行。', '["AOP 切面注解（@Aspect / @Pointcut / @Before / @AfterReturning）","切入点表达式 execution 匹配规则"]', '["切面类与方法的完整示例代码","上述每个注解的含义分别是什么"]', '["AOP · 核心概念与切点"]', '写一个 @Aspect 切面例子并说明各注解含义', '基础', '概念辨析', 10, NULL, 1793696279856),
	(181, 2, 5, 18, 9, '在 Spring AOP 中，切点（Pointcut）与连接点（Joinpoint）分别指什么？二者是何关系？各自对应哪个注解？', '**连接点（Joinpoint）** 是程序执行过程中可被拦截的候选时机，比如方法的调用、异常的抛出；在 Spring AOP 里由于基于代理，**连接点通常就是方法的执行**。

**切点（Pointcut）** 是一个筛选规则，用来从众多连接点里挑出真正要织入增强的那些。二者关系是**连接点是候选集合，切点是过滤器**，一个切点可以匹配多个连接点。

对应注解：声明切点规则用 **@Pointcut**（value 里写切点表达式）；声明连接点位置、也就是做日志/事务等增强的位置用 **@Around / @Before / @After / @AfterReturning / @AfterThrowing** 这些通知注解，它们的参数里用切点表达式指定要拦截的方法。', '["切点与连接点的概念与关系","AOP 相关注解（@Pointcut 与通知注解）"]', '["在 Spring AOP 中，切点（Pointcut）与连接点（Joinpoint）分别指什么","二者是何关系","各自对应哪个注解"]', '["AOP · 核心概念与切点"]', '解释切点与连接点的区别及各配哪注解', '中档', '原理追问', 11, NULL, 1793762062685),
	(182, 2, 5, 18, 6, '一个 Bean 同时用 @PostConstruct 标注了初始化方法，又实现了 InitializingBean 的 afterPropertiesSet()，还在 XML/Bean 定义里配了 init-method。这三者执行的先后顺序是什么？为什么会有这个顺序？', '顺序是 **@PostConstruct → InitializingBean.afterPropertiesSet() → 自定义 init-method**。因为三者处在初始化流程的不同环节：属性填充完成后先处理注解回调（@PostConstruct），再执行 Aware/接口回调（afterPropertiesSet），最后才执行配置里指定的自定义初始化方法，留给使用者兜底扩展。所以同一个 Bean 上同时配置时，就是这个固定顺序。', '["Bean 初始化阶段三类初始化回调的执行顺序","InitializingBean 与 @PostConstruct 的调用时机差异"]', '["一个 Bean 同时用 @PostConstruct 标注了初始化方法，又实现了 InitializingBean 的 afterPropertiesSet()，还在 XML/Bean 定义里配了 init-method。这三者执行的先后顺序是什么","为什么会有这个顺序"]', '["初始化与销毁 · 回调方式"]', '@PostConstruct与InitializingBean并存执行顺序', '基础', '概念辨析', 8, NULL, 1793762054995),
	(183, 2, 5, 18, 7, '@ComponentScan 的 value/basePackages 属性是做什么的？如果不显式指定扫描包，Spring Boot 默认扫描哪个包？', '**value/basePackages 指定要扫描的包路径**，扫描这些包下带 @Component/@Service 等注解的类并注册为 Bean，可以指定多个包。不显式指定时，Spring Boot 默认扫描**启动类（标注 @SpringBootApplication 的类）所在的包及其所有子包**；这也是要求把启动类放在根包下的原因。', '["@ComponentScan 指定扫描包的作用与写法","Spring Boot 默认扫描包的范围"]', '["@ComponentScan 的 value/basePackages 属性是做什么的","如果不显式指定扫描包，Spring Boot 默认扫描哪个包"]', '["Bean配置 · 组件扫描与注册方式"]', '@ComponentScan指定扫描包的写法与作用', '基础', '概念辨析', 7, NULL, 1793762055011),
	(184, 2, 5, 18, 1, '在 Bean 生命周期的属性填充阶段，如果某个依赖（比如通过 @Autowired 声明的字段）在容器中找不到对应的 Bean，会发生什么？容器是直接抛异常跳过，还是给一个 null？请说明默认行为，以及怎样让它允许为空、允许时又会发生什么。', '**默认行为是直接抛异常**，Bean 创建失败，容器启动随之失败，报 **NoSuchBeanDefinitionException**（或 NoUniqueBeanDefinitionException，若存在多个候选却无法裁决），而不是默默给 null。原因是 @Autowired 的 **required 默认为 true**，语义上要求"必须注入"，找不到就是配置错误，fail-fast 更安全。若想允许为空，把 **@Autowired(required = false)** 标在该字段（或用 **@Nullable**、**Optional<依赖>** 包装），此时找不到就保留 null 或空 Optional，Bean 照常创建。但要注意这只是"允许为空"，后续用到该 null 会 NPE，仍需自己判空。', '["@Autowired 的 required 语义","属性填充阶段依赖缺失的默认行为"]', '["在 Bean 生命周期的属性填充阶段，如果某个依赖（比如通过 @Autowired 声明的字段）在容器中找不到对应的 Bean，会发生什么","容器是直接抛异常跳过，还是给一个 null","请说明默认行为，以及怎样让它允许为空、允许时又会发生什么。"]', '["Bean生命周期 · 主干流程"]', '属性填充阶段没拿到依赖会怎样', '基础', '概念辨析', 8, NULL, 1793762074229),
	(185, 2, 5, 18, 8, 'Spring 中三级缓存分别指哪三个缓存？各自的 key 和 value 是什么？请分别说明。', '**三级缓存**指的是 DefaultSingletonBeanRegistry 中的三个 Map：
**① 一级缓存 singletonObjects**：key 是 beanName，value 是**完全初始化好的单例 Bean**，getBean 直接命中它就直接返回。
**② 二级缓存 earlySingletonObjects**：key 是 beanName，value 是**提前曝光的半成品 Bean**（已实例化、未走完初始化，可能已是代理对象），供其他 Bean 在属性注入阶段引用。
**③ 三级缓存 singletonFactories**：key 是 beanName，value 是**ObjectFactory**（一个 lambda，调用 getObject() 才产出提前曝光对象，可以是原始对象也可以是被 AOP 代理后的对象）。
**缓存的迁移顺序**是：实例化后放入三级缓存 → 被别的 Bean 提前引用时从三级缓存取值并提升到二级缓存、删除三级 → 完整初始化后放入一级缓存，删除二、三级。', '["三级缓存的定义与 key/value 结构","三级缓存之间的迁移时机"]', '["Spring 中三级缓存分别指哪三个缓存","各自的 key 和 value 是什么","请分别说明。"]', '["循环依赖 · 三级缓存机制"]', '三级缓存各自在什么时候被使用', '中档', '原理追问', 11, NULL, 1793762084622),
	(186, 2, 5, 18, 3, '一个 Service 用字段注入（@Autowired 标在字段上）时 A、B 两个 Bean 可以互相依赖、正常启动。若改成构造器注入，Spring 启动时就会报循环依赖失败。请说明：为什么构造器注入无法像字段注入那样被三级缓存"救回来"？以及在必须保留双向依赖的前提下，通常怎样改造来打破它？', '**构造器注入在实例化阶段就必须拿到依赖**，此时 Bean 还没创建完成，无法向对方提前暴露「半成品」引用；而三级缓存只在「实例化完成、属性填充之前」提供早期引用，因此救不了构造器注入。要在保留双向依赖的前提下改造：**一侧注入点加 @Lazy**（注入的是延迟代理，首次调用才真正取 Bean）是首选；也可以抽出第三个中介 Bean、或用事件/getBean 延迟获取，把硬依赖拆掉。', '["构造器注入的实例化时机与循环依赖","打破循环依赖的常用手段（@Lazy / 抽取公共 Bean）"]', '["一个 Service 用字段注入（@Autowired 标在字段上）时 A、B 两个 Bean 可以互相依赖、正常启动。若改成构造器注入，Spring 启动时就会报循环依赖失败。请说明：为什么构造器注入无法像字段注入那样被三级缓存\"救回来\"","以及在必须保留双向依赖的前提下，通常怎样改造来打破它"]', '["循环依赖 · 破坏方式与现状"]', '改用构造器注入后如何打破互相依赖', '基础', '概念辨析', 8, NULL, 1793762074246),
	(187, 2, 5, 18, 4, '在 Java 中，final 字段与「不可变」是什么关系？请说明：① final 字段能保证什么、不能保证什么；② 一个类要做到真正不可变，通常需要满足哪些条件。', '① final 字段保证的是**这个变量不能再被重新赋值**（引用不可改），**不保证引用对象的内部状态不可变**（list 仍是可变的）；② 真正不可变类通常要：类不可被继承（final 或构造不泄漏 this）、所有字段 **private final**、不提供任何修改方法、**可变成员做防御性拷贝**（入参和返回值都不直接暴露内部引用）。String 就是典型实现。', '["final 关键字的作用（引用不可变 vs 对象不可变）","不可变类的设计条件"]', '["final 字段能保证什么、不能保证什么","一个类要做到真正不可变，通常需要满足哪些条件。"]', '["构造器注入 · 不可变性优势"]', '用final字段说明不可变与不可变的好处', '基础', '概念辨析', 8, NULL, 1793762112900),
	(188, 2, 5, 18, 2, '除了"同类内部方法调用导致切面不生效"之外，再举出另外 2 个会让 Spring AOP 切面（代理）失效的典型场景，并分别简要说明为什么失效。', '两个典型场景：**① Bean 未纳入 Spring 容器**——对象是自己 new 的或手动装配的，容器没为它生成代理对象，切面无处织入，调用就是普通方法调用。**② 方法不可被代理拦截**——方法是 private/protected/static，或被 final 修饰：JDK 代理只代理接口方法、CGLIB 靠生成子类覆写方法，非 public 或 final 方法拦不住，切面同样不生效。', '["Spring AOP 基于代理的拦截边界","方法可见性与类/方法修饰符对代理的影响"]', '["除了\"同类内部方法调用导致切面不生效\"之外，再举出另外 2 个会让 Spring AOP 切面（代理）失效的典型场景，并分别简要说明为什么失效。"]', '["AOP · 失效场景与原理"]', '同类调用外的其他切面失效场景举例', '基础', '概念辨析', 8, NULL, 1793762074229),
	(189, 2, 5, 18, 5, '一个类没有实现任何接口，却需要被 AOP 增强，Spring 默认会用哪种动态代理？为什么 JDK 动态代理在这里用不了？另外，Spring Boot 里想强制全部改用 CGLIB，配置开关是什么？', '默认用 **CGLIB** 动态代理（生成目标类的子类）。JDK 动态代理的原理是**基于接口**——运行时生成一个实现目标接口的代理类，目标类没有实现任何接口，就没有接口可供代理类实现，所以用不了。Spring Boot 中想强制全部走 CGLIB，配置 **`spring.aop.proxy-target-class=true`**（等价于 `@EnableAspectJAutoProxy(proxyTargetClass = true)`）。', '["JDK 动态代理与 CGLIB 的适用条件差异","Spring Boot 中强制使用 CGLIB 的配置开关"]', '["一个类没有实现任何接口，却需要被 AOP 增强，Spring 默认会用哪种动态代理","为什么 JDK 动态代理在这里用不了","另外，Spring Boot 里想强制全部改用 CGLIB，配置开关是什么"]', '["动态代理 · JDK与CGLIB选型"]', '无接口类为何必须用CGLIB及配置开关', '基础', '概念辨析', 8, NULL, 1793762054981),
	(190, 2, 5, 18, 10, '业务背景：电商下单服务里有一个「风控校验服务 RiskCheckService」，它被几十个 Controller 和 Service 依赖。团队新上了「慢启动风控引擎」：服务启动后的前 2 分钟内，风控模型还在加载词表和预热模型，此时调用会返回降级结果（视为放行），2 分钟后才返回真实结果。

系统现状：RiskCheckService 由第三方 SDK 提供，其实现 Bean 在应用启动时就会初始化，且初始化过程会阻塞主线程约 40 秒，导致服务发布变慢；另外，部分调用方只想在真正走到风控分支时才触发它的首次调用。

约束：不允许改动第三方 SDK；不允许把风控调用改成异步；服务必须能在 K8s 里被 readiness 探针正确识别启动完成。

请回答：
① 注入 RiskCheckService 到几十个调用方时，构造器注入、字段注入（@Autowired 写在字段上）和 @Lazy 注入三种方式，在「启动耗时」「依赖不可用时的表现」「可测试性」三个维度上分别有什么差异？为什么会有这些差异？
② 在 RiskCheckService 的 Bean 上加 @Lazy，或者在调用方的注入点上加 @Lazy，分别延迟了什么？二者在「谁被延迟」「何时真正创建 Bean」上的区别是什么？
③ 针对慢启动、且只想在首次真正调用时才触发初始化的场景，你会选哪种注入方式配合 @Lazy？给出你的取舍理由（至少说明为什么不选另外两种），并说明这样改造后 readiness 探针应如何设置才不会误判服务未就绪。', '① **启动耗时**：构造器注入和字段注入都会在容器启动时创建 RiskCheckService，那 40 秒谁都躲不掉，耗时相当；@Lazy 注入只给代理，Bean 推迟到首次调用才创建，启动最快。**依赖不可用时**：构造器注入启动即失败、fail-fast；字段注入启动不报错，首次调用才暴露问题。**可测试性**：构造器注入最好（可直接 new 单测），字段注入必须依赖容器/反射。② **Bean 上加 @Lazy**：延迟的是这个 Bean 自身，所有拿到它的人都受影响，首次调用才真正创建；**注入点上加 @Lazy**：只延迟这一处注入，注入的是延迟代理，每个注入点自行决定是否延迟，真正创建仍是首次调用时。③ 选**构造器注入 + 注入点 @Lazy**：保留构造器注入的可测性与依赖显式化，又把创建推迟到首次调用；不选字段注入是因为可测试性差、依赖不可见；不选纯 Bean 级 @Lazy 是因为影响面是全局的。readiness 探针应以**应用自身就绪（端口/健康接口）**为准，不能等风控 Bean 初始化完成，否则会误判未就绪。', '["@Lazy 延迟加载与代理注入","依赖注入方式（构造器/字段注入）对比"]', '["注入 RiskCheckService 到几十个调用方时，构造器注入、字段注入（@Autowired 写在字段上）和 @Lazy 注入三种方式，在「启动耗时」「依赖不可用时的表现」「可测试性」三个维度上分别有什么差异？为什么会有这些差异？","在 RiskCheckService 的 Bean 上加 @Lazy，或者在调用方的注入点上加 @Lazy，分别延迟了什么？二者在「谁被延迟」「何时真正创建 Bean」上的区别是什么？","针对慢启动、且只想在首次真正调用时才触发初始化的场景，你会选哪种注入方式配合 @Lazy？给出你的取舍理由（至少说明为什么不选另外两种），并说明这样改造后 readiness 探针应如何设置才不会误判服务未就绪。"]', '["IoC/DI · 概念与两种注入方式","Bean延迟加载 · @Lazy"]', '注册慢启动服务时注入方式与@Lazy取舍', '大题', '场景应用', 23, NULL, 1793762129183),
	(191, 2, 5, 19, 2, 'AOP 的代理对象是在 Bean 生命周期的哪个环节生成的？它和普通 Bean 相比有什么不同？', '**代理对象生成在「初始化之后、放入容器之前」**，通常由 BeanPostProcessor 的后置处理（如 AbstractAutoProxyCreator）对初始化完成的 Bean 做包装，返回代理对象。

**与普通 Bean 的不同**：
1. **容器中保存的对象不同**：普通 Bean 直接存原始对象；AOP 场景存的是代理对象，原始对象由代理内部持有；
2. **能力不同**：代理对象能在方法调用前后织入切面逻辑（事务、日志、权限等），而原始对象没有；
3. **调用方无感**：使用方拿到的都是代理对象，调用方式与普通 Bean 一致，切面逻辑在代理内部拦截执行。', '["AOP 代理生成时机（初始化后 BeanPostProcessor）","代理对象与原始对象的区别"]', '["AOP 的代理对象是在 Bean 生命周期的哪个环节生成的","它和普通 Bean 相比有什么不同"]', '["AOP · 与生命周期的关系"]', 'Bean的代理对象是在生命周期哪个环节生成的，与普通Bean有何不同', '基础', '概念辨析', 8, NULL, 1793778859494),
	(192, 2, 5, 19, 3, 'singleton 与 prototype 两种作用域的 Bean，在容器里的表现有哪些差异？分别用什么注解或属性声明？', '**差异主要在创建次数、获取时机和销毁管理**：
1. **singleton**：容器中**只创建一个实例**，启动时（默认非懒加载）就创建并放入单例池，多次 getBean / 注入拿到的是**同一个对象**，容器关闭时负责销毁回调；
2. **prototype**：**每次 getBean / 每次注入都创建一个新实例**，容器不缓存、不管理其销毁，用完由使用方自己回收。

**声明方式**：用 `@Scope("singleton")` 或 `@Scope("prototype")`；在 XML 中对应 `<bean scope="singleton|prototype">`。singleton 是**默认作用域**。', '["singleton 与 prototype 的差异","作用域声明方式（@Scope / scope 属性）"]', '["singleton 与 prototype 两种作用域的 Bean，在容器里的表现有哪些差异","分别用什么注解或属性声明"]', '["Bean作用域 · singleton与prototype"]', 'singleton与prototype在容器里表现有何差异，用什么注解或属性声明', '基础', '概念辨析', 8, NULL, 1793778859498),
	(193, 2, 5, 19, 5, '构造器注入形成循环依赖时，Spring 容器启动为什么会直接报错？从注入方式上有哪些做法可以规避这种循环？', '因为**构造器注入要求依赖在实例化那一刻就必须就绪**。创建 A 时要调 A 的构造器，就得先有 B；创建 B 又要先有 A，两者互相等对方完成实例化，而 Spring 能提前暴露的“早期引用”只存在于属性赋值阶段，构造器阶段无中间态可用，于是抛 BeanCurrentlyInCreationException。规避做法：**①改用 setter / 字段注入**，把依赖推迟到属性赋值阶段，由三级缓存解决；**②在注入点加 @Lazy**，注入一个代理，真实对象首次调用时才去创建。', '["构造器注入与 setter/字段注入的差异","构造器循环依赖为何不可解与 @Lazy 规避"]', '["构造器注入形成循环依赖时，Spring 容器启动为什么会直接报错","从注入方式上有哪些做法可以规避这种循环"]', '["循环依赖 · 构造器注入无法解决循环依赖"]', '为什么构造器注入形成循环时启动报错，怎么从注入方式上规避', '基础', '概念辨析', 8, NULL, 1793778880091),
	(194, 2, 5, 19, 6, '什么情况才真正构成 Spring 中的循环依赖？Spring 容器是怎么判定它是循环并报错的？', '真正构成循环依赖，是指**多个单例 Bean 在创建过程中形成闭环引用**——A 依赖 B、B 又依赖 A（含自依赖），使得谁都无法先完成创建。Spring 的判定方式：容器在开始创建某个 Bean 前，先把它标记为“**正在创建中**”（记进 singletonsCurrentlyInCreation）；创建过程中若要再次获取这个正在创建中的 Bean，就说明出现了环。此时如果该 Bean 是单例且属性注入，可从三级缓存取到早期引用，正常解决；若是**构造器注入或 prototype 作用域**，拿不到早期引用，就抛 **BeanCurrentlyInCreationException** 报错。', '["循环依赖的成立条件","创建中 Bean 检测与异常抛出"]', '["什么情况才真正构成 Spring 中的循环依赖","Spring 容器是怎么判定它是循环并报错的"]', '["循环依赖 · 成因与检测"]', '什么情况才构成循环依赖，Spring怎么判定并报错', '基础', '概念辨析', 8, NULL, 1793778880094),
	(195, 2, 5, 19, 7, 'Bean 被 AOP 代理后，切面还能生效需要满足什么条件？有哪些常见改法会让增强悄悄失效？', '生效的根本条件只有一条：**方法调用必须经过 Spring 容器里的那个代理对象**，因为增强逻辑织入在代理的 invoke 里。常见让增强失效的改法：**①类内部用 this 自调用**，走的是原始对象，代理被绕过；**②自己 new 出对象使用**，该对象不在容器中，根本没有代理；**③把方法声明成 private / static / final**，CGLIB 或 JDK 动态代理都无法覆盖；**④调用的是容器外的类或未被代理的 Bean**。要让切面生效，就得保证调用方拿到的是注入进来的代理引用。', '["代理对象 vs 目标对象的调用链路","内部调用绕过代理导致增强失效"]', '["Bean 被 AOP 代理后，切面还能生效需要满足什么条件","有哪些常见改法会让增强悄悄失效"]', '["AOP · 失效场景与原理"]', 'Bean被代理后还能保证切面生效的条件，哪些改法会让增强悄悄丢失', '基础', '概念辨析', 7, NULL, 1793778880096),
	(196, 2, 5, 19, 8, '在Spring单例Bean的setter注入场景下，若A依赖B、B又依赖A，请说明这两个Bean在创建A的过程中，是如何借助三级缓存完成提前暴露、从而打破循环的？请按①各级缓存分别存放什么、②A与B依次经过哪几级缓存完成提早暴露的顺序来回答。', '**三级缓存分工**：**一级singletonObjects**存完整成品Bean；**二级earlySingletonObjects**存已提前暴露的早期引用；**三级singletonFactories**存能生成早期引用的ObjectFactory（单例工厂）。

**流转过程**：创建A→实例化A后把A的对象工厂放入**三级缓存**暴露早期引用→填充属性发现依赖B→转去创建B→B实例化后同样先放入三级缓存→B填充属性发现依赖A→从**三级缓存**取A的工厂拿到A早期引用，放入**二级缓存**并清掉三级→B注入A的早期引用完成创建，进入**一级缓存**→回到A，注入B成品→A初始化完成后进入**一级缓存**，并清掉二、三级中的A。

所以循环靠**A提前暴露的早期引用**被B拿到而打破，**只有单例+setter/字段注入**才走得通。

扩展：三级缓存中存工厂而不是直接存半成品，是为了让AOP代理能在需要时统一在工厂里生成，避免早期引用与最终Bean不一致。', '["Spring三级缓存","循环依赖的提前暴露"]', '["各级缓存分别存放什么","A与B依次经过哪几级缓存完成提早暴露的顺序来回答。"]', '["循环依赖 · 三级缓存机制"]', '单例setter循环依赖时，对象在三级缓存间怎么流转完成提前暴露', '中档', '原理追问', 11, NULL, 1793779152362),
	(197, 2, 5, 19, 1, '一个 Bean 从被实例化（new 出来）到可以被业务使用，中间要经历哪几大步？请按顺序列出，并简要说明每步做了什么。', '大方向分四步：**①实例化**，反射调用构造器 new 出对象，此时只是空壳，属性全是默认值；**②属性赋值（依赖注入）**，按 @Autowired 等规则把依赖 Bean 注入进来；**③初始化**，先回调各种 Aware 接口，再执行 BeanPostProcessor 前置处理，然后调用 @PostConstruct / init-method，最后执行 BeanPostProcessor 后置处理（**AOP 代理通常在这一步生成**）；**④使用**，Bean 进入单例池可被业务获取，容器关闭时再走销毁流程。', '["Bean 生命周期主干流程（实例化→属性赋值→初始化→可用）","初始化阶段的回调顺序（Aware / @PostConstruct / init-method）"]', '["一个 Bean 从被实例化（new 出来）到可以被业务使用，中间要经历哪几大步","请按顺序列出，并简要说明每步做了什么。"]', '["Bean生命周期 · 主干流程"]', '一个Bean被new出来后到可使用，中间经历哪几大步，顺序如何', '基础', '概念辨析', 8, NULL, 1793778859489),
	(198, 2, 5, 19, 4, '@Autowired 默认是按类型匹配还是按名称匹配？当容器里有多个同类型的候选 Bean 时，Spring 如何消歧？请说明主要的消歧手段。', '**默认按类型（byType）匹配**。当同类型有多个候选 Bean 时，会按以下顺序尝试消歧：**①@Qualifier**，显式指定要注入的 Bean 名称，优先级最高；**②@Primary**，在被选 Bean 上标为首选，遇到歧义时优先选它；**③名称回退**，既无 @Qualifier 也无 @Primary 时，Spring 用字段名或构造器参数名去比对 Bean 名称，匹配上就注入；**④都不满足则抛 NoUniqueBeanDefinitionException**。', '["@Autowired 的匹配规则（byType）","多候选 Bean 的消歧手段（@Qualifier / @Primary / 名称匹配 / @Resource）"]', '["@Autowired 默认是按类型匹配还是按名称匹配","当容器里有多个同类型的候选 Bean 时，Spring 如何消歧","请说明主要的消歧手段。"]', '["依赖注入 · @Autowired装配规则"]', '@Autowired默认按类型还是按名称匹配，多个候选Bean时怎么消歧', '基础', '概念辨析', 8, NULL, 1793778859501),
	(199, 2, 5, 19, 9, '切面（Aspect）、通知（Advice）、切点（Pointcut）、连接点（Joinpoint）这四个术语各指什么？请写一个最小的 @Aspect 切面代码示例，并在示例里指出这四个概念分别对应代码中的哪一部分。', '**切面 Aspect**：被 @Aspect 标注的类，把通知和切点打包在一起；**通知 Advice**：切面在连接点上做什么、什么时机做，如 @Before/@After/@Around；**切点 Pointcut**：一组匹配规则，圈定哪些方法要被增强；**连接点 Joinpoint**：程序执行过程中可被织入的点，Spring AOP 里就是方法调用。最小示例：
```java
@Aspect @Component
public class LogAspect {                 // ← Aspect 切面
    @Pointcut("execution(* com.demo.service.*.*(..))")  // ← Pointcut 切点
    public void pt(){}
    @Before("pt()")                     // ← Advice 通知
    public void before(JoinPoint jp){   // ← JoinPoint 连接点
        System.out.println(jp.getSignature());
    }
}
```', '["AOP 核心术语（切面/通知/切点/连接点）","基于注解的最小切面写法"]', '["切面（Aspect）、通知（Advice）、切点（Pointcut）、连接点（Joinpoint）这四个术语各指什么","请写一个最小的 @Aspect 切面代码示例，并在示例里指出这四个概念分别对应代码中的哪一部分。"]', '["AOP · 核心概念与切点"]', '切面、通知、切点、连接点四个术语各指什么，写个最小切面对应起来', '中档', '原理追问', 11, NULL, 1793778875446),
	(200, 2, 5, 19, 10, '某新服务模块启动特别慢（本地要一分多钟），老板要求先定位瓶颈再优化。排查发现：模块里大量用@Autowired按类型注入、部分Bean初始化很重（连数据库、加载大字典），还有组件扫描范围开得过大。请回答：①@ComponentScan扫描范围多大对启动耗时有何影响，该如何收敛？②初始化重的Bean用@Lazy延迟加载能带来什么收益、有什么边界和风险？③在启动速度与运行期首访延迟之间，DI装配方式（构造器注入 vs setter/字段注入）和@Lazy该如何取舍，给出你的方案。', '①组件扫描的成本在于**要把扫描包及子包下所有 class 加载成元数据、逐个判断注解和 @Conditional 条件、再注册 BeanDefinition**，范围越大、无关类越多启动越慢。收敛办法：用 **basePackages 精确指向业务包**，不要从根包起扫，把框架包、第三方包排除在外，能显式 @Bean/@Import 的就不靠扫描。②@Lazy 的收益是**把重初始化（连库、加载大字典）从启动期挪到首次调用**，启动明显变快。边界与风险：问题被推迟到运行期才暴露、启动时不再校验该 Bean 能否创建、首访出现明显卡顿、注入到的是代理对象带来的类型判断与回调时机变化。③取舍方案：**启动必须可用的核心 Bean 用构造器注入、不加 @Lazy**，保证创建即完整、依赖缺失尽早暴露；**低频且初始化重的 Bean（字典、常量集等）加 @Lazy**，把成本摊到首访；非核心的循环依赖场景才退让到 setter 注入。整体原则是启动速度优先给冷门 Bean，正确性与可测性优先给核心链路，不做一刀切。', '["组件扫描范围与启动耗时","@Lazy延迟初始化","构造器注入与setter注入的取舍"]', '["@ComponentScan扫描范围多大对启动耗时有何影响，该如何收敛？","初始化重的Bean用@Lazy延迟加载能带来什么收益、有什么边界和风险？","在启动速度与运行期首访延迟之间，DI装配方式（构造器注入 vs setter/字段注入）和@Lazy该如何取舍，给出你的方案。"]', '["IoC/DI · 概念与两种注入方式","Bean延迟加载 · @Lazy","Bean配置 · 组件扫描与注册方式"]', '新服务模块上线慢，串联讲DI选型、@Lazy延迟与扫描装配的取舍', '大题', '场景应用', 23, NULL, 1793779152367),
	(201, 2, 5, 20, 1, 'Spring 用三级缓存解决 setter 注入的循环依赖。请说明：①一级、二级、三级缓存各存什么；②获取一个 Bean 依赖时，三个缓存的查找顺序是怎样的。', '①一级缓存 **singletonObjects** 存的是**完全初始化好的成品单例 Bean**；二级缓存 **earlySingletonObjects** 存的是**提前暴露的半成品早期引用**（已经实例化、还没完成属性填充和初始化）；三级缓存 **singletonFactories** 存的是 **ObjectFactory 工厂**，调用它的 getObject 才能拿到早期引用。②查找一个依赖时按 **一级 → 二级 → 三级** 的顺序来：一级有就直接返回；没有就查二级；二级也没有就查三级，从工厂里 getObject 拿到早期引用并把它升到二级，同时清掉三级里对应的工厂。', '["Spring 三级缓存","setter 循环依赖"]', '["一级、二级、三级缓存各存什么","获取一个 Bean 依赖时，三个缓存的查找顺序是怎样的。"]', '["循环依赖 · 三级缓存机制"]', 'setter 循环依赖中，三个缓存各存什么、按什么顺序查', '基础', '概念辨析', 4, NULL, 1793784335011),
	(202, 2, 5, 20, 3, '@Lazy 注解标在 Bean 类的定义上，和标在注入点（字段或构造器参数）上，效果有什么差别？请分别说明两者各自什么时候创建该 Bean。', '①标在**类定义上**：把这个 Bean 定义设为**延迟初始化**，容器启动刷新阶段不会创建它，**第一次被使用（第一次 getBean）时才创建**。②标在**注入点（字段或构造器参数）上**：只影响这一处注入，注入的是**延迟代理**，容器启动时不真正去创建该 Bean，**直到在代理上第一次调用方法时**才触发容器去创建真实 Bean；而且这个懒加载是**按注入点隔离**的，其他没有标 @Lazy 的注入点仍然会在启动时正常注入真实 Bean。', '["@Lazy 注解","Bean 延迟初始化"]', '["@Lazy 注解标在 Bean 类的定义上，和标在注入点（字段或构造器参数）上，效果有什么差别","请分别说明两者各自什么时候创建该 Bean。"]', '["@Lazy · 延迟加载注入点"]', '@Lazy 标在 Bean 类和标在注入点上，效果差别', '基础', '概念辨析', 4, NULL, 1793784335011),
	(203, 2, 5, 20, 4, '两个 Bean 通过构造器互相依赖（A 的构造器依赖 B，B 的构造器依赖 A），在没有 @Lazy 时启动会报错。请问：如果在 A 构造器的 B 参数上加 @Lazy，为什么应用就能正常启动了？', '因为构造器注入要求在**实例化的那一刻依赖就已经就绪**，所以无 @Lazy 时创建 A 必须先创建 B、创建 B 又必须先创建 A，形成**无法通过提前暴露半成品来化解**的死循环，直接抛异常。而在 A 的 B 参数上加 @Lazy 后，Spring 不会去创建真实 B，而是注入一个 **B 的延迟代理对象**，A 的构造器拿到代理即可完成实例化，启动阶段就不会触发 B 的创建，循环被**打断**；后续真正调用 B 的方法时，代理才去容器里获取真实的 B。', '["构造器循环依赖","@Lazy 延迟代理"]', '["两个 Bean 通过构造器互相依赖（A 的构造器依赖 B，B 的构造器依赖 A），在没有 @Lazy 时启动会报错。请问：如果在 A 构造器的 B 参数上加 @Lazy，为什么应用就能正常启动了？"]', '["依赖注入 · @Lazy延迟加载解决循环依赖"]', '构造器互相依赖时，在其中一个参数上加 @Lazy 为什么能启动', '基础', '概念辨析', 4, NULL, 1793784335019),
	(204, 2, 5, 20, 9, 'Spring Bean 初始化时需要连数据库、销毁时需要关闭资源，应该分别在哪个方法上加哪两个注解？简述注解的作用。', '连接数据库的逻辑放在**初始化方法**上，加 **@PostConstruct**；关闭资源的逻辑放在**销毁方法**上，加 **@PreDestroy**。作用是：@PostConstruct 标记的方法在 Bean **依赖注入完成后、初始化回调（afterPropertiesSet、init-method）之前**由容器调用一次，用来做资源准备；@PreDestroy 标记的方法在容器关闭、Bean 销毁前调用一次，用来释放连接等资源。', '["@PostConstruct 与 @PreDestroy 的作用时机","Bean 初始化与销毁回调"]', '["Spring Bean 初始化时需要连数据库、销毁时需要关闭资源，应该分别在哪个方法上加哪两个注解","简述注解的作用。"]', '["Bean生命周期 · @PostConstruct/@PreDestroy注解初"]', '在 init 里连数据库、在 destroy 里关闭资源，该用哪两个注解', '基础', '概念辨析', 4, NULL, 1793784335088),
	(205, 2, 5, 20, 10, '被代理的目标类没有实现任何接口时，使用 JDK 动态代理会发生什么？Spring 在这种情况下会怎么选择代理方式，判断依据是什么？', 'JDK 动态代理**必须基于接口**：它通过 Proxy 加 InvocationHandler 生成一个**实现相同接口**的代理对象。目标类**没有实现任何接口时，JDK 动态代理无法创建代理对象**。这种情况下 Spring 会改用 **CGLIB**，通过**生成目标类的子类**并重写方法来织入增强。判断依据就是**目标类是否实现了接口**：有接口用 JDK 代理，没有接口用 CGLIB（Spring Boot 2.x 起默认直接用 CGLIB）。', '["JDK 动态代理依赖接口的限制","Spring AOP 代理方式的选择依据（JDK vs CGLIB）"]', '["被代理的目标类没有实现任何接口时，使用 JDK 动态代理会发生什么","Spring 在这种情况下会怎么选择代理方式，判断依据是什么"]', '["AOP · JDK动态代理基于接口实现"]', '目标类没接口时 JDK 代理会怎样，怎么判断用哪种', '基础', '概念辨析', 4, NULL, 1793784335088),
	(206, 2, 5, 20, 11, '某 Bean 原来用字段注入（@Autowired 直接标在字段上）能正常启动，改成构造器注入后启动报错，提示找不到某个依赖。请从依赖注入发生的时机上解释：为什么字段注入能启动成功，而构造器注入会失败？', '差别在**注入发生的时机**：**字段注入**是在 Bean **实例化之后**的属性填充阶段，通过反射给字段赋值，此时对象已经创建出来，容器可以先把它暴露出去、依赖稍后再解析，所以能启动。**构造器注入**发生在**实例化之前**——要 new 出对象就必须先把所有构造参数依赖解析出来，如果这个依赖此刻拿不到（比如它自己还卡在创建中），创建就无法继续，启动直接失败。', '["字段注入与构造器注入的时机差异","Bean 实例化阶段的依赖解析"]', '["某 Bean 原来用字段注入（@Autowired 直接标在字段上）能正常启动，改成构造器注入后启动报错，提示找不到某个依赖。请从依赖注入发生的时机上解释：为什么字段注入能启动成功，而构造器注入会失败？"]', '["@Autowired · 注入点与循环依赖"]', '把字段注入改成构造器注入后启动报错，从时机上解释', '基础', '概念辨析', 4, NULL, 1793784335102),
	(207, 2, 5, 20, 12, '自定义一个 BeanPostProcessor，说明它会作用在哪些 Bean 上，以及在 Bean 生命周期的哪个阶段、对 Bean 做了什么处理。', '自定义的 BeanPostProcessor 会作用于**容器中创建的所有 Bean 实例**。它在 Bean **实例化、依赖注入完成之后**介入：初始化方法（afterPropertiesSet / init-method）**之前**回调 **postProcessBeforeInitialization**，**之后**回调 **postProcessAfterInitialization**。在这两个回调里可以拿到 Bean 实例做修改、包装或**生成代理对象**——Spring AOP 的自动代理就是在 postProcessAfterInitialization 中完成的。', '["BeanPostProcessor 的两个回调时机","BeanPostProcessor 对 Bean 的增强/替换作用"]', '["自定义一个 BeanPostProcessor，说明它会作用在哪些 Bean 上，以及在 Bean 生命周期的哪个阶段、对 Bean 做了什么处理。"]', '["Bean后处理器 · BeanPostProcessor"]', '自定义一个 BPP，说明它在哪个阶段对 Bean 做了什么处理', '基础', '概念辨析', 4, NULL, 1793784335105),
	(208, 2, 5, 20, 13, '在同一个 Service 类中，方法 A 内部直接调用本类的方法 B，而方法 B 上标注了 @Transactional（或自定义 AOP 通知）。运行时发现 B 上的通知没有生效。请回答：①为什么没有执行？②在不拆分到另一个 Bean 的前提下，怎么改才能让通知生效？', '① 因为 Spring AOP **基于代理对象**实现，外部调用先进入代理再转发到目标对象；而方法 A 内部调用 B 时用的是 **this**，直接调到目标对象本身，**不经过代理**，所以 B 上的通知/事务不生效。② 不拆分 Bean 的前提下，让调用走**代理对象**：可以开 **exposeProxy=true** 后用 **AopContext.currentProxy()** 拿到当前代理再调用 B；或者把自身 Bean **注入到自己的字段**里，用注入进来的代理对象调用 B。', '["Spring AOP 代理机制","自调用导致通知失效"]', '["为什么没有执行？","在不拆分到另一个 Bean 的前提下，怎么改才能让通知生效？"]', '["AOP失效 · 同类内部this调用"]', '同一类里方法 A 调方法 B，B 上的通知为何没执行、怎么改', '基础', '概念辨析', 4, NULL, 1793784335628),
	(209, 2, 5, 20, 14, '一个 Bean 同时使用了构造器注入、属性（setter/字段）注入，并在某个方法上标注了 @PostConstruct。请按执行先后对这三者排序，并分别说明每个阶段依赖注入或初始化进行到了哪一步。', '顺序：**构造器注入 → 属性注入 → @PostConstruct**。
①**构造器注入**最先执行，此时对象刚实例化，依赖通过构造参数传入；
②**属性注入**在实例化之后进行，由容器为 setter/字段填充依赖；
③**@PostConstruct** 在依赖注入完成后、Bean 初始化阶段回调，此时所有注入的依赖都已可用。', '["Bean 生命周期","依赖注入与初始化回调顺序"]', '["一个 Bean 同时使用了构造器注入、属性（setter/字段）注入，并在某个方法上标注了 @PostConstruct。请按执行先后对这三者排序，并分别说明每个阶段依赖注入或初始化进行到了哪一步。"]', '["Bean生命周期 · 实例化与初始化顺序"]', '构造器、属性注入、@PostConstruct 三者执行先后排序并说明', '基础', '概念辨析', 4, NULL, 1793784335631),
	(210, 2, 5, 20, 15, '容器中有两个同类型的 Bean。要按名称精确指定注入哪一个用 @Qualifier，要按条件（如某 profile、某条件成立时）选择候选 Bean 用 @Conditional。请分别说明这两个注解通常写在什么位置（字段/构造参数/方法/类等）。', '**@Qualifier** 用来按**名称**精确指定注入哪个 Bean，通常写在：**注入字段上、构造器参数上、方法参数上**（配合 @Autowired / @Inject 使用）。**@Conditional** 用来按**条件**决定是否注册/生效，通常写在：**@Bean 方法上**（条件成立才注册这个 Bean），也可以写在 **@Configuration 类上**（条件成立整个配置类才生效），它还常被用作**元注解**派生出 @ConditionalOnClass、@ConditionalOnProperty、@Profile 这类具体条件注解。', '["@Qualifier 按名称消歧","@Conditional 条件注册"]', '["容器中有两个同类型的 Bean。要按名称精确指定注入哪一个用 @Qualifier，要按条件（如某 profile、某条件成立时）选择候选 Bean 用 @Conditional。请分别说明这两个注解通常写在什么位置（字段/构造参数/方法/类等）。"]', '["依赖注入 · @Primary与@Qualifier消歧"]', '两个同类型 Bean，两种消歧注解分别用在什么位置', '基础', '概念辨析', 4, NULL, 1793784335633),
	(211, 2, 5, 20, 16, '某个业务 Bean 需要拿到 ApplicationContext 来手动获取其他 Bean。请回答：①有哪两种常见获取方式？②如果是通过实现 ApplicationContextAware 获取，容器的 setApplicationContext 方法会在 Bean 生命周期的哪个阶段被调用？', '①**两种方式**：一是实现 **ApplicationContextAware** 接口，由容器回调注入；二是对 ApplicationContext 字段加 **@Autowired** 直接注入。
②**调用时机**：在 Bean **实例化并完成属性注入之后、初始化方法（如 @PostConstruct、afterPropertiesSet）之前**，由容器的 BeanPostProcessor 回调 setApplicationContext，因此初始化阶段就能使用。', '["ApplicationContextAware 回调","Bean 生命周期阶段"]', '["有哪两种常见获取方式？","如果是通过实现 ApplicationContextAware 获取，容器的 setApplicationContext 方法会在 Bean 生命周期的哪个阶段被调用？"]', '["Aware接口 · 常见接口"]', '业务 Bean 需要拿到 ApplicationContext，用什么方式、何时被调用', '基础', '概念辨析', 4, NULL, 1793784335636),
	(212, 2, 5, 20, 17, '同一个 Bean A 依赖 Bean B：若 A 用属性注入（@Autowired 字段）引用 B，能正常启动；若改成构造器注入，启动直接报循环依赖错误。请回答：①两种注入方式下，A 与 B 的创建顺序和依赖关系分别如何？②为什么构造器注入会在启动阶段报错，而属性注入不会？', '① **属性注入**：容器先 **new 出 A**（此时 A 已可被引用），发现需要 B → 去创建 B → B 又依赖 A，于是把 **A 的早期引用（半成品）**注入给 B → B 创建完成 → 再注入给 A → A 完成，因此能启动。**构造器注入**：A 必须**先拿到完整的 B 才能实例化**，无法对外暴露半成品，两边互等。② 因为属性注入是在**实例化之后**填充，容器可以**提前暴露早期引用**打破环；构造器注入在**实例化之前**就要解析依赖，拿不到就启动阶段直接抛循环依赖错误。', '["构造器注入与属性注入的时机差异","Spring 三级缓存解决循环依赖"]', '["两种注入方式下，A 与 B 的创建顺序和依赖关系分别如何？","为什么构造器注入会在启动阶段报错，而属性注入不会？"]', '["循环依赖 · 构造器注入为何不行"]', '属性注入能解、构造器注入报错，从何时产生状态差异解释', '基础', '概念辨析', 4, NULL, 1793784336739),
	(213, 2, 5, 20, 18, '给定切点表达式：execution(* com.example.service.UserService.get*(..))。请回答：①该表达式能匹配哪些类、哪些方法？②方法参数和返回值分别有什么要求？', '① 该表达式匹配 **com.example.service 包下的 UserService 类**（及其子类/实现类中对应的方法），方法名要**以 get 开头**。② 返回值位置的 `*` 表示**任意返回类型**；参数位置的 `(..)` 表示**任意个数、任意类型的参数**，包括没有参数的情况，即对参数和返回值都没有限制。', '["execution 切点表达式语法","AOP 切点匹配范围"]', '["该表达式能匹配哪些类、哪些方法？","方法参数和返回值分别有什么要求？"]', '["AOP · 核心概念与切点"]', '给一句 execution 表达式，让其判断能切入哪些方法', '基础', '概念辨析', 4, NULL, 1793784336739),
	(214, 2, 5, 20, 19, '请用 @PostConstruct 和 @PreDestroy 两个注解，写一个带初始化逻辑和销毁逻辑的 Bean（方法体可省略），并说明这两个方法分别在 Bean 生命周期的哪个阶段被调用。', '在类中写 @PostConstruct 标注的 init() 和 @PreDestroy 标注的 destroy()。**@PostConstruct 在 Bean 实例化、依赖注入完成后、进入初始化阶段时被调用**（早于 InitializingBean.afterPropertiesSet）；**@PreDestroy 在容器关闭、Bean 被销毁之前被调用**（早于 DisposableBean.destroy）。', '["@PostConstruct/@PreDestroy 用法","Bean 生命周期中初始化与销毁的时机"]', '["请用 @PostConstruct 和 @PreDestroy 两个注解，写一个带初始化逻辑和销毁逻辑的 Bean（方法体可省略），并说明这两个方法分别在 Bean 生命周期的哪个阶段被调用。"]', '["初始化与销毁 · 回调方式"]', '用注解写一个含初始化和销毁逻辑的 Bean，说明两个方法何时被调用', '基础', '概念辨析', 4, NULL, 1793784336739),
	(215, 2, 5, 20, 20, '有一个 OrderService 类，它依赖一个 DataSource：DataSource 是运行必需的，缺失就应该启动失败；而另一个 AuditLogger 是可选的，没有也能正常工作。请分别为这两个依赖选择注入方式，并说明选择的理由。', '**DataSource 用构造器注入**：构造器参数即强制依赖，缺失时 Bean 无法实例化、启动直接失败（快速失败），还可声明为 final 保证不可变。**AuditLogger 用 setter（或字段）注入并配合 @Autowired(required = false)**：允许注入为空，缺失也能正常启动，调用处判空即可；也可用 ObjectProvider 按需获取。', '["构造器注入与属性注入的选型","可选依赖的处理方式"]', '["有一个 OrderService 类，它依赖一个 DataSource：DataSource 是运行必需的，缺失就应该启动失败；而另一个 AuditLogger 是可选的，没有也能正常工作。请分别为这两个依赖选择注入方式，并说明选择的理由。"]', '["IoC/DI · 概念与两种注入方式"]', '给一个依赖必填/可选的类，让其选注入方式并说理由', '基础', '概念辨析', 4, NULL, 1793784336739),
	(216, 2, 5, 20, 5, '某类给一个方法加了 @Transactional，类内部另一个方法通过 this 调用它，事务不生效；另有类用 this 调用自身加了自定义 @Log 注解的方法，日志也没打出来。请判断这两种失效的共同原因是什么，并说明事务和自定义注解失效分别和 Spring AOP 的哪种代理机制有关。', '两种失效的**共同原因**是：事务和日志都靠 **AOP 代理**增强，而 `this` 调用是**原始对象内部的直接方法调用**，根本不经过代理对象，拦截器链不执行，增强自然失效。与代理机制的关系是：Spring AOP 有两种实现——目标类有接口时默认用 **JDK 动态代理**，没有接口时用 **CGLIB 生成子类代理**；无论哪一种，方法调用都必须从**代理对象**进入才会被拦截，`this` 拿到的是**原始对象自身**，绕过了这两种代理，所以事务和自定义注解一起失效。', '["Spring AOP 代理机制","类内部自调用导致增强失效"]', '["某类给一个方法加了 @Transactional，类内部另一个方法通过 this 调用它，事务不生效；另有类用 this 调用自身加了自定义 @Log 注解的方法，日志也没打出来。请判断这两种失效的共同原因是什么，并说明事务和自定义注解失效分别和 Spring AOP 的哪种代理机制有关。"]', '["AOP · 内部方法自调用导致切面失效"]', '给出一个提升事务/日志失效的类，让判断原因', '基础', '概念辨析', 4, NULL, 1793784337640),
	(217, 2, 5, 20, 6, 'Spring 创建带 AOP 增强的 Bean 时，要经历实例化、属性填充、初始化、生成代理几个阶段。请说明：①代理对象是在哪个阶段之后生成的；②在容器里以 Bean 名字取到的、被注入到其他 Bean 里的，是代理对象还是原始对象；③原始对象在什么情况下才会对外可见。', '①代理对象在**初始化（initializeBean）完成之后**生成，由 BeanPostProcessor 在初始化后环节织入，然后**替换**容器中的 Bean。②按 Bean 名字从容器取到的、注入到其他 Bean 里的都是**代理对象**，而不是原始对象。③原始对象只是代理内部持有的 **target**：在目标对象内部用 `this` 调用时看到的就是它，代码里想主动拿到它需要通过 `AopContext.currentProxy()`（需开启 exposeProxy）或对代理做解包；**对容器和外部调用者而言，对外可见的始终是代理**。', '["Bean 生命周期阶段","AOP 代理对象生成时机"]', '["代理对象是在哪个阶段之后生成的","在容器里以 Bean 名字取到的、被注入到其他 Bean 里的，是代理对象还是原始对象","原始对象在什么情况下才会对外可见。"]', '["AOP · 与生命周期的关系"]', '结合四阶段说明代理对象与普通对象可见时的先后', '基础', '概念辨析', 4, NULL, 1793784337640),
	(218, 2, 5, 20, 8, 'Spring 解决单例 Bean 循环依赖时采用「先创建半成品、再回填引用」的三级缓存思路，而不是等对象完全造好再注入。请回答：①为什么不直接把完整对象造好再互相注入，而非要提前暴露半成品；②这种提前暴露和 setter/字段注入的时机是什么关系，为什么构造器注入的循环依赖解决不了。', '①因为循环依赖下 A 需要 B、B 需要 A，**两个对象谁都走不到「完整」这一步**，如果坚持造好完整对象再注入就会互相死等。而对象在**实例化之后、属性填充之前**其实已经存在，可以先把这个引用提前暴露出去让别人用，从而打破等待。②提前暴露之所以有效，正是因为它卡在「**实例化之后、属性填充之前**」这个窗口，而 **setter/字段注入恰好发生在实例化之后**，所以 B 可以先把 A 的半成品引用注进去，A 后续再补完属性。**构造器注入则要求在实例化那一刻依赖就已就绪**，此时 A 还没有实例化、根本没有引用可暴露，这个窗口不存在，所以三级缓存解决不了构造器循环依赖。', '["三级缓存解决循环依赖","注入方式与提前暴露时机"]', '["为什么不直接把完整对象造好再互相注入，而非要提前暴露半成品","这种提前暴露和 setter/字段注入的时机是什么关系，为什么构造器注入的循环依赖解决不了。"]', '["循环依赖 · 构造器注入无法解决"]', '为什么不能先造半成品再回填？与 setter 时机对照答', '基础', '概念辨析', 4, NULL, 1793784337655),
	(219, 2, 5, 20, 25, 'Spring AOP 中，同一个类里的方法 a() 调用同类中的方法 b()，而增强（如 @Transactional、@Cacheable 或自定义 @Around）只加在 b() 上。请问：a() 调用 b() 时 b() 上的增强会不会生效？请说明原因。', '**不会生效**。a() 里调用 b() 编译后是 **this.b()**，走的是**目标对象自身**的调用，不经过代理对象，所以事务、缓存、环绕等增强逻辑根本没有被执行。只有当调用从代理对象外部进来时增强才生效。解决：注入自身代理、用 AopContext.currentProxy()，或把 b() 拆到另一个 Bean 中。', '["Spring AOP 代理机制","同类方法内部调用增强失效"]', '["Spring AOP 中，同一个类里的方法 a() 调用同类中的方法 b()，而增强（如 @Transactional、@Cacheable 或自定义 @Around）只加在 b() 上。请问：a() 调用 b() 时 b() 上的增强会不会生效","请说明原因。"]', '["AOP · 失效场景与原理"]', '一个类里两个增强方法互相调用，判断哪些增强会丢', '基础', '概念辨析', 4, NULL, 1793784337674),
	(220, 2, 5, 20, 21, '在 Spring 中，@Lazy 与 prototype 作用域常被拿来对比。请说明：①@Lazy 解决的核心问题是什么，它常加在哪里？②prototype 作用域的核心含义是什么？③两者各自适合什么样的对象（bean）？', '①**@Lazy 把 Bean 的创建推迟到第一次使用时**，用来缩短启动时间、避开暂时用不到的重对象，也常用来打破循环依赖；可以加在 @Component 类、@Bean 方法或注入点（字段、构造参数）上。②**prototype 是每次 getBean 都创建新实例**，容器不缓存，也不管理它的销毁。③@Lazy 适合初始化重、使用频率低、甚至可以不创建的 Bean；prototype 适合有状态、不能被共享的 Bean。', '["@Lazy 延迟创建与打破循环依赖","prototype 作用域每次获取新实例"]', '["@Lazy 解决的核心问题是什么，它常加在哪里？","prototype 作用域的核心含义是什么？","两者各自适合什么样的对象（bean）？"]', '["Bean延迟加载 · @Lazy"]', '@Lazy 与 prototype 的区别，各自适合什么对象', '基础', '概念辨析', 4, NULL, 1793784342250),
	(221, 2, 5, 20, 22, '一个类实现了接口 AService，另一个类没有实现任何接口。分别被 Spring AOP 代理后，从容器里 getBean 拿到的对象实际是什么类型？请分别说明，并说明该类型是怎么决定的。', '实现 AService 的类走 **JDK 动态代理**，getBean 得到的是一个**实现了 AService 接口的代理对象**，只能按接口类型获取，按实现类类型取会失败。未实现接口的类走 **CGLIB**，getBean 得到的是**该类的子类代理对象**，按类类型可以取到。类型由目标类是否实现接口决定；若开启 proxyTargetClass（Spring Boot 默认），则统一用 CGLIB。', '["JDK 动态代理与 CGLIB 代理的选择","代理对象类型与强转"]', '["一个类实现了接口 AService，另一个类没有实现任何接口。分别被 Spring AOP 代理后，从容器里 getBean 拿到的对象实际是什么类型","请分别说明，并说明该类型是怎么决定的。"]', '["动态代理 · JDK与CGLIB"]', '给一个有接口一个无接口的类，说 AOP 后拿到的对象是什么类型', '基础', '概念辨析', 4, NULL, 1793784342255),
	(222, 2, 5, 20, 23, '有两个单例 bean A 和 B，A 里通过字段注入持有 B，B 里通过字段注入持有 A，形成了循环依赖。要求**不改变注入方式**（仍然用字段/setter 注入），把 A 与 B 之间的属性循环拆掉。请说明你的重构思路，并说清这样改之后注入关系发生了什么变化。', '在其中一个**注入点**（如 A 的 b 字段或 B 的 a 字段）上加 **@Lazy**。这样容器注入的是**一个延迟解析的代理对象**，创建 A 时不再需要真实的 B 实例，环就被断开了；直到第一次调用 B 的方法时，才由代理去容器里取真实 B。注入关系从「A 强依赖 B 实例」变成「A 持有 B 的代理、按需解析」。', '["循环依赖的重构拆解","单向依赖与中介组件"]', '["有两个单例 bean A 和 B，A 里通过字段注入持有 B，B 里通过字段注入持有 A，形成了循环依赖。要求**不改变注入方式**（仍然用字段/setter 注入），把 A 与 B 之间的属性循环拆掉。请说明你的重构思路，并说清这样改之后注入关系发生了什么变化。"]', '["循环依赖 · 破坏方式与现状"]', '不改注入方式，怎么重构拆掉 A 与 B 的属性循环', '基础', '概念辨析', 4, NULL, 1793784342260),
	(223, 2, 5, 20, 24, '在 Spring 中，@Component 和 @Bean 都可以把对象交给容器管理。请说明：①两者在注册方式上的区别是什么？②两者在控制能力和使用场景上各自适合什么情况？', '①**@Component 标在类上，由组件扫描发现并注册**；**@Bean 标在 @Configuration 类的方法上，方法返回值被注册为 Bean**。②@Component 适合自己项目里能改源码的类，简单直接；@Bean 控制力更强，适合**第三方类**（无法加注解）、需要按条件装配、需要自定义初始化与销毁、或需要按环境返回不同实现的场景。', '["@Component 与 @Bean 注册方式区别","两种注册方式的使用场景"]', '["两者在注册方式上的区别是什么？","两者在控制能力和使用场景上各自适合什么情况？"]', '["Bean配置 · 组件扫描与注册方式"]', '@Component 与 @Bean 两种注册方式的区别与选择', '基础', '概念辨析', 4, NULL, 1793784342264),
	(224, 2, 5, 20, 2, 'Spring 中有两个 Bean：Bean A 是默认单例作用域，Bean B 标注了 @Scope("prototype")。现在有两个不同的 Bean C 和 D，分别通过依赖注入拿到 A 和 B。请回答：①C 和 D 注入的 Bean A 是不是同一个对象？②C 和 D 注入的 Bean B 是不是同一个对象？并说明各自原因。', '①**是同一个对象**。A 是默认单例作用域，容器中只存在一个实例，C 和 D 注入的都是容器里这**同一个引用**。②**不是同一个对象**。B 是 prototype 作用域，**每次向容器 getBean 都会新建一个实例**并注入，所以 C 和 D 各自拿到独立对象；并且容器只负责创建和注入，**不缓存、也不负责销毁**原型 Bean，销毁要由调用方自己处理。', '["Bean 作用域","单例与多例的实例复用区别"]', '["C 和 D 注入的 Bean A 是不是同一个对象？","C 和 D 注入的 Bean B 是不是同一个对象？并说明各自原因。"]', '["Bean作用域 · singleton与prototype"]', '给两个 Bean，判断注入到别的 Bean 里拿到的是否同一对象', '基础', '概念辨析', 4, NULL, 1793784344970),
	(225, 2, 5, 20, 7, '不借助任何示例，独立写出一个「统计方法耗时」的 Spring AOP 切面骨架。要求写清：① 切面类上需要哪些注解；② 切点表达式怎么圈定目标方法；③ 用哪种通知类型、在方法执行的哪个位置计时并输出耗时。代码骨架即可，不必写完整可运行工程。', '①切面类上要 **@Component**（交给容器管理）和 **@Aspect**（声明为切面），切点用 `@Pointcut("execution(* com.example.service..*.*(..))")` 单独定义。②切点表达式用 **execution**：`* ` 表示任意返回值，`com.example.service..` 表示该包及子包下任意类，`*.*(..)` 表示任意方法、任意参数，从而圈定目标方法。③通知类型用 **@Around**：在 `proceed()` **之前**记录开始时间，`proceed()` 之后记录结束时间并相减输出耗时。骨架示例：`@Aspect @Component class TimeAspect { @Around("execution(* com.example.service..*.*(..))") public Object time(ProceedingJoinPoint pjp) throws Throwable { long s = System.currentTimeMillis(); try { return pjp.proceed(); } finally { System.out.println(pjp.getSignature() + " 耗时 " + (System.currentTimeMillis() - s) + "ms"); } } }`。', '["@Aspect 切面与 @Pointcut 切点表达式","@Around 环绕通知"]', '["切面类上需要哪些注解","切点表达式怎么圈定目标方法","用哪种通知类型、在方法执行的哪个位置计时并输出耗时。代码骨架即可，不必写完整可运行工程。"]', '["AOP · @Aspect/@Pointcut/@JoinPoint注解"]', '不看示例，独立写出一个统计方法耗时的切面骨架', '基础', '概念辨析', 4, NULL, 1793784348243),
	(226, 2, 5, 21, 1, '请用一句执行过程描述 Spring 中 Bean 对象在什么时候被创建、什么时候做初始化准备（如属性填充、初始化回调）。', '容器 refresh 时对**非懒加载单例**先由构造器**实例化**出对象，再做**属性填充**（依赖注入），随后执行**初始化**（Aware 回调 → BeanPostProcessor 前置处理 → @PostConstruct/afterPropertiesSet/init-method → 后置处理，AOP 代理多在后置里生成），之后 Bean 才可被使用。', '["Bean 生命周期主干流程","实例化与初始化的先后关系"]', '["请用一句执行过程描述 Spring 中 Bean 对象在什么时候被创建、什么时候做初始化准备（如属性填充、初始化回调）。"]', '["Bean生命周期 · 实例化与初始化顺序"]', '用一句执行过程描述对象何时被创建、何时做准备', '基础', '概念辨析', 8, NULL, 1793861689452),
	(227, 2, 5, 21, 2, '一个对象内部持有用户会话相关的可变状态，且每次请求都需要独立的一份。请判断它应该用哪种 Spring Bean 作用域，并说明原因。', '应选 **request** 作用域：每个 HTTP 请求创建一个独立实例，请求结束即销毁，天然隔离各请求的可变状态；若要同一会话跨请求保留则用 **session**。**prototype** 是每次 getBean 一个新实例，与请求边界无关，不能保证「每请求一份」。', '["Bean 作用域（singleton / prototype）","有状态对象的作用域选型"]', '["一个对象内部持有用户会话相关的可变状态，且每次请求都需要独立的一份。请判断它应该用哪种 Spring Bean 作用域，并说明原因。"]', '["Spring 作用域 · prototype 适用场景"]', '给有状态对象场景，判断该用哪种作用域及原因', '基础', '概念辨析', 8, NULL, 1793861689469),
	(228, 2, 5, 21, 3, '在 Spring 中，一个 Service 强依赖另一个 Service，缺了它就无法工作；另一个是可有可无的辅助组件，没有也能运行。请分别说明这两类依赖各自适合用哪种注入方式，并说明理由。', '强依赖用**构造器注入**：对象创建时依赖必须就位，保证不可变、非空，缺失则启动即失败；可选依赖用 **setter 注入**并标 `@Autowired(required=false)`（或 @Nullable / ObjectProvider），没有该 Bean 时容器仍能正常启动。', '["依赖注入方式（构造器 / Setter）","必需依赖与可选依赖的选型"]', '["在 Spring 中，一个 Service 强依赖另一个 Service，缺了它就无法工作；另一个是可有可无的辅助组件，没有也能运行。请分别说明这两类依赖各自适合用哪种注入方式，并说明理由。"]', '["Spring 注入方式 · 构造器注入与 setter 注入选型"]', '给必需依赖与可选依赖两例，分别选注入方式', '基础', '概念辨析', 8, NULL, 1793861689469),
	(229, 2, 5, 21, 4, '请列举两个常用的 Spring Aware 接口，并分别说明通过它们能拿到容器中的什么资源。', '常用 Aware 接口例如：

1. **ApplicationContextAware**：回调 `setApplicationContext(ApplicationContext ctx)`，能拿到**当前 IoC 容器本身（ApplicationContext）**，从而可以主动 getBean、发布事件、获取环境信息。
2. **BeanFactoryAware**：回调 `setBeanFactory(BeanFactory bf)`，能拿到**底层的 BeanFactory**，用于以编程方式获取 Bean 或查询 Bean 定义。

另外还有 **BeanNameAware**（拿到当前 Bean 在容器中的名字）、**EnvironmentAware**（拿到 Environment 环境配置）等。它们的共同点是：**让 Bean 在初始化阶段回调，获得容器内部资源**。', '["Aware 接口及回调资源","Bean 生命周期中的 Aware 回调"]', '["请列举两个常用的 Spring Aware 接口，并分别说明通过它们能拿到容器中的什么资源。"]', '["Aware接口 · 常见接口"]', '列举两个常用Aware接口及各自能拿到什么资源', '基础', '概念辨析', 8, NULL, 1793861689485),
	(230, 2, 5, 21, 10, '某电商系统有下单接口 OrderService.createOrder，业务要求：下单时统一记录操作日志，同时 createOrder 需要在一个数据库事务中执行，成功后提交、异常回滚。系统基于 Spring，采用声明式 AOP 实现这两项横切逻辑。请回答：
① 日志切面和事务切面分别应如何与业务代码解耦？说明它们各自的 Advice 类型（如 @Before/@Around 等）以及为什么事务通常用 @Around 而不是 @Before。
② Spring 中这个 OrderService 的代理对象是在什么时机、由谁生成的？请说明 Bean 生命周期的哪个阶段完成代理创建，以及单例 Bean 默认何时完成。
③ 如果 OrderService 有接口，可选 JDK 动态代理或 CGLIB，请说明两者的区别，并给出在本场景下如何选择的依据（至少两点依据）。', '① 日志与事务都抽成切面类，用切点表达式匹配 createOrder，业务类里不出现横切代码，配置类开 @EnableAspectJAutoProxy 即可解耦。日志可用 @Before（或 @Around）做记录；事务必须用 @Around，因为事务要在目标方法**执行前后双向控制**——方法前开启/加入事务，方法后正常则提交、抛异常则回滚，且能决定是否执行目标方法，@Before 只在执行前插一段逻辑，无法感知方法结果与异常。② 代理由 **BeanPostProcessor**（AbstractAutoProxyCreator）在 Bean **初始化阶段**的 postProcessAfterInitialization 中，用后置处理器把原生 Bean 包装成代理返回；单例 Bean 默认在**容器启动预实例化**时就完成代理创建。③ JDK 动态代理基于**接口**生成实现类，通过 InvocationHandler 转发；CGLIB 基于**继承**生成子类字节码，不能代理 final 类/方法。选择依据：一是 OrderService 是否面向接口编程（有接口优先 JDK，Spring Boot 2.x 后默认也是 CGLIB）；二是类是否为 final/方法是否 final、是否调本类方法（JDK 代理更简单无需额外依赖）。', '["AOP 通知类型与切面解耦（@Around 与事务控制）","Bean 生命周期中代理对象的创建时机（BeanPostProcessor）","JDK 动态代理与 CGLIB 的区别与选型"]', '["日志切面和事务切面分别应如何与业务代码解耦？说明它们各自的 Advice 类型（如 @Before/@Around 等）以及为什么事务通常用 @Around 而不是 @Before。","Spring 中这个 OrderService 的代理对象是在什么时机、由谁生成的？请说明 Bean 生命周期的哪个阶段完成代理创建，以及单例 Bean 默认何时完成。","如果 OrderService 有接口，可选 JDK 动态代理或 CGLIB，请说明两者的区别，并给出在本场景下如何选择的依据（至少两点依据）。"]', '["AOP · 核心概念与切点","AOP · 与生命周期的关系","动态代理 · JDK与CGLIB"]', '下单业务需加日志与事务，串起切面、代理生成时机与代理方式选择', '大题', '场景应用', 23, NULL, 1793861690952),
	(231, 2, 5, 21, 5, 'Spring AOP 常被说成是「对容器内 Bean 统一做增强」的机制。请回答：①它增强的目标是什么？②这种统一增强靠的是什么机制实现的（与手写代理相比）？③典型用在哪些横切场景？', '①增强目标是切点表达式命中的**业务方法**（连接点）。②统一增强靠容器在 Bean 初始化后由 **BeanPostProcessor 自动生成代理**（有接口用 JDK 动态代理，无接口用 CGLIB 子类代理）并替换原 Bean，业务代码零侵入；手写代理则需自己创建代理对象、自己控制调用方，无法对容器内 Bean 统一生效。③典型横切：日志、事务、权限、耗时监控。', '["Spring AOP 动态代理","AOP 横切增强的适用场景"]', '["它增强的目标是什么？","这种统一增强靠的是什么机制实现的（与手写代理相比）？","典型用在哪些横切场景？"]', '["Bean后处理器 · BeanPostProcessor"]', '说明它对容器内Bean统一做增强的整体能力定位', '基础', '概念辨析', 8, NULL, 1793861691295),
	(232, 2, 5, 21, 6, '容器中有一个由 Spring 管理的 Bean。请说明：在 Bean 销毁之前，容器会依次做哪几件核心事情？', '单例 Bean 销毁前依次执行：**@PreDestroy**（由 BeanPostProcessor 的 postProcessBeforeDestruction 触发）→ 实现 **DisposableBean 的 destroy()** → 配置的**自定义 destroy-method**；容器 close 时统一处理，prototype 不被容器销毁。', '["Bean 生命周期销毁阶段","销毁回调方法"]', '["容器中有一个由 Spring 管理的 Bean。请说明：在 Bean 销毁之前，容器会依次做哪几件核心事情？"]', '["Bean生命周期 · 主干流程"]', '给一个Bean，说出销毁前容器做哪几件核心事', '基础', '概念辨析', 8, NULL, 1793861691298),
	(233, 2, 5, 21, 7, '同一个依赖，分别用字段注入和 setter 注入。请说明：①两种方式各自在 Bean 生命周期的什么时间点完成注入？②由此带来的一个实际差异是什么？', '两者都在 Bean **实例化之后、属性填充（populateBean）阶段**完成，都早于初始化回调（@PostConstruct、afterPropertiesSet）。区别在执行方式：**字段注入用反射直接给字段赋值**，**setter 注入是调用 setter 方法赋值**。由此带来的实际差异是：setter 注入可以在 setter 方法里加**校验、默认值、防御性包装**等逻辑，字段注入绕过方法，没有这个插入点；此外字段注入会隐藏依赖、不利于脱离容器做单元测试，也无法注入 static/final 字段。', '["依赖注入方式","Bean 生命周期属性填充阶段"]', '["两种方式各自在 Bean 生命周期的什么时间点完成注入？","由此带来的一个实际差异是什么？"]', '["@Autowired · 注入点与循环依赖"]', '同一依赖分别用字段/setter注入，说明时间点差异', '基础', '概念辨析', 7, NULL, 1793861691302),
	(234, 2, 5, 21, 8, '一个接口有两个实现类都被注册进容器，另有一个配置类里的 Bean 只想在某个条件成立时才注册。请说明：①按类型注入出现多个候选 Bean 时，有哪几种方式指定要用哪一个？②想让某个 Bean 按条件决定是否注册，Spring 提供了什么机制？条件不满足时该 Bean 会怎样？', '①多候选时可用 **@Primary** 设默认候选、**@Qualifier("beanName")** 精确指定，或让**字段名/参数名**与 bean 名称一致，也可用 **@Resource** 按名称注入。②条件装配用 **@Conditional**（及 @ConditionalOnProperty 等派生注解）；条件不满足时该 Bean 不注册、不创建，若别处以必需方式注入它，启动会因找不到 Bean 失败。', '["同类型多 Bean 的指定方式","@Conditional 条件注册"]', '["按类型注入出现多个候选 Bean 时，有哪几种方式指定要用哪一个？","想让某个 Bean 按条件决定是否注册，Spring 提供了什么机制？条件不满足时该 Bean 会怎样？"]', '["Spring 注入注解 · @Qualifier 与 @Conditional "]', '同类型多Bean时如何指定，及按条件决定是否注册', '中档', '原理追问', 11, NULL, 1793861691306),
	(235, 2, 5, 21, 9, 'Spring AOP 中，切点表达式 `execution(* com.example.service.UserService.*(..))` 要匹配什么？请说明表达式里 `*`、`..` 以及中间 `UserService.` 这三部分各自代表什么含义。', '匹配 **com.example.service.UserService 这个类中所有方法**：返回值任意、方法名任意、参数任意。第一个 `*` 是**返回值类型任意**，`UserService.` 是**类型限定**（只限该类，不含子类，含子类须写 `UserService+`），第二个 `*` 是**方法名任意**，`..` 表示**任意个数、任意类型的参数**。', '["execution 切点表达式语法","通配符 * 与 .. 的含义"]', '["Spring AOP 中，切点表达式 `execution(* com.example.service.UserService.*(..))` 要匹配什么","请说明表达式里 `*`、`..` 以及中间 `UserService.` 这三部分各自代表什么含义。"]', '["AOP 切入点表达式 · execution 通配匹配"]', '给含*与..的表达式，判断能匹配哪些方法', '中档', '原理追问', 11, NULL, 1793861696673),
	(236, 2, 6, 22, 1, 'Spring Boot 中如何通过 profile 文件切换开发、测试、生产环境的配置？请说明配置文件命名约定，以及有哪几种激活 profile 的方式。', '**命名约定**：用 `application-{profile}.yml` 的格式区分环境，例如 `application-dev.yml`、`application-test.yml`、`application-prod.yml`，公共配置放在 `application.yml`。

**激活方式**：
1. **配置文件激活**：在主配置文件里写 `spring.profiles.active=dev`；
2. **启动参数激活**：`java -jar app.jar --spring.profiles.active=prod`，或 `-Dspring.profiles.active=prod`；
3. **环境变量激活**：设置 `SPRING_PROFILES_ACTIVE=test`。

激活后，**profile 专属配置会覆盖** `application.yml` 中的同名配置，未指定的配置仍从主配置读取。', '["Spring Boot Profile 配置文件命名","profile 激活方式与配置覆盖"]', '["Spring Boot 中如何通过 profile 文件切换开发、测试、生产环境的配置","请说明配置文件命名约定，以及有哪几种激活 profile 的方式。"]', '["配置加载 · 多环境与优先级"]', '如何用 profile 文件切换开发/测试环境', '基础', '概念辨析', 5, NULL, 1793944287880),
	(237, 2, 6, 22, 2, 'Spring Boot 自动配置中常用的条件注解有哪些？请写出三个，并各举一个典型使用场景。', '常用条件注解及场景：
1. **@ConditionalOnClass**：classpath 中存在某个类时才生效。场景：引入 `spring-boot-starter-data-redis` 后才装配 Redis 相关的自动配置。
2. **@ConditionalOnMissingBean**：容器中没有指定类型的 Bean 时才生效。场景：框架给 `RestTemplate` 提供默认 Bean，用户自己定义了就不再注册，实现**可覆盖的默认配置**。
3. **@ConditionalOnProperty**：配置项满足条件时才生效。场景：`@ConditionalOnProperty(name = "xxx.enabled", havingValue = "true")`，用开关控制某功能是否装配。

（也可答 **@ConditionalOnWebApplication**：Web 应用类型匹配时才生效。）', '["Spring Boot 条件注解","自动配置按需装配"]', '["Spring Boot 自动配置中常用的条件注解有哪些","请写出三个，并各举一个典型使用场景。"]', '["自动配置 · 条件注解"]', '给三个常用条件注解各举一个使用场景', '基础', '概念辨析', 5, NULL, 1793944287882),
	(238, 2, 6, 22, 3, 'Spring Boot Starter 通常由哪两部分组成？Starter 的命名有什么约定？官方 Starter 和第三方 Starter 在命名上有何区别？', '**组成**：Starter 一般由两部分构成：
1. **依赖聚合模块**：一个只负责引入相关 jar 的 pom，本身几乎没有代码；
2. **自动配置模块**：提供默认配置类，通过 `META-INF/spring.factories`（或 Spring Boot 2.7+ 的 `AutoConfiguration.imports`）注册自动配置。

**命名约定**：官方 Starter 命名为 `spring-boot-starter-xxx`，如 `spring-boot-starter-web`；**第三方** Starter 建议命名为 `xxx-spring-boot-starter`，把业务名放前面，避免与官方命名冲突。', '["Starter 的构成","Starter 命名约定"]', '["Spring Boot Starter 通常由哪两部分组成","Starter 的命名有什么约定","官方 Starter 和第三方 Starter 在命名上有何区别"]', '["Starter · 是什么与约定"]', 'Starter 由哪两部分组成，命名怎么约定', '基础', '概念辨析', 5, NULL, 1793944287884),
	(239, 2, 6, 22, 4, '@SpringBootApplication 由哪几个注解组成？其中自动配置功能是由哪个注解开启的？该注解又通过什么机制把配置类加载进来？', '**@SpringBootApplication** 是一个组合注解，主要由三个注解组成：
1. **@SpringBootConfiguration**：本质是 `@Configuration`，标记主配置类；
2. **@EnableAutoConfiguration**：**开启自动配置**，自动配置就靠它生效；
3. **@ComponentScan**：扫描当前包及子包下的组件。

**加载机制**：`@EnableAutoConfiguration` 通过 `@Import(AutoConfigurationImportSelector.class)` 导入选择器，由它读取 classpath 下各 jar 的 `META-INF/spring.factories`（Spring Boot 2.7+ 为 `META-INF/spring/org.springframework.boot.autoconfigure.AutoConfiguration.imports`），拿到候选自动配置类列表，再结合条件注解按需装配。', '["@SpringBootApplication 的组成","@EnableAutoConfiguration 自动配置加载机制"]', '["@SpringBootApplication 由哪几个注解组成","其中自动配置功能是由哪个注解开启的","该注解又通过什么机制把配置类加载进来"]', '["自动配置 · 基本原理"]', '@SpringBootApplication 拆开看，自动配置靠哪个注解生效', '基础', '概念辨析', 5, NULL, 1793944287885),
	(240, 2, 6, 22, 17, '一个 HTTP 请求进入 Spring Boot 应用后，最终是怎么到达 Controller 方法的？请说明请求先经过谁分发、再由谁负责匹配到具体的 Controller 方法。', '请求先交给 **DispatcherServlet**（前端控制器），它是统一入口。DispatcherServlet 拿到请求后，交给 **HandlerMapping** 根据 URL、方法等匹配出对应的 **Handler（即 Controller 方法）**，再通过 HandlerAdapter 调用该方法。所以关键两点：**DispatcherServlet 负责分发**，**HandlerMapping 负责找到具体 Controller 方法**。', '["DispatcherServlet 前端控制器","HandlerMapping 请求映射"]', '["一个 HTTP 请求进入 Spring Boot 应用后，最终是怎么到达 Controller 方法的","请说明请求先经过谁分发、再由谁负责匹配到具体的 Controller 方法。"]', '["请求处理 · 核心流程"]', '一个请求从进入到 Controller 经过谁分发', '基础', '概念辨析', 5, NULL, 1793944288015),
	(241, 2, 6, 22, 18, 'Filter 和 Interceptor 是两种常见的请求拦截组件。请分别各举两个典型用途，并说明它们各自处在请求处理链的哪一层。', '**Filter（过滤器）**：属于 **Servlet 容器层**，在 DispatcherServlet 之前生效，能拿到原始请求/响应。典型用途：**编码设置**、**登录/权限粗过滤**、**跨域处理**、**请求日志或 XSS 过滤**（任举两个即可）。**Interceptor（拦截器）**：属于 **Spring MVC 层**，在 DispatcherServlet 之后、Controller 之前生效，能拿到 Handler 信息。典型用途：**登录态校验**、**权限注解校验**、**统一日志/耗时统计**（任举两个即可）。一句话：Filter 在容器层、更靠外；Interceptor 在 MVC 层、更贴近 Controller。', '["Filter 与 Interceptor 的层次区别","两者的典型使用场景"]', '["Filter 和 Interceptor 是两种常见的请求拦截组件。请分别各举两个典型用途，并说明它们各自处在请求处理链的哪一层。"]', '["过滤器与拦截器 · 典型应用"]', '各举两个典型用途并说明放在哪层', '基础', '概念辨析', 5, NULL, 1793944288018),
	(242, 2, 6, 22, 19, '在 Spring Boot 里，想用配置类统一给全局接口设置跨域（CORS），应该怎么写？请说明用到的核心方法，并指出该类上需要加什么注解。', '写一个**配置类**，实现 **WebMvcConfigurer** 接口，重写 **addCorsMappings(CorsRegistry registry)** 方法，在方法里用 **registry.addMapping("/**")** 指定对所有路径生效，再链式调用 **allowedOrigins / allowedMethods / allowedHeaders / allowCredentials / maxAge** 等配置允许的来源、方法、头、是否带凭证和预检缓存时间。配置类上要加 **@Configuration** 注解，让它被 Spring 扫描注册。', '["WebMvcConfigurer 统一跨域配置","addCorsMappings 与 CORS 参数"]', '["在 Spring Boot 里，想用配置类统一给全局接口设置跨域（CORS），应该怎么写","请说明用到的核心方法，并指出该类上需要加什么注解。"]', '["统一响应与跨域 · 常用配置"]', '用配置类统一设置跨域，怎么写', '基础', '概念辨析', 5, NULL, 1793944288020),
	(243, 2, 6, 22, 20, 'Spring Boot 的自动配置类并不是写在业务代码里，而是从依赖 jar 包中的文件被读到的。请说明：这个文件叫什么、在 jar 里的什么位置，以及文件里记录的是什么内容。', '文件是 **META-INF/spring.factories**（新版 Spring Boot 2.7 起也支持 **META-INF/spring/org.springframework.boot.autoconfigure.AutoConfiguration.imports**）。位置在**依赖 jar 包内的 META-INF 目录下**。文件里以**键值对**形式记录了 **自动配置类的全限定类名列表**（键是自动配置相关的接口，值是实现类/自动配置类），Spring Boot 启动时读取它并加载这些自动配置类。', '["spring.factories 自动配置入口","自动配置类的加载来源"]', '["Spring Boot 的自动配置类并不是写在业务代码里，而是从依赖 jar 包中的文件被读到的。请说明：这个文件叫什么、在 jar 里的什么位置，以及文件里记录的是什么内容。"]', '["自动配置 · 加载与顺序"]', '自动配置类从依赖 jar 的哪个文件被读到', '基础', '概念辨析', 5, NULL, 1793944288021),
	(244, 2, 6, 22, 13, 'Spring MVC 中，过滤器（Filter）和拦截器（Interceptor）的标注或注册位置分别是什么？各自更适合用在什么场景？', '**过滤器**基于 Servlet 规范，通过 **@WebFilter** 或在配置类里用 **FilterRegistrationBean** 注册，作用于 **Servlet 容器层面**，能拿到原始的 request/response，适合做**编码设置、跨域、请求日志、敏感字符过滤**等与框架无关的通用处理。**拦截器**是 Spring MVC 的组件，通过实现 **HandlerInterceptor** 并用 **WebMvcConfigurer 的 addInterceptors** 注册，属于 **Spring MVC 层面**，能拿到 **HandlerMethod**，适合做**登录鉴权、权限校验、Controller 方法级的日志或参数预处理**。一句话：**过滤器管容器级粗粒度，拦截器管 Spring MVC 级、能感知具体 Controller 方法**。', '["过滤器与拦截器的注册方式","过滤器与拦截器的适用场景"]', '["Spring MVC 中，过滤器（Filter）和拦截器（Interceptor）的标注或注册位置分别是什么","各自更适合用在什么场景"]', '["Bean 注册 · @Component 与 @Bean"]', '两者标注位置与适用场景有何不同', '基础', '概念辨析', 5, NULL, 1793944288443),
	(245, 2, 6, 22, 14, '举一个你熟悉的 Spring Boot 官方 Starter，说明它帮你省去了哪些手动配置工作。', '以 **spring-boot-starter-web** 为例。它首先通过依赖传递**一次性引入** Spring MVC、内嵌 Tomcat、Jackson 等一整套依赖，不用自己逐个选版本；其次版本由 **parent 的 dependencyManagement 统一管理**，避免版本冲突；再次它触发 **WebMvcAutoConfiguration** 等自动配置类，在类路径条件满足时**自动装配** DispatcherServlet、消息转换器、静态资源映射等 Bean。省掉的就是**依赖选型与版本管理**加**大量 XML 或 Java 手动配置**这两块工作。', '["官方 Starter 的作用","自动配置省去的手动配置"]', '["举一个你熟悉的 Spring Boot 官方 Starter，说明它帮你省去了哪些手动配置工作。"]', '["Starter · 开箱即用的设计"]', '举一个官方 Starter 说明它省了什么', '基础', '概念辨析', 5, NULL, 1793944288443),
	(246, 2, 6, 22, 15, '在 Spring 项目中，哪些横切逻辑适合用 AOP 抽取出来？请至少举出三类，并说明它们共同的特点。', '适合抽取的典型横切逻辑有：**日志记录**、**事务管理**（@Transactional 本身就是 AOP 实现）、**权限校验**、**接口耗时监控**、**统一异常处理或结果包装**、**缓存**。它们的共同特点是：**与业务逻辑无关、在多个方法上重复出现、分散在各处会污染业务代码**，且大多满足**方法执行前后或异常时**插入增强的条件，所以适合用切面统一织入，让业务代码只关注自身职责。', '["AOP 适用的横切场景","横切关注点的特征"]', '["在 Spring 项目中，哪些横切逻辑适合用 AOP 抽取出来","请至少举出三类，并说明它们共同的特点。"]', '["AOP · 基本概念与场景"]', '哪些横切逻辑适合用 AOP 抽出来', '基础', '概念辨析', 5, NULL, 1793944288459),
	(247, 2, 6, 22, 16, 'Spring Boot 中如果想排除某个自动配置类，有哪几种写法？分别写在哪里？', '常见三种写法：一是在启动类或配置类上使用 **@SpringBootApplication(exclude = XxxAutoConfiguration.class)** 或 **@EnableAutoConfiguration(exclude = ...)**，写在**注解属性**里；二是在 **application.yml/properties** 中配置 **spring.autoconfigure.exclude**，写**配置文件**里；三是较老版本可用 **@SpringBootApplication 的 excludeName** 按类全名排除。注意 exclude 的类必须是**自动配置类**，且被排除后相关功能需要**自己手动配置**。', '["自动配置类的排除方式","exclude 的书写位置"]', '["Spring Boot 中如果想排除某个自动配置类，有哪几种写法","分别写在哪里"]', '["自动配置 · 排除与调试"]', '如何排除某个自动配置类，写在哪里', '基础', '概念辨析', 5, NULL, 1793944288459),
	(248, 2, 6, 22, 5, '在 Spring 里，@Autowired 和 @Resource 在“注入来源”和“匹配方式（按名还是按类型）”上有什么不同？请分别说明。', '**@Autowired 是 Spring 提供的注解，@Resource 是 JSR-250（JDK/Jakarta 规范）定义的注解**。

匹配方式上：**@Autowired 默认按类型注入**，类型存在多个候选 bean 时，再结合字段名或 @Qualifier 缩小到具体 bean；可配合 **@Primary** 指定默认候选。**@Resource 默认按名称注入**，名称取注解的 name 属性，没写 name 时取字段名；按名找不到时才回退按类型匹配。

所以两者都不是“纯按名或纯按类型”：Autowired 是**先类型后名称/Qualifier**，Resource 是**先名称后类型**。', '["@Autowired 与 @Resource 的区别","依赖注入的按类型与按名称匹配"]', '["在 Spring 里，@Autowired 和 @Resource 在“注入来源”和“匹配方式（按名还是按类型）”上有什么不同","请分别说明。"]', '["依赖注入 · @Autowired 与 @Resource"]', '两者注入来源有何不同，按名还是按类型', '基础', '概念辨析', 5, NULL, 1793944289644),
	(249, 2, 6, 22, 6, 'Filter 属于哪个规范？请写一个最简单的 Filter 实现（说明它能拦截什么），并说明在 Spring Boot 中如何把它注册到容器里生效。', '**Filter 属于 Servlet 规范**（javax.servlet / jakarta.servlet），不是 Spring 自己的组件，由 Servlet 容器（如 Tomcat）调用，因此能拦截所有进入该应用的请求，包括静态资源和不经过 DispatcherServlet 的请求。

实现：写一个类实现 **javax.servlet.Filter**（新版本为 jakarta.servlet.Filter），在 **doFilter** 方法中写前置/后置逻辑，最后必须调用 **chain.doFilter(request, response)** 放行，否则请求会被截断。

注册到 Spring Boot 容器有两种常见方式：用 **@WebFilter + @ServletComponentScan**，或者用 **FilterRegistrationBean** 注册为 Bean；简单场景也可直接给 Filter 加 **@Component** 交给容器管理。注册时可用 FilterRegistrationBean 的 **urlPatterns、order** 控制拦截路径与执行顺序。', '["Filter 属于 Servlet 规范","Filter 的实现与在 Spring Boot 中的注册方式"]', '["Filter 属于哪个规范","请写一个最简单的 Filter 实现（说明它能拦截什么），并说明在 Spring Boot 中如何把它注册到容器里生效。"]', '["过滤器 · 基本概念与用法"]', 'Filter 属哪个规范，写一个并说明如何注册', '基础', '概念辨析', 5, NULL, 1793944289644),
	(250, 2, 6, 22, 7, '@RequestParam、@PathVariable、@RequestBody 三个注解分别从 HTTP 请求的哪个位置取值？请逐一说明，并说明它们各自绑定到的数据类型大致是什么。', '**@RequestParam**：从请求的**查询参数或表单参数**中取值（如 URL 的 ?name=xx，或 application/x-www-form-urlencoded 表单体），绑定到方法参数的简单类型（String、基本类型等）。

**@PathVariable**：从 **URL 路径模板中的占位符**取值，即 @RequestMapping 里 {id} 这样的路径变量，绑定到字符串或简单类型。

**@RequestBody**：把**整个请求体**（通常是 JSON 数据，Content-Type 为 application/json 时）通过 **HttpMessageConverter** 反序列化成方法参数对应的对象。', '["@RequestParam、@PathVariable、@RequestBody 的取值来源","Spring MVC 参数绑定"]', '["@RequestParam、@PathVariable、@RequestBody 三个注解分别从 HTTP 请求的哪个位置取值","请逐一说明，并说明它们各自绑定到的数据类型大致是什么。"]', '["参数绑定 · 常用注解"]', '三个注解分别从请求哪里取值', '基础', '概念辨析', 5, NULL, 1793944289661),
	(251, 2, 6, 22, 8, '在 Spring Boot 中把一组配置项（比如 app.mail.host、app.mail.port）绑定到一个 Java 对象上，有哪些可用方式？请说明用 @ConfigurationProperties 绑定时的两个注意点：属性名如何映射、以及如何让这个绑定类生效。', '常用方式：**@ConfigurationProperties** 前缀绑定，或用 **@Value** 逐个注入（配置项多时不推荐）；@ConfigurationProperties 更适合**成组、结构化的配置**。

两个注意点：

**属性名映射**：配置项采用 **kebab-case**（如 app.mail.host），绑定类的字段用驼峰命名（host），Spring Boot **自动做松散绑定**（relaxed binding），下划线、驼峰写法也能识别，无需手写映射。

**如何生效**：绑定类需要被容器管理，可用 **@Component** 直接注册，或在配置类上用 **@EnableConfigurationProperties(Xxx.class)** 声明；另外字段**需要提供 getter/setter**（或用构造器绑定），否则绑定不上。

扩展：还可用 @ConfigurationPropertiesScan 扫描绑定类、用 @Validated 对绑定值做校验。', '["@ConfigurationProperties 配置绑定","配置绑定类的生效方式与属性名映射"]', '["在 Spring Boot 中把一组配置项（比如 app.mail.host、app.mail.port）绑定到一个 Java 对象上，有哪些可用方式","请说明用 @ConfigurationProperties 绑定时的两个注意点：属性名如何映射、以及如何让这个绑定类生效。"]', '["配置绑定 · @ConfigurationProperties"]', '把一组配置绑到对象上，需注意什么', '基础', '概念辨析', 5, NULL, 1793944289662),
	(252, 2, 6, 22, 9, '过滤器（Filter）与拦截器（Interceptor）分别属于哪个技术体系？在一个 HTTP 请求的处理链路上，两者的执行先后顺序是怎样的？实际项目中做登录校验、统一编码这类功能时，你怎么在两者之间做选择？', '**所属体系**：**Filter 属于 Servlet 规范**，由 Servlet 容器（Tomcat）管理和调用，与 Spring 无关；**Interceptor 属于 Spring MVC 体系**，由 Spring 容器管理，由 DispatcherServlet 在处理器映射之后调用。

**执行先后**：请求进入时 **Filter 先执行**（在 DispatcherServlet 之前），之后才进入 Spring MVC 调用 Interceptor 的 preHandle，再进入 Controller；响应返回时顺序相反，**Interceptor 的 postHandle/afterCompletion 先走完，Filter 最后收尾**。

**怎么选**：需要**在进入 Spring MVC 之前**拦截（如统一编码、跨域、请求体包装、安全过滤）用 **Filter**；需要**依赖 Spring Bean、能拿到 Handler 方法信息**（如登录鉴权、权限注解、日志记录）用 **Interceptor**。', '["Filter 与 Interceptor 的所属体系","Filter 与 Interceptor 的执行顺序与选型"]', '["过滤器（Filter）与拦截器（Interceptor）分别属于哪个技术体系","在一个 HTTP 请求的处理链路上，两者的执行先后顺序是怎样的","实际项目中做登录校验、统一编码这类功能时，你怎么在两者之间做选择"]', '["过滤器与拦截器 · 区别与选型"]', '两者所属体系与执行先后如何，怎么选', '基础', '概念辨析', 5, NULL, 1793944289845),
	(253, 2, 6, 22, 10, 'Spring Boot 中实现全局异常处理，需要哪两个注解配合完成？这两个注解各自的作用是什么？', '由 **@RestControllerAdvice**（或 @ControllerAdvice）和 **@ExceptionHandler** 两个注解配合完成。

**@RestControllerAdvice** 标注在类上，声明这是一个**全局异常处理类**，作用范围覆盖所有 Controller；它相当于 @ControllerAdvice + @ResponseBody，返回值会直接序列化为 JSON。

**@ExceptionHandler** 标注在方法上，指定该方法**处理哪一类异常**（按异常类型匹配，越具体的异常优先级越高），方法参数接收异常对象，返回值即响应体。

两者配合：类上声明全局拦截，方法上声明具体处理哪种异常。', '["@RestControllerAdvice 全局异常处理","@ExceptionHandler 异常类型匹配"]', '["Spring Boot 中实现全局异常处理，需要哪两个注解配合完成","这两个注解各自的作用是什么"]', '["统一异常处理 · @ControllerAdvice"]', '全局异常处理类由哪两个注解配合完成', '基础', '概念辨析', 5, NULL, 1793944289845),
	(254, 2, 6, 22, 11, 'Spring MVC 的 HandlerInterceptor 接口有三个方法：preHandle、postHandle、afterCompletion。请分别说明这三个方法在请求处理链路的什么时机执行，以及各自返回值的含义。', '**preHandle**：在 **Controller 方法执行之前**执行。返回 **true 表示放行**，继续执行后续拦截器和 Controller；返回 **false 表示中断**，后续拦截器和 Controller 都不执行，但已放行的拦截器会触发 afterCompletion。

**postHandle**：在 **Controller 方法执行完毕、但视图渲染之前**执行，此时可以往 ModelAndView 里补充数据。注意 Controller 抛异常时它**不执行**。

**afterCompletion**：在整个请求**完成之后**执行（视图渲染完毕），无论是否发生异常都会调用，常用于**资源清理、记录耗时**。多个拦截器时，它的执行顺序与 preHandle **相反**。', '["HandlerInterceptor 三个方法的执行时机","preHandle 返回值含义"]', '["Spring MVC 的 HandlerInterceptor 接口有三个方法：preHandle、postHandle、afterCompletion。请分别说明这三个方法在请求处理链路的什么时机执行，以及各自返回值的含义。"]', '["拦截器 · 基本概念与用法"]', 'HandlerInterceptor 三个方法各在何时执行', '基础', '概念辨析', 5, NULL, 1793944289845),
	(255, 2, 6, 22, 12, '请简述从零新建一个自定义 Spring Boot Starter，到它能被其他项目直接引入使用，需要经过哪些步骤？请说明工程结构（需要几个模块、各自职责），以及自动配置类如何被 Spring Boot 发现。', '结论：自定义 Starter 通常拆成 **两个模块**：`xxx-spring-boot-starter`（空壳，只负责引入依赖）和 `xxx-spring-boot-autoconfigure`（放自动配置类、配置属性类、条件注解、`spring.factories` 或 `AutoConfiguration.imports`）。步骤：① 新建父工程，建上述两个模块；② 在 autoconfigure 模块里写 **自动配置类**，配合 `@ConfigurationProperties` 绑定配置、`@ConditionalOnClass/@ConditionalOnMissingBean` 等条件注解控制生效；③ 在 `META-INF/spring/org.springframework.boot.autoconfigure.AutoConfiguration.imports`（Spring Boot 2.7+，老版本用 `META-INF/spring.factories` 的 `EnableAutoConfiguration` 键）中**登记自动配置类全限定名**；④ 在 starter 模块的 pom 里依赖 autoconfigure 模块和所需第三方依赖；⑤ 安装到本地或私服（mvn install/deploy），业务项目引入 starter 依赖即可开箱使用。', '["自定义 Starter 的模块结构与编写步骤","自动配置类的注册方式（AutoConfiguration.imports / spring.factories）"]', '["请简述从零新建一个自定义 Spring Boot Starter，到它能被其他项目直接引入使用，需要经过哪些步骤","请说明工程结构（需要几个模块、各自职责），以及自动配置类如何被 Spring Boot 发现。"]', '["Starter · 自定义步骤"]', '从建工程到能被引入，说清自定义 Starter 步骤', '基础', '概念辨析', 5, NULL, 1793944293250);

-- 导出  表 public.review_card 结构
CREATE TABLE IF NOT EXISTS "review_card" (
	"id" BIGINT NOT NULL,
	"user_id" BIGINT NOT NULL,
	"review_doc_id" BIGINT NOT NULL,
	"point_name" VARCHAR(80) NOT NULL,
	"category" VARCHAR(40) NULL DEFAULT NULL,
	"priority" VARCHAR(16) NULL DEFAULT NULL,
	"content_json" TEXT NULL DEFAULT NULL,
	"sequence" INTEGER NOT NULL,
	"created_at" BIGINT NOT NULL,
	"updated_at" BIGINT NOT NULL,
	PRIMARY KEY ("id"),
	UNIQUE ("review_doc_id", "point_name")
)
CREATE INDEX "idx_review_card_doc" ON "" ("review_doc_id", "sequence");;

-- 正在导出表  public.review_card 的数据：104 rows
DELETE FROM "review_card";
INSERT INTO "review_card" ("id", "user_id", "review_doc_id", "point_name", "category", "priority", "content_json", "sequence", "created_at", "updated_at") VALUES
	(1, 2, 1, 'volatile · 可见性与原子性边界', 'volatile 与可见性', 'high', '{"name":"volatile · 可见性与原子性边界","category":"volatile 与可见性","priority":"high","summary":"volatile 保证可见性和有序性，但不保证复合操作的原子性。","interview":"volatile 能替代 synchronized 吗？它在原子性上有什么限制？","principle":"volatile 写会把工作内存刷回主存，读会从主存拉取，实现可见性；但 i++ 这类读-改-写是多步操作，两条线程可能同时读到旧值再各自加一，丢失更新，因此不原子。synchronized 通过锁互斥让临界区整体串行，可见性和原子性都覆盖。","params":["可见性：写立即刷回主存","原子性：只保证单次读/写的原子","有序性：禁止该变量前后指令重排"],"pitfalls":["i++、count += 1 等复合操作用 volatile 必丢更新","long/double 单次读写在 Java 规范中本就原子，volatile 额外解决的是可见性与对齐问题","以为 volatile 能当轻量锁用，性能未必优于 AtomicLong"],"selfCheck":{"q":"两个线程对 volatile int count 各执行 10000 次 count++，最终值一定等于 20000 吗？","a":"不一定。count++ 是读-改-写三步，volatile 不保证复合操作原子性，两个线程可能同时读到旧值后各自写回，导致更新丢失，最终小于 20000。"}}', 0, 1793250399476, 1793253102878),
	(2, 2, 1, 'volatile · 指令重排序与 happens-befo', 'volatile 与可见性', 'high', '{"name":"volatile · 指令重排序与 happens-befo","category":"volatile 与可见性","priority":"high","summary":"volatile 写与后续读之间建立 happens-before，禁止重排序导致的脏读。","interview":"双检锁单例为什么 instance 必须加 volatile？","principle":"new 对象分三步：分配内存、初始化字段、把引用指向内存。JVM 可能重排成 1-3-2，另一线程在双检锁外看到非 null 引用但字段还没初始化，读到半成品对象。volatile 写禁止前面的初始化指令重排到赋值之后，且 volatile 写 happens-before 后续同变量的读，保证可见。","params":["happens-before：volatile 写先于同变量读","重排序：编译器/CPU/JIT 均可能重排","JDK5+ 内存模型才明确 volatile 语义"],"pitfalls":["双重检查少了 volatile，检查非 null 仍可能拿到半初始化对象","只有 instance 引用赋值那一刻被保护，构造函数内的共享状态仍需自行同步","以为 synchronized 块能挡住块外的 DCL 读取，其实块外的读根本没拿锁"],"selfCheck":{"q":"双检锁中，把 instance 声明成 static final 不加 volatile，会有什么问题？","a":"new 的指令可能重排为先赋引用再初始化字段，另一线程第一次检查发现非 null 就直接返回，拿到字段未初始化的半成品对象。final 也挡不住这种跨线程可见性问题。"}}', 1, 1793250399476, 1793253102878),
	(3, 2, 1, 'volatile · 典型使用场景', 'volatile 与可见性', 'high', '{"name":"volatile · 典型使用场景","category":"volatile 与可见性","priority":"high","summary":"volatile 适合状态标志、一次性发布、DCL 引用，不适合计数器。","interview":"volatile 的正确使用场景有哪些？为什么用在计数器上是错的？","principle":"状态标志（如 shutdown flag）只写一次布尔值，单次写天然原子，volatile 提供可见性即可；一次性发布（配置/不可变对象）配合 final 也可；DCL 引用靠 volatile 禁重排。计数器是复合操作，需要原子类（CAS）或锁；多线程下计数用 AtomicLong、LongAdder 或 synchronized。","params":["状态标志：volatile boolean running = true","发布安全：volatile + 不可变对象","计数器替换：AtomicLong / LongAdder"],"pitfalls":["计数器用 volatile 是最常见误用，结果会偏小","LongAdder 高并发计数优于 AtomicLong，但读取要 sum() 且非强一致","volatile 集合引用只保护引用本身，集合内容的并发修改仍需同步"],"selfCheck":{"q":"一个只读标志位 volatile boolean stop，被多线程读、单线程写，需要再加锁吗？","a":"不需要。单线程写、多线程读的布尔标志没有复合操作，volatile 已保证写立即可见、禁止重排，加锁反而多余。"}}', 2, 1793250399476, 1793253102878),
	(4, 2, 1, 'CAS · 原理与三大问题', 'CAS 与原子类', 'high', '{"name":"CAS · 原理与三大问题","category":"CAS 与原子类","priority":"high","summary":"CAS 是无锁原子操作，靠比较并交换保证一致性，但有 ABA、开销、竞争三大问题。","interview":"面试怎么问：CAS 的原理是什么？有哪些问题？什么时候该放弃 CAS 改用锁？","principle":"CAS(V, expect, update)：读取 V，若等于 expect 则写入 update，否则重试。底层 CPU 指令（cmpxchg）保证原子性。三大问题：ABA 问题（用版本号 AtomicStampedReference 解决）、自旋开销（空转耗 CPU）、竞争激烈时反复失败。竞争激烈时自旋次数暴增，吞吐反降，应改用 synchronized 或 Lock 让线程阻塞让出 CPU。","params":["自旋次数上限：超过阈值应退化为锁","竞争线程数：远超 CPU 核数时慎用 CAS","版本号：AtomicStampedReference 解决 ABA"],"pitfalls":["CAS 只保证单个变量原子，复合操作仍需锁","长时间自旋会浪费 CPU，别在循环里无限重试","ABA 问题在引用/计数场景易被忽视"],"selfCheck":{"q":"高并发下 CAS 一直失败会怎样？何时改用锁？","a":"一直失败会导致线程自旋空转，CPU 飙高、吞吐下降。当竞争激烈、临界区复杂或涉及多变量时，应改用 synchronized/Lock 阻塞线程，避免无效自旋。"}}', 3, 1793250399476, 1793253102878),
	(5, 2, 1, 'AtomicInteger · 常用方法与适用场景', 'CAS 与原子类', 'medium', '{"name":"AtomicInteger · 常用方法与适用场景","category":"CAS 与原子类","priority":"medium","summary":"AtomicInteger 提供原子自增自减等方法，适合低竞争计数；高并发下用 LongAdder 更优。","interview":"面试怎么问：AtomicInteger 常用方法有哪些？高并发计数选 AtomicLong 还是 LongAdder？","principle":"AtomicInteger 基于 CAS 实现原子操作，常用方法：incrementAndGet()、decrementAndGet()、getAndAdd(n)、compareAndSet(expect, update)。CAS 更新失败会自旋重试。竞争激烈时 LongAdder 把计数分散到多个 Cell，最后 sum() 汇总，减少 CAS 竞争，吞吐远高于 AtomicLong。","params":["incrementAndGet：自增并返回新值","compareAndSet(expect, update)：CAS 原子更新","LongAdder.sum()：最终汇总值"],"pitfalls":["AtomicInteger 只保证单个操作原子，多步复合操作仍需锁","get() 和 set() 不是原子的组合，别混用造成丢失","LongAdder 的 sum() 是弱一致，适合统计不适合精确同步"],"selfCheck":{"q":"高并发计数场景为什么推荐 LongAdder 而不是 AtomicLong？","a":"AtomicLong 所有线程对同一变量 CAS，竞争激烈时自旋频繁、性能差。LongAdder 分段计数，线程各自累加到不同 Cell，最后汇总，大幅降低 CAS 竞争，吞吐更高。"}}', 4, 1793250399476, 1793253102878),
	(6, 2, 1, 'synchronized · 三种使用形式与语义', 'synchronized 与锁升级', 'high', '{"name":"synchronized · 三种使用形式与语义","category":"synchronized 与锁升级","priority":"high","summary":"三种形式锁不同对象，本质都是给对象头加锁保证原子性、可见性、有序性","interview":"synchronized 有哪三种用法？各自锁的是什么对象？","principle":"修饰实例方法锁当前实例 this；修饰静态方法锁 Class 对象；修饰代码块锁括号里指定对象。JVM 通过对象头 Mark Word 记录锁状态，进入时加锁、退出或异常时释放，保证同一锁内代码互斥，并通过内存屏障保证可见性和有序性。","params":["实例方法锁 this","静态方法锁 Class","代码块锁括号内对象"],"pitfalls":["锁临时 new 出来的对象每次不同，等于没锁","锁 String 字面量或 Integer 可能因常量池/缓存共享导致意外互斥或互斥失败","非静态方法与静态方法锁对象不同，不互斥"],"selfCheck":{"q":"两个线程一个调用非静态 synchronized 方法，一个调用静态 synchronized 方法，会互斥吗？","a":"不会。非静态方法锁的是实例对象 this，静态方法锁的是 Class 对象，两者锁对象不同，可以并发执行。要互斥必须用同一把锁。"}}', 5, 1793250399476, 1793253102878),
	(7, 2, 1, 'synchronized · 锁升级过程', 'synchronized 与锁升级', 'high', '{"name":"synchronized · 锁升级过程","category":"synchronized 与锁升级","priority":"high","summary":"synchronized 会随竞争升级：无锁→偏向锁→轻量级锁→重量级锁，减少不必要开销。","interview":"synchronized 的锁升级过程是怎样的？什么情况下会升级？","principle":"无竞争时用偏向锁（记录线程ID）；少量竞争用轻量级锁（CAS自旋替换Mark Word）；自旋失败或竞争激烈升级为重量级锁（OS互斥量，线程阻塞）。升级不可逆，JDK15后偏向锁默认关闭。","params":["JDK8默认开启偏向锁，JDK15+默认关闭","自旋次数由JVM自适应调整（约10次）","重量级锁涉及用户态/内核态切换"],"pitfalls":["升级不可逆，降级仅在特定GC阶段","高并发下synchronized并非慢，重量级锁吞吐量反而可能高于自旋","持有锁做慢IO会让线程长期阻塞，无法升级救场"],"selfCheck":{"q":"为什么说高并发场景下 synchronized 反而可能比自旋锁性能更好？","a":"因为激烈竞争下自旋浪费CPU，重量级锁让线程立即阻塞让出CPU，避免空转，吞吐量更高。"}}', 6, 1793250399476, 1793253102878),
	(8, 2, 1, 'synchronized · 等待唤醒与线程协作', 'synchronized 与锁升级', 'medium', '{"name":"synchronized · 等待唤醒与线程协作","category":"synchronized 与锁升级","priority":"medium","summary":"wait/notify 必须在 synchronized 块内调用，用 while 防虚假唤醒，优先 notifyAll 保证正确性。","interview":"为什么 wait 要放在 while 循环里而不是 if？notify 和 notifyAll 怎么选？","principle":"wait 释放锁并进入等待队列，notify/notifyAll 唤醒后需重新竞争锁。被唤醒线程从 wait 后继续执行，但唤醒条件可能已被其他线程消费（虚假唤醒），所以必须用 while 重新检查条件。notifyAll 唤醒全部让它们竞争，正确但开销大；notify 可能唤醒错误线程导致信号丢失。","params":["wait/notify/notifyAll 都是 Object 方法","wait 释放锁，sleep 不释放","notifyAll 性能开销略高但安全"],"pitfalls":["忘记 synchronized 会抛 IllegalMonitorStateException","用 if 判断条件会踩虚假唤醒，导致状态错误","notify 可能唤醒不该唤醒的线程，造成信号丢失或死锁"],"selfCheck":{"q":"虚假唤醒是什么？如何在代码上规避？","a":"线程在没有被 notify 时也可能被唤醒（JVM允许）。用 while 循环包裹 wait 并反复检查条件，条件不满足就继续 wait，即可规避。"}}', 7, 1793250399476, 1793253102878),
	(9, 2, 1, 'ReentrantLock · 与 synchronized', 'Lock 体系', 'high', '{"name":"ReentrantLock · 与 synchronized","category":"Lock 体系","priority":"high","summary":"ReentrantLock 功能更强（可中断、超时、公平锁、多条件），但必须手动释放锁，风险更高。","interview":"ReentrantLock 和 synchronized 怎么选？各有什么风险？","principle":"synchronized 是JVM内置关键字，自动加解锁，异常安全；ReentrantLock 基于AQS，需 lock/unlock 手动配对，支持 tryLock、lockInterruptibly、公平锁、多个Condition。一般优先 synchronized，需要高级特性时用 ReentrantLock。","params":["ReentrantLock 默认非公平锁（new ReentrantLock(true)为公平）","Condition.await/signal 替代 wait/notify","tryLock 可设置超时时间"],"pitfalls":["unlock 必须放 finally，否则异常导致死锁","公平锁吞吐量低，默认非公平即可","用 ReentrantLock 实现等待通知要用 Condition，不能用 wait/notify"],"selfCheck":{"q":"什么业务场景下必须用 ReentrantLock 而不是 synchronized？","a":"需要尝试加锁（tryLock超时）、可中断等待（lockInterruptibly）、公平锁策略、或多条件队列（多个Condition）时必须用 ReentrantLock。"}}', 8, 1793250399476, 1793253102878),
	(10, 2, 1, 'ReentrantLock · 公平锁与非公平锁', 'Lock 体系', 'medium', '{"name":"ReentrantLock · 公平锁与非公平锁","category":"Lock 体系","priority":"medium","summary":"公平锁按FIFO排队但吞吐低，非公平锁允许插队但吞吐高，默认非公平。","interview":"ReentrantLock 公平锁和非公平锁区别？为什么默认用非公平？","principle":"非公平锁在 lock() 时先尝试 CAS 抢锁，抢不到才进队；公平锁直接判断队列中是否有前驱，有则排队。非公平锁刚释放的锁常被刚到线程直接拿走，省去线程唤醒的上下文切换，吞吐更高；公平锁严格 FIFO，避免饥饿但切换开销大。","params":["new ReentrantLock(true) 开启公平锁","默认 new ReentrantLock() 为非公平","tryLock() 不受公平性影响，直接抢"],"pitfalls":["公平锁吞吐下降主因是线程唤醒与切换开销，不是 CAS 慢","需要严格顺序或防止饥饿（如多个等价消费者）才值得上公平锁","可重入计数在两种模式下行为一致"],"selfCheck":{"q":"为什么非公平锁吞吐通常比公平锁高？","a":"非公平锁允许刚唤醒或新来的线程直接抢到刚释放的锁，避免线程切换与等待队列调度开销；公平锁强制 FIFO，每次唤醒都带来上下文切换成本。"}}', 9, 1793250399476, 1793253102878),
	(11, 2, 1, 'ReentrantLock · tryLock 超时与可中断', 'Lock 体系', 'medium', '{"name":"ReentrantLock · tryLock 超时与可中断","category":"Lock 体系","priority":"medium","summary":"tryLock 带超时可等待后抢锁，lockInterruptibly 可被中断，用于打破死锁与长时间阻塞。","interview":"tryLock 超时和 lockInterruptibly 解决什么问题？如何排查嵌套加锁死锁？","principle":"tryLock(timeout) 会自旋+CAS 进入队列，等待期间可被中断，超时返回 false 不会死等；lockInterruptibly 阻塞时收到 interrupt 会抛 InterruptedException 并释放已获资源。嵌套加锁死锁排查：jstack 抓线程栈看 FOUND deadlock，或统一加锁顺序、用 tryLock 超时兜底。","params":["tryLock(long timeout, TimeUnit unit)","lockInterruptibly() 响应中断","lock() 不响应中断，可能永久阻塞"],"pitfalls":["tryLock() 无参版不排队，抢不到立即返回 false，别当公平锁用","catch InterruptedException 后要恢复中断位或向上抛","嵌套多锁时 tryLock 失败要释放已持有锁，否则照样死锁"],"selfCheck":{"q":"用 tryLock 怎么避免嵌套加锁死锁？","a":"对第二把锁用 tryLock(timeout) 试探，拿不到就释放第一把锁并回退重试或走降级逻辑；配合统一加锁顺序更稳。"}}', 10, 1793250399476, 1793253102878),
	(12, 2, 1, 'Condition · 多条件等待唤醒', 'Lock 体系', 'medium', '{"name":"Condition · 多条件等待唤醒","category":"Lock 体系","priority":"medium","summary":"Condition 让一把锁挂多个等待队列，await/signal 按条件精准唤醒，优于单一 wait/notify。","interview":"Condition 相比 wait/notify 好在哪？signal 用错会怎样？","principle":"每个 Condition 有独立的等待队列，await 释放锁并入队，signal 把节点移到锁的同步队列重新竞争。多条件（如 notFull/notEmpty）可精确唤醒对应线程，避免 notifyAll 全员唤醒的惊群。误用 signal 会唤醒错误条件的线程导致其再次 await，或漏 signal 造成永久等待。","params":["lock.newCondition() 创建条件","await() 释放锁并等待","signal() 唤醒一个，signalAll() 全部"],"pitfalls":["await 必须在持有该 lock 的同步块内调用","signal 后被唤醒线程还要重新抢锁，不是立即执行","误用 signal 可能丢失信号，条件判断必须用 while 循环"],"selfCheck":{"q":"Condition 的 await 为什么要配合 while 检查条件？","a":"signal 后线程要重新抢锁才能继续，期间条件可能被其他线程改回不满足（虚假唤醒/竞争），所以用 while 循环复查条件，防止在不满足时继续执行。"}}', 11, 1793250399476, 1793253102878),
	(13, 2, 1, 'AQS · 核心思想与模板结构', 'AQS 原理', 'medium', '{"name":"AQS · 核心思想与模板结构","category":"AQS 原理","priority":"medium","summary":"AQS用一个volatile的state加CLH变体队列，子类只需重写少数方法就能得到同步器。","interview":"AQS的核心思想是什么？为什么用模板方法让子类只实现少量方法？","principle":"核心是维护一个volatile int state和一个FIFO等待队列（Node双向链表，CLH变体）。线程改state成功即获取资源，失败就入队并park阻塞。子类通过模板方法（如tryAcquire/tryRelease/tryAcquireShared）定义state语义，加锁入队阻塞的公共流程由AQS的acquire/release等方法统一实现。这样把同步器拆成\"子类定义资源语义 + 父类管排队调度\"，复用排队、唤醒、中断、超时等复杂逻辑。","params":["state：volatile int，语义由子类定义（如ReentrantLock里表示重入次数）","tryAcquire/tryRelease：独占式子类需重写，返回boolean","tryAcquireShared/tryReleaseShared：共享式子类需重写"],"pitfalls":["子类只需重写少量方法，但必须配合AQS提供的acquire/release模板调用才生效","tryAcquire等不负责排队阻塞，直接改state即可，别在子类里自己park"],"selfCheck":{"q":"AQS把同步器拆成了哪两部分职责？","a":"子类通过tryAcquire/tryRelease定义state资源语义；父类AQS负责排队、阻塞、唤醒、中断和超时等公共调度流程。"}}', 12, 1793250399476, 1793253102878),
	(14, 2, 1, 'AQS · ReentrantLock 的加锁解锁流程', 'AQS 原理', 'medium', '{"name":"AQS · ReentrantLock 的加锁解锁流程","category":"AQS 原理","priority":"medium","summary":"ReentrantLock基于AQS state实现可重入锁，非公平锁允许新线程插队抢state。","interview":"ReentrantLock加锁解锁的流程是什么？非公平锁插队有什么影响？","principle":"加锁：调lock()→sync.acquire(1)→tryAcquire(1)尝试CAS把state从0改1并记录owner线程（重入则state++）；失败则addWaiter入队成Node，acquireQueued里自旋检查前驱是否head，不是则park阻塞。解锁：tryRelease(1)把state减到0，unparkSuccessor唤醒队列下一个线程。非公平锁的nonfairTryAcquire在入队前直接CAS抢一次state（插队）；公平锁fairTryAcquire会先查队列里有没有前驱（hasQueuedPredecessors），有排队者就老实排队，不插队。","params":["state=0表示未锁，>0表示被持有（可重入次数）","nonfairSync默认new ReentrantLock()即非公平锁","公平锁new ReentrantLock(true)"],"pitfalls":["非公平锁可能让后来线程插队，导致队列里线程等待更久甚至饥饿，但吞吐量通常更高","公平锁严格按FIFO，不插队但吞吐低，因唤醒切换开销大","可重入必须在unlock时释放相同次数，否则state没归零其他线程拿不到锁"],"selfCheck":{"q":"公平锁和非公平锁在加锁流程上的关键差异是什么？","a":"非公平锁nonfairTryAcquire在入队前先直接CAS抢一次state可插队；公平锁会先用hasQueuedPredecessors检查队列有无等待者，有就排队不插队，保证FIFO。"}}', 13, 1793250399476, 1793253102878),
	(15, 2, 1, 'AQS · 共享模式与读写锁', 'AQS 原理', 'low', '{"name":"AQS · 共享模式与读写锁","category":"AQS 原理","priority":"low","summary":"共享模式允许多线程同时获锁，ReadWriteLock用读共享写独占提升读多写少吞吐。","interview":"AQS的共享模式怎么工作？ReadWriteLock读多写少有什么取舍？","principle":"共享模式tryAcquireShared返回>=0表示获取成功，可被多线程同时持有（如信号量、读锁），acquireShared获取失败同样入队park。ReadWriteLock用state高16位记读锁持有数、低16位记写锁重入数。读锁tryAcquireShared在无写锁时可共享获取；写锁tryAcquire独占，需读写都为0。读多写少时并发读大幅提升吞吐，但写线程要等所有读释放，读线程持续涌入会让写锁饥饿。","params":["tryAcquireShared返回值>=0获锁成功，<0需入队","state高16位读锁数，低16位写锁重入数","ReentrantReadWriteLock默认非公平"],"pitfalls":["读多写少读锁共享吞吐高，但可能写锁饥饿，写线程迟迟抢不到","公平模式ReadWriteLock可缓解写饥饿，但降低并发度","锁降级（写锁内再拿读锁再放写锁）可行，锁升级（读到写）不行会死锁"],"selfCheck":{"q":"ReadWriteLock在读多写少场景有什么问题？","a":"读锁共享大幅提升并发读吞吐，但写锁独占需等所有读释放，持续的读线程涌入可能导致写锁饥饿，可用公平模式缓解。"}}', 14, 1793250399476, 1793253102878),
	(16, 2, 1, 'volatile · 保证内存可见性', 'volatile', 'medium', '{"name":"volatile · 保证内存可见性","category":"volatile","priority":"medium","summary":"volatile 写后所有线程立即读到最新值，靠主内存强制同步","interview":"volatile 是怎么保证可见性的？","principle":"线程读写变量时会绕过各自的 CPU 缓存/工作内存：写操作把值刷回主内存，读操作从主内存拉最新值（JMM 的 happens-before：volatile 写 happen-before 后续读）。编译器和 CPU 不会在写前后缓存该变量到寄存器中保留旧值。","params":["- 修饰变量，不是方法或类","- 写入主内存、读取主内存是语义层面强制，不是某条特定指令"],"pitfalls":["可见性不等于原子性：i++ 仍会丢失更新","一个线程写，多个线程读时才能凸显效果，别把缓存一致性协议说成 volatile 直接做同步"],"selfCheck":{"q":"volatile 变量 i，多线程执行 i++，结果会等于预期吗？","a":"不会。i++ 是读-改-写三步，volatile 只保证每一步读到最新值，不保证三步原子，仍需 CAS 或加锁。"}}', 15, 1793250399476, 1793253102878),
	(17, 2, 1, 'volatile · 禁止指令重排', 'volatile', 'medium', '{"name":"volatile · 禁止指令重排","category":"volatile","priority":"medium","summary":"volatile 内存读写前后插入屏障，禁止重排跨越该点","interview":"volatile 是怎么禁止指令重排的？举个经典例子","principle":"JMM 规定 volatile 变量的读写是内存访问屏障点：编译器和 CPU 不能把普通读写重排到 volatile 写之前/读之后等跨越位置（对应 LoadStore、StoreStore、StoreLoad、LoadLoad 的组合约束）。经典例子是双检锁单例：对象实例变量必须 volatile，防止 new 对象的「分配内存→初始化→赋值引用」被重排成「分配内存→赋值引用→初始化」，其他线程看到半成品。","params":["- 仅约束该变量相关的重排，不是全序内存屏障","- 顺序语义是 JMM 保证，不依赖具体 CPU 指令"],"pitfalls":["只有写 volatile 变量那个点受保护，普通变量之间仍可重排","双检锁不加 volatile 是高频考点：会拿到半初始化对象"],"selfCheck":{"q":"双检锁单例中为什么实例字段要加 volatile？","a":"防止指令重排：对象未初始化完就被赋给引用，别的线程拿到 null 或半成品对象。"}}', 16, 1793250399476, 1793253102878),
	(18, 2, 1, 'volatile · 状态标志位典型用法', 'volatile', 'medium', '{"name":"volatile · 状态标志位典型用法","category":"volatile","priority":"medium","summary":"用 volatile boolean 做线程停止/开始标志，简单且无锁","interview":"volatile 最常用的场景是什么？怎么写一个优雅停机？","principle":"一个线程写标志位，其他线程轮询读取，volatile 保证每次读到最新值，从而及时响应状态变化。典型：`private volatile boolean running = true; while(running){...}`，关闭方置 running=false 即可。相比 stop() 更安全，不破坏锁和不变量。","params":["- 标志位一般是 boolean 或简单枚举/状态值","- 配合 while 轮询，读写分离，无需加锁"],"pitfalls":["别用于计数器或复合操作（不原子）","长循环要保证循环体内会读取标志，否则 JIT 可能把外提后看不到变化（volatile 修饰就能避免）"],"selfCheck":{"q":"为什么用 volatile boolean 停机比 Thread.stop() 好？","a":"stop() 会强制终止线程、破坏锁导致数据不一致；volatile 标志是协作式退出，线程自己决定退出时机，安全可控。"}}', 17, 1793250399476, 1793253102878),
	(19, 2, 1, 'volatile · 双检锁单例中的指令重排', 'volatile', 'medium', '{"name":"volatile · 双检锁单例中的指令重排","category":"volatile","priority":"medium","summary":"DCL 单例必须用 volatile 禁止 new 操作的指令重排，避免读到半初始化对象。","interview":"双检锁单例为什么要给实例加 volatile？不加会出什么问题？","principle":"new 对象分为三步：分配内存、初始化对象、把引用指向内存。JVM 可能重排成 1-3-2。若线程 A 执行到 1-3 后被打断，线程 B 在外层判空通过，拿到的是未初始化完成的对象。volatile 通过内存屏障禁止这种重排。","params":["必须加在单例的静态实例字段上","锁对象是类的 Class 对象"],"pitfalls":["只用 synchronized 不加 volatile 仍可能读到半初始化对象","外层判空不能省，否则每次都加锁影响性能","反射、序列化仍可能破坏单例，DCL 不是万能的"],"selfCheck":{"q":"DCL 单例只用 synchronized 不加 volatile 会怎样？","a":"仍可能出问题。synchronized 只保证线程间互斥，但不禁止 new 操作内部的指令重排，其他线程可能读到未完成初始化的半成品对象，所以必须加 volatile。"}}', 18, 1793250399476, 1793253102878),
	(20, 2, 1, 'volatile · 禁止指令重排序', 'volatile', 'medium', '{"name":"volatile · 禁止指令重排序","category":"volatile","priority":"medium","summary":"volatile通过内存屏障禁止特定指令重排，保证代码执行顺序符合预期。","interview":"volatile是怎么禁止指令重排序的？","principle":"JMM定义volatile写前写后、volatile读前读后插入内存屏障，禁止屏障两侧指令跨越重排。经典例子是双重检查锁单例：instance字段加volatile，避免new对象时分配内存、初始化、赋值引用三步被重排成先赋值再初始化，导致其他线程拿到未初始化对象。","params":["volatile写：前后各插屏障，写前禁止与上面读写互换，写后禁止与下面读写互换","volatile读：前后各插屏障，读前禁止与上面读写互换，读后禁止与下面读写互换"],"pitfalls":["volatile只保证修饰变量的读写顺序，不保证其他变量之间不重排","DCL单例不加volatile，可能读到半初始化对象"],"selfCheck":{"q":"双重检查锁单例为什么instance必须加volatile？","a":"new对象包含分配内存、初始化、赋值引用三步，可能被重排为先赋值引用再初始化；加volatile禁止重排，保证其他线程拿到已初始化完成的对象。"}}', 19, 1793250399476, 1793253102878),
	(21, 2, 1, 'volatile · 不保证复合操作原子性', 'volatile', 'medium', '{"name":"volatile · 不保证复合操作原子性","category":"volatile","priority":"medium","summary":"volatile 保证可见性与有序性，但 i++ 等复合操作仍非原子，需原子类或锁。","interview":"为什么 volatile 变量做 i++ 还是会丢更新？","principle":"i++ 分为读取、加一、写回三步，volatile 只保证每次读到最新值、写立即可见，不阻止两个线程交错执行。要原子需 AtomicInteger 的 CAS、synchronized 或 Lock。","params":["可见性：写立即刷回主存","有序性：禁止指令重排","原子性：仅对单次读/写赋值保证"],"pitfalls":["boolean 标志位场景适合 volatile，计数器场景不适合","long/double 单次读写在 64 位 JVM 上已被规范保证原子，但复合操作仍不原子","用 volatile 保护计数是面试高频反例"],"selfCheck":{"q":"volatile int count; 两个线程各执行 count++ 1000 次，最终值可能是多少？","a":"小于 2000。++ 是读-改-写复合操作，两线程可能读到同一旧值后各写回一次，导致更新丢失。"}}', 20, 1793250399476, 1793253102878),
	(22, 2, 1, 'volatile · 可见性仅对被修饰变量生效', 'volatile', 'medium', '{"name":"volatile · 可见性仅对被修饰变量生效","category":"volatile","priority":"medium","summary":"volatile 只让被修饰变量的读写跨线程可见，其他普通变量不受保护。","interview":"volatile int a; int b; 线程写 b 后写 a，另一线程读 a 后读 b，b 一定可见吗？","principle":"volatile 通过内存屏障保证：写 volatile 变量前的写操作对读该 volatile 的线程可见（写前不重排、读后不重排）。因此 b 只要写在 a 之前、读在 a 之后，借 a 的屏障即可间接可见，但 b 本身无 volatile 语义。","params":["只对被修饰字段的读写点建屏障","可见性依赖 volatile 变量作为''发布点''","不扩展到未被屏障覆盖的普通字段"],"pitfalls":["不要以为给一个字段加 volatile 就保护了整个对象或集合","可变对象内部字段的修改不因对象引用 volatile 而自动可见","面试要主动提''借用 volatile 做内存屏障''这个间接技巧"],"selfCheck":{"q":"volatile 引用 list，往 list 里 add 元素，其他线程读 list.size() 一定能拿到最新吗？","a":"不能保证。volatile 只保证引用本身可见，list 内部结构是普通字段，add 的修改无同步语义，需 Collections.synchronizedList 或加锁。"}}', 21, 1793250399476, 1793253102878),
	(23, 2, 1, 'happens-before 与 volatile 禁止重排', 'volatile', 'medium', '{"name":"happens-before 与 volatile 禁止重排","category":"volatile","priority":"medium","summary":"happens-before 定义可见与有序规则，volatile 写读建立 hb 关系从而禁止重排。","interview":"volatile 是怎么保证有序性的？happens-before 规则里哪条和它对应？","principle":"JMM 用 happens-before 判断两操作的可见与顺序。规则：volatile 写 happens-before 后续对该变量的 volatile 读；另有程序顺序、锁、线程启动/终止、传递性。编译器与 CPU 不能跨越 hb 关系重排，通过读写屏障在 volatile 点插入屏障实现。","params":["volatile 写 → 后续 volatile 读 有 hb","hb 具传递性可推导更远的可见","单线程内程序顺序默认有 hb"],"pitfalls":["happens-before 不是时间先后，是可见性与有序性的偏序约定","两线程各自读 volatile 不构成 hb，仍可能看到对方之前的普通写问题","只保证不重排到屏障两侧，不会禁止屏障内部的重排优化"],"selfCheck":{"q":"线程 A：x=1; volatileFlag=true; 线程 B：if(volatileFlag) print(x)，B 一定打印 1 吗？","a":"一定。A 对 volatileFlag 的写 happens-before B 对它的读，借传递性 x=1 对 B 可见，且指令不重排到 volatileFlag 写之后。"}}', 22, 1793250399476, 1793253102878),
	(24, 2, 1, 'volatile · 指令重排序与happens-befor', 'volatile', 'medium', '{"name":"volatile · 指令重排序与happens-befor","category":"volatile","priority":"medium","summary":"volatile 保证可见性和禁止重排序，但不保证原子性，通过 happens-before 保证有序。","interview":"面试怎么问：volatile 解决了什么问题？指令重排和 happens-before 是怎么回事？","principle":"volatile 修饰变量：① 可见性：写立即刷回主存，读从主存取；② 禁止指令重排序：编译器和处理器不把 volatile 变量前后的指令乱序。happens-before：volatile 写 happens-before 后续读，保证有序性。典型应用：双重检查锁单例（防止对象半初始化）、状态标志位。","params":["适用场景：状态标志、DCL 单例","不保证原子性：i++ 仍需锁或原子类","内存屏障：插在 volatile 读写前后"],"pitfalls":["volatile 不是原子的，volatile int i; i++ 依然会丢更新","只保证单变量可见性，多变量复合操作需锁","滥用 volatile 会插内存屏障，影响性能"],"selfCheck":{"q":"volatile 能否保证 i++ 的原子性？为什么？","a":"不能。volatile 只保证可见性和有序性，i++ 是读-改-写三步，多线程下仍会丢失更新。需要原子性必须用 synchronized、Lock 或原子类。"}}', 23, 1793250399476, 1793253102878),
	(25, 2, 1, 'volatile · 引用替换与对象字段修改的可见性差异', 'volatile', 'medium', '{"name":"volatile · 引用替换与对象字段修改的可见性差异","category":"volatile","priority":"medium","summary":"volatile保证引用赋值可见，但不保证对象内部字段修改的可见性。","interview":"volatile修饰对象引用，修改对象内部字段，其他线程能立即看到吗？","principle":"volatile修饰引用变量时，只对该引用的读写建立happens-before：引用指向新对象时，新对象的初始化内容对读线程可见。但对旧对象内部字段的修改是普通字段写，不触发volatile语义，也不会刷新缓存或加内存屏障，其他线程可能读到旧值。","params":["仅对引用本身的赋值和读取生效","对象字段默认不具volatile语义","配合final可保证构造期安全发布"],"pitfalls":["误以为volatile对象的字段全变volatile","对象内部字段修改仍需synchronized/Atomic/加volatile字段","可变对象共享时优先用不可变对象替换引用"],"selfCheck":{"q":"volatile List替换整个List和对List做add操作，可见性有什么不同？","a":"替换引用（list=new ArrayList）对读线程立即可见；add修改旧List内部字段，其他线程不保证可见，需额外同步手段。"}}', 24, 1793250399476, 1793253102878),
	(26, 2, 1, 'synchronized · 实例锁与类锁互斥关系', 'synchronized', 'medium', '{"name":"synchronized · 实例锁与类锁互斥关系","category":"synchronized","priority":"medium","summary":"实例锁锁对象实例，类锁锁Class对象，两者不互斥，可同时进入。","interview":"一个线程持synchronized实例方法，另一线程能进synchronized静态方法吗？","principle":"synchronized实例方法锁的是this对象，synchronized静态方法锁的是该类的Class对象。this与Class是两个不同对象，内部各有一把monitor，因此两把锁互不相关，可并发执行。只有锁同一个对象（同一个this或同一个Class）的synchronized块才会互斥。","params":["实例方法锁this","静态方法锁ClassName.class","同步块锁括号内指定对象"],"pitfalls":["误以为同一类的所有synchronized都互斥","静态与实例同步方法并发执行会产生线程安全问题","想让它们互斥，需显式指定同一个锁对象（如ClassName.class）"],"selfCheck":{"q":"synchronized实例方法和synchronized static方法能并发执行吗？","a":"能。前者锁this，后者锁Class对象，是两把不同的锁，不会互斥，可同时进入临界区。"}}', 25, 1793250399476, 1793253102878),
	(27, 2, 1, 'synchronized · 锁对象辨析（实例/类/方法）', 'synchronized', 'medium', '{"name":"synchronized · 锁对象辨析（实例/类/方法）","category":"synchronized","priority":"medium","summary":"synchronized方法锁调用者对象，代码块锁括号指定对象，必须辨析锁的是谁。","interview":"synchronized(this)、synchronized(ClassName.class)、synchronized普通方法分别锁什么对象？","principle":"synchronized修饰实例方法时锁this（当前对象实例）；修饰静态方法时锁ClassName.class（类的Class对象）；修饰代码块时锁括号中指定的对象，可以是this、Class、任意共享对象。只有锁同一个对象的同步块才互斥，锁不同对象则完全并发。","params":["实例方法→this","静态方法→ClassName.class","代码块→括号内对象"],"pitfalls":["锁new出来的临时对象等于没锁（每次不同）","锁Integer等自动装箱对象可能因缓存/对象不同导致失效","字符串字面量作为锁可能被多处共享导致意外互斥"],"selfCheck":{"q":"两个线程分别对同一对象的synchronized(this)块和synchronized实例方法操作，会互斥吗？","a":"会。两者锁的都是同一个this对象，monitor相同，因此互斥；但若锁的是不同对象（如不同实例）则不互斥。"}}', 26, 1793250399476, 1793253102878),
	(28, 2, 1, 'synchronized锁升级 · 升级后状态变化与降级', 'synchronized', 'medium', '{"name":"synchronized锁升级 · 升级后状态变化与降级","category":"synchronized","priority":"medium","summary":"synchronized随竞争升级：无锁→偏向锁→轻量级锁→重量级锁，只升不降为主，避免过早加锁开销。","interview":"synchronized的锁升级过程是怎样的？升级后还会降级吗？","principle":"Mark Word记录锁状态。无竞争时用偏向锁（记录线程ID）；有少量竞争用CAS自旋升级轻量级锁；竞争激烈膨胀为重量级锁（OS互斥量，线程阻塞）。偏向锁可撤销，重量级锁在GC等安全点可降级（如批量重偏向/撤销），实际以只升不降理解更安全。","params":["偏向锁延迟默认约4秒（JVM启动后才启用）","自旋次数/自适应自旋由JVM决定","JDK15后偏向锁默认关闭（JEP 374）"],"pitfalls":["偏向锁不是无锁，仍涉及对象头写入与撤销成本","锁降级只在特定GC阶段发生，业务上不要依赖","大量小对象短同步时升级策略反而更划算"],"selfCheck":{"q":"为什么synchronized要有锁升级而不是一开始就用重量级锁？","a":"重量级锁需内核态切换和线程挂起，开销大；大部分同步段无竞争或低竞争，轻量级CAS自旋成本更低，升级机制平衡性能与正确性。"}}', 27, 1793250399476, 1793253102878),
	(29, 2, 1, 'synchronized · 实例锁与类锁的锁定对象', 'synchronized', 'medium', '{"name":"synchronized · 实例锁与类锁的锁定对象","category":"synchronized","priority":"medium","summary":"实例锁锁的是当前对象（this），类锁锁的是Class对象，两者互不阻塞。","interview":"synchronized的实例锁和类锁锁的是什么对象？会互斥吗？","principle":"synchronized(obj)或实例方法锁的是对象实例的Monitor；static synchronized或synchronized(Xxx.class)锁的是Class对象的Monitor。不同对象头/Monitor，所以实例锁和类锁并发执行不冲突，只有同一把Monitor才互斥。","params":["synchronized(this) = 实例锁","synchronized(Xxx.class) = 类锁","每个对象一个Monitor，Class也是一个对象"],"pitfalls":["实例方法锁的是this，多实例时每个实例各自独立，不互斥","不要以为\"同一个类\"的锁都是一把，实例锁与类锁是两把","synchronized(常量池里的字符串)可能因intern复用造成意外全局锁"],"selfCheck":{"q":"两个线程分别对同一个类的实例方法和静态方法加synchronized，会互斥吗？","a":"不会。实例方法锁this对象的Monitor，静态方法锁Class对象的Monitor，是两把不同的锁，可以并发执行。"}}', 28, 1793250399476, 1793253102878),
	(30, 2, 1, 'synchronized 静态方法与实例方法锁对象辨析', 'synchronized', 'medium', '{"name":"synchronized 静态方法与实例方法锁对象辨析","category":"synchronized","priority":"medium","summary":"静态synchronized锁Class对象，实例synchronized锁this，二者可并发，辨析关键看是不是static。","interview":"synchronized修饰的静态方法和实例方法，锁对象分别是什么？","principle":"方法级synchronized隐式指定锁对象：静态方法同步的是Class对象（方法区中的Class结构对应的对象），实例方法同步的是当前实例this。进入同步方法即执行monitorenter，退出执行monitorexit，异常也会释放锁。","params":["静态方法：锁Xxx.class","实例方法：锁this","方法内部可再用synchronized块换锁对象"],"pitfalls":["同一对象的两个实例方法都用synchronized时互斥，因为锁同一个this","构造方法不能声明synchronized（Java不支持）","同步方法锁粒度是整个方法，长方法易造成性能问题，可改同步块缩小范围"],"selfCheck":{"q":"类A的静态synchronized方法m1和实例synchronized方法m2，线程1调用m1、线程2调用a.m2，能否同时进入？","a":"能。m1锁A.class对象的Monitor，m2锁实例a的Monitor，两把锁不同，互不影响，可以同时进入执行。"}}', 29, 1793250399476, 1793253102878),
	(31, 2, 1, '复合操作非原子 · i++ 内存语义', 'Java并发基础', 'medium', '{"name":"复合操作非原子 · i++ 内存语义","category":"Java并发基础","priority":"medium","summary":"i++ 是读-改-写三步复合操作，多线程下会丢更新。","interview":"为什么多线程下 i++ 会丢更新？","principle":"i++ 分三步：读主存值到线程栈、加 1、写回主存。两线程可能读到同一旧值，各自加 1 后写回，结果只加了 1。即使变量加 volatile，也只能保证每一步可见，无法把三步合并成原子操作。","params":["i++ 等价于 i = i + 1，非原子","volatile 只保证可见性，不保证复合操作原子"],"pitfalls":["volatile int i 不能解决 i++ 并发丢更新","应改用 AtomicInteger 或加锁"],"selfCheck":{"q":"10 个线程各对 i 执行 1000 次 i++，最终 i 一定是 10000 吗？","a":"不一定。i++ 是读-改-写复合操作，多线程下会互相覆盖，最终值通常小于 10000。要保证正确需用 AtomicInteger 或加锁。"}}', 30, 1793250399476, 1793253102878),
	(32, 2, 1, '原子性 · 复合操作不保证原子', 'Java并发基础', 'medium', '{"name":"原子性 · 复合操作不保证原子","category":"Java并发基础","priority":"medium","summary":"原子性指一个操作不可中断，要么全做要么不做。","interview":"什么是原子性？为什么复合操作不是原子的？","principle":"原子性要求操作序列在执行中不被其他线程插入。Java 里单条基本类型读写是原子的，但 a++、if(x==1)x=2、check-then-act 这类多步操作会被线程切换打断，需靠 synchronized、Lock 或原子类保证。","params":["long/double 读写在 32 位 JVM 上可能非原子","JMM 保证引用读写原子"],"pitfalls":["synchronized 只保证被它包住的代码块原子","不要以为单个语句就是原子的"],"selfCheck":{"q":"check-then-act（先判断再改）为什么不是原子的？","a":"判断和修改是两步，中间可能被其他线程插入，导致条件已失效仍在执行。必须用锁或原子 CAS 把两步合并成原子操作。"}}', 31, 1793250399476, 1793253102878),
	(33, 2, 1, 'CAS · 适用场景选型（无锁 vs 加锁）', '并发与锁', 'medium', '{"name":"CAS · 适用场景选型（无锁 vs 加锁）","category":"并发与锁","priority":"medium","summary":"低竞争、临界区短选CAS，高竞争或临界区长选锁。","interview":"什么时候用CAS无锁，什么时候直接上锁？","principle":"CAS基于CPU原子指令，先读旧值再比较交换；无锁实现下竞争低时开销小，但竞争高会自旋浪费CPU；锁会让线程挂起让出CPU，竞争高时吞吐更稳。","params":["AtomicInteger等类默认基于Unsafe的CAS","自旋默认无上限（LongAdder除外）","synchronized轻量级→重量级锁阈值由竞争动态决定"],"pitfalls":["CAS只保证单变量原子性，多变量需AtomicReference+不可变对象或锁","ABA问题需版本号（AtomicStampedReference）","高竞争下CAS吞吐可能低于加锁"],"selfCheck":{"q":"一个多变量的校验+更新操作，用CAS怎么做？","a":"把多个变量封装成不可变对象，用AtomicReference对该对象整体CAS；失败重读重试。或直接用锁。"}}', 32, 1793250399476, 1793253102878),
	(34, 2, 1, 'CAS · 自旋开销与高并发下的性能退化', '并发与锁', 'medium', '{"name":"CAS · 自旋开销与高并发下的性能退化","category":"并发与锁","priority":"medium","summary":"CAS 无锁但自旋会空转，竞争激烈时 CPU 空耗，性能反而不如锁。","interview":"CAS 在高并发下为什么可能比 synchronized 更慢？","principle":"CAS 用 compareAndSet 循环重试更新，失败就自旋。线程少时无阻塞开销低；竞争激烈时大量线程反复读-比-写失败，CPU 空转浪费，且只有单个变量能保证原子，多个变量需加锁或合并。","params":["AtomicInteger 内部依赖 Unsafe.compareAndSwapInt","JDK9+ 用 VarHandle，语义一致"],"pitfalls":["ABA 问题需用 AtomicStampedReference 加版本号","自旋次数无上限会烧 CPU，可用 LongAdder 分段降低竞争"],"selfCheck":{"q":"CAS 的 ABA 问题是什么，怎么解决？","a":"值从 A 改 B 再改回 A，CAS 判定成功但中间已被改过；用带版本号的 AtomicStampedReference 解决。"}}', 33, 1793250399476, 1793253102878),
	(35, 2, 1, 'synchronized · 锁对象选择（类对象 vs 实例', '并发与锁', 'medium', '{"name":"synchronized · 锁对象选择（类对象 vs 实例","category":"并发与锁","priority":"medium","summary":"锁实例对象只互斥同一实例，锁类对象互斥所有实例的静态同步方法。","interview":"synchronized(this) 和 synchronized(类.class) 的区别是什么？","principle":"synchronized(obj) 用 obj 的对象头做锁。锁 this 或非静态同步方法锁的是当前实例，多实例间不互斥；锁 类.class 或静态同步方法锁的是 Class 对象，所有实例共用一把锁。锁 null 会抛 NPE。","params":["非静态方法默认锁 this","静态方法默认锁 当前类.class","字面量 String 会被常量池共享，易误锁"],"pitfalls":["String 常量或 Integer 缓存对象当锁会意外互斥","锁对象应声明为 private final，防止被外部替换或重新赋值"],"selfCheck":{"q":"两个实例同时调用同一个非静态 synchronized 方法会互斥吗？","a":"不会。非静态 synchronized 锁的是各自 this，两个实例的锁不同，可以并发执行；改成静态方法或锁 class 才互斥。"}}', 34, 1793250399476, 1793253102878),
	(36, 2, 1, 'synchronized锁升级 · 单向不可逆与不可降级', '并发与锁', 'medium', '{"name":"synchronized锁升级 · 单向不可逆与不可降级","category":"并发与锁","priority":"medium","summary":"锁按偏向→轻量→重量级单向升级，不会降级，也不可逆。","interview":"synchronized 的锁升级过程是怎样的，能降级吗？","principle":"对象头 Mark Word 记录锁状态：无锁→偏向锁（记录线程 ID，无同步直接进入）→轻量级锁（CAS 自旋抢锁）→重量级锁（膨胀为 Monitor，阻塞排队）。竞争加剧才升级，升级后不会退回偏向或轻量，JVM 默认不主动降级。","params":["JDK15 起偏向锁默认关闭（-XX:+UseBiasedLocking 可开）","自适应自旋次数由 JVM 根据历史动态调整"],"pitfalls":["锁升级不可逆，偏向锁一旦膨胀到重量级就常驻","批量撤销偏向后该类对象会禁用偏向，不要依赖偏向锁优化"],"selfCheck":{"q":"锁升级是单向还是双向的，为什么？","a":"单向。升级靠竞争加剧触发，降级缺少可靠的触发时机且实现复杂，JVM 未做降级，重量级锁一旦产生不会退回轻量或偏向。"}}', 35, 1793250399476, 1793253102878),
	(37, 2, 1, 'volatile · DCL单例中的指令重排与对象逸出', '并发与锁', 'medium', '{"name":"volatile · DCL单例中的指令重排与对象逸出","category":"并发与锁","priority":"medium","summary":"volatile禁止DCL中new对象的指令重排，防止读到半初始化对象。","interview":"DCL单例为什么instance要加volatile？不加会出什么问题？","principle":"new对象分三步：分配内存、初始化、把引用指向内存。2、3步可能重排，导致另一线程在if(instance==null)判空失败后，直接拿到未初始化完的对象。volatile写建立happens-before读，禁止该重排并保证可见性。","params":["volatile保证可见性+禁止重排，不保证原子性","DCL中双重判空：外层减少锁竞争，内层防止重复创建","JDK5后volatile语义按JSR-133增强"],"pitfalls":["不加volatile可能出现对象逸出：其他线程拿到半初始化实例","volatile对i++这类复合操作无效，仍需CAS或锁","静态内部类懒加载是更简洁的替代方案"],"selfCheck":{"q":"不加volatile的DCL会有什么现象？","a":"线程B可能在判空失败后拿到未构造完成的对象，调用其方法时字段为默认值，出现状态不一致。"}}', 36, 1793250399476, 1793253102878),
	(38, 2, 1, 'CAS · 高竞争下的自旋与退化到锁', 'CAS', 'medium', '{"name":"CAS · 高竞争下的自旋与退化到锁","category":"CAS","priority":"medium","summary":"高竞争时CAS自旋空转浪费CPU，需退化为LongAdder或锁。","interview":"CAS在高并发计数场景有什么问题？怎么优化？","principle":"CAS失败后循环重试，线程多时大量自旋浪费CPU且缓存行反复失效。优化：1.用LongAdder分段累加降低争用，最后sum合并；2.自旋N次失败后升级为阻塞锁（如synchronized升级重量级）；3.加随机退避。","params":["LongAdder按CPU核数分Cell，最终sum求和","synchronized自旋次数默认由JVM自适应调整","JDK9+可用VarHandle做更细粒度CAS"],"pitfalls":["LongAdder的sum()非原子，高并发下取值有误差，适合统计不适合严格顺序","退化到锁后唤醒开销大，适合竞争持续高的场景","自旋阈值不当会CPU打满或频繁阻塞"],"selfCheck":{"q":"AtomicLong和LongAdder在1000线程++场景谁快？为什么？","a":"LongAdder快。AtomicLong所有线程争同一个变量，CAS冲突率高；LongAdder分散到多个Cell累加，最后合并，大幅降低争用。"}}', 37, 1793250399476, 1793253102878),
	(39, 2, 1, 'CAS · 比较并交换流程', 'CAS', 'medium', '{"name":"CAS · 比较并交换流程","category":"CAS","priority":"medium","summary":"CAS 是无锁原子操作：比较旧值一致才写入新值，否则重试或失败。","interview":"讲讲 CAS 的执行流程，它为什么是原子的？","principle":"CAS(V,A,B)：读取内存值 V 与期望值 A 比较，相等则写入 B，不等则失败。整个比较+写入由 CPU 指令（如 x86 的 cmpxchg）保证原子性，Java 通过 Unsafe 调用。典型应用是 Atomic 类与自旋更新。","params":["V：内存当前值","A：期望旧值","B：要写入的新值"],"pitfalls":["ABA 问题：值改回原样后 CAS 无法察觉，需 AtomicStampedReference 加版本号","依赖 CPU 指令支持，不是所有平台都等价","需要配合 volatile 保证读到的旧值可见性"],"selfCheck":{"q":"CAS 为什么不需要加锁就能保证原子性？","a":"比较和交换由 CPU 单条指令（如 cmpxchg）完成，中间不会被其他线程打断；Java 通过 Unsafe 调用该指令，所以无需锁。"}}', 38, 1793250399476, 1793253102878),
	(40, 2, 1, 'CAS · 高并发自旋开销', 'CAS', 'medium', '{"name":"CAS · 高并发自旋开销","category":"CAS","priority":"medium","summary":"CAS 失败重试（自旋）在高竞争下 CPU 空转，开销可能超过锁。","interview":"CAS 在高并发下有什么问题？自旋会带来什么开销？","principle":"CAS 失败时通常循环重试。竞争激烈时，大量线程反复读-比较-失败，CPU 忙等却不干活；且每次都要写总线引发缓存一致性流量。轻竞争时 CAS 比锁快，重竞争时反而劣于 synchronized。自旋锁通常配合有限次数或退避策略。","params":["自旋次数：常见设阈值如 10 次后升级为阻塞","锁升级策略：竞争大时转为 OS 互斥"],"pitfalls":["活锁风险：线程持续失败但不阻塞","CPU 资源浪费：自旋线程不释放 CPU","LongAdder 分段累加可缓解热点计数竞争"],"selfCheck":{"q":"为什么高并发计数推荐 LongAdder 而不是 AtomicLong？","a":"AtomicLong 所有线程 CAS 同一变量导致高失败率和自旋浪费；LongAdder 把计数分散到多个 Cell，竞争时各改各的，最后 sum 合并，吞吐高得多。"}}', 39, 1793250399476, 1793253102878),
	(41, 2, 1, 'volatile 与 CAS 适用场景对比', 'CAS', 'medium', '{"name":"volatile 与 CAS 适用场景对比","category":"CAS","priority":"medium","summary":"volatile 解决可见性和有序性，CAS 解决原子性的读-改-写；二者常配合使用。","interview":"volatile 和 CAS 各解决什么问题？什么时候用哪个？","principle":"volatile 保证变量的可见性和禁止指令重排，但不保证复合操作（如 i++）的原子性。CAS 提供原子的比较并交换，解决更新原子性。典型组合：线程内读取 volatile 状态做判断，再用 CAS 更新。volatile 适合状态标志、DCL 单例；CAS 适合计数器、无锁数据结构。","params":["volatile：修饰变量，保证读写直通主内存","CAS：通过 Unsafe/Atomic 类实现原子更新"],"pitfalls":["volatile 不等于线程安全，i++ 仍会丢失更新","volatile 不保证复合操作原子性","CAS 会掩盖可见性问题：只 CAS 不加 volatile 可能读到过期状态"],"selfCheck":{"q":"volatile 修饰的 int 做 i++，多线程下安全吗？","a":"不安全。i++ 是读-改-写三步，volatile 只保证每次读到最新值，不保证三步原子性，仍会丢失更新。应使用 AtomicInteger 或加锁。"}}', 40, 1793250399476, 1793253102878),
	(42, 2, 1, 'volatile · 保证可见性但不保证原子性', 'Java多线程锁机制', 'medium', '{"name":"volatile · 保证可见性但不保证原子性","category":"Java多线程锁机制","priority":"medium","summary":"volatile 保证可见性和有序性，不保证复合操作原子性。","interview":"volatile 解决什么问题？为什么不保证原子性？","principle":"volatile 写会把工作内存刷回主存，volatile 读会从主存取，并建立 happens-before 防止指令重排。但 i++ 这类读-改-写是多步，volatile 只保证每步读到的都是最新值，不能合并成一步，所以不保证原子。","params":["典型场景：状态标志位 flag","典型场景：DCL 双重检查锁单例"],"pitfalls":["volatile int count 做 count++ 仍会丢更新","volatile 不替代 synchronized 或原子类"],"selfCheck":{"q":"volatile 适合用在什么场景？","a":"适合一写多读的标志位或状态变量，如 stop 标志、DCL 单例里的 instance。不适合做 count++ 等复合操作，需用 AtomicInteger 或加锁。"}}', 41, 1793250399476, 1793253102878),
	(43, 2, 1, 'i++ · 读改写三步复合操作非原子', 'Java多线程锁机制', 'medium', '{"name":"i++ · 读改写三步复合操作非原子","category":"Java多线程锁机制","priority":"medium","summary":"i++ 是读-改-写三步,多线程下会丢更新,必须用原子类或加锁保证。","interview":"为什么 i++ 在多线程下线程不安全?","principle":"i++ 拆成三步:①从主内存读 i 到工作内存 ②CPU 计算 i+1 ③写回主内存。线程 A 执行完①后被切换,线程 B 也读到旧值并写回,A 再写回就把 B 的结果覆盖,导致少加。volatile 只保证可见性和禁止重排,不保证这三步的复合原子性,救不了 i++。","params":["volatile 只保可见性,不保复合操作原子性","AtomicInteger.incrementAndGet() 内部用 CAS 保证原子","synchronized 或 ReentrantLock 同步代码块可保证原子"],"pitfalls":["常见误以为 volatile int i; 能让 i++ 安全","读写并发度高时丢更新数量少但仍存在,不要用肉眼判断","i = i+1、i += 1、i-- 都是同样的非原子复合操作"],"selfCheck":{"q":"用 volatile int i 修饰后,i++ 还会丢更新吗?","a":"会。volatile 只保证可见性和有序性,不保证复合操作的原子性。i++ 仍可拆成读-改-写三步,线程切换会丢更新。要安全需 AtomicInteger 或 synchronized。"}}', 42, 1793250399476, 1793253102878),
	(44, 2, 1, 'CAS · 高竞争下的适用性与放弃策略', 'Java多线程锁机制', 'medium', '{"name":"CAS · 高竞争下的适用性与放弃策略","category":"Java多线程锁机制","priority":"medium","summary":"CAS 低竞争高效，高竞争下自旋空转浪费 CPU，需退化为锁或分段","interview":"CAS 在高并发竞争激烈时有什么问题？应该怎么取舍？","principle":"CAS 通过比较并交换无锁更新，失败则循环重试。竞争激烈时大量线程同时失败自旋，CPU 空转且只有少数成功，吞吐量反而低于 synchronized。此时应改用互斥锁让线程阻塞排队，或用 LongAdder、分段 CAS、限次重试后退避等手段降低竞争。","params":["LongAdder 把热点值拆成多段累加，读取时再汇总，适合写多读少","JDK8 后 synchronized 有锁升级和自适应自旋，低竞争下不一定比 CAS 差","可用循环次数阈值或退避策略限制无脑自旋"],"pitfalls":["ABA 问题：值改回原样后 CAS 成功，但中间过程丢失，需版本号（AtomicStampedReference）","自旋重试无上限在高竞争下会严重浪费 CPU，甚至引发活锁","CAS 适合简单计数、状态位等单变量场景，复杂复合操作仍需锁"],"selfCheck":{"q":"什么时候该放弃 CAS 改用锁？","a":"竞争激烈、CAS 多次失败自旋空转、需要保证多个变量的原子复合操作，或需要公平排队时，改用 synchronized/Lock 更合适。"}}', 43, 1793250399476, 1793253102878),
	(45, 2, 1, 'Lock · tryLock 与带超时 tryLock 的区', 'Java多线程锁机制', 'medium', '{"name":"Lock · tryLock 与带超时 tryLock 的区","category":"Java多线程锁机制","priority":"medium","summary":"tryLock 立即返回成败，带超时的 tryLock 会等一段时间再放弃。","interview":"tryLock() 和 tryLock(long, TimeUnit) 有什么区别？","principle":"tryLock() 不进等待队列，直接尝试抢锁，抢不到立刻返回 false；带超时版本先试一次，失败后进队列自旋+挂起，在超时时间内等锁，期间可被中断，超时返回 false。","params":["tryLock() 无参版不响应中断","tryLock(long time, TimeUnit unit) 超时后返回 false","抢到锁返回 true"],"pitfalls":["无参 tryLock 可能活锁或饿死，需自己控制重试","带超时版等待期间可被 interrupt，抛 InterruptedException","tryLock 抢到锁后必须在 finally 里 unlock，否则死锁"],"selfCheck":{"q":"为什么说 tryLock() 不适合替代公平锁？","a":"tryLock() 直接插队抢锁，无视等待队列顺序，破坏公平性，可能导致排队线程长期拿不到锁（饥饿）。"}}', 44, 1793250399476, 1793253102878),
	(46, 2, 1, 'synchronized · 方法锁与静态方法锁的对象差异', 'Java多线程锁机制', 'medium', '{"name":"synchronized · 方法锁与静态方法锁的对象差异","category":"Java多线程锁机制","priority":"medium","summary":"实例方法锁当前对象this，静态方法锁Class对象，锁粒度不同不能互斥。","interview":"synchronized修饰实例方法和静态方法时，锁的对象分别是什么？它们会互斥吗？","principle":"synchronized修饰实例方法时，锁的是当前实例对象this；修饰静态方法时，锁的是该类的Class对象（如MyClass.class）。两者是不同的Monitor对象，因此同一实例的实例方法和静态方法不会互斥，可同时进入。","params":["实例方法锁：this","静态方法锁：MyClass.class","同步代码块：显式指定任意对象作为锁"],"pitfalls":["静态方法与实例方法不互斥，想互斥需都锁Class对象或都锁同一实例","锁Class对象是类级别，所有实例共享，会成为并发瓶颈","不要锁String常量或Integer等共享缓存对象，容易和其他代码互相干扰"],"selfCheck":{"q":"一个类中synchronized实例方法和synchronized静态方法，在多线程下能否同时执行？","a":"可以。实例方法锁this对象，静态方法锁Class对象，两把不同的锁互不影响，因此能同时进入并发执行。"}}', 45, 1793250399476, 1793253102878),
	(47, 2, 1, '自增操作 · 非原子导致计数丢失', '多线程基础', 'medium', '{"name":"自增操作 · 非原子导致计数丢失","category":"多线程基础","priority":"medium","summary":"i++ 是读-改-写三步，多线程下会互相覆盖导致计数丢失。","interview":"为什么多线程下 int i++ 会比预期结果小？","principle":"i++ 分三步：读取 i、加 1、写回。两个线程可能读到同一个旧值，各自加 1 后写回，结果只加了一次。解决办法：synchronized、ReentrantLock、AtomicInteger 的 CAS 自增。","params":["AtomicInteger.incrementAndGet() 用 CAS 实现原子自增","高并发下 AtomicLong/LongAdder 性能更好","LongAdder 分段累加，适合读多写少"],"pitfalls":["volatile 只保证可见性，不能保证 i++ 原子性","AtomicInteger 在极高竞争下 CAS 自旋浪费 CPU，考虑 LongAdder","LongAdder 的 sum() 不是原子快照"],"selfCheck":{"q":"volatile int i; i++ 在多线程下安全吗？","a":"不安全。volatile 保证可见性和有序性，但 i++ 是读-改-写复合操作，仍会丢失更新，必须用锁或原子类。"}}', 46, 1793250399476, 1793253102878),
	(48, 2, 1, 'ReentrantLock · 可重入次数上限', 'Lock', 'medium', '{"name":"ReentrantLock · 可重入次数上限","category":"Lock","priority":"medium","summary":"ReentrantLock 可重入次数受限于 int 计数，理论上锁重入次数上限约 21 亿次。","interview":"ReentrantLock 的可重入次数有上限吗？","principle":"ReentrantLock 内部用 state（int）记录重入次数，每次 lock state+1，unlock state-1，减到 0 才真正释放锁。state 是 32 位 int，最大值 Integer.MAX_VALUE，超过会溢出报错。","params":["state 为 int 类型，上限 Integer.MAX_VALUE","每次 lock/lock 必须配对 unlock","公平锁和非公平锁都有可重入性"],"pitfalls":["lock 次数多于 unlock 会导致其他线程永远拿不到锁","unlock 次数多于 lock 会抛 IllegalMonitorStateException","实际业务几乎不会达到重入上限，但要避免 lock/unlock 不配对"]}', 47, 1793250399476, 1793253102878),
	(49, 2, 1, 'ReentrantLock 公平锁与非公平锁', 'Lock', 'medium', '{"name":"ReentrantLock 公平锁与非公平锁","category":"Lock","priority":"medium","summary":"非公平锁吞吐高但可能饥饿，公平锁按序排队无饥饿但吞吐低。","interview":"ReentrantLock 公平锁和非公平锁有什么区别？怎么选？","principle":"非公平锁在 lock 时先尝试插队 CAS 抢 state，失败才进队列；公平锁先检查队列里有没有前驱，有就乖乖排队。默认非公平。吞吐差异来自插队省去唤醒线程的上下文切换。","params":["构造 new ReentrantLock(true) 为公平，默认 false 非公平","tryLock() 不排队，直接抢一次","state 可重入，同线程重入计数+1"],"pitfalls":["公平锁吞吐明显低，别默认上公平","非公平可能让排队线程长期抢不到，不适合对延迟敏感场景","tryLock() 本质非公平，公平参数对它无效"],"selfCheck":{"q":"为什么默认用非公平锁？","a":"非公平线程能直接插队获取锁，避免刚释放锁就唤醒下一个线程带来的上下文切换开销，整体吞吐更高。"}}', 48, 1793250399476, 1793253102878),
	(50, 2, 1, 'Condition 等待队列与 signal 精准唤醒', 'Lock', 'medium', '{"name":"Condition 等待队列与 signal 精准唤醒","category":"Lock","priority":"medium","summary":"每个 Condition 对应一个等待队列，signal 只唤醒该队列上的一个线程，实现精准唤醒。","interview":"Condition 的 await/signal 和 wait/notify 有什么区别？怎么实现精准唤醒？","principle":"Lock 可创建多个 Condition，每个 Condition 维护自己的等待队列。await 释放锁并入队阻塞，signal 从该队列取一个线程移入同步队列去抢锁，故只唤醒指定条件的线程。","params":["Condition 由 lock.newCondition() 创建","可创建多个实现按条件分组唤醒","signalAll 唤醒该队列全部线程"],"pitfalls":["signal 调用前必须持有该 Lock，否则抛 IllegalMonitorStateException","await 会释放锁，被唤醒后仍需重新抢锁","在 await 之前调用 signal，该信号会丢失"],"selfCheck":{"q":"为什么 Condition 能做到精准唤醒而 wait/notify 不能？","a":"因为每个 Condition 有独立等待队列，signal 只作用于该队列；而 wait/notify 共用对象的单一等待队列，notify 会随机唤醒一个等待线程。"}}', 49, 1793250399476, 1793253102878),
	(51, 2, 1, 'synchronized · 竞态条件导致重复扣款', '多线程问题', 'medium', '{"name":"synchronized · 竞态条件导致重复扣款","category":"多线程问题","priority":"medium","summary":"多线程读改写共享余额无同步，导致扣款次数超过余额。","interview":"为什么高并发下会出现重复扣款？怎么用 synchronized 解决？","principle":"扣款是非原子的三步：读余额、判断、写回。两个线程同时读到 100，各自判断够扣、各自写回 90，实际扣了两次钱。把读-判-写整段放进 synchronized(this) 或 synchronized 方法，同一时刻只有一个线程能执行，天然互斥+可见性，问题消失。","params":["synchronized 方法锁 this，static 方法锁 Class 对象","锁粒度越细吞吐越好，别用全局锁","CAS 版可用 AtomicInteger.decrementAndGet 判断余额"],"pitfalls":["锁对象要一致，synchronized(this) 和 synchronized(另一对象) 不互斥","只锁写不锁读还是会脏读，读也要在同一把锁内","分布式多实例下 JVM 锁无效，需要数据库乐观锁或分布式锁"],"selfCheck":{"q":"只把余额写回那行加 synchronized 行不行？","a":"不行。读-判断-写回三步必须整体互斥，只锁写回仍然会让多个线程基于同一份旧余额判断，照样重复扣款。"}}', 50, 1793250399476, 1793253102878),
	(52, 2, 1, 'wait/notify · 唤醒后仍需竞争锁', '线程协作', 'medium', '{"name":"wait/notify · 唤醒后仍需竞争锁","category":"线程协作","priority":"medium","summary":"notify 唤醒后线程不直接执行，需重新竞争对象监视器锁，抢到才能继续。","interview":"notify 唤醒的线程是立刻执行吗？为什么 wait 要放在 while 循环里？","principle":"wait 让线程释放锁并进入对象等待队列；notify 把它移入同步队列参与锁竞争。被唤醒不代表拿到锁，要等 notify 线程退出同步块释放锁后才能抢到。因此 wait 必须用 while 检查条件，防止虚假唤醒或条件已被他人改掉。","params":["wait/notify 必须在 synchronized 块内调用","wait 释放锁，sleep 不释放锁","notifyAll 唤醒全部等待线程"],"pitfalls":["用 if 判断条件会因虚假唤醒或条件失效出错，应用 while","notify 后被唤醒线程未必立即执行，仍要排队抢锁","在持有锁的代码里漏掉 notify 或条件判断易死锁"],"selfCheck":{"q":"notify 之后被唤醒的线程什么时候能继续运行？","a":"当 notify 线程退出 synchronized 块释放监视器锁后，被唤醒线程与其他线程竞争锁，抢到锁才能继续执行。"}}', 51, 1793250399476, 1793253102878),
	(53, 2, 2, 'ThreadLocal · 基本概念与用法', 'ThreadLocal 基础与用法', 'high', '{"name":"ThreadLocal · 基本概念与用法","category":"ThreadLocal 基础与用法","priority":"high","summary":"ThreadLocal 让每个线程持有独立变量副本，实现线程内数据隔离，无需加锁。","interview":"ThreadLocal 是什么？和 synchronized 解决线程安全的思路有什么区别？","principle":"每个 Thread 内有一个 ThreadLocalMap，key 是 ThreadLocal 对象（弱引用），value 是该线程的副本。读写都以当前线程为入口取自己的 map，天然无竞争。synchronized 是让多线程排队访问同一份数据；ThreadLocal 是让各线程各用各的数据。","params":["new ThreadLocal<>() 创建实例，常 static final 共享","initialValue() 或 withInitial(Supplier) 提供初始值","get()/set()/remove() 三个核心操作"],"pitfalls":["数据需要线程间共享或传递结果时不能用 ThreadLocal，会丢数据","子线程默认拿不到父线程的 ThreadLocal 值，需用 InheritableThreadLocal","与 synchronized 取舍：隔离副本用 ThreadLocal，共享可变状态必须加锁"],"selfCheck":{"q":"ThreadLocal 和 synchronized 都能解决线程安全，什么时候选谁？","a":"数据可按线程隔离、互不共享时选 ThreadLocal（无锁、快）；数据必须被多线程共同读写或要跨线程传递结果时选 synchronized/锁。"}}', 0, 1793607244277, 1793607405709),
	(54, 2, 2, 'ThreadLocal · 核心 API', 'ThreadLocal 基础与用法', 'medium', '{"name":"ThreadLocal · 核心 API","category":"ThreadLocal 基础与用法","priority":"medium","summary":"get/set/remove 三件套，配合 initialValue 初始化；用完必须 remove 防内存泄漏。","interview":"ThreadLocal 为什么用完要 remove？不 remove 在线程池里会怎样？","principle":"get 时若 map 中无值则调 initialValue 填入；set 写入当前线程 map；remove 删除当前线程对应 entry。ThreadLocalMap 的 key 是弱引用，GC 后 key 变 null，但 value 仍被 Entry 引用，若线程长期存活（如线程池核心线程），value 一直不释放，造成内存泄漏，还会污染下次复用该线程的任务。","params":["initialValue() 默认返回 null，可重写或用 withInitial","remove() 清理当前线程的副本","get() 首次访问触发初始化"],"pitfalls":["用完不 remove：内存泄漏 + 线程复用时读到上个任务的脏数据","排查思路：heap dump 看 Thread 对象下 ThreadLocalMap 的 Entry 数量、value 类型与持有链","try/finally 里 remove，保证异常路径也能清理"],"selfCheck":{"q":"线程池里忘了 remove 会出什么问题？怎么排查？","a":"一是 value 一直挂在长生命周期线程上导致内存泄漏；二是复用线程时 get 到上个任务残留值出错。排查用 jmap/heap dump 看 ThreadLocalMap 的 Entry 与引用链，或加断点/日志打印 map size。"}}', 1, 1793607244277, 1793607405709),
	(55, 2, 2, 'ThreadLocal · 典型应用场景', 'ThreadLocal 基础与用法', 'medium', '{"name":"ThreadLocal · 典型应用场景","category":"ThreadLocal 基础与用法","priority":"medium","summary":"典型场景是用户上下文、事务、日期格式化、跨层传参，线程池下替代层层透传参数。","interview":"ThreadLocal 适合用在哪些场景？线程池里用它要注意什么？","principle":"当一个数据在同一线程内被多层方法频繁使用（如当前登录用户、请求 ID、SimpleDateFormat、数据库连接），用 ThreadLocal 一次 set、处处 get，避免方法签名层层加参。在连接池/线程池下，判断标准：数据是线程私有且随任务结束应失效 → 用 ThreadLocal 并在任务结束 remove；数据需跨任务或跨线程共享 → 不要用，改用参数传递或共享对象加锁。","params":["典型：用户上下文 UserContext、请求 traceId、ThreadLocal<SimpleDateFormat>","连接场景：ThreadLocal<Connection> 绑定事务连接（如 Spring 事务同步）","线程池中优先考虑任务开始 set、结束 remove"],"pitfalls":["线程池复用线程：任务必须自己 set，不要指望继承或残留值","任务间需要传值时改用参数/返回值，别用 ThreadLocal 硬传","连接池里把连接放 ThreadLocal 要确保归还，否则连接泄漏"],"selfCheck":{"q":"什么时候该用 ThreadLocal 而不是方法传参？","a":"数据在同一线程内被多层方法高频读取、且属于线程私有（如上下文、格式化器、事务连接）时用 ThreadLocal 省去层层透传；数据量大、需要显式生命周期或跨线程时仍应传参。"}}', 2, 1793607244277, 1793607405709),
	(56, 2, 2, 'ThreadLocal · 存储结构', 'ThreadLocal 原理与陷阱', 'high', '{"name":"ThreadLocal · 存储结构","category":"ThreadLocal 原理与陷阱","priority":"high","summary":"ThreadLocal 用 Thread 自己的 ThreadLocalMap 存值，key 是弱引用的 ThreadLocal 对象。","interview":"ThreadLocal 是怎么实现线程隔离的？key 为什么用弱引用？","principle":"每个 Thread 有个 ThreadLocalMap，key 为 ThreadLocal 实例（弱引用），value 为存的值。get/set 通过当前线程拿到自己的 map，因此线程间互不干扰。key 用弱引用是为了让 ThreadLocal 对象在不再被外部引用时能被 GC 回收，配合 remove 或 expunge 避免泄漏。","params":["ThreadLocalMap 初始容量 16，负载因子 2/3","key 为 WeakReference<ThreadLocal<?>>"],"pitfalls":["弱引用只作用于 key，value 仍是强引用","map 是 Thread 持有而非 ThreadLocal 持有，生命周期跟线程走"],"selfCheck":{"q":"ThreadLocalMap 存在哪里？key 和 value 的引用类型分别是什么？","a":"存在 Thread 对象里（Thread.threadLocals）。key 是弱引用的 ThreadLocal 实例，value 是强引用的业务对象；key 可被 GC，value 不会自动回收。"}}', 3, 1793607244277, 1793607405709),
	(57, 2, 2, 'ThreadLocal · 内存泄漏', 'ThreadLocal 原理与陷阱', 'high', '{"name":"ThreadLocal · 内存泄漏","category":"ThreadLocal 原理与陷阱","priority":"high","summary":"key 被 GC 回收后 value 仍被 map 强引用，线程不死则 value 泄漏。","interview":"ThreadLocal 为什么会内存泄漏？怎么预防？","principle":"ThreadLocal 对象不再被引用后 key 被 GC 清掉，但 entry 的 value 还被 ThreadLocalMap 强引用，只要线程存活（如线程池常驻线程），value 就无法回收，累积导致泄漏。set/get 触发清理过期 entry 只是缓解，不是保证。预防办法：用完 finally 里 remove()，或用 try-with-resources 风格封装，配合监控扫描。","params":["线程池核心线程常驻，泄漏风险最高","清理阈值：启发式扫描 + 连续清理 stale entry"],"pitfalls":["「key 是弱引用所以不会泄漏」是错的","只在 finally remove 才可靠，依赖 GC 触发清理不可靠"],"selfCheck":{"q":"ThreadLocal 泄漏的必要条件是什么？","a":"ThreadLocal 实例失去强引用被 GC，且线程长期存活、value 未 remove，导致 entry 的 value 被 map 强引用而无法回收。"}}', 4, 1793607244277, 1793607405709),
	(58, 2, 2, 'ThreadLocal · 线程池场景下的陷阱', 'ThreadLocal 原理与陷阱', 'medium', '{"name":"ThreadLocal · 线程池场景下的陷阱","category":"ThreadLocal 原理与陷阱","priority":"medium","summary":"线程池复用线程会让 ThreadLocal 残留脏数据，InheritableThreadLocal 也无法传给提交的任务。","interview":"ThreadLocal 在线程池里有什么坑？InheritableThreadLocal 能解决吗？","principle":"线程池线程被复用，上个任务 set 的值若不 remove，会带到下一个任务，产生脏数据或泄漏。InheritableThreadLocal 只在「创建线程时」从父线程复制，线程池里线程早已创建，提交任务时不会复制，故失效。彻底方案是 TransmittableThreadLocal 之类的包装，在任务提交与执行时显式抓取/重放上下文。","params":["线程池线程复用：ThreadLocal 值跨任务残留","InheritableThreadLocal 仅在线程创建时复制"],"pitfalls":["用完不 remove 会污染后续任务","InheritableThreadLocal 对线程池无效，别误以为解决了传递"],"selfCheck":{"q":"为什么 InheritableThreadLocal 传不到线程池里的任务？","a":"它只在线程创建时从父线程复制，线程池里的线程早就存在，提交任务时不会重新复制，所以子任务读到的仍是线程创建时的旧值。"}}', 5, 1793607244277, 1793607405709),
	(59, 2, 2, 'JVM 内存区域 · 划分与职责', 'JVM 内存模型（运行时数据区）', 'medium', '{"name":"JVM 内存区域 · 划分与职责","category":"JVM 内存模型（运行时数据区）","priority":"medium","summary":"运行时数据区分五块：堆、方法区共享，虚拟机栈、本地方法栈、程序计数器线程私有。","interview":"JVM 运行时数据区怎么划分？哪些线程私有、哪些共享？","principle":"堆放对象实例，方法区放类元数据与常量；虚拟机栈放栈帧（局部变量、操作数栈），本地方法栈服务 Native，程序计数器记录当前指令地址。私有区随线程生灭，共享区由 GC 管理。","params":["堆与方法区共享，其余三块线程私有","栈默认约 1MB，可用 -Xss 调整","堆大小用 -Xms / -Xmx 设定"],"pitfalls":["StackOverflowError 来自栈深度超限（递归过深）","OutOfMemoryError 分堆 OOM 与元空间 OOM，不要混为一谈","程序计数器是唯一不会 OOM 的区域"],"selfCheck":{"q":"哪些区域可能抛 OOM？程序计数器会不会？","a":"堆、方法区（元空间）、直接内存可能 OOM；虚拟机栈/本地方法栈既可能 StackOverflow 也可能 OOM（栈动态扩展时）；程序计数器是唯一不会 OOM 的区域。"}}', 6, 1793607244277, 1793607405709),
	(60, 2, 2, 'JVM 内存区域 · 堆的结构', 'JVM 内存模型（运行时数据区）', 'medium', '{"name":"JVM 内存区域 · 堆的结构","category":"JVM 内存模型（运行时数据区）","priority":"medium","summary":"堆分新生代（Eden + 两个 Survivor）与老年代，分代是为了按对象存活时间用不同回收策略。","interview":"堆为什么要分代？对象什么情况下会进入老年代？","principle":"绝大多数对象朝生夕死，放 Eden 用复制算法快速回收；长期存活对象晋升老年代用标记-整理。Minor GC 后存活对象进 Survivor，年龄加 1，达到阈值（默认 15）晋升；大对象直接进老年代。","params":["新生代默认占堆 1/3，Eden:S0:S1 = 8:1:1","晋升年龄阈值默认 15（-XX:MaxTenuringThreshold）","大对象阈值由 -XX:PretenureSizeThreshold 控制"],"pitfalls":["动态年龄判定：Survivor 中同龄对象总和超一半即可提前晋升","大对象直接分配老年代，避免在新生代来回复制","-XX:SurvivorRatio 调 Eden/Survivor 比例，比例失衡会加剧晋升"],"selfCheck":{"q":"除了年龄到 15，还有哪些情况对象会进老年代？","a":"大对象直接进入老年代；Survivor 中相同年龄对象总大小超过 Survivor 一半，该年龄及以上对象提前晋升；Minor GC 后 Survivor 放不下的对象也会直接进老年代。"}}', 7, 1793607244277, 1793607405709),
	(61, 2, 2, 'JVM 内存区域 · 方法区与元空间', 'JVM 内存模型（运行时数据区）', 'medium', '{"name":"JVM 内存区域 · 方法区与元空间","category":"JVM 内存模型（运行时数据区）","priority":"medium","summary":"JDK8 起方法区实现改为元空间，用本地内存；字符串常量池移到堆中。","interview":"方法区和永久代、元空间什么关系？字符串常量池放哪？","principle":"方法区是 JVM 规范，永久代（JDK7 前）和元空间（JDK8 后）是实现。永久代用堆内内存、大小固定，类元数据多时易 OOM: PermGen；元空间用本地内存、默认可自动扩展，缓解类元数据溢出。字符串常量池 JDK7 起从方法区移到堆，便于 GC 回收。","params":["元空间默认上限为本地内存，可用 -XX:MaxMetaspaceSize 限制","JDK7 中字符串常量池已在堆，但永久代仍存在","-XX:MetaspaceSize 设初始阈值，触发 Full GC 与卸载"],"pitfalls":["元空间不是无限的，不限制可能耗尽本地内存导致 OS 层问题","类加载器泄漏会导致元空间 OOM（如热部署）","-XX:PermSize / -XX:MaxPermSize 在 JDK8 已失效"],"selfCheck":{"q":"为什么把字符串常量池从永久代移到堆？","a":"永久代大小固定、回收 Full GC 才触发，常量过多易 OOM: PermGen；堆由成熟 GC 管理、更容易回收字符串，也便于后续字符串去重等优化。"}}', 8, 1793607244277, 1793607405709),
	(62, 2, 2, 'JVM 内存区域 · 栈与栈帧', 'JVM 内存模型（运行时数据区）', 'medium', '{"name":"JVM 内存区域 · 栈与栈帧","category":"JVM 内存模型（运行时数据区）","priority":"medium","summary":"线程私有的虚拟机栈，方法调用入栈、返回出栈，栈帧是每次调用的内存单元。","interview":"递归为什么会 StackOverflowError？栈里都存什么？","principle":"每个线程有一块私有虚拟机栈，方法调用时压入栈帧，返回时弹出。栈帧含局部变量表、操作数栈、动态链接、返回地址等。递归每调用一层就新增一个栈帧，层数过深超过栈容量时抛 StackOverflowError。","params":["栈容量可由 -Xss 设置，默认约 512KB~1MB，视 JVM 而定","局部变量表以「槽位 slot」为单位，32 位类型占 1 槽，64 位（long/double）占 2 槽"],"pitfalls":["递归改迭代是解决栈溢出的常规思路","StackOverflowError 是 Error，不是 Exception，不要用 catch(Exception) 兜底"]}', 9, 1793607244277, 1793607405709),
	(63, 2, 2, '对象内存布局 · 三部分组成', '对象内存布局', 'medium', '{"name":"对象内存布局 · 三部分组成","category":"对象内存布局","priority":"medium","summary":"对象由对象头、实例数据、对齐填充三部分构成。","interview":"一个 Java 对象在内存里占哪些部分？为什么要对齐填充？","principle":"对象头存元信息（Mark Word、类型指针，数组还有长度），实例数据存各字段值（父类字段在前），对齐填充让对象总大小为 8 字节的整数倍。对齐填充的存在是因为 CPU 按字长访问内存，对齐后读取效率高、避免跨缓存行访问。","params":["对齐基准通常为 8 字节","对象默认开启压缩指针（-XX:+UseCompressedOops）可减小对象头"],"pitfalls":["对齐填充不是必须内容，大小凑够就为 0 字节","空对象大小通常为 16 字节（含对象头）"]}', 10, 1793607244277, 1793607405709),
	(64, 2, 2, '对象内存布局 · 对象头与 Mark Word', '对象内存布局', 'medium', '{"name":"对象内存布局 · 对象头与 Mark Word","category":"对象内存布局","priority":"medium","summary":"对象头存哈希码、GC 分代年龄、锁状态等运行时数据，其中 Mark Word 会随锁升级变化。","interview":"Mark Word 是什么？锁升级在它上面怎么体现？","principle":"对象头主要包括 Mark Word 和类型指针。Mark Word 存 hashCode、GC 年龄、锁标志位等，为节省空间会复用位。锁升级路径为无锁→偏向锁→轻量级锁→重量级锁，每次升级会改变 Mark Word 中的锁标志位和存储内容（如指向锁记录或 monitor 的指针）。","params":["Mark Word 大小随平台：32 位 JVM 约 32 位，64 位 JVM 约 64 位","hashCode 在加锁后会被挪到 monitor 中保存"],"pitfalls":["Mark Word 是复用设计，一个对象不能同时存 hashCode 和偏向锁信息","锁状态位只占几位，不要误以为 Mark Word 是独立字段结构"]}', 11, 1793607244277, 1793607405709),
	(65, 2, 2, '对象内存布局 · 对象大小与计算', '对象内存布局', 'medium', '{"name":"对象内存布局 · 对象大小与计算","category":"对象内存布局","priority":"medium","summary":"对象由对象头、实例数据、对齐填充组成，大小需 8 字节对齐。","interview":"一个对象占多少字节？怎么算？","principle":"对象头含 Mark Word 与类型指针（数组还有长度），实例数据存字段，padding 补齐到 8 字节倍数。64 位 JVM 开启压缩指针后，类型指针与引用由 8 字节压到 4 字节。","params":["Mark Word 64 位下约 8 字节","压缩指针开启后类型指针 4 字节","对象总大小按 8 字节对齐"],"pitfalls":["忽略对齐填充直接相加会算错","基本类型与引用大小不同，boolean/byte 1 字节","压缩指针关闭时大小可能翻倍"],"selfCheck":{"q":"空对象 new Object() 占多少字节？","a":"64 位开启压缩指针时是 16 字节：Mark Word 8 字节 + 类型指针 4 字节 + 4 字节对齐填充。"}}', 12, 1793607244277, 1793607405709),
	(66, 2, 2, '对象内存布局 · 访问定位', '对象内存布局', 'low', '{"name":"对象内存布局 · 访问定位","category":"对象内存布局","priority":"low","summary":"访问对象分句柄和直接指针两种，HotSpot 用直接指针。","interview":"Java 是怎么通过 reference 找到对象的？两种方式有什么区别？","principle":"句柄方式：reference 指向句柄池，句柄含对象实例指针和类型指针，对象移动只改句柄；直接指针：reference 直指对象，需在对象头带类型信息，少一次跳转但 GC 移动需改引用。","params":["句柄方式访问多一次指针跳转","直接指针访问更快","HotSpot 默认直接指针"],"pitfalls":["句柄方式稳定但速度慢，不要说反","直接指针下 GC 移动对象要更新 reference","Android 等部分 VM 用句柄，别绝对化"],"selfCheck":{"q":"为什么 HotSpot 选直接指针？","a":"少一次指针定位，访问更快；虽然 GC 移动对象时需更新引用，但整体开销更小，符合 HotSpot 追求性能的取向。"}}', 13, 1793607244277, 1793607405709),
	(67, 2, 2, '类加载 · 双亲委派模型', '类加载机制', 'high', '{"name":"类加载 · 双亲委派模型","category":"类加载机制","priority":"high","summary":"类加载先委派父加载器，父加载器无法加载才自己加载。","interview":"什么是双亲委派？为什么需要它？","principle":"收到加载请求先交给父加载器，递归向上到启动类加载器；父加载器加载失败才由自身加载。保证 java.lang.Object 等核心类由启动类加载器加载，防止被篡改，并确保同一个类在不同加载器下唯一。","params":["启动类加载器 → 扩展类加载器 → 应用类加载器","父加载器加载失败才由子加载器尝试","类的唯一性 = 全限定名 + 加载器"],"pitfalls":["双亲是语义上的父子关系，不是继承","父加载器加载失败会抛异常再由子加载器加载","SPI、Tomcat、OSGi 会打破双亲委派"],"selfCheck":{"q":"双亲委派如何防止自定义 java.lang.String 篡改核心类？","a":"加载请求先委派到启动类加载器，核心类由它加载成功，自定义类根本不会被加载，从而保证核心 API 不被替换。"}}', 14, 1793607244277, 1793607405709),
	(68, 2, 2, '类加载 · 生命周期与阶段', '类加载机制', 'medium', '{"name":"类加载 · 生命周期与阶段","category":"类加载机制","priority":"medium","summary":"类加载含加载、验证、准备、解析、初始化五阶段，初始化才真正执行静态代码。","interview":"哪些情况会触发类的初始化，哪些不会？","principle":"加载把字节流变成方法区的 Class 对象；验证校验字节码；准备为静态变量分配内存并赋零值（final 常量直接赋值）；解析把符号引用换成直接引用；初始化执行 <clinit>，即静态变量赋值与 static 块。","params":["准备阶段静态变量赋零值，final 常量赋真实值","初始化执行 <clinit>，父类先于子类"],"pitfalls":["new、访问静态字段（非 final 常量）、反射、主类会触发初始化","通过数组定义引用类、引用常量、子类引用父类静态字段不触发子类初始化"],"selfCheck":{"q":"通过 `SubClass[] arr = new SubClass[1]` 会触发 SubClass 初始化吗？","a":"不会。数组只触发生成的 [LSubClass; 类的初始化，不触发元素类的初始化，属于典型被动引用。"}}', 15, 1793607244277, 1793607405709),
	(69, 2, 2, '类加载 · 打破双亲委派', '类加载机制', 'medium', '{"name":"类加载 · 打破双亲委派","category":"类加载机制","priority":"medium","summary":"双亲委派可被线程上下文类加载器或重写 loadClass 打破，但有隔离与安全代价。","interview":"怎么打破双亲委派？这么做有什么代价？","principle":"默认 loadClass 先委托父加载器，父加载失败才自己加载。打破方式：一、JNDI/JDBC 等用 Thread.currentThread().getContextClassLoader() 让父加载器反向调用子加载器（SPI）；二、自定义 ClassLoader 重写 loadClass，先自己加载再委托（Tomcat、热部署）。","params":["核心 API：loadClass / findClass，重写后者更安全","线程上下文类加载器可由父线程设置并被子线程继承"],"pitfalls":["打破后可能出现同名类被不同加载器加载，ClassCastException","重写 loadClass 易破坏隔离，Tomcat 靠它实现 webapp 隔离却也常踩 NoClassDefFoundError"],"selfCheck":{"q":"SPI 场景为什么必须用线程上下文类加载器？","a":"SPI 接口由启动类加载器加载，但实现类在应用 classpath 下，启动加载器看不见；用线程上下文类加载器（默认是应用类加载器）反向加载实现类。"}}', 16, 1793607244277, 1793607405709),
	(70, 2, 2, '场景 · 线程池上下文传递', '综合与场景串联', 'medium', '{"name":"场景 · 线程池上下文传递","category":"综合与场景串联","priority":"medium","summary":"线程池跨线程传上下文：ThreadLocal 不行、InheritableThreadLocal 只对新线程有效、显式传参最稳。","interview":"线程池里怎么把用户信息/链路 ID 传给任务线程？三者怎么取舍？","principle":"ThreadLocal 存线程私有变量，线程池线程复用会导致脏数据或拿不到值。InheritableThreadLocal 在 Thread 构造时从父线程复制，但线程池线程只创建一次，后续提交的任务不会继承。因此要么用 TransmittableThreadLocal/包装 Runnable 显式捕获并回放，要么任务参数显式传递。","params":["ThreadLocal 建议用 static final 并配 remove()","InheritableThreadLocal 仅在 new Thread 时复制一次"],"pitfalls":["线程池复用线程导致 ThreadLocal 泄漏与脏上下文","用完不 remove，线程池长生命周期线程会堆积对象甚至内存泄漏"],"selfCheck":{"q":"为什么 InheritableThreadLocal 在线程池里失效？","a":"线程池的工作线程只创建一次并反复复用，只有创建那一刻从父线程复制了上下文，后续提交任务时不会再复制，所以拿不到提交线程的值。"}}', 17, 1793607244277, 1793607405709),
	(71, 2, 2, '场景 · 内存问题排查思路', '综合与场景串联', 'medium', '{"name":"场景 · 内存问题排查思路","category":"综合与场景串联","priority":"medium","summary":"内存问题先分堆内堆外，再结合对象布局和分代判断方向。","interview":"线上出现 OOM/内存涨，你的排查思路是什么？","principle":"先区分堆内存、元空间、直接内存、线程栈。堆内看对象存活与分代：老年代涨多为长生命周期对象/泄漏，Young GC 频繁多为短命对象分配过快。再结合对象布局估算单个对象大小，看是不是大对象、膨胀的字段或 ThreadLocal 持有大 value 未清理。","params":["-Xms/-Xmx 决定堆大小","-Xmn 或分代比例影响 Young/Old 分配","-XX:MaxMetaspaceSize 限制元空间"],"pitfalls":["把直接内存/NIO 堆外泄漏当堆问题查","ThreadLocal 用完不 remove 导致 Entry value 泄漏，表象是老年代缓慢上涨","只看总量不看分代，误判泄漏方向"],"selfCheck":{"q":"老年代持续缓慢上涨、Full GC 后不降，最可能是什么？","a":"存在长生命周期对象或泄漏，常见是缓存无上限、静态集合持有、ThreadLocal 未清理，导致对象晋升老年代后不回收。"}}', 18, 1793607244277, 1793607405709),
	(72, 2, 3, '线程池 · 为什么要用', '线程池核心概念', 'high', '{"name":"线程池 · 为什么要用","category":"线程池核心概念","priority":"high","summary":"线程池用复用线程降低创建销毁开销，并提供统一的任务提交、调度、限流与监控入口。","interview":"为什么项目里要用线程池？不用直接 new Thread 不行吗？","principle":"线程创建销毁成本高、并发失控难管理。线程池预先创建核心线程并反复执行任务，同时把提交、排队、拒绝、监控集中到一处，便于限流、降级与排查。","params":["核心线程数按任务类型定（CPU 密集≈核数，IO 密集可放大）","队列容量承担削峰，太小易触发扩容或拒绝","拒绝策略与监控指标是工程落地必备"],"pitfalls":["任务极少或单次短任务，用线程池反而增加上下文切换与复杂度","CPU 密集短任务开线程池收益低，还可能因排队变慢","别为了『规范』无脑套线程池，先看并发量与任务耗时"],"selfCheck":{"q":"什么场景下不该用线程池？","a":"任务量极少、单次执行很短、CPU 密集且无并发需求时，线程池带来的调度与维护成本大于收益，直接串行或简单并发即可。"}}', 0, 1793608851223, 1793609010879),
	(73, 2, 3, '线程池 · 核心工作流程', '线程池核心概念', 'high', '{"name":"线程池 · 核心工作流程","category":"线程池核心概念","priority":"high","summary":"先建核心线程，满了入队；队列满再开非核心线程，超最大线程数才触发拒绝策略。","interview":"线程池提交一个任务后的完整处理流程是怎样的？","principle":"提交任务：当前线程数<核心线程数则新建核心线程执行；否则尝试入队；入队失败则新建非核心线程执行；超过最大线程数则执行拒绝策略。核心线程默认不会因空闲回收（除非开启 allowCoreThreadTimeOut）。","params":["corePoolSize：常驻线程数","maximumPoolSize：线程数上限","workQueue：任务队列，容量直接影响扩容与拒绝时机"],"pitfalls":["核心线程数没满时直接新建线程，不会先入队","队列无界（如 LinkedBlockingQueue）会让 maximumPoolSize 形同虚设，永不扩容","队列容量太小会过早触发扩容甚至拒绝"],"selfCheck":{"q":"为什么队列用无界队列时最大线程数不起作用？","a":"因为任务永远能入队成功，流程走不到新建非核心线程那一步，线程数恒不超过核心数，队列堆积可能导致 OOM。"}}', 1, 1793608851223, 1793609010879),
	(74, 2, 3, '线程池 · 线程复用原理', '线程池核心概念', 'medium', '{"name":"线程池 · 线程复用原理","category":"线程池核心概念","priority":"medium","summary":"池内线程循环从队列取任务执行，不用重复 start，一个线程跑多个任务。","interview":"线程池是怎么做到线程复用的？和 Thread.start 有什么区别？","principle":"Thread.start 会真正启动一条新线程且不可重复调用；线程池里的 Worker 线程启动一次后进入循环，不断从阻塞队列 take/poll 任务并 run，从而复用同一 OS 线程执行多个任务，省去创建销毁成本。","params":["submit/execute 只是把任务投递到池中，由池内线程取出执行","Worker 数量由核心/最大线程数控制"],"pitfalls":["不能对 submit 返回的任务或池内线程自己调用 start，会抛 IllegalThreadStateException","任务的 run 是被 Worker 线程调用的，调用者线程不会阻塞","调用 shutdown 后仍可复用已建线程完成队列余量，但不再接收新任务"],"selfCheck":{"q":"为什么线程池里不能对任务再自己调用 start？","a":"池内 Worker 线程已经启动过并循环调用任务的 run；Thread.start 只能调用一次，重复调用会抛 IllegalThreadStateException，且线程生命周期由池管理。"}}', 2, 1793608851223, 1793609010879),
	(75, 2, 3, '线程池 · submit 与 execute 区别', '线程池核心概念', 'medium', '{"name":"线程池 · submit 与 execute 区别","category":"线程池核心概念","priority":"medium","summary":"execute 直接抛异常，submit 返回 Future 并吞异常，异常要在 get 时才暴露。","interview":"线程池的 submit 和 execute 有什么区别？submit 提交的任务抛异常会怎样？","principle":"execute 提交 Runnable，异常直接抛给线程的 UncaughtExceptionHandler 或导致线程结束；submit 提交 Callable/Runnable，返回 FutureTask，任务里抛的异常被 FutureTask 内部捕获并记录，直到调用 future.get() 才以 ExecutionException 抛出，不调用就被静默吞掉。","params":["submit 返回 Future<?>，execute 返回 void","submit 支持 Callable 有返回值，execute 只支持 Runnable"],"pitfalls":["submit 吞异常是生产事故高发点，日志里完全看不到报错","用 execute 时建议给线程池设 UncaughtExceptionHandler，否则异常只打默认堆栈","排查法：提交处统一包 try-catch 记日志，或用 CompletableFuture/包装 Runnable 显式捕获"],"selfCheck":{"q":"为什么 submit 提交的任务在控制台看不到异常日志？怎么规避？","a":"因为异常被 FutureTask 捕获存起来，只有调用 future.get() 才抛 ExecutionException。规避：任务体自己 try-catch 记日志，或强制调用 get()，或用 execute 让异常外抛。"}}', 3, 1793608851223, 1793609010879),
	(76, 2, 3, '线程池参数 · corePoolSize 与 maximumPoolSize', '七大参数', 'high', '{"name":"线程池参数 · corePoolSize 与 maximumPoolSize","category":"七大参数","priority":"high","summary":"core 是常驻线程数，max 是扩容上限，线程数在两者之间才随任务增长。","interview":"线程池的 corePoolSize 和 maximumPoolSize 怎么配？CPU 密集和 IO 密集各配多少？","principle":"提交任务时：线程数 < core 就新建核心线程；≥ core 则入队；队列满了且线程数 < max 才新建非核心线程；达到 max 后触发拒绝策略。core 线程默认一直存活（除非设 allowCoreThreadTimeOut），非核心线程空闲超 keepAliveTime 回收。","params":["CPU 密集：core = 核数 + 1","IO 密集：core = 核数 × 2 或 核数 / (1 - 阻塞系数)，阻塞系数常取 0.8~0.9","core 一般 ≤ max，max 起到突发流量的缓冲作用"],"pitfalls":["配太小：任务堆积、队列打满、接口 RT 飙升甚至触发拒绝","配太大：CPU 频繁上下文切换、内存压力大，反而更慢","只关注 core 不管 max，队列又是无界时 max 永远用不上"],"selfCheck":{"q":"8 核机器，一个任务大部分时间在等下游 RPC 返回，corePoolSize 大概配多少？","a":"IO 密集，可按 核数 × 2 = 16，或用公式 8/(1-0.8)=40 取经验值区间。压测为准，配大了浪费切换，配小了吞吐上不去。"}}', 4, 1793608851223, 1793609010879),
	(77, 2, 3, '线程池参数 · workQueue', '七大参数', 'high', '{"name":"线程池参数 · workQueue","category":"七大参数","priority":"high","summary":"workQueue 缓存待执行任务，队列容量决定了线程池何时扩容到 maximumPoolSize。","interview":"线程池的 workQueue 有什么用？为什么说无界队列有风险？队列大小和 maximumPoolSize 是什么关系？","principle":"新任务先入队（线程数已达 core），只有队列满了才继续扩容线程到 max。若队列容量很大甚至无界，队列永远填不满，maximumPoolSize 形同虚设，任务全部堆积在队列里。队列选择：ArrayBlockingQueue（有界数组）、LinkedBlockingQueue（可设容量，默认无界）、SynchronousQueue（不存储，直接移交）、PriorityBlockingQueue（优先级）。","params":["LinkedBlockingQueue 默认容量 Integer.MAX_VALUE，等于无界","ArrayBlockingQueue 必须显式指定容量","队列容量要结合 max 一起设计：先让队列缓冲一定量，满了才扩容线程"],"pitfalls":["用默认无界队列：高峰期任务无限堆积，最终 OOM 或线程池完全不扩容","队列太小 + max 太小：过早触发拒绝策略，正常流量就被拒","SynchronousQueue 不缓冲，必须配较大的 max，否则几乎立即拒绝"],"selfCheck":{"q":"为什么线程池用了无界队列，maximumPoolSize 配再大也没用？","a":"因为扩容逻辑是「队列满了才新建线程到 max」，无界队列永远填不满，线程数一直停留在 corePoolSize，任务全部堆在队列里直到内存耗尽。"}}', 5, 1793608851223, 1793609010879),
	(78, 2, 3, '线程池参数 · handler', '七大参数', 'high', '{"name":"线程池参数 · handler","category":"七大参数","priority":"high","summary":"拒绝策略决定任务无法处理时的处置方式，触发时机与队列类型强相关。","interview":"线程池的拒绝策略有哪几种？什么时候会触发拒绝？","principle":"当线程数达到 maximumPoolSize 且队列已满时触发 handler。队列选择影响触发时机：LinkedBlockingQueue 默认近乎无限容量，几乎不会拒绝，容易 OOM；SynchronousQueue 不存任务，直接交线程执行，易快速触发拒绝；ArrayBlockingQueue 容量固定，是控制拒绝的常用手段。内置四种：AbortPolicy（抛异常，默认）、CallerRunsPolicy（调用者执行）、DiscardPolicy（静默丢弃）、DiscardOldestPolicy（丢最老）。","params":["默认 new ThreadPoolExecutor.AbortPolicy()，抛 RejectedExecutionException","四种内置策略都在 java.util.concurrent 包内"],"pitfalls":["无界队列+默认拒绝策略=拒绝形同虚设，最终 OOM","DiscardPolicy/DiscardOldestPolicy 静默丢任务，易丢关键业务","CallerRunsPolicy 会拖慢调用方（如 Tomcat 线程），有反压风险"],"selfCheck":{"q":"为什么说无界队列下拒绝策略基本不会生效？","a":"无界队列几乎不会满，任务一直入队，线程数永远停在 corePoolSize，不会达到 maximumPoolSize，因此 handler 不会被触发，反而可能堆积任务导致 OOM。"}}', 6, 1793608851223, 1793609010879),
	(79, 2, 3, '线程池参数 · keepAliveTime 与 unit', '七大参数', 'medium', '{"name":"线程池参数 · keepAliveTime 与 unit","category":"七大参数","priority":"medium","summary":"keepAliveTime 定义非核心线程空闲多久后回收，unit 是其时间单位。","interview":"keepAliveTime 作用是什么？allowCoreThreadTimeOut 打开会怎样？","principle":"线程从队列 take 任务时带超时，超过 keepAliveTime 未取到任务且当前线程数 > corePoolSize，则退出销毁。allowCoreThreadTimeOut(true) 后，核心线程也走同样逻辑被回收，池可能缩到 0 线程；下次来任务会重建线程。适用于任务突发、长时间空闲想省资源的场景；不适合长期稳态任务，因为反复建线程有开销。","params":["默认 keepAliveTime=0，非核心线程一空闲立刻回收","unit 常用 TimeUnit.SECONDS / MILLISECONDS","allowCoreThreadTimeOut 默认 false"],"pitfalls":["allowCoreThreadTimeOut 打开后空闲期线程全没，突发流量要重新建线程，有延迟","keepAliveTime 只影响超过 corePoolSize 的线程，除非开启 allowCoreThreadTimeOut","unit 写错（如把秒当毫秒）会让线程存活时间与预期严重不符"],"selfCheck":{"q":"allowCoreThreadTimeOut(true) 适合什么场景？","a":"适合任务突发、空闲期长、想省资源的场景，比如定时或低频任务池；不适合稳态高 QPS 服务，因为核心线程会被反复销毁重建，增加开销和响应延迟。"}}', 7, 1793608851223, 1793609010879),
	(80, 2, 3, '线程池参数 · threadFactory', '七大参数', 'medium', '{"name":"线程池参数 · threadFactory","category":"七大参数","priority":"medium","summary":"threadFactory 负责创建线程，自定义可规范命名、优先级、守护状态，便于排查。","interview":"为什么要自定义 threadFactory？默认线程名有什么问题？","principle":"默认 Executors.defaultThreadFactory() 创建的线程名为 pool-N-thread-M，多个池交错出现时无法从线程名反推业务归属；出问题看 jstack、日志、监控都难以定位。自定义时实现 ThreadFactory.newThread，设置线程名（如 业务名-模块-序号）、优先级、是否 daemon，还可捕获 UncaughtException 统一记录异常。常用 guava 的 ThreadFactoryBuilder 或手写类。","params":["默认线程名 pool-N-thread-M，N 为池序号","优先级默认继承创建者，一般不动","常见命名：order-pool-1、pay-async-3"],"pitfalls":["不命名线程在出问题时无法从线程 dump 定位到具体池","threadFactory 抛异常会让线程创建失败，池可能卡在 core 线程数不上升","自定义工厂忘记设置 daemon，进程关闭时线程不退出，导致应用关闭卡住"],"selfCheck":{"q":"线程池排查问题时，threadFactory 命名规范有什么价值？","a":"线上通过 jstack、日志、监控看到线程名能直接反推业务归属和池类型，快速定位卡死、慢、堆积等问题；默认 pool-N-thread-M 名字无法区分池，排查成本高。"}}', 8, 1793608851223, 1793609010879),
	(81, 2, 3, '拒绝策略 · AbortPolicy', '拒绝策略', 'high', '{"name":"拒绝策略 · AbortPolicy","category":"拒绝策略","priority":"high","summary":"默认拒绝策略，抛 RejectedExecutionException，让调用方立刻感知任务被拒。","interview":"线程池默认的拒绝策略是什么？业务中抛异常怎么兜底降级？","principle":"队列满且线程数达上限时，execute 直接 new RejectedExecutionException 抛给提交线程；submit 则包装进 Future，调用 get 时才抛。抛异常不是坏事，它让问题暴露而不是静默丢失。","params":["默认策略，ThreadPoolExecutor 未指定即用它","异常类型 RejectedExecutionException"],"pitfalls":["submit 提交时异常被 Future 吞掉，不调 get 就看不到","不 try-catch 会让提交线程的业务链路直接失败"],"selfCheck":{"q":"AbortPolicy 抛出异常后，业务层一般怎么兜底？","a":"try-catch 捕获后走降级：写库排队、发 MQ 异步补偿、返回友好提示或降级结果，并打告警日志，避免用户侧直接报错。"}}', 9, 1793608851223, 1793609010879),
	(82, 2, 3, '拒绝策略 · CallerRunsPolicy', '拒绝策略', 'high', '{"name":"拒绝策略 · CallerRunsPolicy","category":"拒绝策略","priority":"high","summary":"不丢任务也不抛异常，由提交任务的线程自己执行该任务，形成天然反压。","interview":"CallerRunsPolicy 有什么风险？什么场景适合用？","principle":"拒绝时不入队，直接在调用 execute/submit 的那个线程里跑 task.run()。提交线程被占用，提交速度自然被拖慢，达到限流效果，任务一定被执行。","params":["无需额外参数，new CallerRunsPolicy() 即可","无异常抛出，不丢任务"],"pitfalls":["提交线程被阻塞，若提交方是 Tomcat 工作线程或 MQ 消费线程，会拖垮吞吐甚至触发超时","任务里若抛异常会直接打到调用线程，影响提交方主流程"],"selfCheck":{"q":"Web 应用在 Tomcat 线程里提交任务，用 CallerRunsPolicy 合适吗？","a":"不合适。会占用 Tomcat 工作线程去跑任务，降低接口并发甚至拖垮线程池；更适合后台异步或对实时性不敏感的场景，不适合在线请求链路。"}}', 10, 1793608851223, 1793609010879),
	(83, 2, 3, '拒绝策略 · DiscardPolicy 与 DiscardOldestPoli', '拒绝策略', 'medium', '{"name":"拒绝策略 · DiscardPolicy 与 DiscardOldestPoli","category":"拒绝策略","priority":"medium","summary":"静默丢任务：前者直接丢当前任务，后者丢队列最老任务再入队，都可能丢数据。","interview":"DiscardPolicy 和 DiscardOldestPolicy 有什么区别？用之前要考虑什么？","principle":"DiscardPolicy 直接吞掉新任务不执行不报错；DiscardOldestPolicy 调 poll() 弹出队头最老任务，再把新任务 offer 进队列，让任务队列保留“更新”的任务，常用于定时刷新类场景。","params":["均无异常提示，调用方无感知","DiscardOldestPolicy 保留新任务丢弃旧任务"],"pitfalls":["订单、支付等强一致业务绝对不能用，任务静默丢失且无告警","DiscardOldestPolicy 丢的是最先排队的任务，可能丢掉已等待很久、快被处理的关键任务","用前需评估：任务是否可丢、是否需要日志/监控补偿、是否幂等"],"selfCheck":{"q":"什么场景可以考虑用 DiscardOldestPolicy？用之前必须想清楚什么？","a":"适合只关心最新状态的场景，如定时刷新缓存、上报最新指标，丢旧任务无影响。用前必须确认任务可丢弃、不涉及资金与订单，且加监控告警便于发现丢弃。"}}', 11, 1793608851223, 1793609010879),
	(84, 2, 3, '自定义线程池 · 为什么不用 Executors', '业务中自定义线程池', 'high', '{"name":"自定义线程池 · 为什么不用 Executors","category":"业务中自定义线程池","priority":"high","summary":"Executors 默认参数易埋雷，自定义线程池才能主动控制容量与队列。","interview":"为什么不推荐用 Executors 创建线程池？","principle":"Executors 用无界队列或极大线程数做默认值，任务堆积时可能 OOM 或线程爆炸；自定义 ThreadPoolExecutor 显式给核心数、最大数、队列容量，把内存与并发风险量化可控，代价是需要自己算参数。","params":["newFixedThreadPool 队列无界 Integer.MAX_VALUE","newCachedThreadPool 最大线程数 Integer.MAX_VALUE","自定义时必须显式指定队列容量与拒绝策略"],"pitfalls":["不是 Executors 本身有 bug，而是默认值掩盖了容量问题","规范禁止≠一刀切：低频管理后台等可控场景用 Executors 也可以"],"selfCheck":{"q":"Executors.newFixedThreadPool 为什么可能 OOM？","a":"它用 LinkedBlockingQueue 且不传容量，默认容量 Integer.MAX_VALUE，任务入队无上限，堆积到内存耗尽也不会触发拒绝策略。"}}', 12, 1793608851223, 1793609010879),
	(85, 2, 3, '自定义线程池 · 参数怎么定', '业务中自定义线程池', 'high', '{"name":"自定义线程池 · 参数怎么定","category":"业务中自定义线程池","priority":"high","summary":"参数靠压测定基线，再用活跃线程、队列积压、拒绝次数动态微调。","interview":"线程池参数你一般怎么定？怎么判断该扩还是缩？","principle":"核心线程数参考 CPU 密集=核数+1、IO 密集=核数×(1+等待/计算) 起步；压测拿到吞吐拐点定最大线程数；队列容量控制积压上限。上线后看指标反推：队列长期积压→加核心线程或扩队列（需评估延迟），频繁拒绝→提高 max 或换更优策略，活跃线程数长期低于核心→收缩核心数省资源。","params":["核心线程数按任务类型估算后以压测校准","队列容量按可容忍延迟×平均 QPS 估算","ThreadPoolExecutor#getActiveCount、getQueue().size、getRejectedExecutionCount 为调整依据"],"pitfalls":["只看 CPU 核数套公式不够：阻塞比、下游吞吐才是决定因素","盲目扩队列会让请求排队变慢，牺牲尾延迟","max 线程数调大要考虑 DB/下游连接池上限"],"selfCheck":{"q":"监控显示队列持续增长且拒绝次数为 0，说明什么？该怎么调？","a":"说明线程处理不过来但队列还在吃内存，可能堆积 OOM。应提高核心线程数或最大线程数，必要时缩小队列容量触发拒绝策略尽早失败。"}}', 13, 1793608851223, 1793609010879),
	(86, 2, 3, '自定义线程池 · 自定义线程工厂与命名规范', '业务中自定义线程池', 'medium', '{"name":"自定义线程池 · 自定义线程工厂与命名规范","category":"业务中自定义线程池","priority":"medium","summary":"自定义 ThreadFactory 统一线程命名，让监控告警可定位到具体业务池。","interview":"你有没有自定义过线程工厂？为什么要给线程命名？","principle":"Executors.defaultThreadFactory 的线程名是 pool-N-thread-M，线上看不出归属。实现 ThreadFactory 接口，统一前缀「业务-模块-池名-序号」，可同时设置 daemon、优先级、UncaughtExceptionHandler。命名后 jstack、监控大盘、告警都能按前缀聚合，快速定位是哪个业务的池打满。","params":["命名模板：biz-module-poolname-thread-N","可选设置线程优先级与未捕获异常处理器","未捕获异常处理器兜底日志，避免静默吞异常"],"pitfalls":["别偷懒用 defaultThreadFactory，出问题难定位","线程名最好带业务标识，多个线程池同名会导致监控混淆","改了名记得确认日志与告警规则按新前缀匹配"],"selfCheck":{"q":"线上线程名都是 pool-1-thread-x，排查问题有什么不便？","a":"无法区分线程归属哪个业务池，jstack 与监控只能看到通用名字，告警也难以精确路由。改用命名规范后可按前缀聚合定位。"}}', 14, 1793608851223, 1793609010879),
	(87, 2, 3, '自定义线程池 · 优雅关闭', '业务中自定义线程池', 'medium', '{"name":"自定义线程池 · 优雅关闭","category":"业务中自定义线程池","priority":"medium","summary":"用完线程池要 shutdown 并 awaitTermination，防止任务丢失和线程泄漏。","interview":"自定义线程池在服务停止时应该怎么关闭？shutdown 和 shutdownNow 有什么区别？","principle":"关闭分两步：先 shutdown() 拒绝新任务、让已提交任务跑完；再 awaitTermination() 等待一段时间；超时再用 shutdownNow() 强停并返回未执行任务。Spring 中把线程池做成 Bean，用 @PreDestroy 或 DisposableBean 挂关闭逻辑，容器销毁时自动执行。","params":["shutdown() 停止接收新任务，已提交的继续执行","shutdownNow() 中断执行中任务，返回未执行任务列表","awaitTermination(timeout) 等待指定时长后返回是否全部结束"],"pitfalls":["只调 shutdown 不等待，进程退出时任务仍在跑会被杀掉，造成任务丢失","忘了关闭，Tomcat/容器停止后线程仍存活，导致线程泄漏","在请求线程里调 shutdownNow，可能中断正在处理的业务，留下脏数据"],"selfCheck":{"q":"为什么 shutdown() 之后还要 awaitTermination()？","a":"shutdown 只是发信号停止接收新任务，不阻塞；awaitTermination 等待存量任务跑完，避免主线程直接退出把任务杀掉。"}}', 15, 1793608851223, 1793609010879),
	(88, 2, 4, 'IoC/DI · 概念与两种注入方式', 'IoC容器与Bean配置', 'high', '{"name":"IoC/DI · 概念与两种注入方式","category":"IoC容器与Bean配置","priority":"high","summary":"IoC把对象创建与依赖装配交给容器，DI有构造器注入与setter注入两种方式。","interview":"构造器注入和setter注入各有什么优缺点？Spring官方推荐哪种？","principle":"IoC即控制反转：对象不再自己new依赖，由容器按配置创建并注入。构造器注入在创建时一次性传入所有依赖，适合必填依赖；setter注入在对象创建后再赋值，适合可选依赖。构造器注入天然支持不可变对象（final字段），且能发现循环依赖。","params":["@Autowired可加在构造器/字段/方法上，构造器唯一时可省略","@Qualifier+@Autowired按名称指定注入哪个Bean","spring-boot-starter-test默认推荐构造器注入"],"pitfalls":["构造器注入遇到循环依赖会启动失败，setter注入可能延迟暴露解决或报错","setter注入下依赖可能为null，必须显式判空","字段注入（@Autowired加字段）不利于测试与不可变性，不推荐"],"selfCheck":{"q":"为什么Spring 4.3+推荐构造器注入？","a":"必填依赖在创建时即校验、字段可final不可变、便于单元测试（无需Spring容器）、能及早暴露循环依赖。"}}', 0, 1793689227499, 1793689409578),
	(89, 2, 4, 'Bean配置 · 组件扫描与注册方式', 'IoC容器与Bean配置', 'medium', '{"name":"Bean配置 · 组件扫描与注册方式","category":"IoC容器与Bean配置","priority":"medium","summary":"Bean可通过@Component等注解扫描、@Bean方法、XML或@Import注册，同名定义可能冲突。","interview":"多个同名Bean定义时会发生什么？@Primary和@Qualifier怎么解决？","principle":"组件扫描由@ComponentScan指定basePackages，扫到@Component/@Service/@Repository/@Controller即注册；@Bean在配置类方法中手动注册。容器启动时若发现两个Bean同名（id相同），默认后定义覆盖前定义（Spring Boot 2.1+默认禁止覆盖，抛异常）。依赖注入时若按类型匹配到多个Bean，再用@Primary定首选、@Qualifier按名匹配。","params":["@ComponentScan(basePackages=\"...\")","@Primary标在Bean定义上作为同类型多个Bean时的首选","@Qualifier(\"beanName\")按名称精确匹配"],"pitfalls":["Spring Boot 2.1+ spring.main.allow-bean-definition-overriding默认false，同名直接启动失败","按类型注入遇多个候选Bean会抛NoUniqueBeanDefinitionException","组件扫描遗漏包（如启动类同级包外）导致Bean未注册"],"selfCheck":{"q":"@Primary和@Qualifier解决的是同一个问题吗？","a":"不是。@Primary解决「按类型注入时多个候选Bean选哪个」，@Qualifier解决「按名称精确指定Bean」；两者都作用于依赖注入阶段，而Bean定义覆盖是注册阶段的问题。"}}', 1, 1793689227499, 1793689409578),
	(90, 2, 4, 'Bean作用域 · singleton与prototype', 'IoC容器与Bean配置', 'medium', '{"name":"Bean作用域 · singleton与prototype","category":"IoC容器与Bean配置","priority":"medium","summary":"singleton每个容器一个实例，prototype每次获取新实例，prototype注入singleton会只创建一次。","interview":"为什么prototype Bean注入到singleton Bean里，得到的还是同一个实例？怎么解决？","principle":"singleton在容器启动时创建并缓存一份；prototype每次getBean或注入时新建。但依赖注入只发生一次（单例初始化时），后续使用同一个注入对象，所以prototype被\"冻结\"成单例效果。解法是注入ObjectFactory<T>/Provider<T>（或ObjectProvider<T>），每次调用get()动态从容器拿新实例。","params":["@Scope(\"prototype\")标注Bean作用域","@Scope(value=\"prototype\", proxyMode=TARGET_CLASS)配合ObjectProvider","@Lazy延迟初始化避免启动时创建"],"pitfalls":["prototype注入singleton后，单例持有该引用直到销毁，内存泄漏与状态污染","prototype Bean的销毁回调不归容器管（容器只管singleton销毁），需自行释放资源","仅在请求/会话作用域需要代理，单纯prototype一般不用proxyMode"],"selfCheck":{"q":"ObjectFactory<T>是怎么解决prototype注入singleton问题的？","a":"它不注入真实Bean，而是注入一个工厂；单例每次用到时调用factory.getObject()，从容器实时获取一个新prototype实例，从而避免被固定成单例。"}}', 2, 1793689227499, 1793689409578),
	(91, 2, 4, 'Bean后处理器 · BeanPostProcessor', 'IoC容器与Bean配置', 'medium', '{"name":"Bean后处理器 · BeanPostProcessor","category":"IoC容器与Bean配置","priority":"medium","summary":"容器级扩展点，在Bean初始化前后插入自定义逻辑，可修改或替换Bean实例。","interview":"BeanPostProcessor的执行时机是什么？它自己是怎么被注册进容器的？","principle":"BeanPostProcessor自身必须在其他Bean实例化之前完成注册，所以容器启动时会先实例化所有实现了该接口的Bean（及BeanFactoryPostProcessor），再处理普通Bean。每个普通Bean在实例化、属性填充后，依次回调postProcessBeforeInitialization、init方法、postProcessAfterInitialization，AOP代理即在此产生。","params":["postProcessBeforeInitialization：init方法之前回调","postProcessAfterInitialization：init方法之后，AOP代理在此生成","实现PriorityOrdered/Ordered可控制多个后处理器顺序"],"pitfalls":["在BeanPostProcessor中注入普通Bean，会导致该Bean被过早初始化，提前暴露、绕过部分后置处理","依赖了后处理器的Bean若被提前实例化，可能失去代理等增强","不要在后处理器里做重量级逻辑，它会作用于所有Bean"],"selfCheck":{"q":"为什么在BeanPostProcessor里@Autowired一个普通Service是个隐患？","a":"因为后处理器要先于普通Bean创建，被注入的Service会被提前实例化，此时其他后处理器还没注册完，该Service可能失去AOP代理或事务等增强。"}}', 3, 1793689227499, 1793689409578),
	(92, 2, 4, 'Bean延迟加载 · @Lazy', 'IoC容器与Bean配置', 'low', '{"name":"Bean延迟加载 · @Lazy","category":"IoC容器与Bean配置","priority":"low","summary":"@Lazy让Bean在首次使用时才创建，可缓解启动慢与部分循环依赖。","interview":"@Lazy是如何解决循环依赖的？它有什么副作用？","principle":"默认单例Bean在容器启动时预实例化。加@Lazy后，容器只注册一个代理（或延迟解析入口），首次调用getBean时才真正创建并初始化。用于循环依赖时，通常加在注入点（构造器参数/字段）上，注入的是占位代理，打破启动期的双向实例化，把创建推迟到首次调用。","params":["@Lazy(value=false)默认值，true表示延迟","可标在类上（整个Bean延迟）或注入点上（仅该依赖延迟）","配合@Lazy(true) + proxyMode可生成目标代理"],"pitfalls":["问题后置：循环依赖被推迟到运行期，首次调用可能抛BeanCurrentlyInCreationException或NPE，错误更难定位","注入的是代理，若依赖最终类/无接口且未开CGLIB，代理失败","掩盖设计问题，真正的循环依赖应靠拆分职责解决"],"selfCheck":{"q":"@Lazy解决循环依赖的代价是什么？","a":"只是把创建推迟，问题后置到运行期，首次调用才暴露异常，调试更困难；且注入的是延迟代理，涉及final类或代理失败时会出错。"}}', 4, 1793689227499, 1793689409578),
	(93, 2, 4, 'Bean生命周期 · 主干流程', 'Bean生命周期', 'high', '{"name":"Bean生命周期 · 主干流程","category":"Bean生命周期","priority":"high","summary":"实例化→属性填充→Aware→初始化前→init→初始化后→使用→销毁，扩展点按需选。","interview":"Bean生命周期各阶段有哪些扩展点？初始化逻辑该放在构造器、@PostConstruct还是InitializingBean？","principle":"主干：1) 实例化（构造器）；2) 属性填充；3) Aware回调（BeanNameAware等）；4) BeanPostProcessor.postProcessBeforeInitialization（@PostConstruct在此生效）；5) InitializingBean.afterPropertiesSet或自定义init-method；6) postProcessAfterInitialization（AOP代理）；7) 使用；8) destroy（@PreDestroy/DisposableBean）。选型：依赖注入用构造器，通用初始化用@PostConstruct，与Spring接口耦合才用InitializingBean。","params":["@PostConstruct：JSR-250，优先推荐，不绑Spring","InitializingBean.afterPropertiesSet：Spring接口，耦合框架","init-method/destroy-method：XML或@Bean属性指定"],"pitfalls":["构造器里拿不到属性填充后的值，别做依赖注入结果的逻辑","初始化顺序：@PostConstruct先于afterPropertiesSet","构造器注入无法解决循环依赖（无提前引用），字段注入才可以"],"selfCheck":{"q":"初始化逻辑应该写在构造器、@PostConstruct还是afterPropertiesSet里？","a":"依赖注入结果的初始化放@PostConstruct（属性已填充且不绑Spring）；构造器只做参数无关的赋值；afterPropertiesSet与Spring强耦合，非必要不用。"}}', 5, 1793689227499, 1793689409578),
	(94, 2, 4, '初始化与销毁 · 回调方式', 'Bean生命周期', 'medium', '{"name":"初始化与销毁 · 回调方式","category":"Bean生命周期","priority":"medium","summary":"Bean 创建后与销毁前的回调有多种写法，混用时 Spring 按固定顺序调用，建议只选一套。","interview":"Spring 中初始化和销毁有哪几种回调方式？同时存在时执行顺序是怎样的？","principle":"初始化顺序大致为：@PostConstruct → InitializingBean.afterPropertiesSet() → 自定义 init-method；销毁反向对应 @PreDestroy → DisposableBean.destroy() → destroy-method。机制是 BeanPostProcessor（如 InitDestroyAnnotationBeanPostProcessor）和 AbstractAutowireCapableBeanFactory 在 doCreateBean 中按约定位置调用。","params":["initMethod / destroyMethod：在 @Bean 或 XML 中指定的方法名","@PostConstruct / @PreDestroy：JSR-250 注解，最常用"],"pitfalls":["混用多套时顺序固定但易误判，官方建议只用一种","destroy 回调只在容器关闭（close）时触发，非 Web 容器要手动关闭才生效","单例 bean 才有完整销毁回调，prototype 销毁由调用方自理"],"selfCheck":{"q":"@PostConstruct、afterPropertiesSet、init-method 三者同时存在，执行顺序是什么？","a":"@PostConstruct 先执行，其次是 InitializingBean.afterPropertiesSet()，最后是自定义 init-method；销毁时顺序相反（@PreDestroy 最先）。"}}', 6, 1793689227499, 1793689409578),
	(95, 2, 4, 'Aware接口 · 常见接口', 'Bean生命周期', 'low', '{"name":"Aware接口 · 常见接口","category":"Bean生命周期","priority":"low","summary":"Aware 接口让 Bean 在初始化阶段回调注入容器自身对象，如 ApplicationContext、BeanFactory、BeanName。","interview":"Spring 里 Aware 接口是干什么的？常见有哪些？和 @Autowired 注入容器对象有什么区别？","principle":"BeanFactory 在 populateBean 之后、initMethod 之前调用 ApplicationContextAwareProcessor 等处理器，逐个回调 awareXxx() 方法把容器对象塞进来。本质是\"回调式注入\"，发生在依赖注入之后、初始化回调之前。","params":["BeanNameAware：拿自己的 bean 名称","BeanFactoryAware / ApplicationContextAware：拿容器本身","EnvironmentAware、ResourceLoaderAware 等：拿环境与资源加载器"],"pitfalls":["Aware 回调早于 @PostConstruct，此时依赖已注入但初始化未完成","能用 @Autowired 注入 ApplicationContext 就别实现 Aware，代码更干净","拿到 ApplicationContext 后在里面 getBean 容易造成循环依赖或过度耦合"],"selfCheck":{"q":"想在 Bean 里拿到 ApplicationContext，有哪两种常见做法？何时用 Aware？","a":"一是实现 ApplicationContextAware 接口，二是 @Autowired 注入 ApplicationContext。优先用注解；只有在不想依赖注解扫描、或写基础组件时才用 Aware。"}}', 7, 1793689227499, 1793689409578),
	(96, 2, 4, '循环依赖 · 三级缓存机制', '循环依赖', 'high', '{"name":"循环依赖 · 三级缓存机制","category":"循环依赖","priority":"high","summary":"单例 + 属性注入的循环依赖靠三级缓存提前暴露半成品引用解决，构造器注入和 prototype 无解。","interview":"Spring 怎么解决循环依赖？三级缓存分别存什么？为什么构造器注入解决不了？","principle":"创建 A 时把 A 的 ObjectFactory（生产早期引用，可能产出代理）放入三级缓存，填充属性时发现需要 B；创建 B 又需要 A，此时从三级缓存拿到 A 的早期引用放进二级缓存并移除三级，B 完成后回填给 A。三级缓存设计是为了在需要时才通过代理工厂生成早期引用（AOP 一致性）。","params":["singletonObjects：成品缓存","earlySingletonObjects：半成品（早期引用）缓存","singletonFactories：ObjectFactory 缓存，用于按需生成早期引用"],"pitfalls":["prototype 作用域不走缓存，每次新建，循环依赖必死","构造器循环依赖无解：A 还没实例化完就要 B，B 又要 A，没有提前暴露点，只能改用 @Lazy 或 setter 注入","只有单例 + 属性/setter 注入才能靠三级缓存解决；@Async、AOP 代理相关的提前引用走的是 ObjectFactory"],"selfCheck":{"q":"为什么构造器注入的循环依赖三级缓存救不了？","a":"因为三级缓存的前提是 A 已实例化（构造完成）才能放入 ObjectFactory 提前暴露引用。构造器注入时 A 尚未构造完就要 B，而 B 又要 A，无可暴露对象，只能 @Lazy 延迟或改 setter 注入。"}}', 8, 1793689227499, 1793689409578),
	(97, 2, 4, '循环依赖 · 构造器注入为何不行', '循环依赖', 'high', '{"name":"循环依赖 · 构造器注入为何不行","category":"循环依赖","priority":"high","summary":"构造器在 Bean 创建早期就要依赖对象，无法先暴露半成品，所以循环构造依赖必死锁。","interview":"为什么构造器注入无法解决循环依赖，而 setter/字段注入可以？","principle":"Spring 解决循环依赖靠三级缓存：实例化后立即把 ObjectFactory 放入三级缓存，供别人提前引用（可能拿到代理前的半成品）。构造器注入发生在实例化阶段，A 没 new 完就要 B，B 又要 A，两个都没进入缓存，只能抛 BeanCurrentlyInCreationException。","params":["@Lazy：注入代理，首次调用才真正取 Bean","setter/字段注入：允许先实例化再填充属性","重构拆分：把公共逻辑抽到第三个 Bean"],"pitfalls":["@Lazy 只是延迟，本质是掩盖问题，若依赖确实需要一起初始化会埋雷","字段注入方便但不利于不可变与测试，团队规范常禁用","即便 setter 注入，构造期依赖仍无法救，两种注入混用时要小心"],"selfCheck":{"q":"A 构造器依赖 B、B 字段依赖 A，能启动吗？","a":"不能。A 实例化阶段就要 B，B 回头要 A 时 A 还没进缓存，构造器注入绕不开，仍会循环依赖异常。"}}', 9, 1793689227499, 1793689409578),
	(98, 2, 4, '循环依赖 · 破坏方式与现状', '循环依赖', 'medium', '{"name":"循环依赖 · 破坏方式与现状","category":"循环依赖","priority":"medium","summary":"新版 Spring Boot 默认禁止循环依赖，需显式开启或重构代码。","interview":"allowCircularReferences 关闭后有什么影响？新版本 Spring Boot 默认行为是什么？","principle":"allowCircularReferences=false 时容器不再走三级缓存提前暴露，发现循环直接抛 BeanCurrentlyInCreationException。Spring Boot 2.6 起默认为 false，鼓励靠设计消除循环而非靠容器兜底；开启方式是 spring.main.allow-circular-references=true 或 setAllowCircularReferences(true)。","params":["allowCircularReferences：默认 false（Boot 2.6+）","spring.main.allow-circular-references=true 临时开启","@Lazy 或重构是推荐的替代方案"],"pitfalls":["直接开启是把技术债往后推，CI/评审常禁止","即便开启，构造器循环依赖依然无解","升级 Boot 2.5→2.6 时该异常突然冒出，需排查存量循环"],"selfCheck":{"q":"Spring Boot 2.6 项目启动抛 BeanCurrentlyInCreationException，第一反应该做什么？","a":"先判断是不是循环依赖，优先用 @Lazy 或拆分 Bean 重构；若只是临时救急才打开 allow-circular-references=true，并记录技术债。"}}', 10, 1793689227499, 1793689409578),
	(99, 2, 4, 'AOP · 核心概念与切点', 'AOP与动态代理', 'high', '{"name":"AOP · 核心概念与切点","category":"AOP与动态代理","priority":"high","summary":"AOP 用动态代理在目标方法前后织入增强，切点表达式决定在哪里生效。","interview":"AOP 的核心概念有哪些？@Pointcut 怎么复用？切点匹配不到目标的常见原因是什么？","principle":"核心概念：切面 Aspect、连接点 Joinpoint（Spring 中基本等于方法）、切点 Pointcut（表达式筛选连接点）、通知 Advice（before/after/around/afterReturning/afterThrowing）、织入 Weaving（生成代理）。代理方式：有接口默认 JDK 动态代理，无接口用 CGLIB；Spring Boot 2.x 默认 CGLIB。@Pointcut 把表达式抽成方法，其他通知用方法名引用，实现复用。","params":["execution(* com.x.service.*.*(..)) 最常用","within / @annotation / bean 也可组合","@Aspect + @Component 才会被扫描为切面"],"pitfalls":["自调用（同类内 this.method()）不走代理，增强失效","切点包路径写错或方法非 public，匹配不到","final 类/方法无法被 CGLIB 代理；@Transactional 同理失效"],"selfCheck":{"q":"@Pointcut(\"execution(* com.demo.service..*.*(..))\") 里两个点号是什么意思？","a":".. 表示匹配 com.demo.service 及其所有子包下的任意类任意方法，一个点是当前包，两个点包含子包，写错会导致切点匹配不到目标。"}}', 11, 1793689227499, 1793689409578),
	(100, 2, 4, '动态代理 · JDK与CGLIB', 'AOP与动态代理', 'high', '{"name":"动态代理 · JDK与CGLIB","category":"AOP与动态代理","priority":"high","summary":"JDK基于接口用反射，CGLIB基于继承用字节码生成子类，Spring默认按有无接口选择。","interview":"JDK动态代理和CGLIB有什么区别，Spring怎么选？","principle":"JDK的Proxy.newProxyInstance为接口生成实现类，InvocationHandler转发方法调用；CGLIB用ASM生成目标类的子类重写方法织入增强。Spring Boot 2.x起默认proxyTargetClass=true优先用CGLIB，可不依赖接口。","params":["JDK要求目标类实现接口，方法调用走InvocationHandler.invoke","CGLIB通过生成子类实现代理，无需接口但要求类可继承","proxyTargetClass=true强制CGLIB，false时有接口用JDK"],"pitfalls":["final方法和final类无法被CGLIB重写/继承，代理会失效或抛错","同类内部自调用不走代理对象，增强不生效，需注入自身或AopContext.currentProxy()","CGLIB要求类有无参构造，且方法是public/protected才能被拦截"],"selfCheck":{"q":"为什么同类中方法A调用方法B，B上的@Transactional不生效？","a":"自调用是this直接调用，没走代理对象，切面不介入。可通过注入自身代理、AopContext.currentProxy()或拆分类解决。"}}', 12, 1793689227499, 1793689409578),
	(101, 2, 4, 'AOP · 失效场景与原理', 'AOP与动态代理', 'high', '{"name":"AOP · 失效场景与原理","category":"AOP与动态代理","priority":"high","summary":"AOP失效分两类：代理根本没生成，或代理生成了但调用绕过了代理对象。","interview":"@Transactional注解失效有哪些常见原因，怎么排查？","principle":"代理未介入：目标类是final、非Spring管理（new出来的）、切点表达式没匹配、方法非public（Spring AOP默认只代理public）。代理被绕过：同类自调用、在Bean初始化早期（如构造器/BeanPostProcessor阶段）使用代理。排查先确认getBean拿到的是代理类（含$$、EnhancerBySpringCGLIB），再看调用路径是否经过代理。","params":["切点表达式execution/@annotation要与方法签名精确匹配","@Transactional默认只对public方法生效","proxyTargetClass影响代理形态但不解决绕过问题"],"pitfalls":["new出来的对象不在容器里，AOP完全不介入","同一类方法自调用绕过代理，是最常见失效原因","异常被catch吞掉或rollbackFor不匹配，导致事务看似失效"],"selfCheck":{"q":"如何快速判断一个Bean的AOP是否生效？","a":"打印getClass().getName()看是否有$$EnhancerBySpringCGLIB或$Proxy前缀，或在增强逻辑打日志，确认调用是否走代理对象。"}}', 13, 1793689227499, 1793689409578),
	(102, 2, 4, 'AOP · 与生命周期的关系', 'AOP与动态代理', 'medium', '{"name":"AOP · 与生命周期的关系","category":"AOP与动态代理","priority":"medium","summary":"AOP在Bean初始化后置阶段介入，getBean和@Autowired拿到的都是代理对象而非原始对象。","interview":"getBean拿到的是原始Bean还是代理对象？AOP在Bean生命周期哪一步生效？","principle":"Bean生命周期：实例化→属性填充→Aware→BeanPostProcessor.postProcessBeforeInitialization→InitializingBean/init-method→postProcessAfterInitialization→使用→销毁。AbstractAutoProxyCreator（AbstractAutowireCapableBeanFactory.applyBeanPostProcessorsAfterInitialization）在这里决定是否用代理对象替换原始对象放入容器，因此依赖注入和getBean拿到的是代理。","params":["AOP代理发生在postProcessAfterInitialization阶段","getBean/getObjectForBeanInstance返回的是代理对象","@Autowired注入的也是代理对象"],"pitfalls":["代理替换发生在初始化后，构造器阶段用不到代理对象","代理对象持有原始对象引用，二者是两个实例，别用==比较","早期Bean或非单例场景，代理创建时机与作用域需留意"],"selfCheck":{"q":"为什么在构造方法里调用带@Async的方法不生效？","a":"构造阶段Bean还没走完初始化，AOP代理尚未生成，此时调用的是原始对象，增强不介入。"}}', 14, 1793689227499, 1793689409578),
	(103, 2, 4, '依赖注入 · @Autowired装配规则', '@Autowired与装配', 'medium', '{"name":"依赖注入 · @Autowired装配规则","category":"@Autowired与装配","priority":"medium","summary":"@Autowired默认按类型装配，同类型多个候选时按名称匹配，再靠@Primary或限定符消歧。","interview":"多个同类型Bean时@Autowired怎么选？报错怎么解决？","principle":"容器先按类型查找候选Bean；只有一个直接注入；有多个再按属性名/参数名与beanName匹配；仍不唯一则抛NoUniqueBeanDefinitionException，此时可用@Primary指定首选，或用@Qualifier限定名称；@Resource是JSR-250规范，默认按名称装配、找不到再按类型，不参与@Primary。","params":["required=false：找不到时注入null而非报错","@Primary标记首选Bean，同类多个时优先","@Qualifier(\"name\")或@Resource(name=…)按名称指定"],"pitfalls":["同类型多个且名称不匹配时启动直接报NoUniqueBeanDefinitionException，异常信息会列出候选beanName","@Resource不走@Primary，混用时行为易预期偏差","接口多实现时推荐组合@Qualifier，比依赖字段名更稳"],"selfCheck":{"q":"@Autowired和@Resource在多个候选Bean时的选择顺序有何区别？","a":"@Autowired先按类型，多个再按名称/名称不匹配靠@Primary或@Qualifier消歧；@Resource先按名称（name属性），找不到再按类型，不认@Primary。"}}', 15, 1793689227499, 1793689409578),
	(104, 2, 4, '@Autowired · 注入点与循环依赖', '@Autowired与装配', 'medium', '{"name":"@Autowired · 注入点与循环依赖","category":"@Autowired与装配","priority":"medium","summary":"@Autowired可注入集合、ObjectProvider；循环依赖靠三级缓存解决构造器之外的注入。","interview":"注入List/Map和ObjectProvider各适用于什么场景？循环依赖怎么破？","principle":"字段/setter注入的循环依赖靠三级缓存：实例化后先暴露早期引用（可能为代理），B注入A的早期引用完成初始化，A再完成填充。注入点是List/Map时，容器收集所有匹配类型的Bean装配成集合（Map的key为beanName）；ObjectProvider延迟解析，调用getObject/getIfAvailable时才按需取Bean，可避免启动期硬依赖和循环依赖。","params":["List<T>/Set<T>：注入所有T类型Bean","Map<String,T>：key为beanName","ObjectProvider<T>：延迟获取，支持getIfAvailable、stream()"],"pitfalls":["构造器注入无法用三级缓存解决循环依赖，会直接启动失败（Spring Boot 2.6+默认禁止循环引用）","ObjectProvider取不到时getIfAvailable返回null，getObject会抛NoSuchBeanDefinitionException","循环依赖+@Async等AOP场景，早期引用可能是代理，注意自注入拿到的是代理对象"],"selfCheck":{"q":"为什么构造器注入的循环依赖解决不了，字段注入却可以？","a":"字段注入时Bean已实例化，可提前把早期引用放入缓存暴露给对方；构造器注入在实例化阶段就要对方，无法提前暴露，只能报错。"}}', 16, 1793689227499, 1793689409578),
	(105, 2, 5, '自动配置 · 基本原理', 'SpringBoot 自动配置', 'high', '{"name":"自动配置 · 基本原理","category":"SpringBoot 自动配置","priority":"high","summary":"SpringBoot 启动时通过 spring.factories 加载自动配置类，按条件筛选后注册 Bean，实现“约定优于配置”。","interview":"SpringBoot 自动配置是怎么实现的？为什么你的自动配置类后加载还能覆盖默认的？","principle":"启动类 @SpringBootApplication 包含 @EnableAutoConfiguration，它用 AutoConfigurationImportSelector 读取 META-INF/spring.factories 中的自动配置类，去重后按 @Conditional 条件过滤，再通过 @Configuration 解析注册 Bean。自动配置类一般加 @ConditionalOnMissingBean 保证用户自定义 Bean 能覆盖默认值。","params":["自动配置类清单：META-INF/spring.factories（Spring Boot 3 用 META-INF/spring/org.springframework.boot.autoconfigure.AutoConfigurati","条件注解默认按类路径、Bean、属性等判断","自动配置类通常标注 @AutoConfiguration 或 @Configuration"],"pitfalls":["条件装配失效常见原因：依赖类不在类路径、@ConditionalOnMissingBean 类型不匹配、属性值未生效","自动配置类加载顺序靠后，用户配置优先，不要用 @Order 强行插队","spring.factories 写错类名或未注册，配置类根本不会被加载"],"selfCheck":{"q":"为什么自动配置类要配合 @ConditionalOnMissingBean？","a":"保证用户自定义 Bean 存在时不注册默认 Bean，实现默认配置可被覆盖，避免冲突。"}}', 0, 1793869784508, 1793869784508),
	(106, 2, 5, '自动配置 · 条件注解', 'SpringBoot 自动配置', 'high', '{"name":"自动配置 · 条件注解","category":"SpringBoot 自动配置","priority":"high","summary":"@Conditional 系列在配置类解析和 Bean 注册两个阶段生效，判断时机不同导致边界问题。","interview":"@ConditionalOnMissingBean 为什么有时对普通 @Bean 不生效？条件判断在什么阶段执行？","principle":"配置类解析阶段先处理 @Conditional 类级别条件，决定是否解析该类；Bean 注册阶段再处理方法/Bean 级别条件，尤其 @ConditionalOnMissingBean 依赖已注册的 Bean 定义。因此方法级条件受注册顺序影响，配置类级条件则较早判断。","params":["@ConditionalOnClass/@ConditionalOnMissingClass：类路径判断","@ConditionalOnBean/@ConditionalOnMissingBean：容器中 Bean 判断，默认按类型","@ConditionalOnProperty：配置属性判断，可指定 havingValue"],"pitfalls":["@ConditionalOnMissingBean 用在普通 @Configuration 的 @Bean 方法上时，可能因注册顺序误判，建议放在自动配置类中","类级别条件在解析阶段判断，属性未加载完可能拿不到值","条件判断只做一次，运行时动态变化不会重新生效"],"selfCheck":{"q":"为什么 @ConditionalOnMissingBean 放在自动配置类里更可靠？","a":"自动配置类在用户配置之后处理，此时用户 Bean 已注册，能正确判断缺失，避免顺序导致的误判。"}}', 1, 1793869784508, 1793869784508),
	(107, 2, 5, '配置绑定 · @ConfigurationProperties', 'SpringBoot 自动配置', 'high', '{"name":"配置绑定 · @ConfigurationProperties","category":"SpringBoot 自动配置","priority":"high","summary":"把配置文件属性批量绑定到 Bean 字段，支持嵌套、集合和校验，需配合 @EnableConfigurationProperties 或 @Component 生效。","interview":"@ConfigurationProperties 怎么绑定嵌套对象和集合？和 @Validated 一起用要注意什么？","principle":"SpringBoot 用 Binder 按属性前缀把 Environment 中的值绑定到目标 Bean，支持松散绑定（relaxed binding）；嵌套对象按字段路径递归绑定，集合按索引或逗号分隔值绑定；加 @Validated 后由 JSR-303 校验器在绑定后校验。","params":["前缀通过 @ConfigurationProperties(prefix = \"xxx\") 指定，需 kebab-case","启用方式：@EnableConfigurationProperties 或 @Component + @ConfigurationProperties","校验需加 @Validated 并引入校验实现（如 hibernate-validator）"],"pitfalls":["集合绑定要提供 getter/setter 或构造绑定，否则可能绑定不上","嵌套对象需有默认构造或可绑定构造，字段不能是 final 且无 setter","校验注解放在字段上需 @Validated 触发，不加不校验"],"selfCheck":{"q":"@ConfigurationProperties 绑定集合时常见失败原因是什么？","a":"缺少 setter 或可变集合、未提供默认构造、属性名不匹配导致绑定不到值。"}}', 2, 1793869784508, 1793869784508),
	(108, 2, 5, '配置加载 · 多环境与优先级', 'SpringBoot 自动配置', 'high', '{"name":"配置加载 · 多环境与优先级","category":"SpringBoot 自动配置","priority":"high","summary":"Spring Boot 按固定顺序加载多来源配置，后加载的覆盖先加载的，命令行参数优先级最高。","interview":"Spring Boot 配置文件的加载顺序和优先级是怎样的？多环境冲突时你怎么排查？","principle":"启动时依次加载：默认属性→application.yml/properties→profile 专属文件→外部配置文件→环境变量→系统属性→命令行参数；后加载的覆盖先加载的。排查时用 /actuator/env 或启动日志看属性最终来源。","params":["spring.profiles.active 指定激活环境","application-{profile}.yml 覆盖 application.yml","命令行 --key=value 优先级最高"],"pitfalls":["profile 文件不会覆盖全部，只覆盖同名 key","外部 config 目录优先于 jar 内配置，易被忽略","环境变量命名要转大写加下划线，否则读不到"],"selfCheck":{"q":"application.yml 和 application-prod.yml 同时配置了 server.port，激活 prod 后生效哪个？","a":"生效 application-prod.yml 中的值，因为 profile 专属文件后加载，会覆盖基础文件中的同名配置。"}}', 3, 1793869784515, 1793869784515),
	(109, 2, 5, '自动配置 · 加载与顺序', 'SpringBoot 自动配置', 'medium', '{"name":"自动配置 · 加载与顺序","category":"SpringBoot 自动配置","priority":"medium","summary":"自动配置类通过 spring.factories 或 AutoConfiguration.imports 注册，按 @AutoConfigureBefore/After 和条件注解决定生效顺序。","interview":"Spring Boot 自动配置是怎么加载的？它和用户自定义配置谁优先？","principle":"启动时读取 META-INF/spring.factories（2.7 前）或 META-INF/spring/org.springframework.boot.autoconfigure.AutoConfiguration.imports（2.7+）得到候选配置类，再按 @AutoConfigureOrder、@AutoConfigureBefore/After 排序，最后用 @Conditional 系列注解过滤，只保留满足条件的配置。","params":["spring.autoconfigure.exclude 排除指定自动配置","@ConditionalOnMissingBean 用户 Bean 优先","@AutoConfigureAfter 控制加载顺序"],"pitfalls":["用户自定义 Bean 与自动配置冲突时，@ConditionalOnMissingBean 保证用户优先","顺序错乱会导致依赖的 Bean 还没注册","2.7 后 spring.factories 注册自动配置已废弃"],"selfCheck":{"q":"为什么用户自己定义的 DataSource Bean 会覆盖自动配置的？","a":"因为自动配置类上标注了 @ConditionalOnMissingBean，容器已有同类型 Bean 时该自动配置不生效，用户配置优先。"}}', 4, 1793869784515, 1793869784515),
	(110, 2, 5, '自动配置 · 排除与调试', 'SpringBoot 自动配置', 'medium', '{"name":"自动配置 · 排除与调试","category":"SpringBoot 自动配置","priority":"medium","summary":"用 exclude 排除自动配置，用 --debug 或 ConditionEvaluationReport 查看每个条件是否满足，定位 Bean 不符合预期的原因。","interview":"线上某个 Bean 不符合预期，你怎么用条件报告定位是哪个条件没满足？","principle":"启动加 --debug 或设置 logging.level.org.springframework.boot.autoconfigure=DEBUG，会打印 ConditionEvaluationReport，列出 Positive/Negative matches；在报告中找到目标自动配置类，看它哪个 @Conditional 判为 Negative，即可定位缺失的 Bean、属性或类。","params":["--debug 输出条件评估报告","spring.autoconfigure.exclude 排除配置类","logging.level.org.springframework.boot.autoconfigure=DEBUG"],"pitfalls":["条件报告只反映启动时刻，运行期动态变化看不到","多个条件同时不满足时容易漏看","排除类名写错会静默不生效"],"selfCheck":{"q":"条件报告里某自动配置显示 Negative match，说明什么？","a":"说明该自动配置的某个 @Conditional 条件未满足，配置类未生效，其声明的 Bean 不会被注册。"}}', 5, 1793869784515, 1793869784515),
	(111, 2, 5, 'Starter · 是什么与约定', 'Starter 机制', 'high', '{"name":"Starter · 是什么与约定","category":"Starter 机制","priority":"high","summary":"Starter 是“依赖包 + 自动配置”的组合，用来一站式引入某项能力。","interview":"Spring Boot 的 Starter 是什么，它遵循什么约定？","principle":"Starter 本质是 Maven/Gradle 依赖描述，可拆成两个模块：自动配置模块（代码、配置类、spring.factories 或 AutoConfiguration.imports）和 starter 模块（只聚合依赖）。官方约定 starter 只负责引依赖，自动配置单独放 autoconfigure 包，避免用户被迫引入多余代码。","params":["自动配置类放 META-INF/spring/org.springframework.boot.autoconfigure.AutoConfiguration.imports","starter 命名：官方 spring-boot-starter-xxx，第三方 xxx-spring-boot-starter"],"pitfalls":["只有一个自动配置类、需求简单时拆两模块反而增加维护成本","拆不拆看复用规模：能力复杂、可能被单独引自动配置时才值得拆"],"selfCheck":{"q":"什么规模才值得把 Starter 拆成自动配置与依赖两个模块？","a":"只有当自动配置能力较复杂、希望用户能只引自动配置而不引入整套依赖时，拆分才有价值；简单场景一个模块即可。"}}', 6, 1793869789871, 1793869789871),
	(112, 2, 5, 'Starter · 自定义步骤', 'Starter 机制', 'high', '{"name":"Starter · 自定义步骤","category":"Starter 机制","priority":"high","summary":"写自动配置类 + 注册到 imports 文件 + 条件注解兜底，做成默认可用、用户可覆盖。","interview":"你会怎么自定义一个 Starter，怎么保证默认生效又能被用户配置覆盖？","principle":"步骤：新建 starter 工程→写 XxxProperties 绑定配置→写自动配置类，用 @ConditionalOnMissingBean、@ConditionalOnProperty、@ConditionalOnClass 控制生效→在 AutoConfiguration.imports 中登记。默认值写在 Properties 里，用户通过 application.yml 覆盖即可。","params":["@ConditionalOnMissingBean 保证用户自定义 Bean 优先","@ConditionalOnProperty 控制开关，默认值设在 Properties 类中"],"pitfalls":["漏写 @ConditionalOnMissingBean，用户 Bean 被覆盖或冲突","自动配置类里直接 new 依赖、没有条件注解，导致缺依赖时报错"],"selfCheck":{"q":"怎样让 Starter 默认提供 Bean，但用户自己定义了同类型 Bean 时不冲突？","a":"在自动配置的 @Bean 方法上加重 @ConditionalOnMissingBean，用户定义了同类型 Bean 时自动配置让位。"}}', 7, 1793869789871, 1793869789871),
	(113, 2, 5, 'Starter · 开箱即用的设计', 'Starter 机制', 'medium', '{"name":"Starter · 开箱即用的设计","category":"Starter 机制","priority":"medium","summary":"公共组件封 Starter 能自动装配、带默认配置，普通 jar 只提供类不会自动生效。","interview":"公共组件应该封装成 Starter 还是普通 jar，怎么选？","principle":"Starter 适合需要自动注册 Bean、读取配置、按条件装配、面向 Spring Boot 使用者的组件；普通 jar 适合纯工具类、与容器无关的库。Starter 用户体验好但耦合 Spring Boot，普通 jar 通用性强但要用户手动配置。","params":["Starter 依赖 spring-boot-autoconfigure，普通 jar 不依赖","Starter 可在 imports 文件声明自动配置类"],"pitfalls":["纯工具库封 Starter 会强绑 Spring Boot，限制非 Boot 用户","Starter 里漏掉条件注解，用户环境不满足时启动失败"],"selfCheck":{"q":"一个纯字符串工具库要不要做成 Starter？","a":"一般不必，它不涉及容器 Bean 和配置，做成普通 jar 更通用；只有需要自动装配 Bean 时才封 Starter。"}}', 8, 1793869789871, 1793869789871),
	(114, 2, 5, '过滤器 · 基本概念与用法', '过滤器与拦截器', 'high', '{"name":"过滤器 · 基本概念与用法","category":"过滤器与拦截器","priority":"high","summary":"过滤器是 Servlet 容器级的组件，在请求进入 DispatcherServlet 之前和响应返回之后生效，用来统一做编码、鉴权、日志等横切处理。","interview":"Spring Boot 里怎么注册一个 Filter？多个 Filter 的先后顺序由什么决定？","principle":"实现 javax.servlet.Filter 的 doFilter，在 FilterChain.doFilter 前后包逻辑。注册方式有两种：一是在 Filter 类上加 @WebFilter+@ServletComponentScan；二是用 FilterRegistrationBean 显式注册并 setOrder。容器按 Order 值升序执行，值越小越先进入、越后返回。","params":["FilterRegistrationBean.setOrder(int)：默认 Ordered.LOWEST_PRECEDENCE","@Order 注解：默认 Ordered.LOWEST_PRECEDENCE（Integer.MAX_VALUE）","@WebFilter 注册的 Filter 顺序不可控，按类名扫描顺序"],"pitfalls":["@WebFilter 无法指定顺序，要与其它 Filter 排先后必须改用 FilterRegistrationBean","过滤器在 DispatcherServlet 之外，拿不到 Spring MVC 的 HandlerMethod 信息"],"selfCheck":{"q":"只加 @Order(1) 到 @WebFilter 标注的 Filter 上，能控制它和其它 Filter 的执行顺序吗？","a":"不能。@Order 只对 Spring 管理的 Bean 排序（如 FilterRegistrationBean）生效，@WebFilter 注册的 Filter 顺序由容器扫描决定，必须改用 FilterRegistrationBean 显式 setOrder。"}}', 9, 1793869792286, 1793869792286),
	(115, 2, 5, '拦截器 · 基本概念与用法', '过滤器与拦截器', 'high', '{"name":"拦截器 · 基本概念与用法","category":"过滤器与拦截器","priority":"high","summary":"拦截器是 Spring MVC 层的组件，围绕 Handler 执行，能做 preHandle、postHandle、afterCompletion 三段式增强，能拿到 HandlerMethod。","interview":"preHandle 返回 false 后，postHandle 和 afterCompletion 还会执行吗？","principle":"实现 HandlerInterceptor 并注册到 WebMvcConfigurer 的 addInterceptors。执行链为：preHandle 依次正序执行，全返回 true 才进 Handler；Handler 返回后 postHandle 逆序执行，再渲染视图，最后 afterCompletion 逆序执行。某个 preHandle 返回 false 时，本拦截器及其后的 preHandle 不再执行，postHandle 全不执行。","params":["preHandle 返回值：true 放行 / false 中断","postHandle：逆序，仅 preHandle 全 true 时执行","afterCompletion：逆序，仅对已成功执行 preHandle 的拦截器调用"],"pitfalls":["preHandle 返回 false 时 postHandle 不执行，但已通过 preHandle 的前序拦截器仍会走 afterCompletion","afterCompletion 常用于清理 ThreadLocal，漏掉会线程复用串数据"],"selfCheck":{"q":"A、B 两个拦截器，A 的 preHandle 返回 true、B 返回 false，哪些方法会被调用？","a":"A.preHandle → B.preHandle(false)，不进 Handler；postHandle 都不执行；afterCompletion 只执行 A 的（B 未通过 preHandle），且逆序。"}}', 10, 1793869792286, 1793869792286),
	(116, 2, 5, '过滤器与拦截器 · 区别与选型', '过滤器与拦截器', 'high', '{"name":"过滤器与拦截器 · 区别与选型","category":"过滤器与拦截器","priority":"high","summary":"过滤器在 Servlet 容器层，能包装或替换请求体；拦截器在 Spring MVC 层，能拿到 Handler 和 Spring 上下文。需要读 body 或包装请求时选过滤器。","interview":"要在拦截器里读请求体，或者要包装 Request，应该选过滤器还是拦截器？两者怎么组合？","principle":"请求体是流，只能读一次，而拦截器拿到的 Request 已被 DispatcherServlet 消费过。方案是：用过滤器把 HttpServletRequest 包装成可重复读的 ContentCachingRequestWrapper 或自定义 Wrapper，再传给后面的拦截器读取。典型链路：编码/日志/包装 Filter → 鉴权 Interceptor → Controller → afterCompletion 清理。","params":["ContentCachingRequestWrapper：缓存 body 供多次读取","OncePerRequestFilter：默认保证一次请求只执行一次","Filter 顺序用 FilterRegistrationBean.setOrder，Interceptor 顺序用 addInterceptors 的 registry 顺序"],"pitfalls":["直接在拦截器里调 getInputStream 读 body，会与框架冲突或读到空","包装 Wrapper 必须在过滤器里传入 FilterChain，否则下游拿不到"],"selfCheck":{"q":"为什么读请求体、包装请求要放在过滤器而不是拦截器？","a":"body 流只能读一次，拦截器阶段流已被 DispatcherServlet 读过；过滤器更早，可用 ContentCachingRequestWrapper 包装后让下游重复读，且包装需经 FilterChain 传下去。"}}', 11, 1793869792286, 1793869792286),
	(117, 2, 5, '过滤器与拦截器 · 典型应用', '过滤器与拦截器', 'medium', '{"name":"过滤器与拦截器 · 典型应用","category":"过滤器与拦截器","priority":"medium","summary":"Filter 在 Servlet 层做粗粒度、全请求处理；Interceptor 在 Spring MVC 层拿得到 Handler 和方法信息，做业务型横切。","interview":"鉴权、日志、限流这些横切逻辑，你会放过滤器还是拦截器？为什么？","principle":"请求先过 Filter 链，再由 DispatcherServlet 分发给 Handler，执行 HandlerInterceptor 的 preHandle、Controller、postHandle、afterCompletion。Filter 能改 Request/Response、管静态资源与所有 URL；Interceptor 能拿 HandlerMethod、访问 Spring 容器 Bean，但不能改请求体。AOP 适合方法级业务横切（事务、日志、权限注解），拦截器适合请求级。","params":["Filter 用 @Order 或 FilterRegistrationBean 定顺序","Interceptor 用 addPathPatterns、excludePathPatterns 配范围","preHandle 返回 false 即中断，afterCompletion 一定会执行"],"pitfalls":["鉴权放 Filter 拿不到方法注解，放 Interceptor 又管不住静态资源","Filter 里抛异常不会进 HandlerExceptionResolver","Interceptor 里注入 Bean 要注意拦截器本身是否被 Spring 管理"],"selfCheck":{"q":"为什么权限注解（如 @PreAuthorize）更适合在拦截器或 AOP 做，而不在 Filter 做？","a":"Filter 阶段还没确定 Handler，拿不到方法与注解信息；只有进入 DispatcherServlet 后拦截器或 AOP 才能读到方法上的权限元数据。"}}', 12, 1793869797332, 1793869797332),
	(118, 2, 5, '参数绑定 · 常用注解', 'Spring MVC 与请求处理', 'high', '{"name":"参数绑定 · 常用注解","category":"Spring MVC 与请求处理","priority":"high","summary":"@RequestParam、@PathVariable、@RequestBody、@ModelAttribute 各管一类来源，复杂对象靠 setter 或构造器逐字段绑定。","interview":"@RequestBody 和 @ModelAttribute 绑定对象有什么区别？日期格式和校验怎么配合？","principle":"Spring MVC 用 HandlerMethodArgumentResolver 按注解选解析器：@RequestParam 取查询串或表单单个值，@PathVariable 取路径变量，@RequestBody 用 HttpMessageConverter 反序列化 JSON，@ModelAttribute 用 WebDataBinder 按字段名绑定请求参数。绑定后触发 JSR-303 校验，失败抛 MethodArgumentNotValidException。","params":["@RequestParam 默认 required=true，可设 defaultValue","@DateTimeFormat 定单个字段格式，@JsonFormat 定 JSON 序列化格式","@Valid 或 @Validated 触发校验，BindingResult 可接错误"],"pitfalls":["@RequestBody 只能读一次体，和表单参数不能混用","嵌套对象或集合绑定需要正确命名，如 list[0].name","日期格式不匹配直接 400，别只指望校验注解"],"selfCheck":{"q":"前端传 JSON 到 @ModelAttribute 对象为什么会拿到 null 字段？","a":"@ModelAttribute 走 WebDataBinder 绑请求参数，不解析 JSON 请求体；应改用 @RequestBody 由消息转换器反序列化。"}}', 13, 1793869797332, 1793869797332),
	(119, 2, 5, '统一异常处理 · @ControllerAdvice', 'Spring MVC 与请求处理', 'high', '{"name":"统一异常处理 · @ControllerAdvice","category":"Spring MVC 与请求处理","priority":"high","summary":"@ControllerAdvice + @ExceptionHandler 统一捕获 Controller 层异常，但过滤器阶段抛的异常进不来。","interview":"全局异常处理器能接住过滤器里抛出的异常吗？为什么？","principle":"DispatcherServlet 处理请求时把异常交给 HandlerExceptionResolver 链，ExceptionHandlerExceptionResolver 找 @ControllerAdvice 里匹配的 @ExceptionHandler。过滤器在 DispatcherServlet 之前或之后执行，异常不经过 DispatcherServlet，因此全局处理器接不住，只能靠 Filter 自己 try-catch 或容器错误页。","params":["@RestControllerAdvice 等于 @ControllerAdvice + @ResponseBody","@ExceptionHandler 可按异常类型精确匹配，子类优先","可用 @Order 控制多个 Advice 的优先级"],"pitfalls":["Filter 抛异常不会进 @ControllerAdvice，需在 Filter 内处理","@ExceptionHandler 方法返回值同样走消息转换，注意状态码设置","异常被 catch 后未重新抛出，全局处理器就失效"],"selfCheck":{"q":"想在过滤器鉴权失败时返回统一 JSON，应该怎么做？","a":"在 Filter 里直接写响应或包装异常转发到统一错误处理入口，不能指望 @ControllerAdvice 捕获 Filter 阶段异常。"}}', 14, 1793869797332, 1793869797332),
	(120, 2, 5, '请求处理 · 核心流程', 'Spring MVC 与请求处理', 'medium', '{"name":"请求处理 · 核心流程","category":"Spring MVC 与请求处理","priority":"medium","summary":"请求经 DispatcherServlet 分发，通过 HandlerMapping 找 handler，HandlerAdapter 执行，参数解析器解析参数，返回值处理器处理结果。","interview":"Spring MVC 中一个请求从进入容器到返回响应，核心流程是怎样的？","principle":"DispatcherServlet 接收请求，遍历 HandlerMapping 得到 HandlerExecutionChain（含拦截器）；用 HandlerAdapter 调用 handler 方法；调用前由 HandlerMethodArgumentResolver 解析参数，调用后由 HandlerMethodReturnValueHandler 处理返回值；最后经过拦截器后置处理并渲染视图或写响应。","params":["常用参数解析器：RequestParamMethodArgumentResolver、RequestBodyMethodArgumentResolver","常用返回值处理器：RequestResponseBodyMethodProcessor、ViewNameMethodReturnValueHandler"],"pitfalls":["自定义参数解析器需实现 HandlerMethodArgumentResolver 并注册到 WebMvcConfigurer","自定义返回值处理器需实现 HandlerMethodReturnValueHandler 并注意顺序"],"selfCheck":{"q":"什么需求下会扩展参数解析器或返回值处理器？","a":"需要统一处理自定义注解参数（如当前用户注入）或统一包装返回值格式时扩展。"}}', 15, 1793869798825, 1793869798825),
	(121, 2, 5, '统一响应与跨域 · 常用配置', 'Spring MVC 与请求处理', 'medium', '{"name":"统一响应与跨域 · 常用配置","category":"Spring MVC 与请求处理","priority":"medium","summary":"统一响应常用 @RestControllerAdvice 包装；跨域用 @CrossOrigin 或 WebMvcConfigurer 配置，预检请求需在过滤器/拦截器放行。","interview":"Spring Boot 中如何做统一响应和跨域配置？预检请求在过滤器和拦截器链中要注意什么？","principle":"统一响应通过 @RestControllerAdvice 或 ResponseBodyAdvice 对返回值包装；跨域可在方法/类上加 @CrossOrigin，或实现 WebMvcConfigurer#addCorsMappings 全局配置。预检 OPTIONS 请求由 CORS 处理器处理，若自定义过滤器/拦截器未放行 OPTIONS，会导致预检失败。","params":["@CrossOrigin 默认允许所有源、所有方法","全局配置用 addCorsMappings 设置 allowedOrigins、allowedMethods 等"],"pitfalls":["拦截器拦截了 OPTIONS 预检请求导致跨域失败","统一响应包装可能影响文件下载或 String 返回值"],"selfCheck":{"q":"跨域预检请求在拦截器链中常出什么问题？","a":"拦截器未放行 OPTIONS 请求，导致预检失败返回 403。"}}', 16, 1793869798825, 1793869798825),
	(122, 2, 5, 'Bean 注册 · @Component 与 @Bean', '常用注解与机制辨析', 'high', '{"name":"Bean 注册 · @Component 与 @Bean","category":"常用注解与机制辨析","priority":"high","summary":"@Component 用于自己写的类，@Bean 用于第三方类；@Bean 方法可控制实例化逻辑，混用时 @Bean 优先级更高。","interview":"@Component 和 @Bean 有什么区别？第三方类无法改源码时为什么只能用 @Bean？混用优先级如何？","principle":"@Component 通过类路径扫描自动注册 Bean；@Bean 在配置类的方法上显式声明 Bean，可自定义初始化。第三方类无法加 @Component，只能通过 @Bean 方法返回实例。若同一类型同时存在，@Bean 定义的 Bean 通常覆盖 @Component 扫描的 Bean（取决于注册顺序和覆盖规则）。","params":["@Component 需配合 @ComponentScan 使用","@Bean 方法所在类需标注 @Configuration 或 @Component"],"pitfalls":["第三方类无源码无法加 @Component，只能用 @Bean","同名 Bean 覆盖在 Spring Boot 2.1+ 默认禁止，需开启 allow-bean-definition-overriding"],"selfCheck":{"q":"@Bean 和 @Component 混用时哪个优先级高？","a":"@Bean 通常优先，因为后注册可能覆盖先注册的 @Component Bean。"}}', 17, 1793869798825, 1793869798825),
	(123, 2, 5, '依赖注入 · @Autowired 与 @Resource', '常用注解与机制辨析', 'high', '{"name":"依赖注入 · @Autowired 与 @Resource","category":"常用注解与机制辨析","priority":"high","summary":"@Autowired按类型注入（Spring提供），@Resource按名称注入（JDK提供），多Bean时分别用@Primary/@Qualifier和name属性消歧。","interview":"@Autowired和@Resource有什么区别？同类型有多个Bean时怎么解决？","principle":"@Autowired默认byType，找不到唯一Bean时按字段名匹配，可配required=false；@Resource默认byName，找不到再byType。多Bean歧义：@Primary标记默认首选，@Qualifier指定Bean名称，@Resource用name指定。","params":["@Autowired(required=false)允许注入失败为null","@Primary标在Bean定义上，同类型优先注入","@Qualifier(\"beanName\")精确指定候选Bean"],"pitfalls":["@Resource按名称匹配依赖字段名或name属性，改字段名可能注入失败","构造器注入多Bean时@Qualifier要写在参数上，不能只写字段上"],"selfCheck":{"q":"同类型有两个Bean，用@Autowired注入报错，两种解决办法？","a":"给其中一个Bean加@Primary设为默认；或在注入点加@Qualifier(\"beanName\")指定具体Bean。"}}', 18, 1793869805971, 1793869805971),
	(124, 2, 5, 'AOP · 基本概念与场景', '常用注解与机制辨析', 'medium', '{"name":"AOP · 基本概念与场景","category":"常用注解与机制辨析","priority":"medium","summary":"AOP把日志、事务、权限等横切逻辑抽成切面，通过代理在方法前后织入，不侵入业务代码。","interview":"AOP的实现原理是什么？AOP、拦截器、过滤器分别在什么场景用？","principle":"核心概念：切面Aspect、切点Pointcut、通知Advice、连接点JoinPoint。Spring AOP基于动态代理：有接口用JDK Proxy，无接口用CGLIB，在方法调用前后织入通知。适合方法级的横切逻辑。","params":["@Aspect定义切面，@Around/@Before/@After等定义通知","@Pointcut(\"execution(* com.xx.service.*(..))\")定义切点","同类内部方法调用不走代理，通知不生效"],"pitfalls":["过滤器在Servlet容器层，拦截器在Spring MVC层，AOP在Bean方法层，层次不同","AOP只能拦截Spring管理的Bean方法，静态方法和内部调用拦不到"],"selfCheck":{"q":"记录接口耗时，用过滤器、拦截器还是AOP？","a":"都行但分工不同：过滤器和拦截器能拿到请求上下文适合HTTP层；AOP适合任意Bean方法级的统一横切，如service层耗时统计。"}}', 19, 1793869805971, 1793869805971);

-- 导出  表 public.review_doc 结构
CREATE TABLE IF NOT EXISTS "review_doc" (
	"id" BIGINT NOT NULL,
	"user_id" BIGINT NOT NULL,
	"practice_id" BIGINT NOT NULL,
	"status" VARCHAR(16) NULL DEFAULT NULL,
	"content_json" TEXT NULL DEFAULT NULL,
	"progress_json" TEXT NULL DEFAULT NULL,
	"created_at" BIGINT NOT NULL,
	"updated_at" BIGINT NOT NULL,
	PRIMARY KEY ("id"),
	CONSTRAINT "review_doc_updated_at_not_null1" CHECK (updated_at IS NOT NULL),
	CONSTRAINT "review_doc_created_at_not_null1" CHECK (created_at IS NOT NULL),
	CONSTRAINT "review_doc_practice_id_not_null1" CHECK (practice_id IS NOT NULL),
	CONSTRAINT "review_doc_user_id_not_null1" CHECK (user_id IS NOT NULL),
	CONSTRAINT "review_doc_id_not_null1" CHECK (id IS NOT NULL)
)
CREATE INDEX "idx_reviewdoc_user_practice" ON "" ("user_id", "practice_id");;

