DELETE FROM "review_doc";
INSERT INTO "review_doc" ("id", "user_id", "practice_id", "status", "content_json", "progress_json", "created_at", "updated_at") VALUES
	(1, 2, 2, 'ready', '{"points":[{"name":"volatile · 可见性与原子性边界","category":"volatile 与可见性","priority":"high","summary":"volatile 保证可见性和有序性，但不保证复合操作的原子性。","interview":"volatile 能替代 synchronized 吗？它在原子性上有什么限制？","principle":"volatile 写会把工作内存刷回主存，读会从主存拉取，实现可见性；但 i++ 这类读-改-写是多步操作，两条线程可能同时读到旧值再各自加一，丢失更新，因此不原子。synchronized 通过锁互斥让临界区整体串行，可见性和原子性都覆盖。","params":["可见性：写立即刷回主存","原子性：只保证单次读/写的原子","有序性：禁止该变量前后指令重排"],"pitfalls":["i++、count += 1 等复合操作用 volatile 必丢更新","long/double 单次读写在 Java 规范中本就原子，volatile 额外解决的是可见性与对齐问题","以为 volatile 能当轻量锁用，性能未必优于 AtomicLong"],"selfCheck":{"q":"两个线程对 volatile int count 各执行 10000 次 count++，最终值一定等于 20000 吗？","a":"不一定。count++ 是读-改-写三步，volatile 不保证复合操作原子性，两个线程可能同时读到旧值后各自写回，导致更新丢失，最终小于 20000。"}},{"name":"volatile · 指令重排序与 happens-befo","category":"volatile 与可见性","priority":"high","summary":"volatile 写与后续读之间建立 happens-before，禁止重排序导致的脏读。","interview":"双检锁单例为什么 instance 必须加 volatile？","principle":"new 对象分三步：分配内存、初始化字段、把引用指向内存。JVM 可能重排成 1-3-2，另一线程在双检锁外看到非 null 引用但字段还没初始化，读到半成品对象。volatile 写禁止前面的初始化指令重排到赋值之后，且 volatile 写 happens-before 后续同变量的读，保证可见。","params":["happens-before：volatile 写先于同变量读","重排序：编译器/CPU/JIT 均可能重排","JDK5+ 内存模型才明确 volatile 语义"],"pitfalls":["双重检查少了 volatile，检查非 null 仍可能拿到半初始化对象","只有 instance 引用赋值那一刻被保护，构造函数内的共享状态仍需自行同步","以为 synchronized 块能挡住块外的 DCL 读取，其实块外的读根本没拿锁"],"selfCheck":{"q":"双检锁中，把 instance 声明成 static final 不加 volatile，会有什么问题？","a":"new 的指令可能重排为先赋引用再初始化字段，另一线程第一次检查发现非 null 就直接返回，拿到字段未初始化的半成品对象。final 也挡不住这种跨线程可见性问题。"}},{"name":"volatile · 典型使用场景","category":"volatile 与可见性","priority":"high","summary":"volatile 适合状态标志、一次性发布、DCL 引用，不适合计数器。","interview":"volatile 的正确使用场景有哪些？为什么用在计数器上是错的？","principle":"状态标志（如 shutdown flag）只写一次布尔值，单次写天然原子，volatile 提供可见性即可；一次性发布（配置/不可变对象）配合 final 也可；DCL 引用靠 volatile 禁重排。计数器是复合操作，需要原子类（CAS）或锁；多线程下计数用 AtomicLong、LongAdder 或 synchronized。","params":["状态标志：volatile boolean running = true","发布安全：volatile + 不可变对象","计数器替换：AtomicLong / LongAdder"],"pitfalls":["计数器用 volatile 是最常见误用，结果会偏小","LongAdder 高并发计数优于 AtomicLong，但读取要 sum() 且非强一致","volatile 集合引用只保护引用本身，集合内容的并发修改仍需同步"],"selfCheck":{"q":"一个只读标志位 volatile boolean stop，被多线程读、单线程写，需要再加锁吗？","a":"不需要。单线程写、多线程读的布尔标志没有复合操作，volatile 已保证写立即可见、禁止重排，加锁反而多余。"}},{"name":"CAS · 原理与三大问题","category":"CAS 与原子类","priority":"high","summary":"CAS 是无锁原子操作，靠比较并交换保证一致性，但有 ABA、开销、竞争三大问题。","interview":"面试怎么问：CAS 的原理是什么？有哪些问题？什么时候该放弃 CAS 改用锁？","principle":"CAS(V, expect, update)：读取 V，若等于 expect 则写入 update，否则重试。底层 CPU 指令（cmpxchg）保证原子性。三大问题：ABA 问题（用版本号 AtomicStampedReference 解决）、自旋开销（空转耗 CPU）、竞争激烈时反复失败。竞争激烈时自旋次数暴增，吞吐反降，应改用 synchronized 或 Lock 让线程阻塞让出 CPU。","params":["自旋次数上限：超过阈值应退化为锁","竞争线程数：远超 CPU 核数时慎用 CAS","版本号：AtomicStampedReference 解决 ABA"],"pitfalls":["CAS 只保证单个变量原子，复合操作仍需锁","长时间自旋会浪费 CPU，别在循环里无限重试","ABA 问题在引用/计数场景易被忽视"],"selfCheck":{"q":"高并发下 CAS 一直失败会怎样？何时改用锁？","a":"一直失败会导致线程自旋空转，CPU 飙高、吞吐下降。当竞争激烈、临界区复杂或涉及多变量时，应改用 synchronized/Lock 阻塞线程，避免无效自旋。"}},{"name":"AtomicInteger · 常用方法与适用场景","category":"CAS 与原子类","priority":"medium","summary":"AtomicInteger 提供原子自增自减等方法，适合低竞争计数；高并发下用 LongAdder 更优。","interview":"面试怎么问：AtomicInteger 常用方法有哪些？高并发计数选 AtomicLong 还是 LongAdder？","principle":"AtomicInteger 基于 CAS 实现原子操作，常用方法：incrementAndGet()、decrementAndGet()、getAndAdd(n)、compareAndSet(expect, update)。CAS 更新失败会自旋重试。竞争激烈时 LongAdder 把计数分散到多个 Cell，最后 sum() 汇总，减少 CAS 竞争，吞吐远高于 AtomicLong。","params":["incrementAndGet：自增并返回新值","compareAndSet(expect, update)：CAS 原子更新","LongAdder.sum()：最终汇总值"],"pitfalls":["AtomicInteger 只保证单个操作原子，多步复合操作仍需锁","get() 和 set() 不是原子的组合，别混用造成丢失","LongAdder 的 sum() 是弱一致，适合统计不适合精确同步"],"selfCheck":{"q":"高并发计数场景为什么推荐 LongAdder 而不是 AtomicLong？","a":"AtomicLong 所有线程对同一变量 CAS，竞争激烈时自旋频繁、性能差。LongAdder 分段计数，线程各自累加到不同 Cell，最后汇总，大幅降低 CAS 竞争，吞吐更高。"}},{"name":"synchronized · 三种使用形式与语义","category":"synchronized 与锁升级","priority":"high","summary":"三种形式锁不同对象，本质都是给对象头加锁保证原子性、可见性、有序性","interview":"synchronized 有哪三种用法？各自锁的是什么对象？","principle":"修饰实例方法锁当前实例 this；修饰静态方法锁 Class 对象；修饰代码块锁括号里指定对象。JVM 通过对象头 Mark Word 记录锁状态，进入时加锁、退出或异常时释放，保证同一锁内代码互斥，并通过内存屏障保证可见性和有序性。","params":["实例方法锁 this","静态方法锁 Class","代码块锁括号内对象"],"pitfalls":["锁临时 new 出来的对象每次不同，等于没锁","锁 String 字面量或 Integer 可能因常量池/缓存共享导致意外互斥或互斥失败","非静态方法与静态方法锁对象不同，不互斥"],"selfCheck":{"q":"两个线程一个调用非静态 synchronized 方法，一个调用静态 synchronized 方法，会互斥吗？","a":"不会。非静态方法锁的是实例对象 this，静态方法锁的是 Class 对象，两者锁对象不同，可以并发执行。要互斥必须用同一把锁。"}},{"name":"synchronized · 锁升级过程","category":"synchronized 与锁升级","priority":"high","summary":"synchronized 会随竞争升级：无锁→偏向锁→轻量级锁→重量级锁，减少不必要开销。","interview":"synchronized 的锁升级过程是怎样的？什么情况下会升级？","principle":"无竞争时用偏向锁（记录线程ID）；少量竞争用轻量级锁（CAS自旋替换Mark Word）；自旋失败或竞争激烈升级为重量级锁（OS互斥量，线程阻塞）。升级不可逆，JDK15后偏向锁默认关闭。","params":["JDK8默认开启偏向锁，JDK15+默认关闭","自旋次数由JVM自适应调整（约10次）","重量级锁涉及用户态/内核态切换"],"pitfalls":["升级不可逆，降级仅在特定GC阶段","高并发下synchronized并非慢，重量级锁吞吐量反而可能高于自旋","持有锁做慢IO会让线程长期阻塞，无法升级救场"],"selfCheck":{"q":"为什么说高并发场景下 synchronized 反而可能比自旋锁性能更好？","a":"因为激烈竞争下自旋浪费CPU，重量级锁让线程立即阻塞让出CPU，避免空转，吞吐量更高。"}},{"name":"synchronized · 等待唤醒与线程协作","category":"synchronized 与锁升级","priority":"medium","summary":"wait/notify 必须在 synchronized 块内调用，用 while 防虚假唤醒，优先 notifyAll 保证正确性。","interview":"为什么 wait 要放在 while 循环里而不是 if？notify 和 notifyAll 怎么选？","principle":"wait 释放锁并进入等待队列，notify/notifyAll 唤醒后需重新竞争锁。被唤醒线程从 wait 后继续执行，但唤醒条件可能已被其他线程消费（虚假唤醒），所以必须用 while 重新检查条件。notifyAll 唤醒全部让它们竞争，正确但开销大；notify 可能唤醒错误线程导致信号丢失。","params":["wait/notify/notifyAll 都是 Object 方法","wait 释放锁，sleep 不释放","notifyAll 性能开销略高但安全"],"pitfalls":["忘记 synchronized 会抛 IllegalMonitorStateException","用 if 判断条件会踩虚假唤醒，导致状态错误","notify 可能唤醒不该唤醒的线程，造成信号丢失或死锁"],"selfCheck":{"q":"虚假唤醒是什么？如何在代码上规避？","a":"线程在没有被 notify 时也可能被唤醒（JVM允许）。用 while 循环包裹 wait 并反复检查条件，条件不满足就继续 wait，即可规避。"}},{"name":"ReentrantLock · 与 synchronized","category":"Lock 体系","priority":"high","summary":"ReentrantLock 功能更强（可中断、超时、公平锁、多条件），但必须手动释放锁，风险更高。","interview":"ReentrantLock 和 synchronized 怎么选？各有什么风险？","principle":"synchronized 是JVM内置关键字，自动加解锁，异常安全；ReentrantLock 基于AQS，需 lock/unlock 手动配对，支持 tryLock、lockInterruptibly、公平锁、多个Condition。一般优先 synchronized，需要高级特性时用 ReentrantLock。","params":["ReentrantLock 默认非公平锁（new ReentrantLock(true)为公平）","Condition.await/signal 替代 wait/notify","tryLock 可设置超时时间"],"pitfalls":["unlock 必须放 finally，否则异常导致死锁","公平锁吞吐量低，默认非公平即可","用 ReentrantLock 实现等待通知要用 Condition，不能用 wait/notify"],"selfCheck":{"q":"什么业务场景下必须用 ReentrantLock 而不是 synchronized？","a":"需要尝试加锁（tryLock超时）、可中断等待（lockInterruptibly）、公平锁策略、或多条件队列（多个Condition）时必须用 ReentrantLock。"}},{"name":"ReentrantLock · 公平锁与非公平锁","category":"Lock 体系","priority":"medium","summary":"公平锁按FIFO排队但吞吐低，非公平锁允许插队但吞吐高，默认非公平。","interview":"ReentrantLock 公平锁和非公平锁区别？为什么默认用非公平？","principle":"非公平锁在 lock() 时先尝试 CAS 抢锁，抢不到才进队；公平锁直接判断队列中是否有前驱，有则排队。非公平锁刚释放的锁常被刚到线程直接拿走，省去线程唤醒的上下文切换，吞吐更高；公平锁严格 FIFO，避免饥饿但切换开销大。","params":["new ReentrantLock(true) 开启公平锁","默认 new ReentrantLock() 为非公平","tryLock() 不受公平性影响，直接抢"],"pitfalls":["公平锁吞吐下降主因是线程唤醒与切换开销，不是 CAS 慢","需要严格顺序或防止饥饿（如多个等价消费者）才值得上公平锁","可重入计数在两种模式下行为一致"],"selfCheck":{"q":"为什么非公平锁吞吐通常比公平锁高？","a":"非公平锁允许刚唤醒或新来的线程直接抢到刚释放的锁，避免线程切换与等待队列调度开销；公平锁强制 FIFO，每次唤醒都带来上下文切换成本。"}},{"name":"ReentrantLock · tryLock 超时与可中断","category":"Lock 体系","priority":"medium","summary":"tryLock 带超时可等待后抢锁，lockInterruptibly 可被中断，用于打破死锁与长时间阻塞。","interview":"tryLock 超时和 lockInterruptibly 解决什么问题？如何排查嵌套加锁死锁？","principle":"tryLock(timeout) 会自旋+CAS 进入队列，等待期间可被中断，超时返回 false 不会死等；lockInterruptibly 阻塞时收到 interrupt 会抛 InterruptedException 并释放已获资源。嵌套加锁死锁排查：jstack 抓线程栈看 FOUND deadlock，或统一加锁顺序、用 tryLock 超时兜底。","params":["tryLock(long timeout, TimeUnit unit)","lockInterruptibly() 响应中断","lock() 不响应中断，可能永久阻塞"],"pitfalls":["tryLock() 无参版不排队，抢不到立即返回 false，别当公平锁用","catch InterruptedException 后要恢复中断位或向上抛","嵌套多锁时 tryLock 失败要释放已持有锁，否则照样死锁"],"selfCheck":{"q":"用 tryLock 怎么避免嵌套加锁死锁？","a":"对第二把锁用 tryLock(timeout) 试探，拿不到就释放第一把锁并回退重试或走降级逻辑；配合统一加锁顺序更稳。"}},{"name":"Condition · 多条件等待唤醒","category":"Lock 体系","priority":"medium","summary":"Condition 让一把锁挂多个等待队列，await/signal 按条件精准唤醒，优于单一 wait/notify。","interview":"Condition 相比 wait/notify 好在哪？signal 用错会怎样？","principle":"每个 Condition 有独立的等待队列，await 释放锁并入队，signal 把节点移到锁的同步队列重新竞争。多条件（如 notFull/notEmpty）可精确唤醒对应线程，避免 notifyAll 全员唤醒的惊群。误用 signal 会唤醒错误条件的线程导致其再次 await，或漏 signal 造成永久等待。","params":["lock.newCondition() 创建条件","await() 释放锁并等待","signal() 唤醒一个，signalAll() 全部"],"pitfalls":["await 必须在持有该 lock 的同步块内调用","signal 后被唤醒线程还要重新抢锁，不是立即执行","误用 signal 可能丢失信号，条件判断必须用 while 循环"],"selfCheck":{"q":"Condition 的 await 为什么要配合 while 检查条件？","a":"signal 后线程要重新抢锁才能继续，期间条件可能被其他线程改回不满足（虚假唤醒/竞争），所以用 while 循环复查条件，防止在不满足时继续执行。"}},{"name":"AQS · 核心思想与模板结构","category":"AQS 原理","priority":"medium","summary":"AQS用一个volatile的state加CLH变体队列，子类只需重写少数方法就能得到同步器。","interview":"AQS的核心思想是什么？为什么用模板方法让子类只实现少量方法？","principle":"核心是维护一个volatile int state和一个FIFO等待队列（Node双向链表，CLH变体）。线程改state成功即获取资源，失败就入队并park阻塞。子类通过模板方法（如tryAcquire/tryRelease/tryAcquireShared）定义state语义，加锁入队阻塞的公共流程由AQS的acquire/release等方法统一实现。这样把同步器拆成\"子类定义资源语义 + 父类管排队调度\"，复用排队、唤醒、中断、超时等复杂逻辑。","params":["state：volatile int，语义由子类定义（如ReentrantLock里表示重入次数）","tryAcquire/tryRelease：独占式子类需重写，返回boolean","tryAcquireShared/tryReleaseShared：共享式子类需重写"],"pitfalls":["子类只需重写少量方法，但必须配合AQS提供的acquire/release模板调用才生效","tryAcquire等不负责排队阻塞，直接改state即可，别在子类里自己park"],"selfCheck":{"q":"AQS把同步器拆成了哪两部分职责？","a":"子类通过tryAcquire/tryRelease定义state资源语义；父类AQS负责排队、阻塞、唤醒、中断和超时等公共调度流程。"}},{"name":"AQS · ReentrantLock 的加锁解锁流程","category":"AQS 原理","priority":"medium","summary":"ReentrantLock基于AQS state实现可重入锁，非公平锁允许新线程插队抢state。","interview":"ReentrantLock加锁解锁的流程是什么？非公平锁插队有什么影响？","principle":"加锁：调lock()→sync.acquire(1)→tryAcquire(1)尝试CAS把state从0改1并记录owner线程（重入则state++）；失败则addWaiter入队成Node，acquireQueued里自旋检查前驱是否head，不是则park阻塞。解锁：tryRelease(1)把state减到0，unparkSuccessor唤醒队列下一个线程。非公平锁的nonfairTryAcquire在入队前直接CAS抢一次state（插队）；公平锁fairTryAcquire会先查队列里有没有前驱（hasQueuedPredecessors），有排队者就老实排队，不插队。","params":["state=0表示未锁，>0表示被持有（可重入次数）","nonfairSync默认new ReentrantLock()即非公平锁","公平锁new ReentrantLock(true)"],"pitfalls":["非公平锁可能让后来线程插队，导致队列里线程等待更久甚至饥饿，但吞吐量通常更高","公平锁严格按FIFO，不插队但吞吐低，因唤醒切换开销大","可重入必须在unlock时释放相同次数，否则state没归零其他线程拿不到锁"],"selfCheck":{"q":"公平锁和非公平锁在加锁流程上的关键差异是什么？","a":"非公平锁nonfairTryAcquire在入队前先直接CAS抢一次state可插队；公平锁会先用hasQueuedPredecessors检查队列有无等待者，有就排队不插队，保证FIFO。"}},{"name":"AQS · 共享模式与读写锁","category":"AQS 原理","priority":"low","summary":"共享模式允许多线程同时获锁，ReadWriteLock用读共享写独占提升读多写少吞吐。","interview":"AQS的共享模式怎么工作？ReadWriteLock读多写少有什么取舍？","principle":"共享模式tryAcquireShared返回>=0表示获取成功，可被多线程同时持有（如信号量、读锁），acquireShared获取失败同样入队park。ReadWriteLock用state高16位记读锁持有数、低16位记写锁重入数。读锁tryAcquireShared在无写锁时可共享获取；写锁tryAcquire独占，需读写都为0。读多写少时并发读大幅提升吞吐，但写线程要等所有读释放，读线程持续涌入会让写锁饥饿。","params":["tryAcquireShared返回值>=0获锁成功，<0需入队","state高16位读锁数，低16位写锁重入数","ReentrantReadWriteLock默认非公平"],"pitfalls":["读多写少读锁共享吞吐高，但可能写锁饥饿，写线程迟迟抢不到","公平模式ReadWriteLock可缓解写饥饿，但降低并发度","锁降级（写锁内再拿读锁再放写锁）可行，锁升级（读到写）不行会死锁"],"selfCheck":{"q":"ReadWriteLock在读多写少场景有什么问题？","a":"读锁共享大幅提升并发读吞吐，但写锁独占需等所有读释放，持续的读线程涌入可能导致写锁饥饿，可用公平模式缓解。"}},{"name":"volatile · 保证内存可见性","category":"volatile","priority":"medium","summary":"volatile 写后所有线程立即读到最新值，靠主内存强制同步","interview":"volatile 是怎么保证可见性的？","principle":"线程读写变量时会绕过各自的 CPU 缓存/工作内存：写操作把值刷回主内存，读操作从主内存拉最新值（JMM 的 happens-before：volatile 写 happen-before 后续读）。编译器和 CPU 不会在写前后缓存该变量到寄存器中保留旧值。","params":["- 修饰变量，不是方法或类","- 写入主内存、读取主内存是语义层面强制，不是某条特定指令"],"pitfalls":["可见性不等于原子性：i++ 仍会丢失更新","一个线程写，多个线程读时才能凸显效果，别把缓存一致性协议说成 volatile 直接做同步"],"selfCheck":{"q":"volatile 变量 i，多线程执行 i++，结果会等于预期吗？","a":"不会。i++ 是读-改-写三步，volatile 只保证每一步读到最新值，不保证三步原子，仍需 CAS 或加锁。"}},{"name":"volatile · 禁止指令重排","category":"volatile","priority":"medium","summary":"volatile 内存读写前后插入屏障，禁止重排跨越该点","interview":"volatile 是怎么禁止指令重排的？举个经典例子","principle":"JMM 规定 volatile 变量的读写是内存访问屏障点：编译器和 CPU 不能把普通读写重排到 volatile 写之前/读之后等跨越位置（对应 LoadStore、StoreStore、StoreLoad、LoadLoad 的组合约束）。经典例子是双检锁单例：对象实例变量必须 volatile，防止 new 对象的「分配内存→初始化→赋值引用」被重排成「分配内存→赋值引用→初始化」，其他线程看到半成品。","params":["- 仅约束该变量相关的重排，不是全序内存屏障","- 顺序语义是 JMM 保证，不依赖具体 CPU 指令"],"pitfalls":["只有写 volatile 变量那个点受保护，普通变量之间仍可重排","双检锁不加 volatile 是高频考点：会拿到半初始化对象"],"selfCheck":{"q":"双检锁单例中为什么实例字段要加 volatile？","a":"防止指令重排：对象未初始化完就被赋给引用，别的线程拿到 null 或半成品对象。"}},{"name":"volatile · 状态标志位典型用法","category":"volatile","priority":"medium","summary":"用 volatile boolean 做线程停止/开始标志，简单且无锁","interview":"volatile 最常用的场景是什么？怎么写一个优雅停机？","principle":"一个线程写标志位，其他线程轮询读取，volatile 保证每次读到最新值，从而及时响应状态变化。典型：`private volatile boolean running = true; while(running){...}`，关闭方置 running=false 即可。相比 stop() 更安全，不破坏锁和不变量。","params":["- 标志位一般是 boolean 或简单枚举/状态值","- 配合 while 轮询，读写分离，无需加锁"],"pitfalls":["别用于计数器或复合操作（不原子）","长循环要保证循环体内会读取标志，否则 JIT 可能把外提后看不到变化（volatile 修饰就能避免）"],"selfCheck":{"q":"为什么用 volatile boolean 停机比 Thread.stop() 好？","a":"stop() 会强制终止线程、破坏锁导致数据不一致；volatile 标志是协作式退出，线程自己决定退出时机，安全可控。"}},{"name":"volatile · 双检锁单例中的指令重排","category":"volatile","priority":"medium","summary":"DCL 单例必须用 volatile 禁止 new 操作的指令重排，避免读到半初始化对象。","interview":"双检锁单例为什么要给实例加 volatile？不加会出什么问题？","principle":"new 对象分为三步：分配内存、初始化对象、把引用指向内存。JVM 可能重排成 1-3-2。若线程 A 执行到 1-3 后被打断，线程 B 在外层判空通过，拿到的是未初始化完成的对象。volatile 通过内存屏障禁止这种重排。","params":["必须加在单例的静态实例字段上","锁对象是类的 Class 对象"],"pitfalls":["只用 synchronized 不加 volatile 仍可能读到半初始化对象","外层判空不能省，否则每次都加锁影响性能","反射、序列化仍可能破坏单例，DCL 不是万能的"],"selfCheck":{"q":"DCL 单例只用 synchronized 不加 volatile 会怎样？","a":"仍可能出问题。synchronized 只保证线程间互斥，但不禁止 new 操作内部的指令重排，其他线程可能读到未完成初始化的半成品对象，所以必须加 volatile。"}},{"name":"volatile · 禁止指令重排序","category":"volatile","priority":"medium","summary":"volatile通过内存屏障禁止特定指令重排，保证代码执行顺序符合预期。","interview":"volatile是怎么禁止指令重排序的？","principle":"JMM定义volatile写前写后、volatile读前读后插入内存屏障，禁止屏障两侧指令跨越重排。经典例子是双重检查锁单例：instance字段加volatile，避免new对象时分配内存、初始化、赋值引用三步被重排成先赋值再初始化，导致其他线程拿到未初始化对象。","params":["volatile写：前后各插屏障，写前禁止与上面读写互换，写后禁止与下面读写互换","volatile读：前后各插屏障，读前禁止与上面读写互换，读后禁止与下面读写互换"],"pitfalls":["volatile只保证修饰变量的读写顺序，不保证其他变量之间不重排","DCL单例不加volatile，可能读到半初始化对象"],"selfCheck":{"q":"双重检查锁单例为什么instance必须加volatile？","a":"new对象包含分配内存、初始化、赋值引用三步，可能被重排为先赋值引用再初始化；加volatile禁止重排，保证其他线程拿到已初始化完成的对象。"}},{"name":"volatile · 不保证复合操作原子性","category":"volatile","priority":"medium","summary":"volatile 保证可见性与有序性，但 i++ 等复合操作仍非原子，需原子类或锁。","interview":"为什么 volatile 变量做 i++ 还是会丢更新？","principle":"i++ 分为读取、加一、写回三步，volatile 只保证每次读到最新值、写立即可见，不阻止两个线程交错执行。要原子需 AtomicInteger 的 CAS、synchronized 或 Lock。","params":["可见性：写立即刷回主存","有序性：禁止指令重排","原子性：仅对单次读/写赋值保证"],"pitfalls":["boolean 标志位场景适合 volatile，计数器场景不适合","long/double 单次读写在 64 位 JVM 上已被规范保证原子，但复合操作仍不原子","用 volatile 保护计数是面试高频反例"],"selfCheck":{"q":"volatile int count; 两个线程各执行 count++ 1000 次，最终值可能是多少？","a":"小于 2000。++ 是读-改-写复合操作，两线程可能读到同一旧值后各写回一次，导致更新丢失。"}},{"name":"volatile · 可见性仅对被修饰变量生效","category":"volatile","priority":"medium","summary":"volatile 只让被修饰变量的读写跨线程可见，其他普通变量不受保护。","interview":"volatile int a; int b; 线程写 b 后写 a，另一线程读 a 后读 b，b 一定可见吗？","principle":"volatile 通过内存屏障保证：写 volatile 变量前的写操作对读该 volatile 的线程可见（写前不重排、读后不重排）。因此 b 只要写在 a 之前、读在 a 之后，借 a 的屏障即可间接可见，但 b 本身无 volatile 语义。","params":["只对被修饰字段的读写点建屏障","可见性依赖 volatile 变量作为''发布点''","不扩展到未被屏障覆盖的普通字段"],"pitfalls":["不要以为给一个字段加 volatile 就保护了整个对象或集合","可变对象内部字段的修改不因对象引用 volatile 而自动可见","面试要主动提''借用 volatile 做内存屏障''这个间接技巧"],"selfCheck":{"q":"volatile 引用 list，往 list 里 add 元素，其他线程读 list.size() 一定能拿到最新吗？","a":"不能保证。volatile 只保证引用本身可见，list 内部结构是普通字段，add 的修改无同步语义，需 Collections.synchronizedList 或加锁。"}},{"name":"happens-before 与 volatile 禁止重排","category":"volatile","priority":"medium","summary":"happens-before 定义可见与有序规则，volatile 写读建立 hb 关系从而禁止重排。","interview":"volatile 是怎么保证有序性的？happens-before 规则里哪条和它对应？","principle":"JMM 用 happens-before 判断两操作的可见与顺序。规则：volatile 写 happens-before 后续对该变量的 volatile 读；另有程序顺序、锁、线程启动/终止、传递性。编译器与 CPU 不能跨越 hb 关系重排，通过读写屏障在 volatile 点插入屏障实现。","params":["volatile 写 → 后续 volatile 读 有 hb","hb 具传递性可推导更远的可见","单线程内程序顺序默认有 hb"],"pitfalls":["happens-before 不是时间先后，是可见性与有序性的偏序约定","两线程各自读 volatile 不构成 hb，仍可能看到对方之前的普通写问题","只保证不重排到屏障两侧，不会禁止屏障内部的重排优化"],"selfCheck":{"q":"线程 A：x=1; volatileFlag=true; 线程 B：if(volatileFlag) print(x)，B 一定打印 1 吗？","a":"一定。A 对 volatileFlag 的写 happens-before B 对它的读，借传递性 x=1 对 B 可见，且指令不重排到 volatileFlag 写之后。"}},{"name":"volatile · 指令重排序与happens-befor","category":"volatile","priority":"medium","summary":"volatile 保证可见性和禁止重排序，但不保证原子性，通过 happens-before 保证有序。","interview":"面试怎么问：volatile 解决了什么问题？指令重排和 happens-before 是怎么回事？","principle":"volatile 修饰变量：① 可见性：写立即刷回主存，读从主存取；② 禁止指令重排序：编译器和处理器不把 volatile 变量前后的指令乱序。happens-before：volatile 写 happens-before 后续读，保证有序性。典型应用：双重检查锁单例（防止对象半初始化）、状态标志位。","params":["适用场景：状态标志、DCL 单例","不保证原子性：i++ 仍需锁或原子类","内存屏障：插在 volatile 读写前后"],"pitfalls":["volatile 不是原子的，volatile int i; i++ 依然会丢更新","只保证单变量可见性，多变量复合操作需锁","滥用 volatile 会插内存屏障，影响性能"],"selfCheck":{"q":"volatile 能否保证 i++ 的原子性？为什么？","a":"不能。volatile 只保证可见性和有序性，i++ 是读-改-写三步，多线程下仍会丢失更新。需要原子性必须用 synchronized、Lock 或原子类。"}},{"name":"volatile · 引用替换与对象字段修改的可见性差异","category":"volatile","priority":"medium","summary":"volatile保证引用赋值可见，但不保证对象内部字段修改的可见性。","interview":"volatile修饰对象引用，修改对象内部字段，其他线程能立即看到吗？","principle":"volatile修饰引用变量时，只对该引用的读写建立happens-before：引用指向新对象时，新对象的初始化内容对读线程可见。但对旧对象内部字段的修改是普通字段写，不触发volatile语义，也不会刷新缓存或加内存屏障，其他线程可能读到旧值。","params":["仅对引用本身的赋值和读取生效","对象字段默认不具volatile语义","配合final可保证构造期安全发布"],"pitfalls":["误以为volatile对象的字段全变volatile","对象内部字段修改仍需synchronized/Atomic/加volatile字段","可变对象共享时优先用不可变对象替换引用"],"selfCheck":{"q":"volatile List替换整个List和对List做add操作，可见性有什么不同？","a":"替换引用（list=new ArrayList）对读线程立即可见；add修改旧List内部字段，其他线程不保证可见，需额外同步手段。"}},{"name":"synchronized · 实例锁与类锁互斥关系","category":"synchronized","priority":"medium","summary":"实例锁锁对象实例，类锁锁Class对象，两者不互斥，可同时进入。","interview":"一个线程持synchronized实例方法，另一线程能进synchronized静态方法吗？","principle":"synchronized实例方法锁的是this对象，synchronized静态方法锁的是该类的Class对象。this与Class是两个不同对象，内部各有一把monitor，因此两把锁互不相关，可并发执行。只有锁同一个对象（同一个this或同一个Class）的synchronized块才会互斥。","params":["实例方法锁this","静态方法锁ClassName.class","同步块锁括号内指定对象"],"pitfalls":["误以为同一类的所有synchronized都互斥","静态与实例同步方法并发执行会产生线程安全问题","想让它们互斥，需显式指定同一个锁对象（如ClassName.class）"],"selfCheck":{"q":"synchronized实例方法和synchronized static方法能并发执行吗？","a":"能。前者锁this，后者锁Class对象，是两把不同的锁，不会互斥，可同时进入临界区。"}},{"name":"synchronized · 锁对象辨析（实例/类/方法）","category":"synchronized","priority":"medium","summary":"synchronized方法锁调用者对象，代码块锁括号指定对象，必须辨析锁的是谁。","interview":"synchronized(this)、synchronized(ClassName.class)、synchronized普通方法分别锁什么对象？","principle":"synchronized修饰实例方法时锁this（当前对象实例）；修饰静态方法时锁ClassName.class（类的Class对象）；修饰代码块时锁括号中指定的对象，可以是this、Class、任意共享对象。只有锁同一个对象的同步块才互斥，锁不同对象则完全并发。","params":["实例方法→this","静态方法→ClassName.class","代码块→括号内对象"],"pitfalls":["锁new出来的临时对象等于没锁（每次不同）","锁Integer等自动装箱对象可能因缓存/对象不同导致失效","字符串字面量作为锁可能被多处共享导致意外互斥"],"selfCheck":{"q":"两个线程分别对同一对象的synchronized(this)块和synchronized实例方法操作，会互斥吗？","a":"会。两者锁的都是同一个this对象，monitor相同，因此互斥；但若锁的是不同对象（如不同实例）则不互斥。"}},{"name":"synchronized锁升级 · 升级后状态变化与降级","category":"synchronized","priority":"medium","summary":"synchronized随竞争升级：无锁→偏向锁→轻量级锁→重量级锁，只升不降为主，避免过早加锁开销。","interview":"synchronized的锁升级过程是怎样的？升级后还会降级吗？","principle":"Mark Word记录锁状态。无竞争时用偏向锁（记录线程ID）；有少量竞争用CAS自旋升级轻量级锁；竞争激烈膨胀为重量级锁（OS互斥量，线程阻塞）。偏向锁可撤销，重量级锁在GC等安全点可降级（如批量重偏向/撤销），实际以只升不降理解更安全。","params":["偏向锁延迟默认约4秒（JVM启动后才启用）","自旋次数/自适应自旋由JVM决定","JDK15后偏向锁默认关闭（JEP 374）"],"pitfalls":["偏向锁不是无锁，仍涉及对象头写入与撤销成本","锁降级只在特定GC阶段发生，业务上不要依赖","大量小对象短同步时升级策略反而更划算"],"selfCheck":{"q":"为什么synchronized要有锁升级而不是一开始就用重量级锁？","a":"重量级锁需内核态切换和线程挂起，开销大；大部分同步段无竞争或低竞争，轻量级CAS自旋成本更低，升级机制平衡性能与正确性。"}},{"name":"synchronized · 实例锁与类锁的锁定对象","category":"synchronized","priority":"medium","summary":"实例锁锁的是当前对象（this），类锁锁的是Class对象，两者互不阻塞。","interview":"synchronized的实例锁和类锁锁的是什么对象？会互斥吗？","principle":"synchronized(obj)或实例方法锁的是对象实例的Monitor；static synchronized或synchronized(Xxx.class)锁的是Class对象的Monitor。不同对象头/Monitor，所以实例锁和类锁并发执行不冲突，只有同一把Monitor才互斥。","params":["synchronized(this) = 实例锁","synchronized(Xxx.class) = 类锁","每个对象一个Monitor，Class也是一个对象"],"pitfalls":["实例方法锁的是this，多实例时每个实例各自独立，不互斥","不要以为\"同一个类\"的锁都是一把，实例锁与类锁是两把","synchronized(常量池里的字符串)可能因intern复用造成意外全局锁"],"selfCheck":{"q":"两个线程分别对同一个类的实例方法和静态方法加synchronized，会互斥吗？","a":"不会。实例方法锁this对象的Monitor，静态方法锁Class对象的Monitor，是两把不同的锁，可以并发执行。"}},{"name":"synchronized 静态方法与实例方法锁对象辨析","category":"synchronized","priority":"medium","summary":"静态synchronized锁Class对象，实例synchronized锁this，二者可并发，辨析关键看是不是static。","interview":"synchronized修饰的静态方法和实例方法，锁对象分别是什么？","principle":"方法级synchronized隐式指定锁对象：静态方法同步的是Class对象（方法区中的Class结构对应的对象），实例方法同步的是当前实例this。进入同步方法即执行monitorenter，退出执行monitorexit，异常也会释放锁。","params":["静态方法：锁Xxx.class","实例方法：锁this","方法内部可再用synchronized块换锁对象"],"pitfalls":["同一对象的两个实例方法都用synchronized时互斥，因为锁同一个this","构造方法不能声明synchronized（Java不支持）","同步方法锁粒度是整个方法，长方法易造成性能问题，可改同步块缩小范围"],"selfCheck":{"q":"类A的静态synchronized方法m1和实例synchronized方法m2，线程1调用m1、线程2调用a.m2，能否同时进入？","a":"能。m1锁A.class对象的Monitor，m2锁实例a的Monitor，两把锁不同，互不影响，可以同时进入执行。"}},{"name":"复合操作非原子 · i++ 内存语义","category":"Java并发基础","priority":"medium","summary":"i++ 是读-改-写三步复合操作，多线程下会丢更新。","interview":"为什么多线程下 i++ 会丢更新？","principle":"i++ 分三步：读主存值到线程栈、加 1、写回主存。两线程可能读到同一旧值，各自加 1 后写回，结果只加了 1。即使变量加 volatile，也只能保证每一步可见，无法把三步合并成原子操作。","params":["i++ 等价于 i = i + 1，非原子","volatile 只保证可见性，不保证复合操作原子"],"pitfalls":["volatile int i 不能解决 i++ 并发丢更新","应改用 AtomicInteger 或加锁"],"selfCheck":{"q":"10 个线程各对 i 执行 1000 次 i++，最终 i 一定是 10000 吗？","a":"不一定。i++ 是读-改-写复合操作，多线程下会互相覆盖，最终值通常小于 10000。要保证正确需用 AtomicInteger 或加锁。"}},{"name":"原子性 · 复合操作不保证原子","category":"Java并发基础","priority":"medium","summary":"原子性指一个操作不可中断，要么全做要么不做。","interview":"什么是原子性？为什么复合操作不是原子的？","principle":"原子性要求操作序列在执行中不被其他线程插入。Java 里单条基本类型读写是原子的，但 a++、if(x==1)x=2、check-then-act 这类多步操作会被线程切换打断，需靠 synchronized、Lock 或原子类保证。","params":["long/double 读写在 32 位 JVM 上可能非原子","JMM 保证引用读写原子"],"pitfalls":["synchronized 只保证被它包住的代码块原子","不要以为单个语句就是原子的"],"selfCheck":{"q":"check-then-act（先判断再改）为什么不是原子的？","a":"判断和修改是两步，中间可能被其他线程插入，导致条件已失效仍在执行。必须用锁或原子 CAS 把两步合并成原子操作。"}},{"name":"CAS · 适用场景选型（无锁 vs 加锁）","category":"并发与锁","priority":"medium","summary":"低竞争、临界区短选CAS，高竞争或临界区长选锁。","interview":"什么时候用CAS无锁，什么时候直接上锁？","principle":"CAS基于CPU原子指令，先读旧值再比较交换；无锁实现下竞争低时开销小，但竞争高会自旋浪费CPU；锁会让线程挂起让出CPU，竞争高时吞吐更稳。","params":["AtomicInteger等类默认基于Unsafe的CAS","自旋默认无上限（LongAdder除外）","synchronized轻量级→重量级锁阈值由竞争动态决定"],"pitfalls":["CAS只保证单变量原子性，多变量需AtomicReference+不可变对象或锁","ABA问题需版本号（AtomicStampedReference）","高竞争下CAS吞吐可能低于加锁"],"selfCheck":{"q":"一个多变量的校验+更新操作，用CAS怎么做？","a":"把多个变量封装成不可变对象，用AtomicReference对该对象整体CAS；失败重读重试。或直接用锁。"}},{"name":"CAS · 自旋开销与高并发下的性能退化","category":"并发与锁","priority":"medium","summary":"CAS 无锁但自旋会空转，竞争激烈时 CPU 空耗，性能反而不如锁。","interview":"CAS 在高并发下为什么可能比 synchronized 更慢？","principle":"CAS 用 compareAndSet 循环重试更新，失败就自旋。线程少时无阻塞开销低；竞争激烈时大量线程反复读-比-写失败，CPU 空转浪费，且只有单个变量能保证原子，多个变量需加锁或合并。","params":["AtomicInteger 内部依赖 Unsafe.compareAndSwapInt","JDK9+ 用 VarHandle，语义一致"],"pitfalls":["ABA 问题需用 AtomicStampedReference 加版本号","自旋次数无上限会烧 CPU，可用 LongAdder 分段降低竞争"],"selfCheck":{"q":"CAS 的 ABA 问题是什么，怎么解决？","a":"值从 A 改 B 再改回 A，CAS 判定成功但中间已被改过；用带版本号的 AtomicStampedReference 解决。"}},{"name":"synchronized · 锁对象选择（类对象 vs 实例","category":"并发与锁","priority":"medium","summary":"锁实例对象只互斥同一实例，锁类对象互斥所有实例的静态同步方法。","interview":"synchronized(this) 和 synchronized(类.class) 的区别是什么？","principle":"synchronized(obj) 用 obj 的对象头做锁。锁 this 或非静态同步方法锁的是当前实例，多实例间不互斥；锁 类.class 或静态同步方法锁的是 Class 对象，所有实例共用一把锁。锁 null 会抛 NPE。","params":["非静态方法默认锁 this","静态方法默认锁 当前类.class","字面量 String 会被常量池共享，易误锁"],"pitfalls":["String 常量或 Integer 缓存对象当锁会意外互斥","锁对象应声明为 private final，防止被外部替换或重新赋值"],"selfCheck":{"q":"两个实例同时调用同一个非静态 synchronized 方法会互斥吗？","a":"不会。非静态 synchronized 锁的是各自 this，两个实例的锁不同，可以并发执行；改成静态方法或锁 class 才互斥。"}},{"name":"synchronized锁升级 · 单向不可逆与不可降级","category":"并发与锁","priority":"medium","summary":"锁按偏向→轻量→重量级单向升级，不会降级，也不可逆。","interview":"synchronized 的锁升级过程是怎样的，能降级吗？","principle":"对象头 Mark Word 记录锁状态：无锁→偏向锁（记录线程 ID，无同步直接进入）→轻量级锁（CAS 自旋抢锁）→重量级锁（膨胀为 Monitor，阻塞排队）。竞争加剧才升级，升级后不会退回偏向或轻量，JVM 默认不主动降级。","params":["JDK15 起偏向锁默认关闭（-XX:+UseBiasedLocking 可开）","自适应自旋次数由 JVM 根据历史动态调整"],"pitfalls":["锁升级不可逆，偏向锁一旦膨胀到重量级就常驻","批量撤销偏向后该类对象会禁用偏向，不要依赖偏向锁优化"],"selfCheck":{"q":"锁升级是单向还是双向的，为什么？","a":"单向。升级靠竞争加剧触发，降级缺少可靠的触发时机且实现复杂，JVM 未做降级，重量级锁一旦产生不会退回轻量或偏向。"}},{"name":"volatile · DCL单例中的指令重排与对象逸出","category":"并发与锁","priority":"medium","summary":"volatile禁止DCL中new对象的指令重排，防止读到半初始化对象。","interview":"DCL单例为什么instance要加volatile？不加会出什么问题？","principle":"new对象分三步：分配内存、初始化、把引用指向内存。2、3步可能重排，导致另一线程在if(instance==null)判空失败后，直接拿到未初始化完的对象。volatile写建立happens-before读，禁止该重排并保证可见性。","params":["volatile保证可见性+禁止重排，不保证原子性","DCL中双重判空：外层减少锁竞争，内层防止重复创建","JDK5后volatile语义按JSR-133增强"],"pitfalls":["不加volatile可能出现对象逸出：其他线程拿到半初始化实例","volatile对i++这类复合操作无效，仍需CAS或锁","静态内部类懒加载是更简洁的替代方案"],"selfCheck":{"q":"不加volatile的DCL会有什么现象？","a":"线程B可能在判空失败后拿到未构造完成的对象，调用其方法时字段为默认值，出现状态不一致。"}},{"name":"CAS · 高竞争下的自旋与退化到锁","category":"CAS","priority":"medium","summary":"高竞争时CAS自旋空转浪费CPU，需退化为LongAdder或锁。","interview":"CAS在高并发计数场景有什么问题？怎么优化？","principle":"CAS失败后循环重试，线程多时大量自旋浪费CPU且缓存行反复失效。优化：1.用LongAdder分段累加降低争用，最后sum合并；2.自旋N次失败后升级为阻塞锁（如synchronized升级重量级）；3.加随机退避。","params":["LongAdder按CPU核数分Cell，最终sum求和","synchronized自旋次数默认由JVM自适应调整","JDK9+可用VarHandle做更细粒度CAS"],"pitfalls":["LongAdder的sum()非原子，高并发下取值有误差，适合统计不适合严格顺序","退化到锁后唤醒开销大，适合竞争持续高的场景","自旋阈值不当会CPU打满或频繁阻塞"],"selfCheck":{"q":"AtomicLong和LongAdder在1000线程++场景谁快？为什么？","a":"LongAdder快。AtomicLong所有线程争同一个变量，CAS冲突率高；LongAdder分散到多个Cell累加，最后合并，大幅降低争用。"}},{"name":"CAS · 比较并交换流程","category":"CAS","priority":"medium","summary":"CAS 是无锁原子操作：比较旧值一致才写入新值，否则重试或失败。","interview":"讲讲 CAS 的执行流程，它为什么是原子的？","principle":"CAS(V,A,B)：读取内存值 V 与期望值 A 比较，相等则写入 B，不等则失败。整个比较+写入由 CPU 指令（如 x86 的 cmpxchg）保证原子性，Java 通过 Unsafe 调用。典型应用是 Atomic 类与自旋更新。","params":["V：内存当前值","A：期望旧值","B：要写入的新值"],"pitfalls":["ABA 问题：值改回原样后 CAS 无法察觉，需 AtomicStampedReference 加版本号","依赖 CPU 指令支持，不是所有平台都等价","需要配合 volatile 保证读到的旧值可见性"],"selfCheck":{"q":"CAS 为什么不需要加锁就能保证原子性？","a":"比较和交换由 CPU 单条指令（如 cmpxchg）完成，中间不会被其他线程打断；Java 通过 Unsafe 调用该指令，所以无需锁。"}},{"name":"CAS · 高并发自旋开销","category":"CAS","priority":"medium","summary":"CAS 失败重试（自旋）在高竞争下 CPU 空转，开销可能超过锁。","interview":"CAS 在高并发下有什么问题？自旋会带来什么开销？","principle":"CAS 失败时通常循环重试。竞争激烈时，大量线程反复读-比较-失败，CPU 忙等却不干活；且每次都要写总线引发缓存一致性流量。轻竞争时 CAS 比锁快，重竞争时反而劣于 synchronized。自旋锁通常配合有限次数或退避策略。","params":["自旋次数：常见设阈值如 10 次后升级为阻塞","锁升级策略：竞争大时转为 OS 互斥"],"pitfalls":["活锁风险：线程持续失败但不阻塞","CPU 资源浪费：自旋线程不释放 CPU","LongAdder 分段累加可缓解热点计数竞争"],"selfCheck":{"q":"为什么高并发计数推荐 LongAdder 而不是 AtomicLong？","a":"AtomicLong 所有线程 CAS 同一变量导致高失败率和自旋浪费；LongAdder 把计数分散到多个 Cell，竞争时各改各的，最后 sum 合并，吞吐高得多。"}},{"name":"volatile 与 CAS 适用场景对比","category":"CAS","priority":"medium","summary":"volatile 解决可见性和有序性，CAS 解决原子性的读-改-写；二者常配合使用。","interview":"volatile 和 CAS 各解决什么问题？什么时候用哪个？","principle":"volatile 保证变量的可见性和禁止指令重排，但不保证复合操作（如 i++）的原子性。CAS 提供原子的比较并交换，解决更新原子性。典型组合：线程内读取 volatile 状态做判断，再用 CAS 更新。volatile 适合状态标志、DCL 单例；CAS 适合计数器、无锁数据结构。","params":["volatile：修饰变量，保证读写直通主内存","CAS：通过 Unsafe/Atomic 类实现原子更新"],"pitfalls":["volatile 不等于线程安全，i++ 仍会丢失更新","volatile 不保证复合操作原子性","CAS 会掩盖可见性问题：只 CAS 不加 volatile 可能读到过期状态"],"selfCheck":{"q":"volatile 修饰的 int 做 i++，多线程下安全吗？","a":"不安全。i++ 是读-改-写三步，volatile 只保证每次读到最新值，不保证三步原子性，仍会丢失更新。应使用 AtomicInteger 或加锁。"}},{"name":"volatile · 保证可见性但不保证原子性","category":"Java多线程锁机制","priority":"medium","summary":"volatile 保证可见性和有序性，不保证复合操作原子性。","interview":"volatile 解决什么问题？为什么不保证原子性？","principle":"volatile 写会把工作内存刷回主存，volatile 读会从主存取，并建立 happens-before 防止指令重排。但 i++ 这类读-改-写是多步，volatile 只保证每步读到的都是最新值，不能合并成一步，所以不保证原子。","params":["典型场景：状态标志位 flag","典型场景：DCL 双重检查锁单例"],"pitfalls":["volatile int count 做 count++ 仍会丢更新","volatile 不替代 synchronized 或原子类"],"selfCheck":{"q":"volatile 适合用在什么场景？","a":"适合一写多读的标志位或状态变量，如 stop 标志、DCL 单例里的 instance。不适合做 count++ 等复合操作，需用 AtomicInteger 或加锁。"}},{"name":"i++ · 读改写三步复合操作非原子","category":"Java多线程锁机制","priority":"medium","summary":"i++ 是读-改-写三步,多线程下会丢更新,必须用原子类或加锁保证。","interview":"为什么 i++ 在多线程下线程不安全?","principle":"i++ 拆成三步:①从主内存读 i 到工作内存 ②CPU 计算 i+1 ③写回主内存。线程 A 执行完①后被切换,线程 B 也读到旧值并写回,A 再写回就把 B 的结果覆盖,导致少加。volatile 只保证可见性和禁止重排,不保证这三步的复合原子性,救不了 i++。","params":["volatile 只保可见性,不保复合操作原子性","AtomicInteger.incrementAndGet() 内部用 CAS 保证原子","synchronized 或 ReentrantLock 同步代码块可保证原子"],"pitfalls":["常见误以为 volatile int i; 能让 i++ 安全","读写并发度高时丢更新数量少但仍存在,不要用肉眼判断","i = i+1、i += 1、i-- 都是同样的非原子复合操作"],"selfCheck":{"q":"用 volatile int i 修饰后,i++ 还会丢更新吗?","a":"会。volatile 只保证可见性和有序性,不保证复合操作的原子性。i++ 仍可拆成读-改-写三步,线程切换会丢更新。要安全需 AtomicInteger 或 synchronized。"}},{"name":"CAS · 高竞争下的适用性与放弃策略","category":"Java多线程锁机制","priority":"medium","summary":"CAS 低竞争高效，高竞争下自旋空转浪费 CPU，需退化为锁或分段","interview":"CAS 在高并发竞争激烈时有什么问题？应该怎么取舍？","principle":"CAS 通过比较并交换无锁更新，失败则循环重试。竞争激烈时大量线程同时失败自旋，CPU 空转且只有少数成功，吞吐量反而低于 synchronized。此时应改用互斥锁让线程阻塞排队，或用 LongAdder、分段 CAS、限次重试后退避等手段降低竞争。","params":["LongAdder 把热点值拆成多段累加，读取时再汇总，适合写多读少","JDK8 后 synchronized 有锁升级和自适应自旋，低竞争下不一定比 CAS 差","可用循环次数阈值或退避策略限制无脑自旋"],"pitfalls":["ABA 问题：值改回原样后 CAS 成功，但中间过程丢失，需版本号（AtomicStampedReference）","自旋重试无上限在高竞争下会严重浪费 CPU，甚至引发活锁","CAS 适合简单计数、状态位等单变量场景，复杂复合操作仍需锁"],"selfCheck":{"q":"什么时候该放弃 CAS 改用锁？","a":"竞争激烈、CAS 多次失败自旋空转、需要保证多个变量的原子复合操作，或需要公平排队时，改用 synchronized/Lock 更合适。"}},{"name":"Lock · tryLock 与带超时 tryLock 的区","category":"Java多线程锁机制","priority":"medium","summary":"tryLock 立即返回成败，带超时的 tryLock 会等一段时间再放弃。","interview":"tryLock() 和 tryLock(long, TimeUnit) 有什么区别？","principle":"tryLock() 不进等待队列，直接尝试抢锁，抢不到立刻返回 false；带超时版本先试一次，失败后进队列自旋+挂起，在超时时间内等锁，期间可被中断，超时返回 false。","params":["tryLock() 无参版不响应中断","tryLock(long time, TimeUnit unit) 超时后返回 false","抢到锁返回 true"],"pitfalls":["无参 tryLock 可能活锁或饿死，需自己控制重试","带超时版等待期间可被 interrupt，抛 InterruptedException","tryLock 抢到锁后必须在 finally 里 unlock，否则死锁"],"selfCheck":{"q":"为什么说 tryLock() 不适合替代公平锁？","a":"tryLock() 直接插队抢锁，无视等待队列顺序，破坏公平性，可能导致排队线程长期拿不到锁（饥饿）。"}},{"name":"synchronized · 方法锁与静态方法锁的对象差异","category":"Java多线程锁机制","priority":"medium","summary":"实例方法锁当前对象this，静态方法锁Class对象，锁粒度不同不能互斥。","interview":"synchronized修饰实例方法和静态方法时，锁的对象分别是什么？它们会互斥吗？","principle":"synchronized修饰实例方法时，锁的是当前实例对象this；修饰静态方法时，锁的是该类的Class对象（如MyClass.class）。两者是不同的Monitor对象，因此同一实例的实例方法和静态方法不会互斥，可同时进入。","params":["实例方法锁：this","静态方法锁：MyClass.class","同步代码块：显式指定任意对象作为锁"],"pitfalls":["静态方法与实例方法不互斥，想互斥需都锁Class对象或都锁同一实例","锁Class对象是类级别，所有实例共享，会成为并发瓶颈","不要锁String常量或Integer等共享缓存对象，容易和其他代码互相干扰"],"selfCheck":{"q":"一个类中synchronized实例方法和synchronized静态方法，在多线程下能否同时执行？","a":"可以。实例方法锁this对象，静态方法锁Class对象，两把不同的锁互不影响，因此能同时进入并发执行。"}},{"name":"自增操作 · 非原子导致计数丢失","category":"多线程基础","priority":"medium","summary":"i++ 是读-改-写三步，多线程下会互相覆盖导致计数丢失。","interview":"为什么多线程下 int i++ 会比预期结果小？","principle":"i++ 分三步：读取 i、加 1、写回。两个线程可能读到同一个旧值，各自加 1 后写回，结果只加了一次。解决办法：synchronized、ReentrantLock、AtomicInteger 的 CAS 自增。","params":["AtomicInteger.incrementAndGet() 用 CAS 实现原子自增","高并发下 AtomicLong/LongAdder 性能更好","LongAdder 分段累加，适合读多写少"],"pitfalls":["volatile 只保证可见性，不能保证 i++ 原子性","AtomicInteger 在极高竞争下 CAS 自旋浪费 CPU，考虑 LongAdder","LongAdder 的 sum() 不是原子快照"],"selfCheck":{"q":"volatile int i; i++ 在多线程下安全吗？","a":"不安全。volatile 保证可见性和有序性，但 i++ 是读-改-写复合操作，仍会丢失更新，必须用锁或原子类。"}},{"name":"ReentrantLock · 可重入次数上限","category":"Lock","priority":"medium","summary":"ReentrantLock 可重入次数受限于 int 计数，理论上锁重入次数上限约 21 亿次。","interview":"ReentrantLock 的可重入次数有上限吗？","principle":"ReentrantLock 内部用 state（int）记录重入次数，每次 lock state+1，unlock state-1，减到 0 才真正释放锁。state 是 32 位 int，最大值 Integer.MAX_VALUE，超过会溢出报错。","params":["state 为 int 类型，上限 Integer.MAX_VALUE","每次 lock/lock 必须配对 unlock","公平锁和非公平锁都有可重入性"],"pitfalls":["lock 次数多于 unlock 会导致其他线程永远拿不到锁","unlock 次数多于 lock 会抛 IllegalMonitorStateException","实际业务几乎不会达到重入上限，但要避免 lock/unlock 不配对"]},{"name":"ReentrantLock 公平锁与非公平锁","category":"Lock","priority":"medium","summary":"非公平锁吞吐高但可能饥饿，公平锁按序排队无饥饿但吞吐低。","interview":"ReentrantLock 公平锁和非公平锁有什么区别？怎么选？","principle":"非公平锁在 lock 时先尝试插队 CAS 抢 state，失败才进队列；公平锁先检查队列里有没有前驱，有就乖乖排队。默认非公平。吞吐差异来自插队省去唤醒线程的上下文切换。","params":["构造 new ReentrantLock(true) 为公平，默认 false 非公平","tryLock() 不排队，直接抢一次","state 可重入，同线程重入计数+1"],"pitfalls":["公平锁吞吐明显低，别默认上公平","非公平可能让排队线程长期抢不到，不适合对延迟敏感场景","tryLock() 本质非公平，公平参数对它无效"],"selfCheck":{"q":"为什么默认用非公平锁？","a":"非公平线程能直接插队获取锁，避免刚释放锁就唤醒下一个线程带来的上下文切换开销，整体吞吐更高。"}},{"name":"Condition 等待队列与 signal 精准唤醒","category":"Lock","priority":"medium","summary":"每个 Condition 对应一个等待队列，signal 只唤醒该队列上的一个线程，实现精准唤醒。","interview":"Condition 的 await/signal 和 wait/notify 有什么区别？怎么实现精准唤醒？","principle":"Lock 可创建多个 Condition，每个 Condition 维护自己的等待队列。await 释放锁并入队阻塞，signal 从该队列取一个线程移入同步队列去抢锁，故只唤醒指定条件的线程。","params":["Condition 由 lock.newCondition() 创建","可创建多个实现按条件分组唤醒","signalAll 唤醒该队列全部线程"],"pitfalls":["signal 调用前必须持有该 Lock，否则抛 IllegalMonitorStateException","await 会释放锁，被唤醒后仍需重新抢锁","在 await 之前调用 signal，该信号会丢失"],"selfCheck":{"q":"为什么 Condition 能做到精准唤醒而 wait/notify 不能？","a":"因为每个 Condition 有独立等待队列，signal 只作用于该队列；而 wait/notify 共用对象的单一等待队列，notify 会随机唤醒一个等待线程。"}},{"name":"synchronized · 竞态条件导致重复扣款","category":"多线程问题","priority":"medium","summary":"多线程读改写共享余额无同步，导致扣款次数超过余额。","interview":"为什么高并发下会出现重复扣款？怎么用 synchronized 解决？","principle":"扣款是非原子的三步：读余额、判断、写回。两个线程同时读到 100，各自判断够扣、各自写回 90，实际扣了两次钱。把读-判-写整段放进 synchronized(this) 或 synchronized 方法，同一时刻只有一个线程能执行，天然互斥+可见性，问题消失。","params":["synchronized 方法锁 this，static 方法锁 Class 对象","锁粒度越细吞吐越好，别用全局锁","CAS 版可用 AtomicInteger.decrementAndGet 判断余额"],"pitfalls":["锁对象要一致，synchronized(this) 和 synchronized(另一对象) 不互斥","只锁写不锁读还是会脏读，读也要在同一把锁内","分布式多实例下 JVM 锁无效，需要数据库乐观锁或分布式锁"],"selfCheck":{"q":"只把余额写回那行加 synchronized 行不行？","a":"不行。读-判断-写回三步必须整体互斥，只锁写回仍然会让多个线程基于同一份旧余额判断，照样重复扣款。"}},{"name":"wait/notify · 唤醒后仍需竞争锁","category":"线程协作","priority":"medium","summary":"notify 唤醒后线程不直接执行，需重新竞争对象监视器锁，抢到才能继续。","interview":"notify 唤醒的线程是立刻执行吗？为什么 wait 要放在 while 循环里？","principle":"wait 让线程释放锁并进入对象等待队列；notify 把它移入同步队列参与锁竞争。被唤醒不代表拿到锁，要等 notify 线程退出同步块释放锁后才能抢到。因此 wait 必须用 while 检查条件，防止虚假唤醒或条件已被他人改掉。","params":["wait/notify 必须在 synchronized 块内调用","wait 释放锁，sleep 不释放锁","notifyAll 唤醒全部等待线程"],"pitfalls":["用 if 判断条件会因虚假唤醒或条件失效出错，应用 while","notify 后被唤醒线程未必立即执行，仍要排队抢锁","在持有锁的代码里漏掉 notify 或条件判断易死锁"],"selfCheck":{"q":"notify 之后被唤醒的线程什么时候能继续运行？","a":"当 notify 线程退出 synchronized 块释放监视器锁后，被唤醒线程与其他线程竞争锁，抢到锁才能继续执行。"}}]}', NULL, 1793250399476, 1793253102878),
	(2, 2, 3, 'ready', '{"points":[{"name":"ThreadLocal · 基本概念与用法","category":"ThreadLocal 基础与用法","priority":"high","summary":"ThreadLocal 让每个线程持有独立变量副本，实现线程内数据隔离，无需加锁。","interview":"ThreadLocal 是什么？和 synchronized 解决线程安全的思路有什么区别？","principle":"每个 Thread 内有一个 ThreadLocalMap，key 是 ThreadLocal 对象（弱引用），value 是该线程的副本。读写都以当前线程为入口取自己的 map，天然无竞争。synchronized 是让多线程排队访问同一份数据；ThreadLocal 是让各线程各用各的数据。","params":["new ThreadLocal<>() 创建实例，常 static final 共享","initialValue() 或 withInitial(Supplier) 提供初始值","get()/set()/remove() 三个核心操作"],"pitfalls":["数据需要线程间共享或传递结果时不能用 ThreadLocal，会丢数据","子线程默认拿不到父线程的 ThreadLocal 值，需用 InheritableThreadLocal","与 synchronized 取舍：隔离副本用 ThreadLocal，共享可变状态必须加锁"],"selfCheck":{"q":"ThreadLocal 和 synchronized 都能解决线程安全，什么时候选谁？","a":"数据可按线程隔离、互不共享时选 ThreadLocal（无锁、快）；数据必须被多线程共同读写或要跨线程传递结果时选 synchronized/锁。"}},{"name":"ThreadLocal · 核心 API","category":"ThreadLocal 基础与用法","priority":"medium","summary":"get/set/remove 三件套，配合 initialValue 初始化；用完必须 remove 防内存泄漏。","interview":"ThreadLocal 为什么用完要 remove？不 remove 在线程池里会怎样？","principle":"get 时若 map 中无值则调 initialValue 填入；set 写入当前线程 map；remove 删除当前线程对应 entry。ThreadLocalMap 的 key 是弱引用，GC 后 key 变 null，但 value 仍被 Entry 引用，若线程长期存活（如线程池核心线程），value 一直不释放，造成内存泄漏，还会污染下次复用该线程的任务。","params":["initialValue() 默认返回 null，可重写或用 withInitial","remove() 清理当前线程的副本","get() 首次访问触发初始化"],"pitfalls":["用完不 remove：内存泄漏 + 线程复用时读到上个任务的脏数据","排查思路：heap dump 看 Thread 对象下 ThreadLocalMap 的 Entry 数量、value 类型与持有链","try/finally 里 remove，保证异常路径也能清理"],"selfCheck":{"q":"线程池里忘了 remove 会出什么问题？怎么排查？","a":"一是 value 一直挂在长生命周期线程上导致内存泄漏；二是复用线程时 get 到上个任务残留值出错。排查用 jmap/heap dump 看 ThreadLocalMap 的 Entry 与引用链，或加断点/日志打印 map size。"}},{"name":"ThreadLocal · 典型应用场景","category":"ThreadLocal 基础与用法","priority":"medium","summary":"典型场景是用户上下文、事务、日期格式化、跨层传参，线程池下替代层层透传参数。","interview":"ThreadLocal 适合用在哪些场景？线程池里用它要注意什么？","principle":"当一个数据在同一线程内被多层方法频繁使用（如当前登录用户、请求 ID、SimpleDateFormat、数据库连接），用 ThreadLocal 一次 set、处处 get，避免方法签名层层加参。在连接池/线程池下，判断标准：数据是线程私有且随任务结束应失效 → 用 ThreadLocal 并在任务结束 remove；数据需跨任务或跨线程共享 → 不要用，改用参数传递或共享对象加锁。","params":["典型：用户上下文 UserContext、请求 traceId、ThreadLocal<SimpleDateFormat>","连接场景：ThreadLocal<Connection> 绑定事务连接（如 Spring 事务同步）","线程池中优先考虑任务开始 set、结束 remove"],"pitfalls":["线程池复用线程：任务必须自己 set，不要指望继承或残留值","任务间需要传值时改用参数/返回值，别用 ThreadLocal 硬传","连接池里把连接放 ThreadLocal 要确保归还，否则连接泄漏"],"selfCheck":{"q":"什么时候该用 ThreadLocal 而不是方法传参？","a":"数据在同一线程内被多层方法高频读取、且属于线程私有（如上下文、格式化器、事务连接）时用 ThreadLocal 省去层层透传；数据量大、需要显式生命周期或跨线程时仍应传参。"}},{"name":"ThreadLocal · 存储结构","category":"ThreadLocal 原理与陷阱","priority":"high","summary":"ThreadLocal 用 Thread 自己的 ThreadLocalMap 存值，key 是弱引用的 ThreadLocal 对象。","interview":"ThreadLocal 是怎么实现线程隔离的？key 为什么用弱引用？","principle":"每个 Thread 有个 ThreadLocalMap，key 为 ThreadLocal 实例（弱引用），value 为存的值。get/set 通过当前线程拿到自己的 map，因此线程间互不干扰。key 用弱引用是为了让 ThreadLocal 对象在不再被外部引用时能被 GC 回收，配合 remove 或 expunge 避免泄漏。","params":["ThreadLocalMap 初始容量 16，负载因子 2/3","key 为 WeakReference<ThreadLocal<?>>"],"pitfalls":["弱引用只作用于 key，value 仍是强引用","map 是 Thread 持有而非 ThreadLocal 持有，生命周期跟线程走"],"selfCheck":{"q":"ThreadLocalMap 存在哪里？key 和 value 的引用类型分别是什么？","a":"存在 Thread 对象里（Thread.threadLocals）。key 是弱引用的 ThreadLocal 实例，value 是强引用的业务对象；key 可被 GC，value 不会自动回收。"}},{"name":"ThreadLocal · 内存泄漏","category":"ThreadLocal 原理与陷阱","priority":"high","summary":"key 被 GC 回收后 value 仍被 map 强引用，线程不死则 value 泄漏。","interview":"ThreadLocal 为什么会内存泄漏？怎么预防？","principle":"ThreadLocal 对象不再被引用后 key 被 GC 清掉，但 entry 的 value 还被 ThreadLocalMap 强引用，只要线程存活（如线程池常驻线程），value 就无法回收，累积导致泄漏。set/get 触发清理过期 entry 只是缓解，不是保证。预防办法：用完 finally 里 remove()，或用 try-with-resources 风格封装，配合监控扫描。","params":["线程池核心线程常驻，泄漏风险最高","清理阈值：启发式扫描 + 连续清理 stale entry"],"pitfalls":["「key 是弱引用所以不会泄漏」是错的","只在 finally remove 才可靠，依赖 GC 触发清理不可靠"],"selfCheck":{"q":"ThreadLocal 泄漏的必要条件是什么？","a":"ThreadLocal 实例失去强引用被 GC，且线程长期存活、value 未 remove，导致 entry 的 value 被 map 强引用而无法回收。"}},{"name":"ThreadLocal · 线程池场景下的陷阱","category":"ThreadLocal 原理与陷阱","priority":"medium","summary":"线程池复用线程会让 ThreadLocal 残留脏数据，InheritableThreadLocal 也无法传给提交的任务。","interview":"ThreadLocal 在线程池里有什么坑？InheritableThreadLocal 能解决吗？","principle":"线程池线程被复用，上个任务 set 的值若不 remove，会带到下一个任务，产生脏数据或泄漏。InheritableThreadLocal 只在「创建线程时」从父线程复制，线程池里线程早已创建，提交任务时不会复制，故失效。彻底方案是 TransmittableThreadLocal 之类的包装，在任务提交与执行时显式抓取/重放上下文。","params":["线程池线程复用：ThreadLocal 值跨任务残留","InheritableThreadLocal 仅在线程创建时复制"],"pitfalls":["用完不 remove 会污染后续任务","InheritableThreadLocal 对线程池无效，别误以为解决了传递"],"selfCheck":{"q":"为什么 InheritableThreadLocal 传不到线程池里的任务？","a":"它只在线程创建时从父线程复制，线程池里的线程早就存在，提交任务时不会重新复制，所以子任务读到的仍是线程创建时的旧值。"}},{"name":"JVM 内存区域 · 划分与职责","category":"JVM 内存模型（运行时数据区）","priority":"medium","summary":"运行时数据区分五块：堆、方法区共享，虚拟机栈、本地方法栈、程序计数器线程私有。","interview":"JVM 运行时数据区怎么划分？哪些线程私有、哪些共享？","principle":"堆放对象实例，方法区放类元数据与常量；虚拟机栈放栈帧（局部变量、操作数栈），本地方法栈服务 Native，程序计数器记录当前指令地址。私有区随线程生灭，共享区由 GC 管理。","params":["堆与方法区共享，其余三块线程私有","栈默认约 1MB，可用 -Xss 调整","堆大小用 -Xms / -Xmx 设定"],"pitfalls":["StackOverflowError 来自栈深度超限（递归过深）","OutOfMemoryError 分堆 OOM 与元空间 OOM，不要混为一谈","程序计数器是唯一不会 OOM 的区域"],"selfCheck":{"q":"哪些区域可能抛 OOM？程序计数器会不会？","a":"堆、方法区（元空间）、直接内存可能 OOM；虚拟机栈/本地方法栈既可能 StackOverflow 也可能 OOM（栈动态扩展时）；程序计数器是唯一不会 OOM 的区域。"}},{"name":"JVM 内存区域 · 堆的结构","category":"JVM 内存模型（运行时数据区）","priority":"medium","summary":"堆分新生代（Eden + 两个 Survivor）与老年代，分代是为了按对象存活时间用不同回收策略。","interview":"堆为什么要分代？对象什么情况下会进入老年代？","principle":"绝大多数对象朝生夕死，放 Eden 用复制算法快速回收；长期存活对象晋升老年代用标记-整理。Minor GC 后存活对象进 Survivor，年龄加 1，达到阈值（默认 15）晋升；大对象直接进老年代。","params":["新生代默认占堆 1/3，Eden:S0:S1 = 8:1:1","晋升年龄阈值默认 15（-XX:MaxTenuringThreshold）","大对象阈值由 -XX:PretenureSizeThreshold 控制"],"pitfalls":["动态年龄判定：Survivor 中同龄对象总和超一半即可提前晋升","大对象直接分配老年代，避免在新生代来回复制","-XX:SurvivorRatio 调 Eden/Survivor 比例，比例失衡会加剧晋升"],"selfCheck":{"q":"除了年龄到 15，还有哪些情况对象会进老年代？","a":"大对象直接进入老年代；Survivor 中相同年龄对象总大小超过 Survivor 一半，该年龄及以上对象提前晋升；Minor GC 后 Survivor 放不下的对象也会直接进老年代。"}},{"name":"JVM 内存区域 · 方法区与元空间","category":"JVM 内存模型（运行时数据区）","priority":"medium","summary":"JDK8 起方法区实现改为元空间，用本地内存；字符串常量池移到堆中。","interview":"方法区和永久代、元空间什么关系？字符串常量池放哪？","principle":"方法区是 JVM 规范，永久代（JDK7 前）和元空间（JDK8 后）是实现。永久代用堆内内存、大小固定，类元数据多时易 OOM: PermGen；元空间用本地内存、默认可自动扩展，缓解类元数据溢出。字符串常量池 JDK7 起从方法区移到堆，便于 GC 回收。","params":["元空间默认上限为本地内存，可用 -XX:MaxMetaspaceSize 限制","JDK7 中字符串常量池已在堆，但永久代仍存在","-XX:MetaspaceSize 设初始阈值，触发 Full GC 与卸载"],"pitfalls":["元空间不是无限的，不限制可能耗尽本地内存导致 OS 层问题","类加载器泄漏会导致元空间 OOM（如热部署）","-XX:PermSize / -XX:MaxPermSize 在 JDK8 已失效"],"selfCheck":{"q":"为什么把字符串常量池从永久代移到堆？","a":"永久代大小固定、回收 Full GC 才触发，常量过多易 OOM: PermGen；堆由成熟 GC 管理、更容易回收字符串，也便于后续字符串去重等优化。"}},{"name":"JVM 内存区域 · 栈与栈帧","category":"JVM 内存模型（运行时数据区）","priority":"medium","summary":"线程私有的虚拟机栈，方法调用入栈、返回出栈，栈帧是每次调用的内存单元。","interview":"递归为什么会 StackOverflowError？栈里都存什么？","principle":"每个线程有一块私有虚拟机栈，方法调用时压入栈帧，返回时弹出。栈帧含局部变量表、操作数栈、动态链接、返回地址等。递归每调用一层就新增一个栈帧，层数过深超过栈容量时抛 StackOverflowError。","params":["栈容量可由 -Xss 设置，默认约 512KB~1MB，视 JVM 而定","局部变量表以「槽位 slot」为单位，32 位类型占 1 槽，64 位（long/double）占 2 槽"],"pitfalls":["递归改迭代是解决栈溢出的常规思路","StackOverflowError 是 Error，不是 Exception，不要用 catch(Exception) 兜底"]},{"name":"对象内存布局 · 三部分组成","category":"对象内存布局","priority":"medium","summary":"对象由对象头、实例数据、对齐填充三部分构成。","interview":"一个 Java 对象在内存里占哪些部分？为什么要对齐填充？","principle":"对象头存元信息（Mark Word、类型指针，数组还有长度），实例数据存各字段值（父类字段在前），对齐填充让对象总大小为 8 字节的整数倍。对齐填充的存在是因为 CPU 按字长访问内存，对齐后读取效率高、避免跨缓存行访问。","params":["对齐基准通常为 8 字节","对象默认开启压缩指针（-XX:+UseCompressedOops）可减小对象头"],"pitfalls":["对齐填充不是必须内容，大小凑够就为 0 字节","空对象大小通常为 16 字节（含对象头）"]},{"name":"对象内存布局 · 对象头与 Mark Word","category":"对象内存布局","priority":"medium","summary":"对象头存哈希码、GC 分代年龄、锁状态等运行时数据，其中 Mark Word 会随锁升级变化。","interview":"Mark Word 是什么？锁升级在它上面怎么体现？","principle":"对象头主要包括 Mark Word 和类型指针。Mark Word 存 hashCode、GC 年龄、锁标志位等，为节省空间会复用位。锁升级路径为无锁→偏向锁→轻量级锁→重量级锁，每次升级会改变 Mark Word 中的锁标志位和存储内容（如指向锁记录或 monitor 的指针）。","params":["Mark Word 大小随平台：32 位 JVM 约 32 位，64 位 JVM 约 64 位","hashCode 在加锁后会被挪到 monitor 中保存"],"pitfalls":["Mark Word 是复用设计，一个对象不能同时存 hashCode 和偏向锁信息","锁状态位只占几位，不要误以为 Mark Word 是独立字段结构"]},{"name":"对象内存布局 · 对象大小与计算","category":"对象内存布局","priority":"medium","summary":"对象由对象头、实例数据、对齐填充组成，大小需 8 字节对齐。","interview":"一个对象占多少字节？怎么算？","principle":"对象头含 Mark Word 与类型指针（数组还有长度），实例数据存字段，padding 补齐到 8 字节倍数。64 位 JVM 开启压缩指针后，类型指针与引用由 8 字节压到 4 字节。","params":["Mark Word 64 位下约 8 字节","压缩指针开启后类型指针 4 字节","对象总大小按 8 字节对齐"],"pitfalls":["忽略对齐填充直接相加会算错","基本类型与引用大小不同，boolean/byte 1 字节","压缩指针关闭时大小可能翻倍"],"selfCheck":{"q":"空对象 new Object() 占多少字节？","a":"64 位开启压缩指针时是 16 字节：Mark Word 8 字节 + 类型指针 4 字节 + 4 字节对齐填充。"}},{"name":"对象内存布局 · 访问定位","category":"对象内存布局","priority":"low","summary":"访问对象分句柄和直接指针两种，HotSpot 用直接指针。","interview":"Java 是怎么通过 reference 找到对象的？两种方式有什么区别？","principle":"句柄方式：reference 指向句柄池，句柄含对象实例指针和类型指针，对象移动只改句柄；直接指针：reference 直指对象，需在对象头带类型信息，少一次跳转但 GC 移动需改引用。","params":["句柄方式访问多一次指针跳转","直接指针访问更快","HotSpot 默认直接指针"],"pitfalls":["句柄方式稳定但速度慢，不要说反","直接指针下 GC 移动对象要更新 reference","Android 等部分 VM 用句柄，别绝对化"],"selfCheck":{"q":"为什么 HotSpot 选直接指针？","a":"少一次指针定位，访问更快；虽然 GC 移动对象时需更新引用，但整体开销更小，符合 HotSpot 追求性能的取向。"}},{"name":"类加载 · 双亲委派模型","category":"类加载机制","priority":"high","summary":"类加载先委派父加载器，父加载器无法加载才自己加载。","interview":"什么是双亲委派？为什么需要它？","principle":"收到加载请求先交给父加载器，递归向上到启动类加载器；父加载器加载失败才由自身加载。保证 java.lang.Object 等核心类由启动类加载器加载，防止被篡改，并确保同一个类在不同加载器下唯一。","params":["启动类加载器 → 扩展类加载器 → 应用类加载器","父加载器加载失败才由子加载器尝试","类的唯一性 = 全限定名 + 加载器"],"pitfalls":["双亲是语义上的父子关系，不是继承","父加载器加载失败会抛异常再由子加载器加载","SPI、Tomcat、OSGi 会打破双亲委派"],"selfCheck":{"q":"双亲委派如何防止自定义 java.lang.String 篡改核心类？","a":"加载请求先委派到启动类加载器，核心类由它加载成功，自定义类根本不会被加载，从而保证核心 API 不被替换。"}},{"name":"类加载 · 生命周期与阶段","category":"类加载机制","priority":"medium","summary":"类加载含加载、验证、准备、解析、初始化五阶段，初始化才真正执行静态代码。","interview":"哪些情况会触发类的初始化，哪些不会？","principle":"加载把字节流变成方法区的 Class 对象；验证校验字节码；准备为静态变量分配内存并赋零值（final 常量直接赋值）；解析把符号引用换成直接引用；初始化执行 <clinit>，即静态变量赋值与 static 块。","params":["准备阶段静态变量赋零值，final 常量赋真实值","初始化执行 <clinit>，父类先于子类"],"pitfalls":["new、访问静态字段（非 final 常量）、反射、主类会触发初始化","通过数组定义引用类、引用常量、子类引用父类静态字段不触发子类初始化"],"selfCheck":{"q":"通过 `SubClass[] arr = new SubClass[1]` 会触发 SubClass 初始化吗？","a":"不会。数组只触发生成的 [LSubClass; 类的初始化，不触发元素类的初始化，属于典型被动引用。"}},{"name":"类加载 · 打破双亲委派","category":"类加载机制","priority":"medium","summary":"双亲委派可被线程上下文类加载器或重写 loadClass 打破，但有隔离与安全代价。","interview":"怎么打破双亲委派？这么做有什么代价？","principle":"默认 loadClass 先委托父加载器，父加载失败才自己加载。打破方式：一、JNDI/JDBC 等用 Thread.currentThread().getContextClassLoader() 让父加载器反向调用子加载器（SPI）；二、自定义 ClassLoader 重写 loadClass，先自己加载再委托（Tomcat、热部署）。","params":["核心 API：loadClass / findClass，重写后者更安全","线程上下文类加载器可由父线程设置并被子线程继承"],"pitfalls":["打破后可能出现同名类被不同加载器加载，ClassCastException","重写 loadClass 易破坏隔离，Tomcat 靠它实现 webapp 隔离却也常踩 NoClassDefFoundError"],"selfCheck":{"q":"SPI 场景为什么必须用线程上下文类加载器？","a":"SPI 接口由启动类加载器加载，但实现类在应用 classpath 下，启动加载器看不见；用线程上下文类加载器（默认是应用类加载器）反向加载实现类。"}},{"name":"场景 · 线程池上下文传递","category":"综合与场景串联","priority":"medium","summary":"线程池跨线程传上下文：ThreadLocal 不行、InheritableThreadLocal 只对新线程有效、显式传参最稳。","interview":"线程池里怎么把用户信息/链路 ID 传给任务线程？三者怎么取舍？","principle":"ThreadLocal 存线程私有变量，线程池线程复用会导致脏数据或拿不到值。InheritableThreadLocal 在 Thread 构造时从父线程复制，但线程池线程只创建一次，后续提交的任务不会继承。因此要么用 TransmittableThreadLocal/包装 Runnable 显式捕获并回放，要么任务参数显式传递。","params":["ThreadLocal 建议用 static final 并配 remove()","InheritableThreadLocal 仅在 new Thread 时复制一次"],"pitfalls":["线程池复用线程导致 ThreadLocal 泄漏与脏上下文","用完不 remove，线程池长生命周期线程会堆积对象甚至内存泄漏"],"selfCheck":{"q":"为什么 InheritableThreadLocal 在线程池里失效？","a":"线程池的工作线程只创建一次并反复复用，只有创建那一刻从父线程复制了上下文，后续提交任务时不会再复制，所以拿不到提交线程的值。"}},{"name":"场景 · 内存问题排查思路","category":"综合与场景串联","priority":"medium","summary":"内存问题先分堆内堆外，再结合对象布局和分代判断方向。","interview":"线上出现 OOM/内存涨，你的排查思路是什么？","principle":"先区分堆内存、元空间、直接内存、线程栈。堆内看对象存活与分代：老年代涨多为长生命周期对象/泄漏，Young GC 频繁多为短命对象分配过快。再结合对象布局估算单个对象大小，看是不是大对象、膨胀的字段或 ThreadLocal 持有大 value 未清理。","params":["-Xms/-Xmx 决定堆大小","-Xmn 或分代比例影响 Young/Old 分配","-XX:MaxMetaspaceSize 限制元空间"],"pitfalls":["把直接内存/NIO 堆外泄漏当堆问题查","ThreadLocal 用完不 remove 导致 Entry value 泄漏，表象是老年代缓慢上涨","只看总量不看分代，误判泄漏方向"],"selfCheck":{"q":"老年代持续缓慢上涨、Full GC 后不降，最可能是什么？","a":"存在长生命周期对象或泄漏，常见是缓存无上限、静态集合持有、ThreadLocal 未清理，导致对象晋升老年代后不回收。"}}]}', NULL, 1793607244277, 1793607405709),
	(3, 2, 4, 'ready', '{"points":[{"name":"线程池 · 为什么要用","category":"线程池核心概念","priority":"high","summary":"线程池用复用线程降低创建销毁开销，并提供统一的任务提交、调度、限流与监控入口。","interview":"为什么项目里要用线程池？不用直接 new Thread 不行吗？","principle":"线程创建销毁成本高、并发失控难管理。线程池预先创建核心线程并反复执行任务，同时把提交、排队、拒绝、监控集中到一处，便于限流、降级与排查。","params":["核心线程数按任务类型定（CPU 密集≈核数，IO 密集可放大）","队列容量承担削峰，太小易触发扩容或拒绝","拒绝策略与监控指标是工程落地必备"],"pitfalls":["任务极少或单次短任务，用线程池反而增加上下文切换与复杂度","CPU 密集短任务开线程池收益低，还可能因排队变慢","别为了『规范』无脑套线程池，先看并发量与任务耗时"],"selfCheck":{"q":"什么场景下不该用线程池？","a":"任务量极少、单次执行很短、CPU 密集且无并发需求时，线程池带来的调度与维护成本大于收益，直接串行或简单并发即可。"}},{"name":"线程池 · 核心工作流程","category":"线程池核心概念","priority":"high","summary":"先建核心线程，满了入队；队列满再开非核心线程，超最大线程数才触发拒绝策略。","interview":"线程池提交一个任务后的完整处理流程是怎样的？","principle":"提交任务：当前线程数<核心线程数则新建核心线程执行；否则尝试入队；入队失败则新建非核心线程执行；超过最大线程数则执行拒绝策略。核心线程默认不会因空闲回收（除非开启 allowCoreThreadTimeOut）。","params":["corePoolSize：常驻线程数","maximumPoolSize：线程数上限","workQueue：任务队列，容量直接影响扩容与拒绝时机"],"pitfalls":["核心线程数没满时直接新建线程，不会先入队","队列无界（如 LinkedBlockingQueue）会让 maximumPoolSize 形同虚设，永不扩容","队列容量太小会过早触发扩容甚至拒绝"],"selfCheck":{"q":"为什么队列用无界队列时最大线程数不起作用？","a":"因为任务永远能入队成功，流程走不到新建非核心线程那一步，线程数恒不超过核心数，队列堆积可能导致 OOM。"}},{"name":"线程池 · 线程复用原理","category":"线程池核心概念","priority":"medium","summary":"池内线程循环从队列取任务执行，不用重复 start，一个线程跑多个任务。","interview":"线程池是怎么做到线程复用的？和 Thread.start 有什么区别？","principle":"Thread.start 会真正启动一条新线程且不可重复调用；线程池里的 Worker 线程启动一次后进入循环，不断从阻塞队列 take/poll 任务并 run，从而复用同一 OS 线程执行多个任务，省去创建销毁成本。","params":["submit/execute 只是把任务投递到池中，由池内线程取出执行","Worker 数量由核心/最大线程数控制"],"pitfalls":["不能对 submit 返回的任务或池内线程自己调用 start，会抛 IllegalThreadStateException","任务的 run 是被 Worker 线程调用的，调用者线程不会阻塞","调用 shutdown 后仍可复用已建线程完成队列余量，但不再接收新任务"],"selfCheck":{"q":"为什么线程池里不能对任务再自己调用 start？","a":"池内 Worker 线程已经启动过并循环调用任务的 run；Thread.start 只能调用一次，重复调用会抛 IllegalThreadStateException，且线程生命周期由池管理。"}},{"name":"线程池 · submit 与 execute 区别","category":"线程池核心概念","priority":"medium","summary":"execute 直接抛异常，submit 返回 Future 并吞异常，异常要在 get 时才暴露。","interview":"线程池的 submit 和 execute 有什么区别？submit 提交的任务抛异常会怎样？","principle":"execute 提交 Runnable，异常直接抛给线程的 UncaughtExceptionHandler 或导致线程结束；submit 提交 Callable/Runnable，返回 FutureTask，任务里抛的异常被 FutureTask 内部捕获并记录，直到调用 future.get() 才以 ExecutionException 抛出，不调用就被静默吞掉。","params":["submit 返回 Future<?>，execute 返回 void","submit 支持 Callable 有返回值，execute 只支持 Runnable"],"pitfalls":["submit 吞异常是生产事故高发点，日志里完全看不到报错","用 execute 时建议给线程池设 UncaughtExceptionHandler，否则异常只打默认堆栈","排查法：提交处统一包 try-catch 记日志，或用 CompletableFuture/包装 Runnable 显式捕获"],"selfCheck":{"q":"为什么 submit 提交的任务在控制台看不到异常日志？怎么规避？","a":"因为异常被 FutureTask 捕获存起来，只有调用 future.get() 才抛 ExecutionException。规避：任务体自己 try-catch 记日志，或强制调用 get()，或用 execute 让异常外抛。"}},{"name":"线程池参数 · corePoolSize 与 maximumPoolSize","category":"七大参数","priority":"high","summary":"core 是常驻线程数，max 是扩容上限，线程数在两者之间才随任务增长。","interview":"线程池的 corePoolSize 和 maximumPoolSize 怎么配？CPU 密集和 IO 密集各配多少？","principle":"提交任务时：线程数 < core 就新建核心线程；≥ core 则入队；队列满了且线程数 < max 才新建非核心线程；达到 max 后触发拒绝策略。core 线程默认一直存活（除非设 allowCoreThreadTimeOut），非核心线程空闲超 keepAliveTime 回收。","params":["CPU 密集：core = 核数 + 1","IO 密集：core = 核数 × 2 或 核数 / (1 - 阻塞系数)，阻塞系数常取 0.8~0.9","core 一般 ≤ max，max 起到突发流量的缓冲作用"],"pitfalls":["配太小：任务堆积、队列打满、接口 RT 飙升甚至触发拒绝","配太大：CPU 频繁上下文切换、内存压力大，反而更慢","只关注 core 不管 max，队列又是无界时 max 永远用不上"],"selfCheck":{"q":"8 核机器，一个任务大部分时间在等下游 RPC 返回，corePoolSize 大概配多少？","a":"IO 密集，可按 核数 × 2 = 16，或用公式 8/(1-0.8)=40 取经验值区间。压测为准，配大了浪费切换，配小了吞吐上不去。"}},{"name":"线程池参数 · workQueue","category":"七大参数","priority":"high","summary":"workQueue 缓存待执行任务，队列容量决定了线程池何时扩容到 maximumPoolSize。","interview":"线程池的 workQueue 有什么用？为什么说无界队列有风险？队列大小和 maximumPoolSize 是什么关系？","principle":"新任务先入队（线程数已达 core），只有队列满了才继续扩容线程到 max。若队列容量很大甚至无界，队列永远填不满，maximumPoolSize 形同虚设，任务全部堆积在队列里。队列选择：ArrayBlockingQueue（有界数组）、LinkedBlockingQueue（可设容量，默认无界）、SynchronousQueue（不存储，直接移交）、PriorityBlockingQueue（优先级）。","params":["LinkedBlockingQueue 默认容量 Integer.MAX_VALUE，等于无界","ArrayBlockingQueue 必须显式指定容量","队列容量要结合 max 一起设计：先让队列缓冲一定量，满了才扩容线程"],"pitfalls":["用默认无界队列：高峰期任务无限堆积，最终 OOM 或线程池完全不扩容","队列太小 + max 太小：过早触发拒绝策略，正常流量就被拒","SynchronousQueue 不缓冲，必须配较大的 max，否则几乎立即拒绝"],"selfCheck":{"q":"为什么线程池用了无界队列，maximumPoolSize 配再大也没用？","a":"因为扩容逻辑是「队列满了才新建线程到 max」，无界队列永远填不满，线程数一直停留在 corePoolSize，任务全部堆在队列里直到内存耗尽。"}},{"name":"线程池参数 · handler","category":"七大参数","priority":"high","summary":"拒绝策略决定任务无法处理时的处置方式，触发时机与队列类型强相关。","interview":"线程池的拒绝策略有哪几种？什么时候会触发拒绝？","principle":"当线程数达到 maximumPoolSize 且队列已满时触发 handler。队列选择影响触发时机：LinkedBlockingQueue 默认近乎无限容量，几乎不会拒绝，容易 OOM；SynchronousQueue 不存任务，直接交线程执行，易快速触发拒绝；ArrayBlockingQueue 容量固定，是控制拒绝的常用手段。内置四种：AbortPolicy（抛异常，默认）、CallerRunsPolicy（调用者执行）、DiscardPolicy（静默丢弃）、DiscardOldestPolicy（丢最老）。","params":["默认 new ThreadPoolExecutor.AbortPolicy()，抛 RejectedExecutionException","四种内置策略都在 java.util.concurrent 包内"],"pitfalls":["无界队列+默认拒绝策略=拒绝形同虚设，最终 OOM","DiscardPolicy/DiscardOldestPolicy 静默丢任务，易丢关键业务","CallerRunsPolicy 会拖慢调用方（如 Tomcat 线程），有反压风险"],"selfCheck":{"q":"为什么说无界队列下拒绝策略基本不会生效？","a":"无界队列几乎不会满，任务一直入队，线程数永远停在 corePoolSize，不会达到 maximumPoolSize，因此 handler 不会被触发，反而可能堆积任务导致 OOM。"}},{"name":"线程池参数 · keepAliveTime 与 unit","category":"七大参数","priority":"medium","summary":"keepAliveTime 定义非核心线程空闲多久后回收，unit 是其时间单位。","interview":"keepAliveTime 作用是什么？allowCoreThreadTimeOut 打开会怎样？","principle":"线程从队列 take 任务时带超时，超过 keepAliveTime 未取到任务且当前线程数 > corePoolSize，则退出销毁。allowCoreThreadTimeOut(true) 后，核心线程也走同样逻辑被回收，池可能缩到 0 线程；下次来任务会重建线程。适用于任务突发、长时间空闲想省资源的场景；不适合长期稳态任务，因为反复建线程有开销。","params":["默认 keepAliveTime=0，非核心线程一空闲立刻回收","unit 常用 TimeUnit.SECONDS / MILLISECONDS","allowCoreThreadTimeOut 默认 false"],"pitfalls":["allowCoreThreadTimeOut 打开后空闲期线程全没，突发流量要重新建线程，有延迟","keepAliveTime 只影响超过 corePoolSize 的线程，除非开启 allowCoreThreadTimeOut","unit 写错（如把秒当毫秒）会让线程存活时间与预期严重不符"],"selfCheck":{"q":"allowCoreThreadTimeOut(true) 适合什么场景？","a":"适合任务突发、空闲期长、想省资源的场景，比如定时或低频任务池；不适合稳态高 QPS 服务，因为核心线程会被反复销毁重建，增加开销和响应延迟。"}},{"name":"线程池参数 · threadFactory","category":"七大参数","priority":"medium","summary":"threadFactory 负责创建线程，自定义可规范命名、优先级、守护状态，便于排查。","interview":"为什么要自定义 threadFactory？默认线程名有什么问题？","principle":"默认 Executors.defaultThreadFactory() 创建的线程名为 pool-N-thread-M，多个池交错出现时无法从线程名反推业务归属；出问题看 jstack、日志、监控都难以定位。自定义时实现 ThreadFactory.newThread，设置线程名（如 业务名-模块-序号）、优先级、是否 daemon，还可捕获 UncaughtException 统一记录异常。常用 guava 的 ThreadFactoryBuilder 或手写类。","params":["默认线程名 pool-N-thread-M，N 为池序号","优先级默认继承创建者，一般不动","常见命名：order-pool-1、pay-async-3"],"pitfalls":["不命名线程在出问题时无法从线程 dump 定位到具体池","threadFactory 抛异常会让线程创建失败，池可能卡在 core 线程数不上升","自定义工厂忘记设置 daemon，进程关闭时线程不退出，导致应用关闭卡住"],"selfCheck":{"q":"线程池排查问题时，threadFactory 命名规范有什么价值？","a":"线上通过 jstack、日志、监控看到线程名能直接反推业务归属和池类型，快速定位卡死、慢、堆积等问题；默认 pool-N-thread-M 名字无法区分池，排查成本高。"}},{"name":"拒绝策略 · AbortPolicy","category":"拒绝策略","priority":"high","summary":"默认拒绝策略，抛 RejectedExecutionException，让调用方立刻感知任务被拒。","interview":"线程池默认的拒绝策略是什么？业务中抛异常怎么兜底降级？","principle":"队列满且线程数达上限时，execute 直接 new RejectedExecutionException 抛给提交线程；submit 则包装进 Future，调用 get 时才抛。抛异常不是坏事，它让问题暴露而不是静默丢失。","params":["默认策略，ThreadPoolExecutor 未指定即用它","异常类型 RejectedExecutionException"],"pitfalls":["submit 提交时异常被 Future 吞掉，不调 get 就看不到","不 try-catch 会让提交线程的业务链路直接失败"],"selfCheck":{"q":"AbortPolicy 抛出异常后，业务层一般怎么兜底？","a":"try-catch 捕获后走降级：写库排队、发 MQ 异步补偿、返回友好提示或降级结果，并打告警日志，避免用户侧直接报错。"}},{"name":"拒绝策略 · CallerRunsPolicy","category":"拒绝策略","priority":"high","summary":"不丢任务也不抛异常，由提交任务的线程自己执行该任务，形成天然反压。","interview":"CallerRunsPolicy 有什么风险？什么场景适合用？","principle":"拒绝时不入队，直接在调用 execute/submit 的那个线程里跑 task.run()。提交线程被占用，提交速度自然被拖慢，达到限流效果，任务一定被执行。","params":["无需额外参数，new CallerRunsPolicy() 即可","无异常抛出，不丢任务"],"pitfalls":["提交线程被阻塞，若提交方是 Tomcat 工作线程或 MQ 消费线程，会拖垮吞吐甚至触发超时","任务里若抛异常会直接打到调用线程，影响提交方主流程"],"selfCheck":{"q":"Web 应用在 Tomcat 线程里提交任务，用 CallerRunsPolicy 合适吗？","a":"不合适。会占用 Tomcat 工作线程去跑任务，降低接口并发甚至拖垮线程池；更适合后台异步或对实时性不敏感的场景，不适合在线请求链路。"}},{"name":"拒绝策略 · DiscardPolicy 与 DiscardOldestPoli","category":"拒绝策略","priority":"medium","summary":"静默丢任务：前者直接丢当前任务，后者丢队列最老任务再入队，都可能丢数据。","interview":"DiscardPolicy 和 DiscardOldestPolicy 有什么区别？用之前要考虑什么？","principle":"DiscardPolicy 直接吞掉新任务不执行不报错；DiscardOldestPolicy 调 poll() 弹出队头最老任务，再把新任务 offer 进队列，让任务队列保留“更新”的任务，常用于定时刷新类场景。","params":["均无异常提示，调用方无感知","DiscardOldestPolicy 保留新任务丢弃旧任务"],"pitfalls":["订单、支付等强一致业务绝对不能用，任务静默丢失且无告警","DiscardOldestPolicy 丢的是最先排队的任务，可能丢掉已等待很久、快被处理的关键任务","用前需评估：任务是否可丢、是否需要日志/监控补偿、是否幂等"],"selfCheck":{"q":"什么场景可以考虑用 DiscardOldestPolicy？用之前必须想清楚什么？","a":"适合只关心最新状态的场景，如定时刷新缓存、上报最新指标，丢旧任务无影响。用前必须确认任务可丢弃、不涉及资金与订单，且加监控告警便于发现丢弃。"}},{"name":"自定义线程池 · 为什么不用 Executors","category":"业务中自定义线程池","priority":"high","summary":"Executors 默认参数易埋雷，自定义线程池才能主动控制容量与队列。","interview":"为什么不推荐用 Executors 创建线程池？","principle":"Executors 用无界队列或极大线程数做默认值，任务堆积时可能 OOM 或线程爆炸；自定义 ThreadPoolExecutor 显式给核心数、最大数、队列容量，把内存与并发风险量化可控，代价是需要自己算参数。","params":["newFixedThreadPool 队列无界 Integer.MAX_VALUE","newCachedThreadPool 最大线程数 Integer.MAX_VALUE","自定义时必须显式指定队列容量与拒绝策略"],"pitfalls":["不是 Executors 本身有 bug，而是默认值掩盖了容量问题","规范禁止≠一刀切：低频管理后台等可控场景用 Executors 也可以"],"selfCheck":{"q":"Executors.newFixedThreadPool 为什么可能 OOM？","a":"它用 LinkedBlockingQueue 且不传容量，默认容量 Integer.MAX_VALUE，任务入队无上限，堆积到内存耗尽也不会触发拒绝策略。"}},{"name":"自定义线程池 · 参数怎么定","category":"业务中自定义线程池","priority":"high","summary":"参数靠压测定基线，再用活跃线程、队列积压、拒绝次数动态微调。","interview":"线程池参数你一般怎么定？怎么判断该扩还是缩？","principle":"核心线程数参考 CPU 密集=核数+1、IO 密集=核数×(1+等待/计算) 起步；压测拿到吞吐拐点定最大线程数；队列容量控制积压上限。上线后看指标反推：队列长期积压→加核心线程或扩队列（需评估延迟），频繁拒绝→提高 max 或换更优策略，活跃线程数长期低于核心→收缩核心数省资源。","params":["核心线程数按任务类型估算后以压测校准","队列容量按可容忍延迟×平均 QPS 估算","ThreadPoolExecutor#getActiveCount、getQueue().size、getRejectedExecutionCount 为调整依据"],"pitfalls":["只看 CPU 核数套公式不够：阻塞比、下游吞吐才是决定因素","盲目扩队列会让请求排队变慢，牺牲尾延迟","max 线程数调大要考虑 DB/下游连接池上限"],"selfCheck":{"q":"监控显示队列持续增长且拒绝次数为 0，说明什么？该怎么调？","a":"说明线程处理不过来但队列还在吃内存，可能堆积 OOM。应提高核心线程数或最大线程数，必要时缩小队列容量触发拒绝策略尽早失败。"}},{"name":"自定义线程池 · 自定义线程工厂与命名规范","category":"业务中自定义线程池","priority":"medium","summary":"自定义 ThreadFactory 统一线程命名，让监控告警可定位到具体业务池。","interview":"你有没有自定义过线程工厂？为什么要给线程命名？","principle":"Executors.defaultThreadFactory 的线程名是 pool-N-thread-M，线上看不出归属。实现 ThreadFactory 接口，统一前缀「业务-模块-池名-序号」，可同时设置 daemon、优先级、UncaughtExceptionHandler。命名后 jstack、监控大盘、告警都能按前缀聚合，快速定位是哪个业务的池打满。","params":["命名模板：biz-module-poolname-thread-N","可选设置线程优先级与未捕获异常处理器","未捕获异常处理器兜底日志，避免静默吞异常"],"pitfalls":["别偷懒用 defaultThreadFactory，出问题难定位","线程名最好带业务标识，多个线程池同名会导致监控混淆","改了名记得确认日志与告警规则按新前缀匹配"],"selfCheck":{"q":"线上线程名都是 pool-1-thread-x，排查问题有什么不便？","a":"无法区分线程归属哪个业务池，jstack 与监控只能看到通用名字，告警也难以精确路由。改用命名规范后可按前缀聚合定位。"}},{"name":"自定义线程池 · 优雅关闭","category":"业务中自定义线程池","priority":"medium","summary":"用完线程池要 shutdown 并 awaitTermination，防止任务丢失和线程泄漏。","interview":"自定义线程池在服务停止时应该怎么关闭？shutdown 和 shutdownNow 有什么区别？","principle":"关闭分两步：先 shutdown() 拒绝新任务、让已提交任务跑完；再 awaitTermination() 等待一段时间；超时再用 shutdownNow() 强停并返回未执行任务。Spring 中把线程池做成 Bean，用 @PreDestroy 或 DisposableBean 挂关闭逻辑，容器销毁时自动执行。","params":["shutdown() 停止接收新任务，已提交的继续执行","shutdownNow() 中断执行中任务，返回未执行任务列表","awaitTermination(timeout) 等待指定时长后返回是否全部结束"],"pitfalls":["只调 shutdown 不等待，进程退出时任务仍在跑会被杀掉，造成任务丢失","忘了关闭，Tomcat/容器停止后线程仍存活，导致线程泄漏","在请求线程里调 shutdownNow，可能中断正在处理的业务，留下脏数据"],"selfCheck":{"q":"为什么 shutdown() 之后还要 awaitTermination()？","a":"shutdown 只是发信号停止接收新任务，不阻塞；awaitTermination 等待存量任务跑完，避免主线程直接退出把任务杀掉。"}}]}', NULL, 1793608851223, 1793609010879),
	(4, 2, 5, 'ready', '{"points":[{"name":"IoC/DI · 概念与两种注入方式","category":"IoC容器与Bean配置","priority":"high","summary":"IoC把对象创建与依赖装配交给容器，DI有构造器注入与setter注入两种方式。","interview":"构造器注入和setter注入各有什么优缺点？Spring官方推荐哪种？","principle":"IoC即控制反转：对象不再自己new依赖，由容器按配置创建并注入。构造器注入在创建时一次性传入所有依赖，适合必填依赖；setter注入在对象创建后再赋值，适合可选依赖。构造器注入天然支持不可变对象（final字段），且能发现循环依赖。","params":["@Autowired可加在构造器/字段/方法上，构造器唯一时可省略","@Qualifier+@Autowired按名称指定注入哪个Bean","spring-boot-starter-test默认推荐构造器注入"],"pitfalls":["构造器注入遇到循环依赖会启动失败，setter注入可能延迟暴露解决或报错","setter注入下依赖可能为null，必须显式判空","字段注入（@Autowired加字段）不利于测试与不可变性，不推荐"],"selfCheck":{"q":"为什么Spring 4.3+推荐构造器注入？","a":"必填依赖在创建时即校验、字段可final不可变、便于单元测试（无需Spring容器）、能及早暴露循环依赖。"}},{"name":"Bean配置 · 组件扫描与注册方式","category":"IoC容器与Bean配置","priority":"medium","summary":"Bean可通过@Component等注解扫描、@Bean方法、XML或@Import注册，同名定义可能冲突。","interview":"多个同名Bean定义时会发生什么？@Primary和@Qualifier怎么解决？","principle":"组件扫描由@ComponentScan指定basePackages，扫到@Component/@Service/@Repository/@Controller即注册；@Bean在配置类方法中手动注册。容器启动时若发现两个Bean同名（id相同），默认后定义覆盖前定义（Spring Boot 2.1+默认禁止覆盖，抛异常）。依赖注入时若按类型匹配到多个Bean，再用@Primary定首选、@Qualifier按名匹配。","params":["@ComponentScan(basePackages=\"...\")","@Primary标在Bean定义上作为同类型多个Bean时的首选","@Qualifier(\"beanName\")按名称精确匹配"],"pitfalls":["Spring Boot 2.1+ spring.main.allow-bean-definition-overriding默认false，同名直接启动失败","按类型注入遇多个候选Bean会抛NoUniqueBeanDefinitionException","组件扫描遗漏包（如启动类同级包外）导致Bean未注册"],"selfCheck":{"q":"@Primary和@Qualifier解决的是同一个问题吗？","a":"不是。@Primary解决「按类型注入时多个候选Bean选哪个」，@Qualifier解决「按名称精确指定Bean」；两者都作用于依赖注入阶段，而Bean定义覆盖是注册阶段的问题。"}},{"name":"Bean作用域 · singleton与prototype","category":"IoC容器与Bean配置","priority":"medium","summary":"singleton每个容器一个实例，prototype每次获取新实例，prototype注入singleton会只创建一次。","interview":"为什么prototype Bean注入到singleton Bean里，得到的还是同一个实例？怎么解决？","principle":"singleton在容器启动时创建并缓存一份；prototype每次getBean或注入时新建。但依赖注入只发生一次（单例初始化时），后续使用同一个注入对象，所以prototype被\"冻结\"成单例效果。解法是注入ObjectFactory<T>/Provider<T>（或ObjectProvider<T>），每次调用get()动态从容器拿新实例。","params":["@Scope(\"prototype\")标注Bean作用域","@Scope(value=\"prototype\", proxyMode=TARGET_CLASS)配合ObjectProvider","@Lazy延迟初始化避免启动时创建"],"pitfalls":["prototype注入singleton后，单例持有该引用直到销毁，内存泄漏与状态污染","prototype Bean的销毁回调不归容器管（容器只管singleton销毁），需自行释放资源","仅在请求/会话作用域需要代理，单纯prototype一般不用proxyMode"],"selfCheck":{"q":"ObjectFactory<T>是怎么解决prototype注入singleton问题的？","a":"它不注入真实Bean，而是注入一个工厂；单例每次用到时调用factory.getObject()，从容器实时获取一个新prototype实例，从而避免被固定成单例。"}},{"name":"Bean后处理器 · BeanPostProcessor","category":"IoC容器与Bean配置","priority":"medium","summary":"容器级扩展点，在Bean初始化前后插入自定义逻辑，可修改或替换Bean实例。","interview":"BeanPostProcessor的执行时机是什么？它自己是怎么被注册进容器的？","principle":"BeanPostProcessor自身必须在其他Bean实例化之前完成注册，所以容器启动时会先实例化所有实现了该接口的Bean（及BeanFactoryPostProcessor），再处理普通Bean。每个普通Bean在实例化、属性填充后，依次回调postProcessBeforeInitialization、init方法、postProcessAfterInitialization，AOP代理即在此产生。","params":["postProcessBeforeInitialization：init方法之前回调","postProcessAfterInitialization：init方法之后，AOP代理在此生成","实现PriorityOrdered/Ordered可控制多个后处理器顺序"],"pitfalls":["在BeanPostProcessor中注入普通Bean，会导致该Bean被过早初始化，提前暴露、绕过部分后置处理","依赖了后处理器的Bean若被提前实例化，可能失去代理等增强","不要在后处理器里做重量级逻辑，它会作用于所有Bean"],"selfCheck":{"q":"为什么在BeanPostProcessor里@Autowired一个普通Service是个隐患？","a":"因为后处理器要先于普通Bean创建，被注入的Service会被提前实例化，此时其他后处理器还没注册完，该Service可能失去AOP代理或事务等增强。"}},{"name":"Bean延迟加载 · @Lazy","category":"IoC容器与Bean配置","priority":"low","summary":"@Lazy让Bean在首次使用时才创建，可缓解启动慢与部分循环依赖。","interview":"@Lazy是如何解决循环依赖的？它有什么副作用？","principle":"默认单例Bean在容器启动时预实例化。加@Lazy后，容器只注册一个代理（或延迟解析入口），首次调用getBean时才真正创建并初始化。用于循环依赖时，通常加在注入点（构造器参数/字段）上，注入的是占位代理，打破启动期的双向实例化，把创建推迟到首次调用。","params":["@Lazy(value=false)默认值，true表示延迟","可标在类上（整个Bean延迟）或注入点上（仅该依赖延迟）","配合@Lazy(true) + proxyMode可生成目标代理"],"pitfalls":["问题后置：循环依赖被推迟到运行期，首次调用可能抛BeanCurrentlyInCreationException或NPE，错误更难定位","注入的是代理，若依赖最终类/无接口且未开CGLIB，代理失败","掩盖设计问题，真正的循环依赖应靠拆分职责解决"],"selfCheck":{"q":"@Lazy解决循环依赖的代价是什么？","a":"只是把创建推迟，问题后置到运行期，首次调用才暴露异常，调试更困难；且注入的是延迟代理，涉及final类或代理失败时会出错。"}},{"name":"Bean生命周期 · 主干流程","category":"Bean生命周期","priority":"high","summary":"实例化→属性填充→Aware→初始化前→init→初始化后→使用→销毁，扩展点按需选。","interview":"Bean生命周期各阶段有哪些扩展点？初始化逻辑该放在构造器、@PostConstruct还是InitializingBean？","principle":"主干：1) 实例化（构造器）；2) 属性填充；3) Aware回调（BeanNameAware等）；4) BeanPostProcessor.postProcessBeforeInitialization（@PostConstruct在此生效）；5) InitializingBean.afterPropertiesSet或自定义init-method；6) postProcessAfterInitialization（AOP代理）；7) 使用；8) destroy（@PreDestroy/DisposableBean）。选型：依赖注入用构造器，通用初始化用@PostConstruct，与Spring接口耦合才用InitializingBean。","params":["@PostConstruct：JSR-250，优先推荐，不绑Spring","InitializingBean.afterPropertiesSet：Spring接口，耦合框架","init-method/destroy-method：XML或@Bean属性指定"],"pitfalls":["构造器里拿不到属性填充后的值，别做依赖注入结果的逻辑","初始化顺序：@PostConstruct先于afterPropertiesSet","构造器注入无法解决循环依赖（无提前引用），字段注入才可以"],"selfCheck":{"q":"初始化逻辑应该写在构造器、@PostConstruct还是afterPropertiesSet里？","a":"依赖注入结果的初始化放@PostConstruct（属性已填充且不绑Spring）；构造器只做参数无关的赋值；afterPropertiesSet与Spring强耦合，非必要不用。"}},{"name":"初始化与销毁 · 回调方式","category":"Bean生命周期","priority":"medium","summary":"Bean 创建后与销毁前的回调有多种写法，混用时 Spring 按固定顺序调用，建议只选一套。","interview":"Spring 中初始化和销毁有哪几种回调方式？同时存在时执行顺序是怎样的？","principle":"初始化顺序大致为：@PostConstruct → InitializingBean.afterPropertiesSet() → 自定义 init-method；销毁反向对应 @PreDestroy → DisposableBean.destroy() → destroy-method。机制是 BeanPostProcessor（如 InitDestroyAnnotationBeanPostProcessor）和 AbstractAutowireCapableBeanFactory 在 doCreateBean 中按约定位置调用。","params":["initMethod / destroyMethod：在 @Bean 或 XML 中指定的方法名","@PostConstruct / @PreDestroy：JSR-250 注解，最常用"],"pitfalls":["混用多套时顺序固定但易误判，官方建议只用一种","destroy 回调只在容器关闭（close）时触发，非 Web 容器要手动关闭才生效","单例 bean 才有完整销毁回调，prototype 销毁由调用方自理"],"selfCheck":{"q":"@PostConstruct、afterPropertiesSet、init-method 三者同时存在，执行顺序是什么？","a":"@PostConstruct 先执行，其次是 InitializingBean.afterPropertiesSet()，最后是自定义 init-method；销毁时顺序相反（@PreDestroy 最先）。"}},{"name":"Aware接口 · 常见接口","category":"Bean生命周期","priority":"low","summary":"Aware 接口让 Bean 在初始化阶段回调注入容器自身对象，如 ApplicationContext、BeanFactory、BeanName。","interview":"Spring 里 Aware 接口是干什么的？常见有哪些？和 @Autowired 注入容器对象有什么区别？","principle":"BeanFactory 在 populateBean 之后、initMethod 之前调用 ApplicationContextAwareProcessor 等处理器，逐个回调 awareXxx() 方法把容器对象塞进来。本质是\"回调式注入\"，发生在依赖注入之后、初始化回调之前。","params":["BeanNameAware：拿自己的 bean 名称","BeanFactoryAware / ApplicationContextAware：拿容器本身","EnvironmentAware、ResourceLoaderAware 等：拿环境与资源加载器"],"pitfalls":["Aware 回调早于 @PostConstruct，此时依赖已注入但初始化未完成","能用 @Autowired 注入 ApplicationContext 就别实现 Aware，代码更干净","拿到 ApplicationContext 后在里面 getBean 容易造成循环依赖或过度耦合"],"selfCheck":{"q":"想在 Bean 里拿到 ApplicationContext，有哪两种常见做法？何时用 Aware？","a":"一是实现 ApplicationContextAware 接口，二是 @Autowired 注入 ApplicationContext。优先用注解；只有在不想依赖注解扫描、或写基础组件时才用 Aware。"}},{"name":"循环依赖 · 三级缓存机制","category":"循环依赖","priority":"high","summary":"单例 + 属性注入的循环依赖靠三级缓存提前暴露半成品引用解决，构造器注入和 prototype 无解。","interview":"Spring 怎么解决循环依赖？三级缓存分别存什么？为什么构造器注入解决不了？","principle":"创建 A 时把 A 的 ObjectFactory（生产早期引用，可能产出代理）放入三级缓存，填充属性时发现需要 B；创建 B 又需要 A，此时从三级缓存拿到 A 的早期引用放进二级缓存并移除三级，B 完成后回填给 A。三级缓存设计是为了在需要时才通过代理工厂生成早期引用（AOP 一致性）。","params":["singletonObjects：成品缓存","earlySingletonObjects：半成品（早期引用）缓存","singletonFactories：ObjectFactory 缓存，用于按需生成早期引用"],"pitfalls":["prototype 作用域不走缓存，每次新建，循环依赖必死","构造器循环依赖无解：A 还没实例化完就要 B，B 又要 A，没有提前暴露点，只能改用 @Lazy 或 setter 注入","只有单例 + 属性/setter 注入才能靠三级缓存解决；@Async、AOP 代理相关的提前引用走的是 ObjectFactory"],"selfCheck":{"q":"为什么构造器注入的循环依赖三级缓存救不了？","a":"因为三级缓存的前提是 A 已实例化（构造完成）才能放入 ObjectFactory 提前暴露引用。构造器注入时 A 尚未构造完就要 B，而 B 又要 A，无可暴露对象，只能 @Lazy 延迟或改 setter 注入。"}},{"name":"循环依赖 · 构造器注入为何不行","category":"循环依赖","priority":"high","summary":"构造器在 Bean 创建早期就要依赖对象，无法先暴露半成品，所以循环构造依赖必死锁。","interview":"为什么构造器注入无法解决循环依赖，而 setter/字段注入可以？","principle":"Spring 解决循环依赖靠三级缓存：实例化后立即把 ObjectFactory 放入三级缓存，供别人提前引用（可能拿到代理前的半成品）。构造器注入发生在实例化阶段，A 没 new 完就要 B，B 又要 A，两个都没进入缓存，只能抛 BeanCurrentlyInCreationException。","params":["@Lazy：注入代理，首次调用才真正取 Bean","setter/字段注入：允许先实例化再填充属性","重构拆分：把公共逻辑抽到第三个 Bean"],"pitfalls":["@Lazy 只是延迟，本质是掩盖问题，若依赖确实需要一起初始化会埋雷","字段注入方便但不利于不可变与测试，团队规范常禁用","即便 setter 注入，构造期依赖仍无法救，两种注入混用时要小心"],"selfCheck":{"q":"A 构造器依赖 B、B 字段依赖 A，能启动吗？","a":"不能。A 实例化阶段就要 B，B 回头要 A 时 A 还没进缓存，构造器注入绕不开，仍会循环依赖异常。"}},{"name":"循环依赖 · 破坏方式与现状","category":"循环依赖","priority":"medium","summary":"新版 Spring Boot 默认禁止循环依赖，需显式开启或重构代码。","interview":"allowCircularReferences 关闭后有什么影响？新版本 Spring Boot 默认行为是什么？","principle":"allowCircularReferences=false 时容器不再走三级缓存提前暴露，发现循环直接抛 BeanCurrentlyInCreationException。Spring Boot 2.6 起默认为 false，鼓励靠设计消除循环而非靠容器兜底；开启方式是 spring.main.allow-circular-references=true 或 setAllowCircularReferences(true)。","params":["allowCircularReferences：默认 false（Boot 2.6+）","spring.main.allow-circular-references=true 临时开启","@Lazy 或重构是推荐的替代方案"],"pitfalls":["直接开启是把技术债往后推，CI/评审常禁止","即便开启，构造器循环依赖依然无解","升级 Boot 2.5→2.6 时该异常突然冒出，需排查存量循环"],"selfCheck":{"q":"Spring Boot 2.6 项目启动抛 BeanCurrentlyInCreationException，第一反应该做什么？","a":"先判断是不是循环依赖，优先用 @Lazy 或拆分 Bean 重构；若只是临时救急才打开 allow-circular-references=true，并记录技术债。"}},{"name":"AOP · 核心概念与切点","category":"AOP与动态代理","priority":"high","summary":"AOP 用动态代理在目标方法前后织入增强，切点表达式决定在哪里生效。","interview":"AOP 的核心概念有哪些？@Pointcut 怎么复用？切点匹配不到目标的常见原因是什么？","principle":"核心概念：切面 Aspect、连接点 Joinpoint（Spring 中基本等于方法）、切点 Pointcut（表达式筛选连接点）、通知 Advice（before/after/around/afterReturning/afterThrowing）、织入 Weaving（生成代理）。代理方式：有接口默认 JDK 动态代理，无接口用 CGLIB；Spring Boot 2.x 默认 CGLIB。@Pointcut 把表达式抽成方法，其他通知用方法名引用，实现复用。","params":["execution(* com.x.service.*.*(..)) 最常用","within / @annotation / bean 也可组合","@Aspect + @Component 才会被扫描为切面"],"pitfalls":["自调用（同类内 this.method()）不走代理，增强失效","切点包路径写错或方法非 public，匹配不到","final 类/方法无法被 CGLIB 代理；@Transactional 同理失效"],"selfCheck":{"q":"@Pointcut(\"execution(* com.demo.service..*.*(..))\") 里两个点号是什么意思？","a":".. 表示匹配 com.demo.service 及其所有子包下的任意类任意方法，一个点是当前包，两个点包含子包，写错会导致切点匹配不到目标。"}},{"name":"动态代理 · JDK与CGLIB","category":"AOP与动态代理","priority":"high","summary":"JDK基于接口用反射，CGLIB基于继承用字节码生成子类，Spring默认按有无接口选择。","interview":"JDK动态代理和CGLIB有什么区别，Spring怎么选？","principle":"JDK的Proxy.newProxyInstance为接口生成实现类，InvocationHandler转发方法调用；CGLIB用ASM生成目标类的子类重写方法织入增强。Spring Boot 2.x起默认proxyTargetClass=true优先用CGLIB，可不依赖接口。","params":["JDK要求目标类实现接口，方法调用走InvocationHandler.invoke","CGLIB通过生成子类实现代理，无需接口但要求类可继承","proxyTargetClass=true强制CGLIB，false时有接口用JDK"],"pitfalls":["final方法和final类无法被CGLIB重写/继承，代理会失效或抛错","同类内部自调用不走代理对象，增强不生效，需注入自身或AopContext.currentProxy()","CGLIB要求类有无参构造，且方法是public/protected才能被拦截"],"selfCheck":{"q":"为什么同类中方法A调用方法B，B上的@Transactional不生效？","a":"自调用是this直接调用，没走代理对象，切面不介入。可通过注入自身代理、AopContext.currentProxy()或拆分类解决。"}},{"name":"AOP · 失效场景与原理","category":"AOP与动态代理","priority":"high","summary":"AOP失效分两类：代理根本没生成，或代理生成了但调用绕过了代理对象。","interview":"@Transactional注解失效有哪些常见原因，怎么排查？","principle":"代理未介入：目标类是final、非Spring管理（new出来的）、切点表达式没匹配、方法非public（Spring AOP默认只代理public）。代理被绕过：同类自调用、在Bean初始化早期（如构造器/BeanPostProcessor阶段）使用代理。排查先确认getBean拿到的是代理类（含$$、EnhancerBySpringCGLIB），再看调用路径是否经过代理。","params":["切点表达式execution/@annotation要与方法签名精确匹配","@Transactional默认只对public方法生效","proxyTargetClass影响代理形态但不解决绕过问题"],"pitfalls":["new出来的对象不在容器里，AOP完全不介入","同一类方法自调用绕过代理，是最常见失效原因","异常被catch吞掉或rollbackFor不匹配，导致事务看似失效"],"selfCheck":{"q":"如何快速判断一个Bean的AOP是否生效？","a":"打印getClass().getName()看是否有$$EnhancerBySpringCGLIB或$Proxy前缀，或在增强逻辑打日志，确认调用是否走代理对象。"}},{"name":"AOP · 与生命周期的关系","category":"AOP与动态代理","priority":"medium","summary":"AOP在Bean初始化后置阶段介入，getBean和@Autowired拿到的都是代理对象而非原始对象。","interview":"getBean拿到的是原始Bean还是代理对象？AOP在Bean生命周期哪一步生效？","principle":"Bean生命周期：实例化→属性填充→Aware→BeanPostProcessor.postProcessBeforeInitialization→InitializingBean/init-method→postProcessAfterInitialization→使用→销毁。AbstractAutoProxyCreator（AbstractAutowireCapableBeanFactory.applyBeanPostProcessorsAfterInitialization）在这里决定是否用代理对象替换原始对象放入容器，因此依赖注入和getBean拿到的是代理。","params":["AOP代理发生在postProcessAfterInitialization阶段","getBean/getObjectForBeanInstance返回的是代理对象","@Autowired注入的也是代理对象"],"pitfalls":["代理替换发生在初始化后，构造器阶段用不到代理对象","代理对象持有原始对象引用，二者是两个实例，别用==比较","早期Bean或非单例场景，代理创建时机与作用域需留意"],"selfCheck":{"q":"为什么在构造方法里调用带@Async的方法不生效？","a":"构造阶段Bean还没走完初始化，AOP代理尚未生成，此时调用的是原始对象，增强不介入。"}},{"name":"依赖注入 · @Autowired装配规则","category":"@Autowired与装配","priority":"medium","summary":"@Autowired默认按类型装配，同类型多个候选时按名称匹配，再靠@Primary或限定符消歧。","interview":"多个同类型Bean时@Autowired怎么选？报错怎么解决？","principle":"容器先按类型查找候选Bean；只有一个直接注入；有多个再按属性名/参数名与beanName匹配；仍不唯一则抛NoUniqueBeanDefinitionException，此时可用@Primary指定首选，或用@Qualifier限定名称；@Resource是JSR-250规范，默认按名称装配、找不到再按类型，不参与@Primary。","params":["required=false：找不到时注入null而非报错","@Primary标记首选Bean，同类多个时优先","@Qualifier(\"name\")或@Resource(name=…)按名称指定"],"pitfalls":["同类型多个且名称不匹配时启动直接报NoUniqueBeanDefinitionException，异常信息会列出候选beanName","@Resource不走@Primary，混用时行为易预期偏差","接口多实现时推荐组合@Qualifier，比依赖字段名更稳"],"selfCheck":{"q":"@Autowired和@Resource在多个候选Bean时的选择顺序有何区别？","a":"@Autowired先按类型，多个再按名称/名称不匹配靠@Primary或@Qualifier消歧；@Resource先按名称（name属性），找不到再按类型，不认@Primary。"}},{"name":"@Autowired · 注入点与循环依赖","category":"@Autowired与装配","priority":"medium","summary":"@Autowired可注入集合、ObjectProvider；循环依赖靠三级缓存解决构造器之外的注入。","interview":"注入List/Map和ObjectProvider各适用于什么场景？循环依赖怎么破？","principle":"字段/setter注入的循环依赖靠三级缓存：实例化后先暴露早期引用（可能为代理），B注入A的早期引用完成初始化，A再完成填充。注入点是List/Map时，容器收集所有匹配类型的Bean装配成集合（Map的key为beanName）；ObjectProvider延迟解析，调用getObject/getIfAvailable时才按需取Bean，可避免启动期硬依赖和循环依赖。","params":["List<T>/Set<T>：注入所有T类型Bean","Map<String,T>：key为beanName","ObjectProvider<T>：延迟获取，支持getIfAvailable、stream()"],"pitfalls":["构造器注入无法用三级缓存解决循环依赖，会直接启动失败（Spring Boot 2.6+默认禁止循环引用）","ObjectProvider取不到时getIfAvailable返回null，getObject会抛NoSuchBeanDefinitionException","循环依赖+@Async等AOP场景，早期引用可能是代理，注意自注入拿到的是代理对象"],"selfCheck":{"q":"为什么构造器注入的循环依赖解决不了，字段注入却可以？","a":"字段注入时Bean已实例化，可提前把早期引用放入缓存暴露给对方；构造器注入在实例化阶段就要对方，无法提前暴露，只能报错。"}}]}', NULL, 1793689227499, 1793689409578),
	(5, 2, 6, 'ready', NULL, NULL, 1793869755466, 1793869805971);

