INSERT INTO "users" ("id", "username", "password_hash", "nickname", "avatar_ext", "api_key_cipher", "api_key_nonce", "api_key_version", "api_key_last4", "api_base", "model", "api_format", "temperature", "summary_json", "summary_at", "summary_status", "summary_error", "summary_started_at", "created_at", "updated_at") VALUES
	(1, 'testuser1', '$argon2id$v=19$m=16384,t=2,p=1$6CQx6Aj1BWDvC5JBLNQaFw$FfW6VwJ9IycBD4TB4fEpMsAUHZ8vzWF9MKeKYBXObmk', 'testuser1', NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1793756057549, 1793756057549),
	(2, 'admin', '$argon2id$v=19$m=16384,t=2,p=1$9DBKrrIZ2bUgAmffafaD/Q$GmpM9GDVRni79dXlnoJlN9qADByKcnxPvdatlc2PGXY', '管理员', 'jpg', 'LOzXxK+VcAHPBEbmQMIrO//OuqKgReF2HbyCktHJZiH6vUch5usLpXhNRFLJFQXCblVh', 'EWeoJpgNRPPmPvkf', 1, 'd145', 'https://api.deepseek.com/anthropic', 'deepseek-flash', 'anthropic', 1, '{"profile":{"title":"Java 并发与 Spring 核心概念有零散积累，但作答完整度低、原理深度不足的初级后端开发","overview":"共 235 题、平均 47.8 分，最近一卷 50.5 分。已覆盖集合、多线程锁机制、线程池、Spring IOC/AOP/循环依赖等高频点，部分结论性知识（三级缓存、JDK/CGLIB 代理选型、volatile 禁重排、线程池主干流程）掌握稳定。但普遍存在只给结论不推机制、多问漏答、场景题维度不全、未作答率高等问题，错题本 119 题待订正且已解决为 0。AQS、锁升级、ThreadLocal、JVM、SpringBoot 自动配置等大块知识点几乎未学或未练，整体处于初级水平。"},"strengths":[{"point":"循环依赖与 AOP 代理选型的关键结论掌握较稳","evidence":"最强 10 点中循环依赖·三级缓存机制(100)、AOP·JDK动态代理基于接口实现(100)；卷 4 评价明确“三级缓存流程、AOP 自调用失效、JDK 与 CGLIB 选型掌握较稳”。"},{"point":"volatile 与 synchronized 基础语义掌握较好","evidence":"volatile 与可见性：已掌握 2 / 待巩固 1；最强 10 点中 volatile·禁止指令重排(100)、volatile·不保证复合操作原子性(100)、synchronized·三种使用形式与语义(93)。"},{"point":"线程池主干流程与内置线程池风险点记忆扎实","evidence":"线程池平均 61.4 分，四块练习中最高；卷 1/卷 2/卷 3 均评价“基础概念扎实”；已掌握 SynchronousQueue 直接交接、FixedThreadPool 无界队列 OOM、任务提交 core→queue→max→拒绝流程。"},{"point":"集合基础概念题得分较高","evidence":"Java 集合平均 59.2 分，卷 1 评价“基础概念掌握较扎实，复杂度、扩容倍数、树化条件得分高”；已掌握 fail-fast 与 CME 原因等。"}],"weaknesses":[{"point":"作答完整度低、多问漏答、只给结论不讲机制，是失分主因","evidence":"多处卷评指出“只给结论不展开机制”、“简答题漏答第二问”、“大题多问漏点”；Spring 练习卷 1 仅作答 3/10 题；错题本 119 题待订正、已解决 0。","advice":"每道题按题面逐问编号作答，先写结论再用 2–3 句补机制；错题本按“未作答→低分”顺序订正并口头复述。"},{"point":"AQS、锁升级、Condition、happens-before 等并发原理长期薄弱","evidence":"AQS 原理未学 3、Java 多线程锁机制未学 9；锁机制练习平均 44.1 分；卷 6 评价 happens-before 语义答反；薄弱点含 AQS 自旋入队阻塞、锁升级触发条件、Condition await/signal 语义。","advice":"用一页纸画出 AQS 抢锁失败→入队→阻塞主干和锁升级四阶段触发条件，每天默写一遍直到能讲清不可逆原因。"},{"point":"Spring 生命周期销毁链、作用域选型、注入时机说不清","evidence":"Bean 生命周期已掌握 0 / 待巩固 2 / 学习中 1 / 未学 1；薄弱点含 Aware 接口空答、销毁链漏 BeanPostProcessor、字段注入与 setter 注入时机差异答不出、会话级可变状态误选 prototype。","advice":"对照记忆点中“销毁顺序三步”和“属性填充阶段”两条背诵，再用一个会话购物车例子口述作用域选 request 的理由。"},{"point":"大块知识点几乎未覆盖：ThreadLocal、JVM 内存模型、类加载与 SpringBoot 自动配置","evidence":"ThreadLocal 未学 6、JVM 内存模型未学 4、类加载未学 3、SpringBoot 自动配置未学 6、Starter 未学 3、过滤器与拦截器未学 4；对应练习均为 0 张卷、0 道题。","advice":"按“ThreadLocal→JVM 内存模型→SpringBoot 自动配置/Starter”顺序各做一套速通卷，先保证答完再谈深度。"},{"point":"线程池场景化选型、拒绝策略兜底与核心线程存活策略未掌握","evidence":"最弱 10 点全部为线程池条目（核心/非核心存活策略、拒绝策略补偿、execute/submit 异常差异、CPU/IO 密集型线程数估算等均为 0）；薄弱点含 shutdown 与 shutdownNow 区别未掌握。","advice":"以“下单后发短信”场景写一份自定义线程池参数表（核心数、队列、拒绝策略、兜底落盘），并对比 execute 与 submit 异常路径。"}],"jobAdvice":{"targetLevel":"junior","positions":["Java 后端开发（初级）","Java 并发/中间件方向初级开发","Spring 生态应用开发（初级）"],"reasons":["大量知识点未覆盖：ThreadLocal、JVM、类加载、SpringBoot 自动配置、Starter、过滤器与拦截器等均为未学状态，0 张卷 0 道题，不满足 mid 的覆盖面要求。","已覆盖部分深度不足：平均 47.8 分、错题 119 题待订正且已解决 0，多卷评价为“只给结论不讲机制”，场景题表现弱。","仅集合、线程池、部分 Spring 结论性知识得分接近及格线（59.2 / 61.4），适合以初级岗切入并边面边补。"]},"interviewFocus":["Spring 循环依赖三级缓存流程 + AOP 代理创建时机（BeanPostProcessor 在初始化后生成代理），要求能画出调用链而非只背结论。","synchronized 锁升级四阶段触发条件与不可逆原因、AQS 抢锁失败后自旋入队阻塞主干，配合 Condition await/signal 语义。","线程池七大参数 + 自定义线程池场景设计（核心数估算、有界队列容量权衡、拒绝策略补偿与最终一致）。","volatile 的 happens-before 语义与 DCL 单例写法，避免重排序与可见性表述答反。","Bean 生命周期完整链路（实例化→属性填充→初始化→销毁）及 Aware 接口、销毁回调顺序。"],"actionPlan":[{"step":"两周内清空错题本：119 道待订正题按“未作答→低分”排序，每天订正 10 道并口头复述机制。","why":"错题已解决 0，且未作答与只给结论是失分主因；订正是把 47.8 均分拉过及格线的最短路径。"},{"step":"用 3 天专攻并发原理：手写 AQS 入队阻塞流程图与锁升级状态迁移表，每天默写一遍。","why":"AQS 未学 3、锁机制均分 44.1，且 happens-before 曾答反；这是并发岗面试必问且当前最短板。"},{"step":"补齐 Spring 生命周期与注入时机：按记忆点背诵销毁三步与属性填充阶段，并用会话购物车案例口述作用域选型。","why":"Bean 生命周期已掌握 0、Aware 接口空答、作用域误选 prototype，均为卷评明确失分点。"},{"step":"按顺序完成三套速通卷：ThreadLocal → JVM 内存模型 → SpringBoot 自动配置/Starter，每套先保证全卷作答再复盘。","why":"这几块分别有 6/4/6 个未学知识点且 0 张卷记录，是初级岗覆盖面缺口，不补会在简历筛选与一面被直接问倒。"},{"step":"写一份自定义线程池场景方案（参数表 + 拒绝策略兜底 + execute/submit 异常对比），并对照最弱 10 点逐条自测。","why":"最弱 10 点全为线程池条目且均为 0 分，而线程池是均分最高（61.4）的模块，投入产出比最高。"}],"generatedAt":0}', 1793942591601, 'idle', NULL, NULL, 1793755971889, 1793952932241);

